update content_bodies set title = '大沼国定公園の四季', description = '大沼国定公園の四季を彩り豊かに表現した動画です。四季折々の美しい風景が楽しめる内容となっており、自然の変化やその魅力を感じることができます。春の新緑、夏の青空、秋の紅葉、冬の雪景色など、各季節の特徴が映し出されており、訪れる人々に感動を与えることでしょう。' where id = 'gaveaYfmHWZYo3NsmjFI3';
