update content_bodies set title = '根室市観光PR動画　DEEP HOKKAIDO NEMURO　プロモーション”歴史”編', description = '日本本土最東端に位置する根室は、一般的な北海道の魅力とは異なる独自の体験を提供します。北海道民でさえあまり知らない、根室の深い魅力を紹介する動画『DEEP HOKKAIDO NEMURO』では、グルメ、自然、文化をテーマにしています。音楽は岡崎雄二郎が担当し、根室観光大使の大川正義がプロデュースを手掛けています。詳細は根室観光NAVIのウェブサイトをご覧ください。' where id = '1ZuFhepdFoYdY6VGlVVVL';
update content_bodies set title = 'Nemuro City Tourism PR Video: DEEP HOKKAIDO NEMURO - History Edition', description = 'Located at the easternmost point of Japan''s main island, Nemuro offers a unique experience that differs from the typical Hokkaido charm. It showcases a deep and lesser-known side of Hokkaido, even to its residents. The video, themed ''DEEP HOKKAIDO NEMURO'', highlights the attractions of Nemuro, encompassing gourmet, nature, and culture. The project features music by Yujiro Okazaki and is produced by Masayoshi Okawa, a tourism ambassador for Nemuro. For more information, visit the Nemuro Tourism NAVI website.' where id = 'slKxDhn6WyKiWryblkyWy';
update content_bodies set title = '根室市観光PR動画　DEEP HOKKAIDO NEMURO　ダイジェスト”自然（冬）”編', description = '日本本土最東端に位置する根室は、一般的な北海道の魅力とは異なる独自の体験を提供します。北海道民でさえあまり知らない、ディープな北海道の一面を紹介しています。この動画では、根室のグルメや自然、文化を『DEEP HOKKAIDO NEMURO』というコンセプトのもとに紹介し、その魅力を伝えています。詳細は根室観光NAVIのウェブサイトをご覧ください。' where id = 'nSTsr6mVlzwh3cGGSgbaJ';
update content_bodies set title = 'Nemun City Tourism PR Video: DEEP HOKKAIDO NEMURO - Nature (Winter) Edition', description = 'Located at the easternmost point of Japan''s main island, Nemuro offers a unique experience that differs from the typical Hokkaido charm. It showcases a deep and lesser-known side of Hokkaido, even to many locals. The video introduces the attractions of Nemuro under the concept of ''DEEP HOKKAIDO NEMURO,'' highlighting its gourmet, nature, and culture. For more information, visit the Nemuro Tourism NAVI website.' where id = 'HSSxVILqnsbsvH8Mc6V6z';
