update content_bodies set title = '日本・越前町のイルカウォッチングツアー', description = '2018年3月26日、福井県の越前町の海岸で、船「オーシャンクイーン」から多くのイルカを観察しました。素晴らしい体験でした。' where id = 'OvvUKcp85RgkY7GW-8jBt';
update content_bodies set title = 'Dolphin Watch Tour in Koshino, Japan', description = 'On March 26, 2018, we enjoyed an incredible dolphin watching experience at Koshino coast in Fukui, Japan. From the ship ''Ocean Queen'', we observed numerous dolphins, making the trip truly amazing.' where id = 'z3sLR95nM6hU5UCr9okv8';
