update content_bodies set title = '北海道弟子屈町　冬', description = '弟子屈町の冬の魅力を紹介します。美しい雪景色や冬のアクティビティが楽しめるこの町は、訪れる人々に特別な体験を提供します。' where id = 'xaDt7jx8m92PiUAnReqWS';
