update content_bodies set title = 'ロケ地紹介: 水口岡山城跡', description = '滋賀県甲賀市にあるロケ地を360度カメラで紹介します。水口岡山城跡は、歴史的な背景を持つ場所であり、撮影に適した美しい景観が広がっています。360度カメラを使用することで、訪れる人々はこの場所の魅力をより深く体感できるでしょう。' where id = '4BHe94MBl5dYC39jP-hq8';
