update content_bodies set title = '【大分県】おんせん県おおいた観光動画　～大分市：ダイジェスト15秒～', description = '大分県は日本一の温泉県として知られています。この動画は、大分市を紹介する観光PR動画の15秒ダイジェスト版です。大分県内の18市町村の魅力を伝える内容となっており、地域の特性や観光スポットが紹介されています。詳細は大分県観光情報公式サイトをご覧ください。' where id = 'wF0esSvOLFtlwMveIy6hM';
update content_bodies set title = 'Oita Prefecture: Oita City Tourism Video - 15 Second Digest', description = 'This is a 15-second digest of the tourism promotional video for Oita City, part of Oita Prefecture, which is renowned as Japan''s top hot spring destination. The video showcases attractions across 18 cities and towns within Oita Prefecture, highlighting the unique appeal of the region. For more information, visit the official Oita tourism website.' where id = '0A_gPgK3PcAPgGfeVYf4s';
update content_bodies set title = '日本一の信楽高原鐵道(ショートVER)', description = '「スカーレット」で甲賀を盛り上げる推進協議会が制作した信楽高原鐵道のプロモーションビデオ（ショートバージョン）です。ドラマに出演し、脚本も手がけた三谷昌登さんが企画・脚本を担当し、信楽太郎こと木本武宏さんが信楽高原鐵道に乗って信楽を巡るショートドラマが展開されます。車窓からの美しい景色を楽しみながら、ぜひ甲賀市信楽を訪れてみてください。「皆さんも是非一度いらしてください。信楽高原鐵道に乗って！」フルバージョンは以下のリンクからご覧いただけます。https://youtu.be/-Tgi8aEFR0U（このPVは、甲賀を盛り上げる推進協議会から甲賀ロケーション推進協議会へ継承されました。）' where id = 'y7y9tMK_rP5H2XPfXmwUZ';
update content_bodies set title = 'Shigaraki Kogen Railway: Short Version', description = 'A promotional video (short version) for the Shigaraki Kogen Railway has been created by the promotion council to boost Koka, inspired by the drama ''Scarlet.'' The project and script were developed by Masato Mitani, who also acted in the drama, while Takehiro Kimoto, known as Shigaraki Taro, takes a ride on the railway to explore Shigaraki in a short drama format. Enjoy the scenic views from the train as you visit Shigaraki in Koka City. ''We invite everyone to come and experience the Shigaraki Kogen Railway!'' The full version can be found here: https://youtu.be/-Tgi8aEFR0U. (This promotional video has been passed from the promotion council for boosting Koka to the Koka Location Promotion Council.)' where id = 'GTw4hsCBY6uCdhZY2-emj';
update content_bodies set title = 'ロケ地紹介：頓宮大茶園', description = '滋賀県甲賀市にあるロケ地を360度カメラで紹介します。' where id = 'pHLJjDz9cA1L-rO1rOp2e';
update content_bodies set title = 'Location Introduction: Tongo Tea Garden', description = 'This is a 360-degree camera introduction of a filming location in Koka City, Shiga Prefecture.' where id = 'zz9JOuoGWWx-Vk1hp9_Ct';
update content_bodies set title = 'ロケ地紹介360度カメラ', description = '滋賀県甲賀市のロケ地を360度カメラで紹介します。美しい風景や特徴的な場所を、視覚的に体験できる内容となっています。' where id = '3OUh6qBygvHTRORc44ETB';
update content_bodies set title = 'Location Introduction with 360-Degree Camera', description = 'This introduces filming locations in Koka City, Shiga Prefecture, using a 360-degree camera.' where id = 'tA0KvvhzqF1tIjX6whkLZ';
update content_bodies set title = 'ロケ地紹介: 鶏鳴の滝', description = '滋賀県甲賀市にあるロケ地、鶏鳴の滝を360度カメラで紹介します。この美しい滝は、自然の中での撮影に最適な場所であり、訪れる人々に感動を与える景観を提供しています。' where id = 'YRU2sJ2QkABjgmrSTeVJJ';
update content_bodies set title = 'Location Introduction: Chiryu Falls', description = 'This is a 360-degree camera introduction of a filming location in Koka City, Shiga Prefecture.' where id = 'pCEAwxXK944l9AnQhJR3b';
update content_bodies set title = 'ロケ地紹介：みなくち子どもの森', description = '滋賀県甲賀市にあるロケ地「みなくち子どもの森」を360度カメラで紹介します。この場所は、自然豊かな環境の中で子どもたちが遊び、学ぶことができるスペースです。360度カメラを使用することで、訪れる前にその魅力を視覚的に体験することができます。' where id = '3YY6WcdrLj9ihjUz2hNxR';
update content_bodies set title = 'Location Introduction: Minakuchi Children''s Forest', description = 'This is a 360-degree camera introduction of a filming location in Koka City, Shiga Prefecture.' where id = 'Pm_Sy3T66QtjQ1h-8tqR6';
update content_bodies set title = 'フォトジェニックを探して', description = '甲賀映像祭2023の甲賀市民部門において、甲賀市長賞を受賞した作品についての情報です。' where id = '_0K9ziQNk8m1Vz1eg3aY6';
update content_bodies set title = 'Searching for Photogenic Moments', description = 'Koka Film Festival 2023, Koka City Citizen Division, Koka City Mayor''s Award.' where id = '4_3oqw-VqpVgTvm3pMGWz';
update content_bodies set title = 'しがらきやきものモノがたり', description = '甲賀映像祭2023の甲賀市民部門で準グランプリを受賞したこの動画は、やきものの町・信楽の魅力を伝えています。信楽で育った著者は、年齢を重ねるにつれて町への愛着が深まったことを語ります。信楽は単なる伝統工芸の地ではなく、常に新しいものが生み出されるクリエイティブで活気のある場所です。地元の作家や窯元から受ける刺激は大きく、著者自身ももっと頑張ろうと感じさせられます。この動画を通じて、信楽の良さを多くの人に知ってもらい、『ええとこ』と感じてもらえれば幸いです。' where id = 'Nyp9K_oAnhSYhQIEsdZDN';
update content_bodies set title = 'The Story of Shigaraki Pottery', description = 'This video, which won the semi-grand prize in the Koka Citizen Division at the Koka Film Festival 2023, reflects on the beauty of Shigaraki, a town known for its pottery. The author, who grew up in Shigaraki, shares how their appreciation for the town has deepened with age. Shigaraki is not just a place of traditional crafts and local industry; it is a vibrant and creative community where new things are constantly being created. The author draws inspiration from local artists and potters, feeling motivated to strive harder in their own endeavors. The video aims to showcase the charm of Shigaraki, hoping that many viewers will come to appreciate it as a wonderful place.' where id = 'o01T9CjQUX1gT1Fnko6vD';
update content_bodies set title = '岩尾池の一本杉', description = '甲賀映像祭2023において、クリエーター部門で甲賀ロケーション推進協議会長賞を受賞した作品です。' where id = 'gCZAocFLnhmw9v29QYaL-';
update content_bodies set title = 'Iwaoi Pond''s Single Cedar', description = 'Awarded at the Koka Film Festival 2023, this work received the Koka Location Promotion Council Chairman''s Award in the Creator Category.' where id = '4KKa7IvYpmRndOLmzLRJE';
update content_bodies set title = '17歳それぞれのこうか', description = '甲賀映像祭2023のクリエーター部門でグランプリを受賞したこの動画は、甲賀市の有名な場所ではなく、普段生活している高校生たちの好きな場所を紹介しています。通学路にある何気ない景色こそが、甲賀の魅力を表しているのではないかという思いから制作されました。' where id = 'zWV5kE58uw_Fu6ypS9x7l';
update content_bodies set title = 'The Unique Perspectives of 17-Year-Olds', description = 'This video, which won the Grand Prize in the Creator Category at the Koka Film Festival 2023, showcases the favorite places of high school students in Koka City, rather than the well-known spots. It emphasizes that the ordinary scenery along their commuting routes may represent the true charm of Koka.' where id = 'FoNaJmXfdbrP2yW6Fj7e-';
update content_bodies set title = '忍者好きが巡るええとこ甲賀', description = '甲賀映像祭2023【クリエーター部門】甲賀市長賞を受賞しました。子供の頃から忍者が好きで、甲賀には何度も遊びに行き、楽しい時間を過ごしてきました。大人になり忍者になった今も、訪れるたびに新たな発見があり、忍者についてより深く知ることができる場所だと実感しています。甲賀には多くの魅力があり、今回は『忍者の里 甲賀』をもっと多くの人に紹介したいと思い、忍者好き目線とママ目線で、子供と一緒に楽しめる『ええとこ甲賀』をセレクトして映像作品にしました。' where id = 'Gd1YqUYqcKIVb3AB403nP';
update content_bodies set title = 'Exploring the Wonderful Koga for Ninja Lovers', description = 'The Koga Film Festival 2023 awarded the Koga City Mayor''s Prize in the Creator''s Category. Since childhood, I have loved ninjas and have visited Koga many times, enjoying my time there. As an adult and a ninja myself, I continue to discover new aspects of this place with each visit, deepening my understanding of ninjas. Koga has various attractions, and I want to introduce ''Ninja Village Koga'' to more people. I created a video work that highlights the best of ''Wonderful Koga'' from both a ninja enthusiast''s perspective and a parent''s viewpoint, ensuring that families can enjoy it together.' where id = 'mnBjC7OP1Lm_SgBbLh0tZ';
update content_bodies set title = 'ほっ!と信楽', description = '信楽町の魅力を詰め込んだ動画を制作しました。信楽町の特性や文化、風景などが表現されており、地域の魅力を広く伝えることを目的としています。ぜひご覧いただき、応援をよろしくお願いします。' where id = 'b0h-EcGMQNblbpnfoHFTp';
update content_bodies set title = 'Hott! to Shigaraki', description = 'We have created a video that encapsulates the charm of Shigaraki Town. Thank you for your support.' where id = '8OrcgNYmzOpbld6Ja9Y4X';
update content_bodies set title = 'ロケ地紹介: 忍術村第三駐車場', description = '滋賀県甲賀市にあるロケ地を360度カメラで紹介します。忍術村の第三駐車場は、映画やドラマの撮影に利用される場所で、周囲の風景や施設を360度の視点で楽しむことができます。訪れる人々は、リアルな映像を通じてこの特別な場所の雰囲気を感じることができるでしょう。' where id = 'ts5ipRSIy-1AnMQC7yr2f';
update content_bodies set title = 'Location Introduction: Ninjutsu Village Third Parking Lot', description = 'This is a 360-degree camera introduction of a filming location in Koka City, Shiga Prefecture.' where id = 'dGfSs7PYmqQw6Fpc6xXT2';
update content_bodies set title = 'ロケ地紹介360度カメラ: 忍術村', description = '滋賀県甲賀市にあるロケ地を360度カメラで紹介します。忍術村は、忍者文化が色濃く残る地域で、観光客にとって魅力的なスポットです。360度カメラを使用することで、訪れる前にその雰囲気を体感できる貴重な機会を提供します。' where id = 'MKQ5o7Xv1fiObTCgHJNuH';
update content_bodies set title = 'Location Introduction: Ninja Village', description = 'This is a 360-degree camera introduction of a filming location in Koka City, Shiga Prefecture.' where id = 'HfQqwm-nxaUuZj5UjkVrD';
update content_bodies set title = 'ええとこなんやけどなぁ～(ロケ地紹介ビデオ)', description = 'このビデオは甲賀市ロケーション推進協議会によるもので、甲賀市にある素晴らしいロケ地を紹介しています。甲南の岩尾山や息障寺、水口城、油日神社、信楽の窯元散策路など、さまざまなスポットが登場します。ロケに関するお手伝いは私たちにお任せくださいというメッセージも伝えています。' where id = 'A6B-8GUgrhAXB63PPZWJ0';
update content_bodies set title = 'A Great Place to Visit! (Location Introduction Video)', description = 'This promotional video by the Koka City Location Promotion Council showcases the many wonderful filming locations in Koka City. The video highlights various sites including Konan''s Iwao Mountain and Ikashoji Temple, Mizukuchi Castle, Ayuhiji Shrine, the Shigaraki Kiln Walking Path, and more. It emphasizes the council''s readiness to assist with filming-related needs.' where id = 'aZ307Spt6wImyS-njkWlt';
update content_bodies set title = '【大賞受賞】2023テレどまつり作品『綾華』-北海道編-', description = '2023年テレどまつり大賞受賞作品『綾華』は、北海道の美しさを表現しています。皆さまのご声援のおかげで、この名誉ある賞を受賞できました！『綾華』というテーマは、「綾なす華」を意味し、人々が花のように地域に彩りを与える様子を象徴しています。北海道の雄大な自然の中で、人々が華麗に舞い、鮮やかな衣装を纏っています。祭りは人々の生活を豊かにし、日常を非日常へと変える力を持っています。このストーリーは、祝祭を通じて人生がどのように華やかになるかを描いています。' where id = '5nAHAKIbJU2DxNk2tsKW0';
update content_bodies set title = 'Grand Prize Winning Work ''Ryouga'' - Hokkaido Edition at the 2023 TV Festival', description = 'The 2023 TV Festival Grand Prize winning work ''Ryouga'' showcases the beauty of Hokkaido. Thanks to the support of everyone, we are honored to receive this prestigious award! The theme ''Ryouga,'' meaning ''multicolored flower,'' symbolizes how people, like flowers, bring vibrancy to their communities. In the breathtaking and unexplored nature of Hokkaido, humans dance splendidly, adorned in colorful costumes. Festivals enrich lives, transforming the ordinary into the extraordinary. This story captures the essence of how life becomes more colorful through celebration.' where id = 'vcWLlPV7TTvIcFKVICF63';
update content_bodies set title = '【大分県】おんせん県おおいた観光動画　～大分市：2分ver.～', description = '大分県の観光PR動画「大分市編」では、日本一の温泉県として知られる大分市の魅力を紹介しています。高崎山やとり天、七夕まつりなど、多彩な観光スポットが登場し、大分市の魅力が詰まった内容です。旅行の参考にぜひご覧ください。詳細は大分県観光情報公式サイトをご覧ください。' where id = 'tdyM40QHg1o49E-okNbIf';
update content_bodies set title = 'Oita Prefecture: Onsen-Ken Oita Tourism Video - Oita City 2-Minute Version', description = 'This promotional video showcases Oita City, part of Oita Prefecture, known as Japan''s top onsen (hot spring) destination. The video highlights various attractions, including Takasakiyama, Toriten (fried chicken), and the Tanabata Festival, emphasizing the rich charm of Oita City. It serves as a great reference for travelers planning their visit. For more information, visit the official Oita tourism website.' where id = 's2nn3cMeCmT4UfiFuHri6';
update content_bodies set title = '【大分県】おんせん県おおいた観光動画　～大分市：アクティビティver.～', description = '大分県内の18市町村を紹介する観光PR動画「大分市：アクティビティ」をお届けします。大分県は日本一の温泉県として知られ、高崎山森林セラピーや早吸日女神社の蛸断祈願などのアクティビティが楽しめます。旅行の参考にぜひご覧ください。' where id = '-q1zu3SzTHJUx7Y8nAzQH';
update content_bodies set title = 'Oita Prefecture: Oita City Activity Tourism Video', description = 'This promotional video showcases activities in Oita City, part of Oita Prefecture, known as Japan''s top hot spring destination. It features attractions such as Takasaki Mountain Forest Therapy and the Hayasui Hime Shrine, which is famous for its octopus-slaying prayers. This video serves as a great reference for travelers looking to explore the region.' where id = 'uf-BsEuDDDVlzYLmwu-kw';
update content_bodies set title = '美しい日本の田舎での週末：北海道・黒松内の冬', description = 'この動画は「美しい日本の田舎での週末：北海道・黒松内の冬」について紹介しています。' where id = 'iQEleb3OYsEODJASXXz7z';
update content_bodies set title = 'A Weekend In Japanese Beautiful Countryside: Winter In Kuromatsunai - Hokkaido, Japan', description = 'This video introduces ''A Weekend In Japanese Beautiful Countryside: Winter In Kuromatsunai - Hokkaido, Japan''.' where id = 'HmXACVS_A9uPTjHR7HDr7';
update content_bodies set title = '【ミッドナイトおおいた】おんせん県おおいた MV feat. マーク・パンサー full[公式/大分県]', description = 'この曲は、大分県の温泉を称賛しています。白いタオルを用意し、かけ湯をしてから温泉に入るという大分のスタンダードを紹介し、豊富な湯量と泉質がもたらす心身のリラックスを強調しています。歌詞では、大分の美しい自然や夜の魅力も描かれ、訪れる人々にユニークな体験を提供することを目的としています。「ミッドナイトおおいた」プロジェクトは、大分の夜の文化や食、活気ある雰囲気を紹介し、初めての訪問者やリピーターに隠れた魅力を発見してもらうことを目指しています。マーク・パンサーなどのアーティストが参加し、大分の魅力を伝えるアッパーチューンが特徴です。' where id = 'TJKA6wOIk8HbgDsfzBQwC';
update content_bodies set title = 'Midnight Oita: Onsen Prefecture Oita MV feat. Mark Panther Full [Official/Oita Prefecture]', description = 'The song celebrates Oita Prefecture, known for its hot springs. It highlights the standard practices of enjoying the hot springs, such as preparing a white towel and taking a cleansing bath before entering the soothing waters. The lyrics emphasize the rich variety and quality of Oita''s hot springs, which provide relaxation for both body and mind. The video showcases the beauty of Oita, from its scenic nature to its vibrant nightlife, inviting visitors to explore the unique experiences available in the area. The ''Midnight Oita'' project aims to reveal the charm of Oita''s night scene, featuring local culture, food, and the lively atmosphere of the city after sunset. With contributions from artists like Mark Panther, the project aims to attract both first-time visitors and returning guests to discover the hidden gems of Oita.' where id = 'gV2a4MQTMFpOTT5lG_iVW';
update content_bodies set title = '【ミッドナイトおおいた】おんせん県の人を知る。おおいたをもっと好きになる。 vol.1 full [公式/大分県]', description = '「ミッドナイトおおいた」は、大分県の魅力を深く掘り下げるプログラムです。温泉で有名な大分県ですが、夜の楽しみ方も豊富です。夕暮れから深夜にかけて、リラックスできるスポットが揃い、初めての人もリピーターも楽しめる内容となっています。ドキュメンタリータッチで、人々や場所、食に焦点を当て、大分の夜の魅力を紹介します。街の賑わいや飲み屋街の灯りの中で、夜を楽しむ人々の生き生きとした声が響き、大分の夜がどれほど特別で観光客にとって体験する価値があるのかを伝えます。大分を訪れたことがある人も、まだない人も、未知の魅力に引き込まれることでしょう。' where id = '0Pq95hkn6KsfooqtkNkz_';
update content_bodies set title = 'Midnight Oita: Discover the People of the Onsen Prefecture and Fall in Love with Oita More. vol.1 full [Official/Oita Prefecture]', description = 'Midnight Oita highlights the charm of Oita Prefecture, known for its hot springs but offering much more. The program showcases the best spots to enjoy from dusk to midnight, inviting both newcomers and returning visitors to explore the unique allure of Oita''s nightlife. Through a documentary-style approach, it focuses on the people, places, and food that define the nighttime experience in Oita. Viewers will hear the vibrant voices of those enjoying the night, discovering why Oita''s evenings are special and worth experiencing for tourists. The series aims to captivate anyone who has visited or is yet to visit Oita, revealing the untapped charm of the region.' where id = 'QWwYWtzjqRRmgXH2Q65cE';
update content_bodies set title = '令和３年度ツーリズム商談会プレゼンテーション動画①（大分市）', description = '大分市は別府・由布に隣接し、周辺観光が便利な場所にあります。ここには1,000頭以上のおサルが暮らす「高崎山自然動物園」や水族館など、子どもから大人まで楽しめるスポットが豊富です。また、関あじや関さば、そしてとり天といった地元グルメや、県内有数の源泉数を誇る温泉も楽しむことができます。工業都市でありながら、多様な魅力を持つ大分市の魅力が詰まっています。' where id = '9Pv8duDmucnRSpT0i-BPm';
update content_bodies set title = 'Tourism Business Meeting Presentation Video 2021 (Oita City)', description = 'Oita City, conveniently located for touring the surrounding areas, is adjacent to Beppu and Yufu. It is home to the Takasakiyama Natural Zoo, where over 1,000 monkeys live, and an aquarium, offering enjoyable spots for both children and adults. Additionally, visitors can savor local delicacies such as Seki mackerel and Toriten, as well as enjoy one of the highest numbers of hot springs in the prefecture. Despite being an industrial city, Oita City boasts a variety of attractions.' where id = '2TCi7KhncEU9iN8829HJm';
update content_bodies set title = '【ミッドナイトおおいた】おんせん県の場所を知る。おおいたをもっと好きになる。', description = '「ミッドナイトおおいた」は、大分県の魅力を夜の時間帯に焦点を当てて紹介するプロジェクトです。温泉で有名な大分県ですが、夜の楽しみ方も豊富です。夕暮れから深夜にかけて、街のスポットをゆったりと楽しむことができます。ドキュメンタリータッチで、人々や場所、食に焦点を当て、大分の夜の魅力を掘り下げます。街の雑踏や飲み屋街の灯りの中で、夜を楽しむ人々の生き生きとした声が響き、大分の夜がどれほど特別であるかを伝えます。初めての方も、再訪の方も、まだ見ぬ大分の魅力に引き込まれることでしょう。' where id = '6SCRxSHN-w49mJnzZf5Y1';
update content_bodies set title = 'Discover Oita: The Onsen Prefecture', description = 'Midnight Oita showcases the charm of Oita Prefecture, known for its hot springs but offering much more. This initiative highlights the best spots to enjoy from dusk to midnight, making it a city where visitors can truly experience the nightlife. The documentary-style presentation focuses on the people, places, and food that define Oita''s unique night culture. Viewers will hear the vibrant voices of those enjoying the night, exploring why Oita''s evenings are special and why tourists should experience them. Whether you are a first-time visitor or have been before, the allure of Oita''s nighttime attractions is sure to captivate.' where id = 'ioe8PDhaMq-tED_MQINsa';
update content_bodies set title = '【ミッドナイトおおいた】おんせん県の場所を知る。おおいたをもっと好きになる。 vol.2 full [公式/大分県]', description = '「ミッドナイトおおいた」は、大分県の魅力を夜の時間帯に焦点を当てて紹介するプロジェクトです。温泉で有名な大分県ですが、夜の楽しみ方も豊富です。夕暮れから深夜にかけて、リラックスできるスポットが揃い、初めて訪れる人もリピーターも楽しめる内容となっています。ドキュメンタリータッチで、人々や場所、食に焦点を当て、大分の夜の魅力を掘り下げます。街の賑わいや飲み屋街の灯りの中で、夜を楽しむ人々の声が響き、大分の夜がどれほど特別であるかを伝えます。大分県に来たことがある方も、まだ訪れたことがない方も、夜の魅力に引き込まれることでしょう。' where id = 'Ibr5Ti60Lwghgu1zAxzxi';
update content_bodies set title = 'Discover Oita: The Midnight Oita Experience', description = 'Midnight Oita highlights the charm of Oita Prefecture, known for its hot springs but offering much more. This initiative showcases the best spots to enjoy from dusk to midnight, inviting both newcomers and returning visitors to explore the unique nighttime attractions of Oita. The documentary-style presentation focuses on the people, places, and food that define Oita''s vibrant nightlife. Viewers will hear the lively voices of those enjoying the night, discovering why Oita''s evenings are special and worth experiencing. Whether you''ve visited before or are planning your first trip, the allure of Oita''s nighttime culture is sure to captivate you.' where id = 'ykPbvGr65twh-AoSfG192';
update content_bodies set title = '【ミッドナイトおおいた】おんせん県の食を知る。おおいたをもっと好きになる。 vol.1', description = '「ミッドナイトおおいた」は、大分県の魅力を夜の時間帯に焦点を当てて紹介するプロジェクトです。温泉で有名な大分県ですが、夜の楽しみ方も豊富です。夕暮れから深夜にかけて、ゆったりと過ごせるスポットが揃い、初めて訪れる人もリピーターも楽しめる内容となっています。ドキュメンタリータッチで、人々や場所、食に焦点を当て、大分の夜の魅力を掘り下げます。街の賑わいや飲み屋街の灯りの中で、訪れる人々の生き生きとした声が響き、大分の夜がどれほど特別であるかを伝えます。大分県の魅力を再発見し、もっと好きになること間違いなしです。' where id = 'vTMKUDTAb3wjw_ZXn6Rrp';
update content_bodies set title = 'Midnight Oita: Discover the Cuisine of Oita Prefecture', description = 'Midnight Oita highlights the charm of Oita Prefecture, known for its hot springs, but also offers much more. This initiative showcases the best spots to enjoy from dusk until midnight, inviting both newcomers and returning visitors to explore the unique nighttime attractions of Oita. The documentary-style presentation focuses on the people, places, and food that define Oita''s nightlife, capturing the vibrant atmosphere of the streets as they come alive with lights and sounds. It emphasizes the significance of Oita''s nights and why they are a must-experience for tourists. Whether you have visited Oita before or not, you are sure to fall in love with its undiscovered allure.' where id = 'Rb4VXarWb9Dc_V8ip03zI';
update content_bodies set title = '【ミッドナイトおおいた】おんせん県の食を知る。おおいたをもっと好きになる。 vol.2', description = '「ミッドナイトおおいた」は、大分県の魅力を深く掘り下げるプロジェクトで、温泉だけでなく、夕暮れから深夜にかけて楽しめるスポットを紹介します。初めての人もリピーターも、大分の夜の魅力を体験することができる内容です。ドキュメンタリータッチで、人々や場所、食に焦点を当て、大分の夜を楽しむ人々の生き生きとした声を伝えます。大分の夜がどのように特別で、観光客が体験すべき理由を探ります。大分を訪れたことがある方も、まだない方も、未知の魅力に引き込まれることでしょう。' where id = 'b834E7N1nEdka8i6V2yZ2';
update content_bodies set title = 'Midnight Oita: Discover the Cuisine of Oita Prefecture', description = 'Midnight Oita highlights the charm of Oita Prefecture, known for its hot springs but offering much more. This initiative showcases the best spots to enjoy from dusk to midnight, inviting both first-time visitors and returning guests to explore the unique nighttime attractions of Oita. The documentary-style presentation focuses on the people, places, and food that define Oita''s nightlife, capturing the vibrant atmosphere of the streets and the lively voices of those enjoying the night. It emphasizes why Oita''s night scene is special and worth experiencing for tourists. Whether you have visited Oita before or not, you are sure to be captivated by its undiscovered allure.' where id = 'CCTikRlLkVmzc3a2B5Hm1';
update content_bodies set title = '【大分県】おんせん県おおいた観光動画　～中津市：2分ver.～', description = '大分県の観光PR動画「中津市編」では、日本一の温泉県である大分県の魅力を紹介しています。中津城やコスモス祭り、青の洞門、そして中津からあげやはも料理など、多彩な観光スポットが登場します。中津市の魅力が詰まったこの動画は、旅行の参考にぜひご覧ください。' where id = '_u4FzhpCXwKbvM5S7iCz2';
update content_bodies set title = 'Oita Prefecture: Onsen-Ken Oita Tourism Video - Nakatsu City (2 min version)', description = 'This promotional video showcases Nakatsu City, part of Oita Prefecture, known as Japan''s top onsen (hot spring) destination. The video highlights various attractions including Nakatsu Castle, the Cosmos Festival, the Aoi Cave, and local specialties such as Nakatsu fried chicken and eel dishes. It serves as a great reference for travelers looking to explore the rich offerings of Nakatsu City.' where id = 'cvaOf9u6yhDZon7i9VbBY';
update content_bodies set title = '【大分県】おんせん県おおいた観光動画　～中津市：ダイジェスト15秒～', description = '大分県は日本一の温泉県として知られています。この動画は、大分県内の18市町村の観光PR動画の中から、中津市編の15秒ダイジェストです。中津市の魅力を紹介しており、観光情報を提供しています。詳細は大分県観光情報公式サイトをご覧ください。' where id = '_v7HU2DhSfKyZNNmEpAYn';
update content_bodies set title = 'Oita Prefecture: Onsen-Ken Oita Tourism Video - Nakatsu City Digest 15 Seconds', description = 'This is a 15-second digest of the tourism promotional video for Nakatsu City, part of Oita Prefecture, which is known as Japan''s number one onsen (hot spring) destination. The video showcases the attractions of Nakatsu City within Oita Prefecture, which consists of 18 cities and towns. For more information, visit the official Oita tourism website.' where id = 'WQ_K1BhG_kM6Xwn8Izp0H';
