update content_bodies set title = 'Oita Prefecture: Onsen-Ken Oita Tourism Video - Beppu City (2 min version)', description = 'This promotional video showcases Beppu City, part of Oita Prefecture, known as Japan''s top onsen (hot spring) destination. The video highlights various attractions, including the Hell Tour, Beppu Rakutenchi amusement park, hell-steamed cuisine, and Beppu cold noodles. It serves as a great reference for travelers looking to explore the rich offerings of Beppu City.' where id = 'l70p13irLp_poQoIcuNn7';
