update content_bodies set title = 'Oita Prefecture: Onsen-Ken Oita Tourism Video - Saiki City (2-minute version)', description = 'This is a promotional video for Saiki City, part of Oita Prefecture, known as Japan''s top onsen (hot spring) destination. The video showcases various attractions in Saiki City, including the Sky Observatory, Bungo Futami Coast, and Saiki Sushi. It is filled with the charm of Saiki City and serves as a great reference for travelers planning their visit. For more information, visit the official Oita Prefecture tourism website.' where id = 'N5jjuGCqNKid7_stzgqzk';
