update content_bodies set title = '国東アートや佐伯グルメなど！おすすめ情報満載！ぐるり秋号vol.71', description = '本号では、映えスポットが豊富な「国東半島アート巡り」を特集し、さらに美味しい海鮮や可愛い雑貨を楽しむ「佐伯で贅沢グルメ旅」を紹介します。国東半島のアートを巡りながら、素敵な写真を撮ることができ、佐伯では贅沢な食事を堪能できる情報が満載です。' where id = '8Y712lafyETEBRb3y-r3L';
update content_bodies set title = 'Kunisaki Art and Saiki Gourmet: A Treasure Trove of Recommendations! GURURI Autumn Issue Vol. 71', description = 'This issue features the picturesque ''Kunisaki Peninsula Art Tour'' filled with Instagram-worthy spots, as well as a luxurious gourmet journey in Saiki, where you can indulge in delicious seafood and find charming miscellaneous goods.' where id = '7-k_hsN_ERUD_JfTFfiTB';
