update content_bodies set title = 'Oita Prefecture: Onsen-Ken Oita Tourism Video - Usuki City: 2-Minute Version', description = 'This is a promotional video for Usuki City, part of Oita Prefecture, known as Japan''s top onsen (hot spring) destination. The video showcases various attractions in Usuki City, including the National Treasure Usuki Stone Buddhas, the Fureai Limestone Cave, and Usuki fugu (pufferfish). It is filled with the charm of Usuki City and serves as a great reference for travelers. For more information, visit the official Oita tourism website.' where id = 'EA-N95pD5y8UOcHwwnL1L';
update content_bodies set title = '【大分県】おんせん県おおいた観光動画　～臼杵市：アクティビティver.～', description = '大分県の観光PR動画「臼杵市：アクティビティ」では、日本一の温泉県である大分県内の18市町村の魅力を紹介しています。動画では、ソフトクリームや臼杵クーポン、臼杵煎餅の手塗り体験など、地域のアクティビティが取り上げられています。旅行の参考にぜひご覧ください。詳細は大分県観光情報公式サイトをご覧ください。' where id = 'I5MfjN-A32uma-JhWIiOO';
