update content_bodies set title = 'Oita Prefecture: Onsen-Ken Oita Tourism Video - Hiji Town: 2-Minute Version', description = 'This is a promotional video for Hiji Town, part of Oita Prefecture, known as Japan''s top onsen (hot spring) area. The video showcases various attractions in Hiji Town, including the beautiful Miyama Kirishima on Mount Keizuyama, a fishing boat cruise in Beppu Bay, Harmonyland amusement park, and delicious joshikarei (flatfish). It serves as a great reference for travelers looking to explore the charm of Hiji Town. For more information, visit the official Oita tourism website.' where id = 'pLYt51NVq0GS9a9TYz_Q_';
