update content_bodies set title = 'Oita Prefecture: Onsen-Ken Oita Tourism Video - Hiji Town: Activity Version', description = 'This is a promotional video for tourism in Hiji Town, part of Oita Prefecture, known as Japan''s top onsen (hot spring) area. The video highlights various activities available in the region, including a Beppu Bay fishing boat cruise and Harmonyland amusement park. It serves as a great reference for travelers looking to explore the attractions of Oita Prefecture.' where id = 'znFnh1dAeHDkLHA0oH2v4';
