update content_bodies set title = 'Oita Prefecture: Onsen-Ken Oita Tourism Video - Hiji Town Digest 15 Seconds', description = 'This is a 15-second digest of the tourism promotional video for Hiji Town, part of Oita Prefecture, known as Japan''s number one onsen (hot spring) area. The video showcases the attractions of Hiji Town within Oita Prefecture, which consists of 18 cities and towns. For more information, visit the official Oita tourism website.' where id = '-PxCPH6NW14BCfkh8TtXh';
update content_bodies set title = '厚岸道立自然公園は厚岸霧多布昆布森国定公園（仮称）へ・・・《Forever&Ever 〜美しい自然のその先へ》', description = 'このプロモーションビデオは、2021年春に「厚岸霧多布昆布森国定公園」の指定を目指して制作されました。映像の撮影を担当しました。2021年3月30日に正式に指定されました！制作は厚岸道立自然公園国定公園化促進期成会が行い、釧路町、厚岸町、浜中町、標茶町が参加しています。企画・編集は株式会社スタッフが担当し、撮影はノーザンフォトの北村康春が行いました。ウイスキーの映像は「厚岸蒸溜所」から提供されています。' where id = 'h5eBqVGy6zye1m18Nr9XA';
update content_bodies set title = 'Akkeshi Prefectural Nature Park to Become Akkeshi-Kiritappu Kombu Forest National Park (Tentative) ...《Forever & Ever - Beyond Beautiful Nature》', description = 'This promotional video was created with the aim of designating the ''Akkeshi-Kiritappu Kombu Forest National Park'' in spring 2021. I was responsible for the filming of the visuals. The designation was officially granted on March 30, 2021! The production was led by the Akkeshi Prefectural Nature Park National Park Promotion Committee, which includes Kushiro, Akkeshi, Hamana, and Shibecha towns. Planning and editing were done by Staff Co., Ltd., and the filming was conducted by Yasuharu Kitamura of Northern Photo. The whiskey footage was provided by Akkeshi Distillery.' where id = 'vx2kNHQKpzCn3G8-KRVgh';
update content_bodies set title = 'ゲストハウス六番沢', description = 'ゲストハウス六番沢は、周囲2キロ四方に人家がない湿原の際に位置する宿泊施設です。霧多布湿原の自然に囲まれた静かな環境で、訪れる人々にリラックスしたひとときを提供します。' where id = 'dMdESBIk2YnNpcpDCnLne';
update content_bodies set title = 'Guest House ROKUBANZAWA PV 2023', description = 'Guest House ROKUBANZAWA is located in a remote area, surrounded by a 2-kilometer radius with no nearby houses, situated at the edge of the Kiritappu Wetland.' where id = '18lMH8Lz8Rg07GahepEkZ';
update content_bodies set title = '阿寒摩周・釧路湿原をめぐるBIKE＆CAMPツアー', description = '「第６回日本国際観光映像祭」に入選した阿寒観光ハイヤー提供の「阿寒摩周・釧路湿原をめぐるBIKE＆CAMPツアー」のプロモーション映像です。このツアーでは、E-BIKE（電動アシスト付き自転車）を利用して阿寒摩周国立公園と釧路湿原国立公園を巡ります。宿泊は国立公園内のキャンプ場で、テントの設営や撤去はスタッフが行うため、参加者はリラックスしてキャンプを楽しむことができます。翌日は釧路湿原でカヌーを楽しんだ後、釧路川沿いを自転車で走り、幣舞橋を目指します。東北海道の2つの国立公園を快適に巡る新しい自転車旅で、北海道の美しい自然の映像も楽しめます。' where id = 'EClH9w-gc4gWF1r4VHQ68';
update content_bodies set title = 'Akan Mashu and Kushiro Wetland Bike & Camp Tour', description = 'This promotional video showcases the ''Akan Mashu and Kushiro Wetland Bike & Camp Tour'' provided by Akan Tourist Hire, which was selected for the 6th Japan International Tourism Film Festival. Participants will explore the Akan Mashu National Park and Kushiro Wetland National Park using E-Bikes (electric assist bicycles), with camping accommodations at national park campsites. Staff will set up and take down the tents, allowing guests to enjoy a relaxed camping experience. The following day includes canoeing in the Kushiro Wetland, followed by a bike ride along the Kushiro River to the goal at the Chiebai Bridge. This is a comfortable and new cycling journey through two national parks in eastern Hokkaido, complemented by beautiful visuals of Hokkaido''s great nature.' where id = '_XXbdf1JM84bXRJcjmU-3';
update content_bodies set title = '「風と土のナベタカ」霧多布湿原サンセットカヌー PV', description = '現役漁師でカヌーガイドの「風と土のナベタカ」が、霧多布湿原の琵琶瀬川でサンセットカヌーを提供します。夕焼けを映す水面をゆっくり漂うカヌーの上で、鳥になった気分を味わいながら、空からの美しい映像を楽しむことができます。' where id = 'CjbPff1gjL4Msvgg6MLol';
update content_bodies set title = 'Sunset Canoe at Kirita Wetland - Nabeta Ka', description = 'Nabeta Ka, an active fisherman and canoe guide, offers a sunset canoe experience on the Biwase River in the Kirita Wetland. Enjoy the serene atmosphere as the canoe drifts slowly over the water reflecting the sunset. Experience the feeling of being a bird and take in the aerial views.' where id = 'CgrW9wCcsmZmxIZ5Dqkn3';
update content_bodies set title = '2017 11 魔女のサンセットカヌー', description = '霧多布湿原を流れる琵琶瀬川で行われた「サンセットカヌー」では、美しい夕日と水面に映る幻想的な風景の中でカヌーが漂う様子を楽しむことができます。魔女たちと共に、心癒されるひとときをお過ごしください。' where id = 'piFBPZP8DRtHRT694MRY-';
update content_bodies set title = '2017 11 Witch''s Sunset Canoe', description = 'Enjoy the beautiful images of canoes drifting on the serene surface of the Biwase River in the Misty Cape Wetlands during the ''Sunset Canoe'' event. The stunning sunset and the mirror-like water create a magical atmosphere with the witches.' where id = 'EeEba3l6bj5e_tl0Fj64B';
update content_bodies set title = '歴史・科学・自然が融合するまち肝付町をたっぷり巡る旅', description = '鹿児島県の大隅半島東側に位置する肝付町は、中央に標高900m級の肝属山系があり、町土の9割が山林で占められた自然豊かな地域です。神話が息づく伝承の地でありながら、ロケットが飛び立つ宇宙科学の最前線でもあります。真矢ミキさんが案内するこの旅では、肝付町の魅力をたっぷりと感じることができ、過去、現在、未来を一度に体験することができます。' where id = '2r1bLgYDGVRMn_737nnLS';
update content_bodies set title = 'A Journey Through Kimotsuki Town, Where History, Science, and Nature Converge', description = 'Located on the eastern side of the Osumi Peninsula in Kagoshima Prefecture, Kimotsuki Town is rich in nature, with 90% of its land covered by forests and the 900-meter-high Kimotsuki mountain range at its center. This town is a place where ancient myths and legends thrive, while also being at the forefront of space science with rocket launches. Miki Maya guides viewers on a journey to explore the charm of Kimotsuki Town, where one can experience the past, present, and future all at once.' where id = 'fhGIDIr_L8vAkZHlF-PZf';
update content_bodies set title = '山口紗弥加｜宮崎県川南町でゆるふわ春旅【旅色Movie】', description = '宮崎県中央部の海岸沿いに位置する川南町は、自然豊かで、東に日向灘、西に九州山地を抱える地域です。全国有数の食料生産基地であり、絶好のサーフスポットもあるため、移住者が多いとされています。町を訪れた山口紗弥加さんは、名物に感動し、お土産をたくさん購入し、いずれは「移住したい」と語るほどの魅力を感じていました。山口さんは1980年2月14日生まれで、福岡県出身。ドラマ『若者のすべて』で女優デビューし、幅広い役を演じる実力派として知られています。2018年には『ブラックスキャンダル』で連続ドラマ初主演を果たし、その後も『絶対正義』や『モトカレマニア』などの話題作に出演。2020年4月24日公開予定の映画『糸』にも出演しています。' where id = 'mQANompmaToap88kyvN4-';
update content_bodies set title = 'Sayaka Yamaguchi | Relaxing Spring Trip in Kawaminami Town, Miyazaki Prefecture【Tabiiro Movie】', description = 'Kawaminami Town, located along the coast in central Miyazaki Prefecture, is rich in nature, bordered by the Hyuga-nada Sea to the east and the Kyushu Mountains to the west. It is one of Japan''s leading food production bases and is known for its excellent surfing spots, attracting many new residents. Sayaka Yamaguchi, who visited the town, was so impressed by the local specialties that she bought numerous souvenirs and expressed a desire to eventually move there. Yamaguchi, born on February 14, 1980, in Fukuoka Prefecture, made her acting debut in the drama ''Wakamono no Subete'' and has gained a reputation for her strong acting skills in various challenging roles. She starred in ''Black Scandal'' in 2018 and has continued to appear in popular dramas, including ''Zettai Seigi'' and ''Motokare Mania.'' She is also set to appear in the movie ''Ito,'' scheduled for release on April 24, 2020.' where id = 'yrj-MwE5P_O4Zh7AbdChs';
update content_bodies set title = '臼田あさ美｜鹿児島県大崎町でローカルな旅【旅色movie】', description = '大崎町は山や海、田園風景が広がり、自然を存分に感じられる場所です。地元の人々の息づかいを感じながら、暮らすように旅を楽しむことができます。女優の臼田あさ美さんがナビゲートし、「新平酒造」ではできたての焼酎を味わい、「肉のたかしや」ではブランド牛・大崎牛を堪能します。また、大崎海岸では競走馬が走る圧巻の光景も楽しめます。地元の人々とのふれあいを通じて、忙しい日常では味わえないゆったりとした時間を臼田さんと共に楽しむことができます。' where id = '_dPJL08LKZe3W9PkZLqxZ';
update content_bodies set title = 'Asami Usuda | A Local Journey in Osaki Town, Kagoshima Prefecture [Tabiiro Movie]', description = 'Osaki Town offers a rich experience of nature, featuring mountains, the sea, and rural landscapes. Visitors can enjoy a leisurely travel experience, feeling the presence of local residents. Actress Asami Usuda guides the journey, where she visits ''Shinpei Shuzou'' to taste freshly made shochu, and ''Niku no Takashiya'' to savor the renowned Osaki beef. The stunning sight of racehorses running along Osaki Beach is also a highlight. This trip allows for interaction with locals and the enjoyment of a relaxed pace, providing a refreshing escape from busy daily life.' where id = '7amrU5gAHy2ECql5i4aZl';
update content_bodies set title = '西田尚美さんがゆるっと島旅｜鹿児島県 長島町＜旅色＞60秒ver', description = 'ナチュラルな雰囲気が魅力の西田尚美さんが、鹿児島県の最北端に位置する長島町を訪れる旅ムービーです。美しい海風景に感嘆し、名物を味わい、フォトジェニックな花園も訪れます。彼女の素敵な島旅の様子は、素顔も垣間見え、一緒に旅をしているような感覚を与えます。見るだけで心が癒される特別なムービーです。' where id = '-P1JWrBEbCCslcT_9g4u0';
update content_bodies set title = 'Naomi Nishida''s Relaxed Island Trip | Nagashima Town, Kagoshima Prefecture <Travel Color> 60-second version', description = 'This 60-second travel movie features Naomi Nishida, who has a natural charm, visiting Nagashima Town, located at the northernmost tip of Kagoshima Prefecture. She marvels at the beautiful coastal scenery surrounding the islands, enjoys local delicacies, and visits a photogenic flower garden. The film captures her delightful island journey, offering glimpses of her true self, making viewers feel as if they are traveling alongside her. It''s a special movie that soothes the heart just by watching.' where id = 'MPztSf8Su9-V2sKo9jjCL';
update content_bodies set title = '森泉｜歩くたびに惚れ惚れする 芸術のあるまち 湧水町へ【旅色Movie】', description = '湧水町は、その名の通り、豊富な湧き水が自慢の町です。雄大な自然と調和したアート作品が点在し、乗馬やパラグライダーなどのアクティビティも楽しめます。森泉さんと共に、1泊2日の旅で町の魅力を全力で体験します。旅のプランには、「霧島アートの森」での芸術体験や、「霧島アート牧場」でのホーストレッキング、561段と555段の「枕木階段」への挑戦、「魚野テイクオフ場」でのパラグライダー体験、「里山の麺処と和布あそびあら木」でのアーモンドラーメンの試食、そして「丸池湧水」での自然の癒しが含まれています。' where id = '3nj_GR4mdT0YQyRiNX815';
update content_bodies set title = 'Mori Izumi | A Journey to Yusui Town, a Place of Art That Captivates with Every Step【Tabiiro Movie】', description = 'Yusui Town, true to its name, boasts abundant spring water. Visitors can enjoy a harmonious blend of magnificent nature and art, along with activities such as horseback riding and paragliding. Join Mori Izumi on a one-night, two-day adventure where she fully embraces all the experiences the town has to offer. The itinerary includes visiting the Kirishima Art Forest, enjoying horse trekking at Kirishima Art Ranch, challenging the 561-step and 555-step ''Makuragi Stairs'', experiencing paragliding at the Ueno Takeoff Point, tasting almond ramen at Satoyama Noodle Shop, and finding relaxation at Maruike Spring Water.' where id = 'stq1XbFWyyVpHSloeUz-a';
update content_bodies set title = '西田尚美｜鹿児島県長島町 ゆるっと潮風トリップ【旅色Movie】', description = 'ナチュラルな雰囲気が魅力の西田尚美さんが、鹿児島県の最北端に位置する長島町を訪れる旅ムービーです。美しい海風景に感嘆し、名物を味わい、フォトジェニックな花園も訪れます。素敵な島旅を楽しむ様子は、彼女の素顔も垣間見え、一緒に旅をしているような感覚を与えます。見るだけで心が癒される特別なムービーです。' where id = '4I55U355TSvBPlQmYW7xQ';
update content_bodies set title = 'Naomi Nishida | Nagashima Town, Kagoshima Prefecture - Relaxing Seaside Trip [Tabiiro Movie]', description = 'This travel movie features Naomi Nishida, who embodies a natural charm, as she visits Nagashima Town, located at the northernmost tip of Kagoshima Prefecture. The film showcases the stunning coastal scenery of the islands, where she enjoys local delicacies and visits picturesque flower gardens. Her delightful island journey offers glimpses of her true self, making viewers feel as if they are traveling alongside her. This special movie is sure to soothe the heart.' where id = 'xI8ReRNo5-PEiS73-hWQy';
update content_bodies set title = '葵わかな｜創造的に、進化するまち。 熊本県 益城町へ【旅色Movie】', description = '葵わかなさんが訪れたのは、四季折々の自然に囲まれた益城町です。彼女は旅を通じて「緑がたくさんあるのが印象的でした」と感じました。この旅は、自然の重みと復興に向けた前向きな“創造”を体感できる学びと遊びの時間です。訪れた場所には、国指定天然記念物の「布田川断層地帯」、自然の力を感じる潮井水源、復興まちづくりセンター「にじいろ」、麦わらの一味コックのサンジ像、オシャレなコンテナ施設「BOX PARK マシキラリ」、癒しのカフェ「ミモザ」、有機栽培の「グレープガーデン益城」でのぶどう狩りなどがあります。' where id = '9zSboCg2Krh3HxqHlg5Dz';
update content_bodies set title = 'Wakana Aoi | A Creative and Evolving Town: Mashiki Town, Kumamoto Prefecture [Tabiiro Movie]', description = 'In this travel feature, Wakana Aoi visits Mashiki Town, surrounded by rich nature that changes with the seasons. She notes the impressive greenery throughout her journey. The trip offers a blend of learning and play, highlighting the weight of nature and the positive ''creation'' towards recovery. Key locations include the nationally designated natural monument ''Futagawa Fault Zone,'' the powerful Chioi Spring, the ''Nijiiro'' recovery town development center, a statue of Sanji from ''One Piece,'' the stylish container facility ''BOX PARK Mashikirari,'' a relaxing café called ''Mimosa,'' and organic grape picking at ''Grape Garden Mashiki.''' where id = 'KwEj6Jaq0vnEF-7PzDOWe';
update content_bodies set title = '肝付町のツアー', description = '肝付町は鹿児島県の大隅半島の東部に位置し、町の中心には標高900メートルの肝付山脈があります。自然が豊かで、町の90％は山や森林に占められています。古代の伝統や伝説が息づく場所であり、最先端の宇宙科学の拠点でもあり、ロケットが打ち上げられる場所でもあります。ミキ・マヤが肝付町の魅力的な旅にあなたを案内し、過去、現在、未来を同時に感じることができる場所を紹介します。' where id = '-Whhu9t21s7NV5TIyVN2_';
update content_bodies set title = 'A tour of Kimotsuki town in Japan', description = 'Kimotsuki town is situated in the eastern part of the Osumi peninsula in Kagoshima prefecture, featuring the Kimotsuki mountain range that rises 900 meters above sea level. The town is rich in natural beauty, with 90% of its area covered by mountains and forests. It is a unique blend of ancient traditions and modern space science, being home to a rocket launch site. Miki Maya invites you to explore Kimotsuki town, where you can experience the intertwining of history, contemporary life, and future advancements.' where id = 'IN9kYTT4lHMUhiYCBM_oI';
update content_bodies set title = '肝付町のツアー', description = '肝付町は鹿児島県の大隅半島の東部に位置し、町の中心には標高900メートルの肝付山脈があります。自然が豊かで、町の90％は山や森林に占められています。古代の伝統や伝説が息づく場所であり、最先端の宇宙科学の拠点でもあり、ロケットが打ち上げられる場所でもあります。ミキ・マヤが肝付町の魅力的な旅にあなたを案内し、過去、現在、未来を同時に感じることができる場所を紹介します。' where id = 'i1dq9Eo0W5vVXfRxtfJ2R';
update content_bodies set title = 'A tour of Kimotsuki town in Japan', description = 'Kimotsuki town is situated in the eastern part of the Osumi peninsula in Kagoshima prefecture, featuring the Kimotsuki mountain range that rises 900 meters above sea level. The town is rich in natural beauty, with 90% of its area covered by mountains and forests. It is a unique blend of ancient traditions and modern space science, being home to a rocket launch site. Miki Maya invites you to explore Kimotsuki town, where you can experience the intertwining of history, contemporary life, and future advancements.' where id = 'DzLIXIV3Pav3lvNfmPvjg';
update content_bodies set title = '長濱ねる｜ただいま。大分・佐伯の旅【旅色Movie】', description = '長濱ねるさんが九州で最も面積が大きい大分県佐伯市を1泊2日で巡る旅に出ます。海や山、城下町など多彩な景観が魅力で、2日間では回りきれないほどの見どころが満載です。佐伯市のビュースポットを訪れ、美味しい料理を楽しむ様子が描かれ、つかの間の癒しの旅を通じて、穏やかな素顔が垣間見えます。' where id = '3ncHQdH0TsN-xgX3-gMu0';
update content_bodies set title = 'Neru Nagahama | Welcome Back. A Trip to Saiki, Oita【Tabiiro Movie】', description = 'Neru Nagahama embarks on a 1-night, 2-day journey through Saiki City in Oita Prefecture, the largest city in Kyushu. The area boasts diverse landscapes, including mountains, the sea, and a castle town, offering an abundance of attractions that cannot be fully explored in just two days. The travel movie showcases various scenic spots in Saiki City and indulges in delicious local cuisine, providing a brief escape and revealing Nagahama''s gentle personality.' where id = 'NttoewbH0qZ_SeCUb02c_';
update content_bodies set title = '足立梨花｜種子島の玄関口 西之表市でゆるり、旅時間。', description = '足立梨花さんが訪れたのは、種子島の“玄関口”ともいわれる西之表市です。空と海が織りなす美しいブルーのコントラストや、自生植物と太陽光が作り出す景観は、まさに自然の宝箱です。彼女は種子島の歴史や文化に触れながら、地元の海の幸を楽しむランチや、日本初の「ヨガの聖地」でのヨガ体験を満喫しました。旅の中では、「赤尾木城文化伝承館月窓亭」や「種子島開発総合センター鉄砲館」などの文化的なスポットを訪れ、ヘゴ自生群落や浦田海水浴場での撮影も楽しみました。' where id = 'L6M-newB8KOIZVJXIhxeX';
update content_bodies set title = 'Rika Adachi | Relaxing Travel Time in Nishinoomote City, the Gateway to Tanegashima', description = 'Rika Adachi visits Nishinoomote City, known as the ''gateway'' to Tanegashima. The stunning contrast of blue skies and ocean, along with beautiful landscapes created by native plants and sunlight, make it a true treasure of nature. She explores the history and culture of Tanegashima while enjoying the local seafood for lunch and experiencing yoga at Japan''s first ''sacred place for yoga.'' The journey includes stops at various cultural sites, such as the Akakoki Castle Cultural Heritage Center and the Tanegashima Development Comprehensive Center, as well as a visit to the He-go self-growing area and the Uratada Beach for picturesque photography.' where id = 'DidSze-Z5YmFHhUkpVvYh';
update content_bodies set title = '矢田亜希子｜福岡のガーデンシティ 春日市のおいしい旅時間【旅色Movie】', description = '矢田亜希子さんが「食べるのが大好き」と語るこの旅では、彼女の魅力的な笑顔と食への情熱が伝わってきます。春日市でのグルメ旅では、手打ちパスタランチを楽しむ「La Lucon」、白水大池公園で味わうドーナツ、焼鳥居酒屋ウエスタンでのもつ鍋、春日公園でのスムージー、そしてミシュラン1つ星の「菊鮨」での贅沢ランチと、様々なおいしいものを堪能します。' where id = '7INDq-88LKIao7rUFADQf';
update content_bodies set title = 'Akiko Yada | Delicious Travel Time in Kasuga City, Fukuoka【Tabiiro Movie】', description = 'In this delightful travel segment, Akiko Yada shares her love for food with a charming smile. Her enthusiasm for gourmet experiences shines through as she selects donuts and engages passionately with shop owners. The journey takes viewers through Kasuga City, where Akiko indulges in various culinary delights, including handmade pasta at ''La Lucon,'' takeout donuts from ''Okashi no Kikai Kobo Tech'' enjoyed at Shirakawa Oike Park, a hearty meal of motsunabe at ''Yakitori Izakaya Western,'' refreshing smoothies from ''Blue Roof Kasuga Park,'' and a luxurious lunch at the Michelin-starred ''Kikusushi.''' where id = 'syQ_qbpLB37I4ZCedDZMi';
update content_bodies set title = '堀田真由｜福岡県・糸田町でほっとする旅【旅色Movie】', description = '糸田町は、初めて訪れる人にもふるさとのように優しく、リラックスした旅にぴったりの場所です。堀田真由さんがこの町の魅力を巡り、自然や歴史、グルメなど多彩な体験を紹介します。動画では、堀田さんにとって特別なスポットが登場し、新烏尾公園を散策したり、泌泉で涼んだり、糸田ふれあい市でおかつバーガーを味わったり、糸田城址で思いを馳せたり、無双窯元で陶芸体験をしたり、筑豊極ホルモンしんかいで美味しい料理を楽しんだり、金山サクラ・アジサイ園で色とりどりのアジサイを堪能したりします。' where id = 'Hwk5xFEdspv_6MKUlO1sH';
update content_bodies set title = 'Mayu Hotta | A Relaxing Trip in Itoda Town, Fukuoka Prefecture【Tabiiro Movie】', description = 'Itoda Town, a place that feels like a familiar hometown even for first-time visitors, is perfect for a relaxing journey. Mayu Hotta explores the town''s abundant attractions, including nature, history, and gourmet experiences. The video features various spots that hold significance for her, such as Shin Karasuo Park, where she strolls, and Takigiri, where she cools off. She also tastes the Okatsu Burger at Itoda Fureai Market, reflects at the Itoda Castle Ruins, experiences pottery at Muso Kiln, enjoys delicious food at Chikuho Goku Hormone Shinkai, and admires the colorful hydrangeas at Kanayama Sakura and Hydrangea Garden.' where id = 'XPpQWB3IR6FTmtcilCybE';
update content_bodies set title = '南沙良｜熊本の南小国町・黒川温泉を巡る旅', description = '南沙良さんと共に、熊本・南小国町の美しい自然と温泉を巡る旅に出かけます。360度のパノラマ絶景に圧倒され、情緒ある温泉街を散策しながら地元の美味しい食べ物を楽しむ様子が描かれています。動画では、黒川温泉の散策や「風の舎」での入湯手形購入、馬肉メンチカツを味わう「湯音」、神秘的な「夫婦滝」、リラックスできる「茶菓房　林檎の樹」、ゴーカートを楽しむ「瀬の本レストハウス」、阿蘇五岳を一望できる「押戸石の丘」など、様々な見どころが紹介されています。南さんと一緒に旅する気分を味わってください。' where id = 'wLgy59UARJ-9fISRD_DT3';
update content_bodies set title = 'Minami Sara''s Journey Through Kumamoto''s Minamioguni Town and Kurokawa Onsen', description = 'Join Minami Sara on a journey through the beautiful nature and hot springs of Kumamoto''s Minamioguni Town. Experience breathtaking 360-degree panoramic views and enjoy strolling through the charming hot spring town while sampling local delicacies. The video captures various highlights, including exploring Kurokawa Onsen, purchasing a hot spring pass at ''Kaze no Sha,'' tasting horse meat croquettes at ''Yune,'' admiring the mystical atmosphere of ''Fufu Falls,'' relaxing at ''Chakabou Ringo no Ki,'' driving go-karts at ''Senomoto Rest House,'' and enjoying a panoramic view of the Aso Five Peaks from ''Oshido Stone Hill.'' Immerse yourself in the travel experience alongside Minami Sara.' where id = 'wSGLVFPWXV8W06ypGSwev';
update content_bodies set title = '玉城ティナ｜薩摩川内市まち巡り【旅色Movie】', description = '玉城ティナさんが鹿児島県薩摩川内市を旅するスペシャルムービーです。薩摩川内市は、心が洗われるような澄んだ空気に包まれ、自然豊かで山海の幸をたっぷり楽しむことができます。ティナさんと共に、自然やグルメ、温泉、歴史を楽しむ欲張りな旅に出かけました。ムービーでは、限定ランチやお土産購入、歴史体験、農場見学、海の幸を満喫する様子が紹介されています。' where id = '_ZLc2Tj_vhBtKx7U9v9Ze';
update content_bodies set title = 'Tina Tamashiro | Exploring Satsumasendai City [Tabiiro Movie]', description = 'This special movie features Tina Tamashiro traveling in Satsumasendai City, Kagoshima Prefecture. The city is enveloped in refreshing air that feels like a cleansing experience. It is rich in nature and offers an abundance of local delicacies from both land and sea. The journey with Tina includes enjoying nature, gourmet food, hot springs, and history, making it a fulfilling travel experience.' where id = 'xYf7DqmIB2YuS1FwERotF';
update content_bodies set title = 'トリンドル玲奈｜心くすぐる無人島の旅へ 宮崎県・門川町の物語 60秒Ver', description = '温暖な気候と雄大な日向灘、緑豊かな山々が広がる門川町は、静かでのんびりとした雰囲気が漂っています。ここでは人も自然もゆったりとした時間を過ごし、浜辺や町を歩くと時間を忘れてしまいます。女優のトリンドル玲奈さんと共に、そんな門川町の魅力を発見する旅に出かけました。' where id = 'QODmQ_MoFfTjM1n17gwYw';
update content_bodies set title = 'Reina Trindl''s Heartwarming Journey to a Deserted Island: A Story from Kadogawa Town, Miyazaki Prefecture - 60 Seconds Version', description = 'In the serene and majestic Hyuga-nada, with its warm climate and lush green mountains, Kadogawa Town offers a tranquil escape where both people and nature seem to take their time. Walking along the beach and through the town, one can easily lose track of time. Actress Reina Trindl embarks on a journey to discover the charms of Kadogawa, a place that beautifully complements nature.' where id = '6RtH3QUxOo4KQ-YKoT82i';
update content_bodies set title = 'トリンドル玲奈｜心くすぐる無人島の旅へ　宮崎県・門川町の物語', description = '宮崎県の門川町は、温暖な気候と雄大な日向灘、緑豊かな山々に囲まれた静かな場所です。女優のトリンドル玲奈さんと共に、そんな門川町の魅力を発見する旅に出かけました。旅では、無人島「乙島」への船旅や、地元の旬を楽しむ「とんぼ」での食事、日本唯一のビー玉工場「松野工業」訪問、そして「今日のおやつ!ノーブル!」でのひと息を楽しむ様子が描かれています。' where id = 'uJQvDVDM6DtajZ0j8i9BI';
update content_bodies set title = 'Reina Triendl | A Heartwarming Journey to an Uninhabited Island: The Story of Kadogawa Town, Miyazaki Prefecture', description = 'In the serene and warm Kadogawa Town, located by the beautiful Hyuga Sea, actress Reina Triendl embarks on a journey to discover the town''s charm. The area is characterized by its stunning natural scenery, where both people and nature exude a relaxed atmosphere. The journey includes a short boat ride to the uninhabited island of Oshima, enjoying local seasonal delicacies at a restaurant called ''Tonbo'', visiting Japan''s only marble factory, Matsuno Industry, and concluding the trip with a sweet treat at ''Noble''.' where id = 'G7EAfc-QNkkXjPcLCGyqi';
update content_bodies set title = '上白石萌歌｜奥薩摩・伊佐のふわり旅日和【旅色Movie】', description = '伊佐市は鹿児島県本土の最北地に位置し、川内川などの清流に囲まれた美しい自然景観が魅力です。寒暖差が激しい盆地後系で、2020年の最低気温はマイナス6.4℃、最高平均気温は37.6℃と気温差が明確です。この環境が豊かな食文化を育み、「薩摩の米蔵」としても知られています。また、「曽木の滝」と呼ばれる東洋のナイアガラや、5月から9月にしか姿を現さない曽木発電所遺構など、歴史的な魅力も詰まった町です。自然、食、カルチャーが多彩に揃う伊佐市の旅に出かけてみませんか。' where id = 'g9U3vcKRjXAVAVIrmFMt7';
update content_bodies set title = 'Moka Kamishiraishi | A Gentle Journey in Okusatsuma, Isa【Tabiiro Movie】', description = 'Isa City is located in the northernmost part of Kagoshima Prefecture. Surrounded by clear streams like the Sendai River, it boasts beautiful natural scenery. The region experiences significant temperature variations, with a record low of -6.4°C in December 2020 and an average high of 37.6°C in August. This environment fosters a rich food culture, earning it the nickname ''Satsuma''s Rice Storehouse.'' The city is also home to historical attractions such as the ''Sogi Falls,'' known as the ''Niagara of the East,'' and the ''Sogi Power Plant Ruins,'' which only appear from May to September. Come explore the diverse charms of Isa City, filled with nature, food, and culture.' where id = 'MAkeVh3czZX_7GNOD_BeG';
update content_bodies set title = '藤原紀香｜癒しの旅に出よう 鹿児島県 徳之島町へ', description = '藤原紀香さんと共に、南国ムード漂う絶景スポットや美食が楽しめる徳之島町を巡ります。徳之島町は、日々の忙しさを忘れさせてくれる大自然に囲まれた場所で、リフレッシュに最適な旅先です。旅のプランには、「金見崎ソテツトンネル」の散策や、「金見崎展望台」からのパノラマビュー、「Cafe Ohana」での絶景ランチ、夜光貝磨き体験、そして「畦プリスビーチ」での徳之島ブルーを満喫する内容が含まれています。' where id = 'MXss6Mt_7JaXftoKpiQ7H';
update content_bodies set title = 'Norika Fujiwara | Let''s Go on a Healing Journey to Tokunoshima Town, Kagoshima Prefecture', description = 'Join Norika Fujiwara as she explores the breathtaking spots and culinary delights of Tokunoshima Town, a place where the tropical atmosphere and stunning nature provide a perfect escape from daily hustle and bustle. This refreshing journey allows visitors to unwind and rejuvenate in the serene environment of Tokunoshima. The itinerary includes a stroll through the Kanmimizaki Sago Palm Tunnel, panoramic views from the Kanmimizaki Observatory, a scenic lunch at Cafe Ohana, a night shell polishing experience, and a visit to Azekurisu Beach to enjoy the beautiful Tokunoshima blue.' where id = '-xyXpvZG8qdfihRkETRz5';
update content_bodies set title = '溝端淳平｜爽やかな水と歴史あるまち並みが残る場所いざ、知られざる松江へ【旅色Movie】', description = '溝端淳平さんが旅したのは島根県松江市で、国宝松江城天守を見学したり、文豪小泉八雲の旧居を訪れたりといった歴史探訪を楽しみます。また、120年以上の歴史を持つ米田酒造での日本酒の飲み比べや、海上アクティビティなど、松江市ならではの水に関連した体験も満喫できます。知られざる松江の魅力を探る旅に出かけましょう。' where id = 'pgrJTFlV2qMc4-vGsiNNt';
update content_bodies set title = 'Junpei Mizobata | Discover the Hidden Charm of Matsue, a City with Refreshing Water and Historic Streets【Tabiiro Movie】', description = 'Junpei Mizobata travels to Matsue City in Shimane Prefecture, where he explores historical sites such as the National Treasure Matsue Castle and the former residence of the famous author Lafcadio Hearn. The journey also includes unique experiences like sake tasting at a 120-year-old sake brewery and engaging in water activities, showcasing the rich water resources of Matsue. Join him in discovering the hidden attractions of this charming city.' where id = 'Y_41Ck1plRmX33674WtcQ';
update content_bodies set title = '中村 蒼｜歴史の舞台を訪ね歩く 岡山市タイムトリップ', description = '俳優の中村蒼さんが訪れた岡山市は、岡山桃太郎空港から車で約40分の場所にあり、晴れの日が多い「晴れの国」として知られています。彼は戦国時代から江戸時代の史跡を巡り、美しい風景や岡山ならではのグルメを堪能しました。旅のハイライトには、備中高松城址の散策、吉備津神社での景観美の鑑賞、桃太郎伝説に関連する吉備津彦神社への参拝、岡山の郷土料理を楽しむ福寿司、岡山城の歴史を学ぶこと、旭川遊覧クルーズでの優雅な時間、酒工房独歩館でのお土産選びが含まれています。' where id = 'SoV78tRAtsvTbFf7CuotC';
update content_bodies set title = 'Aoi Nakamura | Exploring Historical Sites in Okayama City - Time Trip', description = 'Actor Aoi Nakamura visits Okayama City, located about 40 minutes by car from Okayama Momotaro Airport, known for its sunny weather and historical significance. The journey includes exploring sites from the Sengoku to Edo periods, enjoying beautiful landscapes, and tasting local delicacies unique to Okayama. Highlights of the trip include walking through the ruins of Bichu Takamatsu Castle, appreciating the beauty of Kibitsu Shrine, visiting Kibitsuhiko Shrine related to the Momotaro legend, savoring Okayama''s local cuisine at Fukuzushi, learning about Okayama Castle''s historical importance, enjoying a cruise on the Asahi River, and selecting souvenirs at the Doppokan sake brewery.' where id = '3Mrc__Y_6P0LWS6Bbw0Zd';
update content_bodies set title = '安斉星来｜日本の秘境を新発見 岡山・新見市で“自然ステイ”【旅色Movie】', description = '安斉星来さんが岡山県新見市で1泊2日の旅を楽しみます。旅では、200以上の鍾乳洞や300種の珍しい植物が自生する湿原を散策し、特産グルメを味わいます。また、森に囲まれたグランピング施設や美肌の湯が自慢の天然温泉でリラックスし、自然の恵みを多様な形で体験します。' where id = 'HB2rk6Eif8-_cL1xR62Wc';
update content_bodies set title = 'Seira Anzai Discovers Japan''s Hidden Gems: Nature Stay in Niimi City, Okayama', description = 'Seira Anzai embarks on a two-day trip to Niimi City, Okayama, where she explores over 200 caves and a wetland home to 300 unique plant species. The journey includes tasting local gourmet specialties, relaxing in a glamping facility surrounded by forests, and enjoying a natural hot spring. The trip showcases the diverse blessings of nature in various forms, from breathtaking landscapes to culinary delights.' where id = '107Djsyxibc-ZDrB4Se58';
update content_bodies set title = '比嘉愛未｜広島・竹原を巡るさんぽ旅【旅色Movie】', description = '比嘉愛未さんと映画『吟ずる者たち』のロケ地である広島・竹原を巡る旅を楽しむ内容です。レトロな街並みを散策し、野生のうさぎに出会う様子が描かれています。旅のプランには、カフェホクストンでのブランチ、大久野島（うさぎ島）訪問、うさぎのはなくソフトクリームを食べながらの散策、たけはら町並み保存地区の散策、竹工房での竹細工づくり、藤井酒造での試飲が含まれています。' where id = 'vPJ3rTZlM98oN0iecTxwA';
update content_bodies set title = 'Manami Higa''s Walking Tour in Takehara, Hiroshima | Tabiiro Movie', description = 'Join Manami Higa on a journey through Takehara, Hiroshima, a filming location for the movie ''Ginzuru Monotachi.'' Experience the charm of retro streets, encounter wild rabbits, and enjoy the trip as if you were with her. The itinerary includes brunch at Cafe Hoxton, a visit to Okunoshima (Rabbit Island) to see adorable rabbits, tasting ''Rabbit''s Nose Soft Serve'' while exploring, walking through the picturesque Takehara Townscape Preservation District, making bamboo crafts at Takehara Machinami Bamboo Workshop, and sampling sake at Fujii Sake Brewery Exchange Hall.' where id = 'lxwcpdNO8jk_qWqhOGPAM';
update content_bodies set title = '宇和島を巡る', description = 'この動画は宇和島を巡ることについて紹介しています。宇和島の魅力や観光スポットを訪れる様子が描かれており、地域の文化や歴史にも触れています。視聴者は、宇和島の美しい風景や地元の特産品を楽しむことができる内容となっています。' where id = '3M0ReQPSogEWn7E76YQWR';
update content_bodies set title = 'Exploring Uwajima', description = 'This video introduces the exploration of Uwajima.' where id = 'jxRpNClXsHQ3iiHbf7aLD';
update content_bodies set title = '南沙良｜境港市（鳥取）でときめきの旅【旅色Movie】', description = '女優の南沙良さんが鳥取県境港市でサイクリングをし、妖怪と出会い、港町のグルメを楽しむ旅ムービーです。境港市は涼しげな波音と磯の香りに包まれ、美保湾と雄大な大山の美しい景色が広がります。また、漫画家・水木しげる氏の出身地としても知られ、町の至る所で妖怪に出会うことができます。南沙良さんは爽やかな笑顔で、この不思議な魅力にあふれる町を旅しました。' where id = 'cjH2yrnN-RVm27ZR2NVz6';
update content_bodies set title = 'Nanasa Sera | A Heart-Pounding Journey in Sakaiminato City (Tottori)【Tabi-iro Movie】', description = 'In this travel movie, actress Nanasa Sera explores Sakaiminato City in Tottori Prefecture, engaging in cycling, encountering yokai, and enjoying the local gourmet offerings. The city is enveloped in the refreshing sounds of waves and the scent of the sea, showcasing the unique atmosphere of a port town. With beautiful views of Mihon Bay and the majestic Daisen mountain, Sakaiminato is also known as the hometown of manga artist Shigeru Mizuki, where visitors can meet various yokai throughout the town. Nanasa Sera embarks on this journey, capturing the town''s mysterious charm with her bright smile.' where id = 'FKUElTqqT5nQPhJcg4-mE';
update content_bodies set title = '南沙良｜境港市（鳥取）でときめきの旅 60秒ver【旅色Movie】', description = '女優の南沙良さんが鳥取県境港市でサイクリングを楽しみ、妖怪と出会い、港町のグルメを堪能する様子を60秒にまとめた旅ムービーです。美保湾と大山の美しい景色が広がる境港市は、漫画家・水木しげる氏の出身地としても知られ、町の至る所で妖怪に出会うことができます。爽やかな笑顔で、南沙良さんがこの不思議な魅力にあふれる町を旅する様子が描かれています。フルバージョンは、こちらからご覧いただけます→ https://youtu.be/pd3yDpooIo4' where id = 'JZokKl6-2x_gYsP4wXGsS';
update content_bodies set title = 'Minami Sara | A Heart-Pounding Journey in Sakaiminato City (Tottori) 60-Second Version [Tabiiro Movie]', description = 'In this 60-second travel movie, actress Minami Sara explores Sakaiminato City in Tottori Prefecture, enjoying cycling, encountering yokai, and savoring the local cuisine of this port town. The film captures the essence of Sakaiminato, known for its beautiful views of Mihon Bay and the majestic Daisen mountain, as well as its unique charm tied to the famous manga artist Shigeru Mizuki. With refreshing smiles, Minami Sara showcases the town''s mysterious allure. For the full version, visit: https://youtu.be/pd3yDpooIo4' where id = '6x88dZUQ7kerf8Q2IXzJ5';
update content_bodies set title = '【南沙良】境港市でときめきの旅｜鳥取県境港市＜旅色＞30秒ver.', description = '女優の南沙良さんが鳥取県境港市を訪れ、サイクリングや妖怪との出会い、港町のグルメを楽しむ様子を収めた30秒の旅ムービーです。美保湾と大山の美しい景色に囲まれたこの町は、漫画家・水木しげる氏の出身地としても知られ、町の至る所で妖怪に出会うことができます。波音と磯の香りに包まれた境港市の不思議な魅力を、爽やかな笑顔で南沙良さんが紹介しています。フルバージョンはリンクからご覧いただけます。' where id = 'lNr-m0OhatXeUtqj3FRTr';
update content_bodies set title = 'A Heartwarming Journey in Sakaiminato City | Tottori Prefecture', description = 'In this 30-second travel movie, actress Sara Minami explores Sakaiminato City in Tottori Prefecture, engaging in activities like cycling and encountering local yokai. The film captures the essence of this charming port town, known for its beautiful views of Mihon Bay and Mount Daisen, as well as its unique atmosphere filled with the sounds of waves and the scent of the sea. Sakaiminato is also famous as the hometown of manga artist Shigeru Mizuki, where visitors can meet various yokai throughout the town. With a refreshing smile, Sara Minami showcases the town''s mysterious allure. For a full version, visit the provided link.' where id = 'fp2_a5n8IdJgzlaIpSMNL';
update content_bodies set title = '新垣結衣が神々の宿る島へ【宮島・岩国】', description = '新垣結衣が素顔を垣間見せる旅ムービーで、瀬戸内海に浮かぶ神の島・宮島や、名橋・錦帯橋を有する情緒豊かな城下町・岩国を訪れます。宮島の大聖院ではぐち聞き地蔵に話しかけ、岩国の白蛇神社ではおみくじを引くなど、茶目っ気たっぷりに旅を楽しむ様子が描かれています。また、ファン必見の「ガッキーロス」をテーマにした特集もあり、彼女の8年の軌跡を振り返る内容となっています。' where id = 'UDlCJZSyZjW4EoSQIYvJ0';
update content_bodies set title = 'Yui Aragaki''s Trip to the Island of Gods: Miyajima & Iwakuni', description = 'This travel movie offers a glimpse into the real Yui Aragaki as she explores the sacred island of Miyajima, located in the Seto Inland Sea, and the charming castle town of Iwakuni, known for its famous Kintai Bridge. During her journey, she interacts with the ''Guchi Kiko Jizo'' at Daisho-in Temple in Miyajima and draws fortunes at the white snake shrine in Iwakuni, showcasing her playful spirit. This trip is a must-see for fans experiencing ''Gakki Loss,'' as it reflects on Yui Aragaki''s eight-year journey in the travel magazine ''Tabiiro.''' where id = 'm-5IOJvcS2LdJCxezeYEP';
update content_bodies set title = '筧美和子はわい温泉や東郷湖周辺を巡り町の魅力', description = '鳥取県のほぼ中央に位置する湯梨浜町は、豊かな自然に囲まれた町で、ウォーキングやグラウンド・ゴルフが楽しめます。東郷湖や温泉、歴史ある神社など、見所がたくさんあります。この動画では、筧美和子さんが風光明媚な湯梨浜町を巡り、その魅力を紹介します。町の観光資源をPRするための取り組みの一環として、湯梨浜町と観光協会の協力を得て制作されています。' where id = '3FmagFVhTjbDb515OI7-N';
update content_bodies set title = 'Miwa Kato Explores the Charms of Yurihama Town, Tottori Prefecture', description = 'Yurihama Town, located in the heart of Tottori Prefecture, offers a wealth of natural beauty, making it an ideal spot for walking and ground golf. The town is rich in attractions, including Togo Lake, hot springs, and historic shrines. In this video, Miwa Kato takes viewers on a tour of the picturesque Yurihama Town, showcasing its scenic landscapes and cultural highlights. The video is part of a promotional effort to highlight the town''s tourism potential, supported by the Yurihama Town and its tourism association.' where id = 'r6Z6mQ8kmGdXxaqEoRZCr';
update content_bodies set title = '筧美和子はわい温泉や東郷湖周辺を巡り町の魅力', description = '鳥取県のほぼ中央に位置する湯梨浜町は、豊かな自然に囲まれた町で、ウォーキングやグラウンド・ゴルフが楽しめます。東郷湖や温泉、歴史ある神社など、見所がたくさんあります。この動画では、筧美和子さんが湯梨浜町の風光明媚なスポットを巡り、その魅力を紹介します。湯梨浜町と湯梨浜町観光協会が協力しており、地域の宿泊施設や飲食店の情報も提供しています。' where id = 'GfdmK5kEMgFaJgmH8B6iU';
update content_bodies set title = 'Miwa Kato Explores the Charms of Yurihama Town, Tottori Prefecture', description = 'Yurihama Town, located in the heart of Tottori Prefecture, offers a rich natural environment perfect for walking and ground golf. The area is filled with attractions such as Lake Togo, hot springs, and historic shrines. In this video, Miwa Kato explores the scenic beauty of Yurihama Town, showcasing its various highlights. The town is supported by the Yurihama Town and the Yurihama Tourism Association, which provide information on local accommodations and dining options.' where id = 'X7qbf9b-4ZtFj8pe0vsz1';
update content_bodies set title = '筧美和子｜湯梨浜町（鳥取県）を自遊に歩く冬の旅', description = '鳥取県のほぼ中央に位置する湯梨浜町は、自然豊かな環境でウォーキングやグラウンド・ゴルフが楽しめる町です。東郷湖や温泉、歴史ある神社などの見所も多く、風光明媚なこの町を筧美和子さんが巡ります。動画記事には、湯梨浜町の公式サイトや観光協会のリンク、特別ムービーも紹介されています。' where id = 'AWiw5lZiUzkFPkWhAIqQi';
update content_bodies set title = 'Miwa Kato''s Winter Journey in Yurihama Town, Tottori Prefecture', description = 'Yurihama Town, located in the heart of Tottori Prefecture, offers a rich natural environment perfect for walking and ground golf. The town is filled with attractions such as Lake Togo, hot springs, and historic shrines. In this video, Miwa Kato explores the scenic beauty of Yurihama Town. The article includes links to the town''s official website and tourism association, as well as special movie versions showcasing the area.' where id = 'Q8qprGOOwuakeXuojATwH';
update content_bodies set title = '高橋メアリージュン｜松江市（鳥取県）を巡る旅 15秒Ver【旅色Movie】', description = '松江は宍道湖や中海に囲まれた水の都で、江戸初期の城郭が残る城下町です。藩主にゆかりのあるお茶や和菓子文化、伝説の占いの池、美肌の温泉など、豊かな自然と歴史を体験できる旅で、まるでご褒美のような時間を過ごせます。' where id = 'Cc0GjNoYqlRQ0Sb2be9cz';
update content_bodies set title = 'Maryjun Takahashi | A Journey Through Matsue City (Tottori Prefecture) 15-Second Version【Tabiiro Movie】', description = 'Matsue, a water city surrounded by Lake Shinji and Nakagawa, is a castle town with remnants from the early Edo period. The journey offers experiences of rich nature and history, including tea and wagashi culture linked to the feudal lord, a legendary fortune-telling pond, and beautiful skin hot springs, providing a rewarding time.' where id = 'MWdrROrwjnx93xH7lAZp1';
update content_bodies set title = '高橋メアリージュン｜松江市（島根県）を巡る旅', description = '松江は宍道湖や中海に囲まれた水の都で、江戸初期の城郭が残る城下町です。この旅では、藩主ゆかりのお茶や和菓子文化を楽しみ、伝説の占いの池や美肌の温泉を訪れることで、豊かな自然と歴史を体験します。松江観光協会や松江市の公式サイトで詳細情報を確認できます。高橋メアリージュンは1987年滋賀県生まれのモデル・女優で、ファッション誌『CanCam』の専属モデルとして活躍し、2012年には連続テレビ小説「純と愛」で女優デビューを果たしました。' where id = 's7jjOmOpxYS4RRNSFYKy0';
update content_bodies set title = 'Maryjun Takahashi''s Journey Through Matsue City, Shimane Prefecture', description = 'Matsue, a castle town surrounded by the waters of Lake Shinji and Nakatsu, offers a rich experience of nature and history. The journey includes exploring the cultural heritage linked to the feudal lords, enjoying traditional tea and sweets, and visiting the legendary fortune-telling pond and beautiful hot springs. This trip is a rewarding experience that showcases the unique charm of Matsue. For more information, visit the Matsue Tourism Association and Matsue City websites. Maryjun Takahashi, born in 1987 in Shiga Prefecture, is a model and actress known for her work in fashion magazines and television dramas. She made her acting debut in the 2012 NHK morning drama ''Jun to Ai'' and has since expanded her career in various media.' where id = '4uJtsSBbgCIkM4MYvH7BA';
update content_bodies set title = '片山友希｜愛媛県・西予市で全開リフレッシュ旅', description = '海抜0mの海辺から標高1,400mの山間地まで、変化に富んだ景観が魅力の西予市。俳優・片山友希さんが、歴史ある開明学校や懐かしい卯之町の町並みを訪れ、宇和米博物館での楽しいレース、田舎風割烹ちゃぼ亭での贅沢な午後、ギャラリーしろかわでのユニークなアート鑑賞、ギャラリー喫茶苔筵でのリラックスしたひととき、そして狩浜の段畑での深呼吸で旅を締めくくります。' where id = 'hUdUAbqWdA6tdfGTd10qR';
update content_bodies set title = 'Yuki Katayama | Refreshing Trip in Seiyo City, Ehime Prefecture', description = 'Seiyo City, with its diverse landscapes ranging from sea level to 1,400 meters in the mountains, offers breathtaking views and charming retro townscapes. In this travel feature, actor Yuki Katayama explores various attractions, including the historical Kaimei School and the nostalgic streets of Unomachi, a fun race at the Uwabekkan Museum, a luxurious afternoon at Chabo-tei, unique art at Gallery Shirokawa, a relaxing break at Koke-mura Café, and concludes with a refreshing breath at the terraced fields of Karihama.' where id = '_DU4QCJPwOAHxAZP7j89i';
update content_bodies set title = '【貫地谷しほり】麒麟のまち（鳥取・兵庫）を旅する＜旅色＞（30秒ver）', description = '鳥取県鳥取市、岩美町、若桜町、智頭町、八頭町、兵庫県新温泉町、香美町からなるこのエリアには、日本最大級の「鳥取砂丘」や美しい「浦富海岸」、滋味深い里山料理が楽しめる「みたき園」、のどかな「若桜鉄道」、1000年以上の歴史を持つ「湯村温泉」、そして鳥取の「民芸品」など、魅力的なスポットが点在しています。心と体を癒す旅に出かけましょう。' where id = 'Ax928UFCjBqZKi9at8LYR';
update content_bodies set title = 'Traveling in Kirin no Machi (Tottori and Hyogo) with Shihori Kanjiya', description = 'This area, comprising Tottori City, Iwami Town, Wakasa Town, Chizu Town, Yazu Town in Tottori Prefecture, and Shinonsen Town and Kami Town in Hyogo Prefecture, features stunning attractions such as the Tottori Sand Dunes, the breathtaking Uradome Coast, and the flavorful local cuisine at Mitaki-en. Visitors can enjoy a scenic train ride on the Wakasa Railway, relax in the historic Yumura Onsen, and explore traditional crafts unique to Tottori. This journey promises to heal both body and mind.' where id = '2fBOKjPBCxaK6UraoTNZa';
update content_bodies set title = '【貫地谷しほり】麒麟のまち（鳥取・兵庫）を旅する＜旅色＞（60秒ver）', description = '鳥取県鳥取市、岩美町、若桜町、智頭町、八頭町、兵庫県新温泉町、香美町からなるこのエリアには、日本最大級の「鳥取砂丘」や美しい「浦富海岸」、滋味深い里山料理が楽しめる「みたき園」、のどかな「若桜鉄道」、1000年以上の歴史を持つ「湯村温泉」、そして鳥取の「民芸品」など、魅力的なスポットが点在しています。心と体を癒す旅に出かけましょう。' where id = 'BU0cyI6lGkrQgkHUvZ6AS';
update content_bodies set title = 'Traveling in Kirin no Machi (Tottori and Hyogo) with Shihori Kanjiya', description = 'This area, comprising Tottori City, Iwami Town, Wakasa Town, Chizu Town, Yazu Town in Tottori Prefecture, and Shinonsen Town and Kami Town in Hyogo Prefecture, features stunning attractions such as the Tottori Sand Dunes, the breathtaking Uradome Coast, and the flavorful local cuisine at Mitaki-en. Visitors can enjoy a scenic train ride on the Wakasa Railway, relax in the historic Yumura Onsen, and explore traditional crafts unique to Tottori. This journey promises to heal both body and mind.' where id = 'G5Scj6H38jpzvZYMr6VJ8';
update content_bodies set title = '貫地谷しほり｜麒麟のまち（鳥取・兵庫）を旅する【旅色Movie】', description = '鳥取県鳥取市、岩美町、若桜町、智頭町、八頭町、兵庫県新温泉町、香美町からなるこのエリアには、日本最大級の「鳥取砂丘」や美しい「浦富海岸」などの絶景が広がっています。また、山間での滋味深い里山料理を楽しめる「みたき園」、のどかな鉄道旅ができる「若桜鉄道」、1000年以上の歴史を持つ「湯村温泉」、そして鳥取の手しごとが光る「民芸品」など、各地に魅力が満載です。心と体を癒す旅に出かけましょう。' where id = 'unpeQjRmfzZVvVuW9gqjB';
update content_bodies set title = 'Shihori Kanjiya | Traveling in Kirin no Machi (Tottori and Hyogo) [Tabiiro Movie]', description = 'This area, consisting of Tottori City, Iwami Town, Wakasa Town, Chizu Town, and Yazu Town in Tottori Prefecture, as well as Shinonsen Town and Kami Town in Hyogo Prefecture, features stunning landscapes such as the largest sand dunes in Japan, Tottori Sand Dunes, and the breathtaking Uradome Coast. Visitors can enjoy local mountain cuisine at Mitaki-en, take a scenic train ride on the Wakasa Railway, relax in the historic Yumura Onsen, and explore traditional crafts from Tottori. This journey promises to heal both the mind and body.' where id = 'dYvjYPGa04i7N8bLDbyBm';
update content_bodies set title = '【小倉優子】伝統の着物で、風情ある街並みをそぞろ歩き｜鳥取県倉吉市', description = '小倉優子さんが訪れた鳥取県中部の倉吉市は、かつて城下町として栄えた歴史ある場所です。赤瓦の屋根を持つ白壁の土蔵や商家が並ぶ中心部は、過去の面影を残し、情緒あふれる観光エリアとして人気を集めています。まるでタイムスリップしたかのような雰囲気が漂い、訪れる人々を魅了しています。倉吉のレトロトリップについての詳細は、リンクを参照してください。' where id = 'GNiBMhzu57BEzyDqG9jQP';
update content_bodies set title = 'Yuko Ogura Strolls Through the Scenic Streets in Traditional Kimono | Kurayoshi City, Tottori Prefecture', description = 'Yuko Ogura explores Kurayoshi City, located in central Tottori Prefecture, known for its historical charm as a former castle town. The city features picturesque streets lined with white-walled storehouses and red-tiled roofs, preserving the essence of a bygone era. This popular tourist area offers a nostalgic atmosphere, making it feel like a time slip. For more information on the retro trip in Kurayoshi, visit the provided links.' where id = 'SKZHJS3XMHGzbYNNQdeH4';
update content_bodies set title = '【小倉優子】伝統の着物で、風情ある街並みをそぞろ歩き｜鳥取県倉吉市＜旅色＞（60秒ver）', description = '鳥取県中部に位置する倉吉市は、かつて城下町として栄えた地域で、赤瓦の屋根と白壁の土蔵が並ぶ情緒ある観光エリアです。過去の面影を残し、まるでタイムスリップしたかのような雰囲気を楽しむことができます。小倉優子さんが見つけたこの旅のSNS映えスポットは、訪れる人々に新たな体験を提供します。詳細は、レトロトリップや特別ムービーのリンクを参照してください。' where id = 'fC2gBqP8kSr9essdy1MX4';
update content_bodies set title = 'Yuko Ogura Strolls Through the Scenic Streets in Traditional Kimono | Kurayoshi City, Tottori Prefecture <Tabiiro> (60 sec version)', description = 'Kurayoshi City, located in central Tottori Prefecture, was once a thriving castle town. Its center features a popular tourist area with red-tiled roofs and white-walled storehouses that preserve the charm of a bygone era, making visitors feel as if they have stepped back in time. Yuko Ogura discovers this travel spot perfect for social media sharing. For more details, visit the provided links for retro trips and special movie versions.' where id = '0URBBwP49WVd-5pTpdaUl';
update content_bodies set title = '小倉優子｜伝統の着物で、風情ある街並みをそぞろ歩き｜鳥取県倉吉市【旅色Movie】', description = '小倉優子さんが鳥取県中部の倉吉市を訪れ、かつて城下町として栄えたこの地域の魅力を伝えます。倉吉市は、白壁土蔵や赤瓦の商家が並ぶ情緒ある街並みが特徴で、過去の面影を残す人気の観光地です。まるでタイムスリップしたかのような雰囲気が漂い、SNS映えするスポットも多数あります。動画では「倉吉レトロトリップ」を紹介し、訪れる価値のある美しい場所を紹介しています。' where id = 'aYKe2YZY4EKDpfawAYna2';
update content_bodies set title = 'Yuko Ogura Strolls Through the Scenic Streets in Traditional Kimono | Kurayoshi City, Tottori Prefecture [Tabiiro Movie]', description = 'Yuko Ogura explores Kurayoshi City, located in central Tottori Prefecture, known for its historical charm as a former castle town. The city features picturesque streets lined with white-walled storehouses and red-tiled roofs, preserving the essence of a bygone era. This popular tourist area offers a nostalgic atmosphere, making it feel like a time slip. The video highlights the ''Kurayoshi Retro Trip,'' showcasing beautiful spots perfect for social media sharing.' where id = 'SzVQOvxAujS2FqDkaqWCd';
update content_bodies set title = '土屋太鳳｜撮影の舞台裏｜運をひらく 旅はじめ（徳島県・鳴門市）【旅色Movie】', description = '創刊15周年を迎える『旅色』に登場した土屋太鳳さん。特集は「2023年の運気を上げる旅」で、占い師・ぷりあでぃす玲奈さんが運気を上げるためのキーワードを教えてくれます。この動画では、徳島県鳴門市での撮影の舞台裏をこっそりお見せします。' where id = '-iRXZ6XI4GLrNBDlfORUQ';
update content_bodies set title = 'Tao Tsuchiya | Behind the Scenes of Filming | Journey to Open Luck (Naruto City, Tokushima Prefecture) [Tabiiro Movie]', description = 'Tao Tsuchiya appears in the special feature of ''Tabiiro,'' celebrating its 15th anniversary. The theme is ''Travel to Boost Your Luck in 2023.'' The fortune teller Reina Puriadisu shares keywords for enhancing luck during travels, and this video provides a sneak peek behind the scenes of the filming in Naruto City, Tokushima Prefecture.' where id = '3DSlABUXX8RY3G2nq-ZWH';
update content_bodies set title = 'おのののか｜コバルトブルーの風がふわり 心ゆるむ下関トリップ【旅色Movie】', description = '山口県下関市は三方を海に囲まれた活気ある港町で、絶景スポット巡りが楽しめる場所です。関門海峡や角島大橋などの名所はもちろん、地酒や名物グルメのお店も豊富で、旅の楽しみが尽きることはありません。旅好きのおのののかさんが、心ゆるむ旅を満喫し、様々な観光地やグルメを体験しました。' where id = '_OGEFBomiItGb9PCQJYd8';
update content_bodies set title = 'Onono Noka | A Relaxing Trip to Shimonoseki with Cobalt Blue Winds【Tabiiro Movie】', description = 'Shimonoseki City in Yamaguchi Prefecture is surrounded by the sea and offers a vibrant port town atmosphere along with stunning sightseeing spots. Notable attractions include the Kanmon Straits and the Tsunoshima Bridge, making it a must-visit destination. The city is also known for its local sake and gourmet specialties, ensuring endless enjoyment for travelers. Onono Noka, a travel enthusiast, fully enjoyed a relaxing trip exploring these highlights.' where id = 'CPnz3oTQsXYqJ6NLPexw4';
update content_bodies set title = '中尾明慶｜未来を彫刻するまち山口県宇部市のアートJourney', description = '中尾明慶さんが訪れたのは、アートと自然が調和する山口県宇部市です。旅は空港から始まり、市内中心部や市民の憩いの場「ときわ公園」など、さまざまな場所で彫刻と出会うことができます。また、地元の人々に愛されるグルメや絶景スポットも豊富にあります。非日常が日常に溶け込む宇部市のアートJourneyが始まります。' where id = 'ZHaqEshSu2UWe25pyKrJX';
update content_bodies set title = 'Akiyoshi Nakao | Art Journey in Ube City, Yamaguchi Prefecture', description = 'Akiyoshi Nakao visits Ube City, where art and nature harmoniously coexist. The journey begins at the airport and continues through the city center and the popular ''Tokiwa Park,'' where sculptures can be found in various locations. The city also offers beloved local cuisine and stunning scenic spots. This art journey in Ube City blends the extraordinary with the everyday.' where id = 'YSjTtXGbo4j_QLY_jjXYK';
update content_bodies set title = '広瀬アリス｜神々が集うまち　まばゆい出雲へ【旅色Movie】', description = '広瀬アリスさんが2023年11月13日から神在月を迎える島根県出雲市を訪れます。出雲を訪れるのは初めての広瀬さんは、出雲大社をはじめとするパワースポットや、分子ガストロノミーを取り入れた創作料理を楽しむレストランを巡ります。動画では、出雲大社や甘味処「出雲ぜんざい餅」、2023年5月にオープンした複合施設「WINDY FARM ATMOSPHERE」などの重要なスポットを紹介。さらに、海を眺めながらの「GARB CLIFF TERRACE IZUMO」や、厳選食材を使った京料理を楽しむ「京彩厨房 なが田」、日御碕神社の参拝、鉄板焼きと創作料理を堪能する「美喰Labo 我龍」、最後に宇龍漁港での散策が描かれています。' where id = 'pxMUUgzVhJKly5Oetmj-f';
update content_bodies set title = 'Alice Hirose | A Radiant Izumo Where Gods Gather【Tabiiro Movie】', description = 'Alice Hirose visits Izumo City in Shimane Prefecture, which welcomes the month of Kaminarizuki starting November 13, 2023. This is her first visit to Shimane, where she explores various power spots, including Izumo Taisha, and experiences unique dining at a creative restaurant that incorporates molecular gastronomy techniques. The video showcases her journey through significant locations such as the sacred Izumo Taisha, a sweet shop called Izumo Zenzai Mochi, and the newly opened WINDY FARM ATMOSPHERE complex. She also enjoys delicious meals at GARB CLIFF TERRACE IZUMO and Kyo-sai Chubo Nagata, visits Hinomisaki Shrine, and indulges in teppanyaki and creative dishes at Bishoku Labo Garyo, concluding her day with a stroll at Uryu Fishing Port.' where id = 'pcjTVQKDSBxMBRLicIGpb';
update content_bodies set title = '夏菜｜京都に、宇治田原町。ハートフルなまち｜15秒ver【旅色Movie】', description = '京都・宇治田原町は「近畿の真ん中」に位置し、日本緑茶の発祥地として知られています。この短い旅の映画では、自然体なスタイルで多くの人に支持されている女優・夏菜さんがこの魅力的な町を巡ります。宇治田原町の独自の文化や美しさを紹介し、視聴者に京都の深い旅へと誘います。さらに長いバージョンに興味がある方のために、拡張コンテンツへのリンクも提供されています。' where id = 'L7sw86su09TPTCLINrITi';
update content_bodies set title = 'Natsuna | Ujitawara Town, Kyoto: A Heartful Town | 15-Second Version [Tabiiro Movie]', description = 'Ujitawara Town, located in the heart of the Kinki region, is known as the birthplace of Japanese green tea. In this short travel movie, actress Natsuna, who is well-loved for her natural style, explores this charming town. The video invites viewers to embark on a deep journey through Kyoto, showcasing the unique culture and beauty of Ujitawara. For those interested in a longer version, links to extended content are provided.' where id = 'zkojIQGooZDC8h-PZd9Ot';
update content_bodies set title = 'ハートフルなまち　京都に、宇治田原町', description = '京都・宇治田原町は「近畿の真ん中」に位置し、日本緑茶の発祥地として知られています。この旅では、自然体なスタイルで多くの人に支持されている女優・夏菜さんと共に、宇治田原町を巡ります。ディープな京都の魅力を体験できる内容となっており、旅のルートはリンクから確認できます。また、フルバージョンの動画もYouTubeで視聴可能です。夏菜さんは1989年に埼玉県で生まれ、2006年にドラマでデビューし、その後も多くの作品で活躍しています。' where id = '_KDM0j8istmh8Uni-z5ba';
update content_bodies set title = 'Ujitawara Town, Kyoto: A Heartfelt Journey with Natsuna', description = 'Ujitawara Town, located in the heart of Kyoto, is known as the birthplace of Japanese green tea. In this travel segment, actress Natsuna, who is well-loved for her natural style, explores this charming town. The journey promises a deep dive into the unique culture and beauty of Kyoto, showcasing the town''s rich heritage and scenic landscapes. Viewers can find the travel route linked in the description and can also watch the full version of the journey on YouTube. Natsuna, born in 1989 in Saitama Prefecture, debuted in 2006 and has since gained recognition for her roles in various dramas and films, as well as her work in variety shows and voice acting.' where id = 'VJj1b-09Bc3cpX7oDcPwY';
update content_bodies set title = '夏菜｜京都に、宇治田原町。ハートフルなまち｜180秒ver【旅色Movie】', description = '京都・宇治田原町は「近畿の真ん中」に位置し、日本緑茶の発祥地として知られています。この旅色ムービーでは、自然体なスタイルで多くの人に支持されている夏菜さんが、この魅力的な町を巡ります。京都の独特な文化や美しさを深く体験できる旅が約束されています。宇治田原町の旅をもっとコンパクトに知りたい方には、短いバージョンの動画も用意されています。夏菜さんは1989年に埼玉県で生まれ、2006年にデビューし、ドラマや映画で注目を集めました。彼女はバラエティ番組や声優、ナレーションにも活躍の幅を広げ、自身のYouTubeチャンネルも開設しています。' where id = 'ZiCRU3qFbCbpvX2iFg3v_';
update content_bodies set title = 'Natsuna | Ujitawara Town, Kyoto: A Heartful Town | 180 Seconds Version [Tabiiro Movie]', description = 'Ujitawara Town, located in the heart of the Kinki region, is known as the birthplace of Japanese green tea. In this travel movie, Natsuna, a popular figure known for her natural style, explores this charming town. The journey promises a deep dive into the unique culture and beauty of Kyoto. For those interested in a more compact version of the trip, shorter videos are available. Natsuna, born in 1989 in Saitama Prefecture, debuted in 2006 and gained attention through various dramas and films, including ''Kimi ni Todoke'' and ''GANTZ.'' She has also expanded her career into variety shows, voice acting, and narration, and has launched her own YouTube channel.' where id = 'MB2KTtPzOp2VG3LguKmaX';
update content_bodies set title = '鈴木ちなみ｜大阪でおとなの街歩き【旅色Movie】', description = '鈴木ちなみが大阪の新たな魅力を発見する動画です。たこ焼きや串カツのイメージを超え、彼女は大人の旅が楽しめる街であることを知ります。高校の卒業旅行でユニバーサル・スタジオ・ジャパンを訪れたことがある彼女ですが、今回は初めての場所ばかり。特に中崎町の古着屋やリノベーションされた建物に感動し、若者たちが古い町並みを再生している様子が印象的でした。また、北浜の歴史的な建物も新鮮で、観光客ではなく地元の人々が楽しむ場所であることを感じました。' where id = 'a_L0lUKSM4F-BoKNnNelm';
update content_bodies set title = 'Chinami Suzuki | Adult City Walk in Osaka [Tabiiro Movie]', description = 'In this video, Chinami Suzuki explores a different side of Osaka, moving beyond the typical images of takoyaki and kushikatsu. She reflects on her past visits, including a high school graduation trip to Universal Studios Japan, but this time she discovers new places. Notably, she finds the vintage shops in Nakazakicho, where renovated buildings and young staff create a vibrant atmosphere. The historical architecture in Kitahama also impresses her, as it feels more like a local hangout than a tourist spot. This experience reveals Osaka as a city rich in adult travel opportunities.' where id = 'rzL4U-XN2bDNzu0ZPgvXu';
update content_bodies set title = '【松井珠理奈】近江商人のふるさと豊郷町で楽しむ歴史とグルメの旅＜旅色＞（15秒ver）', description = '豊郷町は、江戸時代から明治にかけて活躍した近江商人のふるさとです。歴史的な偉人の足跡をたどりながら散策することで、懐かしい風景に出会い、ノスタルジックな気分を味わえます。また、豊郷町にある「豊郷小学校旧校舎群」は、アニメ「けいおん！」の舞台のモデルとも言われ、多くのファンが訪れる聖地となっています。豊郷町は彦根駅から電車で約20分の距離に位置しています。' where id = 'QTUwUjaxt_mtD5m8EJwR0';
update content_bodies set title = 'A Journey of History and Gourmet in Toyosato Town, Hometown of Omi Merchants', description = 'Toyosato Town, known as the hometown of Omi merchants who thrived from the Edo to the Meiji period, offers a nostalgic experience as visitors can leisurely stroll while tracing the footsteps of historical figures. The town features the Toyosato Elementary School Old School Building, which is said to have inspired the setting for the anime ''K-On!'' and attracts many fans as a pilgrimage site. Toyosato is conveniently located about 20 minutes by train from Hikone Station.' where id = 'zxlv2-ZLrLBmMioarIouj';
update content_bodies set title = '松井珠理奈｜近江商人のふるさと豊郷町で楽しむ歴史とグルメの旅', description = '豊郷町は江戸時代から明治にかけて活躍した近江商人のふるさとです。歴史的な偉人の足跡をたどりながら散策することで、懐かしい風景に出会い、ノスタルジックな気分を味わえます。また、豊郷町にある「豊郷小学校旧校舎群」は、アニメ「けいおん！」の舞台のモデルとされ、多くのファンが聖地巡礼に訪れています。豊郷町は彦根駅から電車で約20分の距離に位置しています。' where id = '98jp8ILRxoFE5JOiWMghE';
update content_bodies set title = 'Juri Matsui | A Journey Through History and Gourmet in Toyosato Town, Hometown of Omi Merchants', description = 'Toyosato Town, the hometown of Omi merchants, flourished from the Edo to the Meiji period. Visitors can leisurely stroll while tracing the footsteps of historical figures, encountering nostalgic landscapes that evoke a sense of nostalgia. The ''Toyosato Elementary School Old School Building Group'' is said to have inspired the setting for the anime ''K-On!'', attracting many fans who visit as part of a pilgrimage. Toyosato Town is about a 20-minute train ride from Hikone Station.' where id = '3Tx8leJlqhoFgYBxiO5ji';
update content_bodies set title = '宇和島に住む', description = 'この動画は宇和島に住むことについて紹介しています。宇和島は美しい自然と豊かな文化を持つ地域で、地元の人々の生活や風景が映し出されています。動画では、宇和島の魅力や日常生活の様子が詳しく紹介されており、視聴者にこの地域の特性や住みやすさを伝えています。' where id = 'Btk_VpPu0EvHhC41Qm9ND';
update content_bodies set title = 'Living in Uwajima', description = 'This video introduces living in Uwajima.' where id = 'FDWyKwSBlBIDMUhchQAf6';
update content_bodies set title = '【松井珠理奈】近江商人のふるさと豊郷町で楽しむ歴史とグルメの旅＜旅色＞（60秒ver）', description = '豊郷町は、江戸時代から明治にかけて活躍した近江商人のふるさとです。歴史的な偉人の足跡をたどりながら散策することで、懐かしい風景に出会い、ノスタルジックな気分を味わえます。また、豊郷町にある「豊郷小学校旧校舎群」は、アニメ「けいおん！」の舞台のモデルとも言われ、多くのファンが訪れる聖地となっています。豊郷町は彦根駅から電車で約20分の距離にあります。' where id = 'e2aBhYArH-pQf9lCm1bFr';
update content_bodies set title = 'A Journey Through History and Gourmet in Toyosato Town, Hometown of Omi Merchants', description = 'Toyosato Town, the hometown of Omi merchants who thrived from the Edo to the Meiji period, offers a nostalgic experience as visitors can leisurely stroll while tracing the footsteps of historical figures. The town features the Toyosato Elementary School Old School Building, which is said to have inspired the setting of the anime ''K-On!'' and attracts many fans as a pilgrimage site. Toyosato is located about 20 minutes by train from Hikone Station.' where id = 'a8bXjh0j-277_VIl_LySA';
update content_bodies set title = 'SKE48の松井珠理奈さんが案内！近江商人のふるさと「滋賀県豊郷町」を観光PR', description = 'SKE48の松井珠理奈さんが滋賀県豊郷町を観光PRしています。滋賀県で最も小さな町でありながら、近江商人のふるさととして知られるこの町の歴史を巡り、近江牛などのグルメを楽しむ贅沢な旅を提案しています。豊郷町は彦根駅から電車で約20分の距離に位置しています。' where id = 'awXlK5FoZC0pGFuzVvmCX';
update content_bodies set title = 'SKE48''s Jurina Matsui Guides You! Tourism PR for Toyosato Town, the Hometown of Omi Merchants in Shiga Prefecture', description = 'Jurina Matsui from SKE48 promotes tourism in Toyosato Town, the smallest town in Shiga Prefecture, known as the hometown of Omi merchants. The tour explores the town''s rich history and indulges in gourmet experiences, including Omi beef. Toyosato Town is conveniently located about 20 minutes by train from Hikone Station.' where id = 'vTRhdrm5DH1v15mAZnwwZ';
update content_bodies set title = '国産アイアン発祥の地「兵庫県市川町」でアクティブ旅', description = '女優の川島海荷が、兵庫県の市川町を訪れ、自然豊かなこの町での観光を楽しみます。市川町はハートの形をした町で、日本で初めてゴルフクラブのアイアンヘッドが作られた場所として知られています。清流・市川が流れるこの町では、ゴルフ体験や地元の食材を使った贅沢なBBQを楽しむことができ、夏のアクティブな旅にぴったりです。市川町は姫路駅から車で約30分の距離にあり、アクセスも良好です。' where id = 'QsjnCMrQM9bZYnMkC8WRp';
update content_bodies set title = 'Active Travel in Ichikawacho, Hyogo Prefecture, the Birthplace of Domestic Golf Irons', description = 'Kawahima Kaihaku, an actress and talent, explores Ichikawacho in Hyogo Prefecture, known for its rich nature and as the birthplace of the domestic golf iron. The town, shaped like a heart and located in the center of Hyogo, features the clear stream of Ichikawa flowing through it. Visitors can enjoy a golf experience and a luxurious BBQ featuring local produce amidst the beautiful scenery. Ichikawacho is conveniently located about 30 minutes by car from Himeji Station, making it an ideal destination for an active summer getaway.' where id = '-YhQQKwVEag42l3iStO_6';
update content_bodies set title = '川島海荷｜国産アイアン発祥の地「兵庫県市川町」でアクティブ旅', description = '女優でタレントの川島海荷が、兵庫県のほぼ中央に位置する市川町でアクティブな旅を楽しみます。市川町は、日本で初めてゴルフクラブのアイアンヘッドが作られた地として知られ、自然豊かな環境の中で文化やアクティビティを体験できます。地元の食材を使った贅沢なBBQやゴルフ体験など、夏に訪れたい魅力的な旅の提案が満載です。市川町は姫路駅から車で約30分の距離にあり、アクセスも良好です。' where id = 'Qty9A6sPAvAWj9izWYoYA';
update content_bodies set title = 'Kaihaku Kawashima''s Active Trip in Ichikawacho, Hyogo Prefecture, the Birthplace of Domestic Iron', description = 'Kaihaku Kawashima, an actress and talent, embarks on an active journey in Ichikawacho, located in the heart of Hyogo Prefecture. Known as the birthplace of the domestic golf iron, this town offers a unique blend of culture and nature. Visitors can enjoy a golf experience and a luxurious BBQ featuring local produce amidst the town''s rich natural surroundings. Ichikawacho is conveniently located about 30 minutes by car from Himeji Station, making it an accessible destination for those looking to explore the beauty and activities of this charming area.' where id = 'zfEu3QlMBvzOBSfwfmLkt';
update content_bodies set title = '【川島海荷】国産アイアン発祥の地「兵庫県市川町」でアクティブ旅＜旅色＞（60秒ver）', description = '兵庫県のほぼ中央に位置する市川町は、ハートの形をした自然豊かな町で、日本で初めてゴルフクラブのアイアンヘッドが作られた場所として知られています。川島海荷さんがこの町でアクティブな旅を楽しみ、地元の食材を使った豪華なBBQやゴルフ体験を通じて、文化や自然を満喫します。市川町は姫路駅から車で約30分の距離にあり、訪れるには便利な場所です。' where id = '6x3AAqBDJO9A_rcVwuTCW';
update content_bodies set title = 'Active Travel in Ichikawacho, Hyogo Prefecture, the Birthplace of Domestic Iron', description = 'Kawahima Kaihaku, an actress and talent, embarks on an active sightseeing journey in Ichikawacho, located in the heart of Hyogo Prefecture. Known as the birthplace of the domestic golf iron, this town offers a unique blend of culture and nature. Visitors can enjoy a golf experience and indulge in a luxurious BBQ featuring local produce amidst the town''s rich natural surroundings. Ichikawacho is conveniently located about 30 minutes by car from Himeji Station, making it an accessible destination for those looking to explore the beauty and heritage of this charming area.' where id = '0b_5WsMBZ8w-njiA-vtoQ';
update content_bodies set title = '【佐野ひなこ】レトロな街並みとグルメを満喫する｜和歌山県湯浅町＜旅色＞（15秒ver）', description = '女優・タレントの佐野ひなこが和歌山県湯浅町を訪れ、醤油の発祥地として知られるこの町の魅力を紹介します。レトロな街並みは醸造文化の伝統を伝え、歴史を感じながら散策できます。特産品のしらすやみかんを味わい、自然と触れ合うことができる旅です。湯浅町は日本遺産にも認定されており、歴史、自然、グルメが楽しめる素晴らしい体験が待っています。' where id = '-pW9eY3toYbIl4n4zS5uU';
update content_bodies set title = 'Enjoy Retro Streets and Gourmet in Yuasa-cho, Wakayama Prefecture | Tabiiro (15 sec version)', description = 'Hinako Sano, an actress and talent, explores Yuasa-cho in Wakayama Prefecture, known as the birthplace of soy sauce and a site of Japanese heritage. The town features retro streets that showcase its brewing culture and history. Visitors can enjoy local delicacies like Shirasu and oranges while experiencing the natural beauty of the area. This trip promises a delightful blend of history, nature, and gourmet experiences.' where id = 'KbgMHMRazaYIiAxhFQH_5';
update content_bodies set title = '佐野ひなこ｜和歌山県湯浅町 レトロな街並みとグルメを満喫する【旅色Movie】', description = '湯浅町は日本の食文化に欠かせない醤油の発祥地であり、醸造文化の伝統を今に伝えるレトロな街並みが魅力です。町を歩きながら歴史に触れ、自然と遊び、特産品を味わうことができます。湯浅の旅は魅力にあふれています。詳細は特別動画や観光情報サイトをチェックしてください。' where id = 'guKCLJynGlphg4JpdsN1Z';
update content_bodies set title = 'Hinako Sano | Enjoy Retro Streets and Gourmet in Yuasa Town, Wakayama【Tabiiro Movie】', description = 'Yuasa Town, known as the birthplace of soy sauce, showcases a retro streetscape that reflects Japan''s brewing culture. Visitors can explore the town, immerse themselves in its history, enjoy nature, and taste local specialties. This travel experience in Yuasa is filled with charm. For more information, check out the special movie links and the Yuasa tourism website.' where id = 'WyXUuC6Y7hMc-rSRQago7';
update content_bodies set title = 'レトロな街並みとグルメを満喫する｜和歌山県湯浅町', description = '和歌山県湯浅町は、日本の食文化に欠かせない醤油の発祥地であり、醸造文化の伝統を今に伝えるレトロな街並みが魅力です。町を歩きながら歴史に触れ、自然と遊び、特産品を味わうことができます。湯浅の魅力を存分に楽しむ旅が待っています。' where id = 'VK65N6EHQnPwOXXm-4QaW';
update content_bodies set title = 'Enjoy Retro Streets and Gourmet Food in Yuasa Town, Wakayama Prefecture', description = 'Yuasa Town, known as the birthplace of soy sauce, offers a unique blend of historical charm and culinary delights. Visitors can explore the retro streets that showcase the town''s rich brewing culture, engage with its history, enjoy nature, and taste local specialties. This destination is a must-visit for those looking to experience the allure of Yuasa.' where id = 'aHp6VD21YvEla1_Tkf2D-';
update content_bodies set title = '中村ゆり｜フルーツの生産量が日本トップクラス 和歌山県湯浅のおいしい旅 30秒Ver', description = '湯浅町は醤油の発祥地として知られ、海の幸も豊富でグルメ旅行に最適な場所です。観光名所や絶景スポットが多く、見どころがたくさんある湯浅町を中村ゆりさんと一緒に散策します。' where id = 'WlPDqw3120sj332DHKEFI';
update content_bodies set title = 'Yuri Nakamura | A Delicious Journey in Yuasa, Wakayama, Known for Its Top-Class Fruit Production - 30-Second Version', description = 'Yuasa Town is famous as the birthplace of soy sauce and is rich in seafood, making it perfect for a gourmet trip. The town is filled with tourist attractions and breathtaking spots, and you will explore the many highlights of Yuasa Town alongside Yuri Nakamura.' where id = 'C9d8IDvpKDu2C0Lp8pHIG';
update content_bodies set title = '安田美沙子｜あたらしい大阪発見！ 魅惑のまち羽曳野をあじわう旅へ【旅色Movie】', description = '安田美沙子さんが訪れた羽曳野市は、古墳と共に人々の暮らしがあり、貴重な史跡が豊富に残る場所です。彼女は「こんな素敵な場所があったんだ！」と感動し、新しい発見の連続でした。古代ロマンあふれる街歩きと、羽曳野ならではの料理や特産品を味わう旅が始まります。旅のプランには、応神天皇陵古墳や誉田八幡宮、地元のワインやベーグル、ハニワづくり体験などが含まれています。' where id = '4ghm_cT_Z_f4uriFwmXku';
update content_bodies set title = 'Misako Yasuda | Discovering the Fascinating City of Habikino, Osaka【Tabiiro Movie】', description = 'Misako Yasuda visits Habikino City, a place rich in history with ancient burial mounds and numerous historical sites. She expresses her excitement at discovering such a wonderful location, saying, ''I had no idea such a beautiful place existed!'' The journey begins with a walk through this ancient city, where she experiences local cuisine and specialties unique to Habikino. The itinerary includes visits to the Emperor Ojin Tomb, Hoshida Hachiman Shrine, and local wineries, as well as enjoying bagels and participating in a haniwa-making experience.' where id = 'oWMJwjeRe2Vmlrgzpgjwj';
update content_bodies set title = '安田美佐子｜羽曳野市・大阪【旅色ムービー】', description = '安田美佐子さんは、古墳と貴重な歴史的遺産が共存する羽曳野市を訪れました。彼女は新たな発見に感動し、「素晴らしい場所があった！」と語ります。旅の中では、仁徳天皇陵や本田八幡宮を訪れ、国宝に触れる体験をします。また、河内ワインで大阪ワインについて学び、飛鳥ワインのブドウ畑を訪れます。地元の料理も楽しみ、「cot BAGLE STAND Bagel」でパンを買って食べたり、「MAISON INCO」でランチを取ったりします。さらに、河内古墳の里で埴輪作りを体験し、花の竹内街道で休憩を取ります。この旅は羽曳野の独特な文化と特産品を紹介しています。' where id = 'SG-uSsKaKOECUjim-r1wr';
update content_bodies set title = 'Misako Yasuda｜Habikino City_Osaka【Tabiiro Movie】', description = 'Mrs. Misako Yasuda explores Habikino City, a place rich in history and burial mounds. She expresses her amazement at the discoveries, stating, ''There was such a wonderful place!'' The journey includes visits to significant sites such as the Imperial Tomb of Emperor Ojin and Honda Hachimangu Shrine, where she interacts with a National Treasure. She learns about Osaka Wine at Kawachi Wine and visits vineyards at Asuka Wine. The experience also features local cuisine, including a stop at ''cot BAGLE STAND Bagel'' for bread and lunch at ''MAISON INCO.'' Additionally, she participates in a Haniwa making experience at Kawachi Konda Haniwa no Sato Okuraya and takes a break at Flower Takenouchi Kaido Karusato. This journey highlights the unique culture and specialties of Habikino.' where id = 'BuMWC0sqcB-VlK6A8sACR';
update content_bodies set title = 'トリンドル玲奈｜ホテルを拠点に地域を巡る 新感覚なローカルトリップ in 兵庫県但馬エリア', description = 'トリンドル玲奈さんが体験したのは、道の駅に隣接するホテルに宿泊し、地元の魅力を発見する旅です。自然豊かな「フェアフィールド･バイ･マリオット但馬やぶ」を拠点に、兵庫県の但馬地方の町を巡りました。旅の内容には、伝統的な建物が残る城下町の散策、日本最古の時計台の見学、自分だけのレザー小物作り体験、地元のお土産探し、カフェレストランでの食事、そして美しい滝の訪問が含まれています。' where id = 'uxPE5WklWoU4fymVWpqKS';
update content_bodies set title = 'Reina Triendl | A New Sensation Local Trip in the Tajima Area of Hyogo Prefecture', description = 'Reina Triendl experiences a journey discovering local attractions while staying at a hotel adjacent to a roadside station. Using the nature-rich ''Fairfield by Marriott Tajima Yabu'' as a base, she explores the towns of the Tajima region in Hyogo Prefecture. The trip includes visits to traditional buildings in the castle town, the oldest clock tower in Japan, a leather goods workshop, and a local souvenir shop. Triendl also enjoys a meal at a café restaurant and visits a beautiful hidden spot with a large waterfall.' where id = 'LvfZ79GtuXcoEw2QY4qoh';
update content_bodies set title = '岡本玲｜「おいしさ」と「心地よさ」が待っている 湯浅（和歌山県）のうまさを巡る旅', description = '和歌山県湯浅町は醤油醸造の発祥地として知られ、豊かな自然から生まれる特産品や美味しいグルメが豊富です。温暖な気候と町の人々の温かいもてなしの中、和歌山出身の女優・岡本玲さんが湯浅町のグルメを堪能します。旅の中では、レトロに改装されたJR湯浅駅、歴史ある旧栖原家住宅、醤油づくり体験、心地よい宿泊施設、農家直営の柑橘ソフトクリームを楽しむ様子が描かれています。' where id = '3hfvwEcrhSX7nNtvBZlDr';
update content_bodies set title = 'Rei Okamoto | A Journey to Experience the ''Deliciousness'' and ''Comfort'' of Yuasa, Wakayama Prefecture', description = 'Yuasa Town in Wakayama Prefecture is known as the birthplace of soy sauce brewing, offering a variety of local specialties and delicious gourmet foods. The warm climate and the hospitality of the town''s residents enhance the experience as actress Rei Okamoto, originally from Wakayama, enjoys the culinary delights of Yuasa. The journey includes visits to the retro renovated JR Yuasa Station, the historic Suhara family residence, a soy sauce-making experience, a relaxing stay at a cozy inn, and tasting citrus soft serve from a local farm.' where id = '3-iTi5vD5Q78zgHMD6fuM';
update content_bodies set title = '矢田亜希子｜風の吹くまま 気の向くまま 群馬県板倉町の旅手帖', description = '矢田亜希子さんが訪れたのは、都心から約1時間の距離にある群馬県板倉町です。この町は、世界的に貴重な湿地である渡良瀬遊水地を有し、豊かな自然と広がる青空に包まれています。彼女は、空を舞うグライダーや清流で育った川魚料理など、ここでしか味わえない景色や味を楽しみました。' where id = 'GGNrnu_9UbrbippT9QaN4';
update content_bodies set title = 'Akiko Yada | A Journey in Itakura Town, Gunma Prefecture', description = 'In this travelogue, Akiko Yada visits Itakura Town, the closest town to Tokyo in Gunma Prefecture, located about an hour away from the city. The area is known for its precious wetland, the Watarase Yusui-chi, and is surrounded by rich nature and endless blue skies. During her visit, she enjoys unique experiences such as watching gliders soar in the sky and tasting gourmet river fish dishes that can only be found here.' where id = 'HtDDwaO_D9lhdbpMC-yxP';
update content_bodies set title = '工藤美桜｜巡るほどに心がはずむ いま、気になる宇都宮', description = '栃木県宇都宮市は、JR駅前の再開発やLRTの開業により、食の魅力を保ちながら急成長を遂げています。懐かしさと新しさが共存するこの街には、フォトジェニックなスポットがたくさんあります。工藤美桜さんが「餃子像」や進化系餃子を味わう「芭莉龍」、1600年の歴史を持つ「宇都宮二荒山神社」、お土産コーナーの「来らっせ本店」、餃子通りの名店、老舗バー「夢酒OGAWA」での特別な一杯、竹林に囲まれた「若竹の杜 若山農場」でのリフレッシュ、コーヒーブレイクの「THE STANDARD BAKERS」、地下30メートルの「大谷資料館」での神秘的なひと時など、宇都宮の魅力を巡ります。' where id = 'vtpdOR2Drgkl7NuRDRVGT';
update content_bodies set title = 'Mio Kudo | Exploring Utsunomiya, a City Full of Heart', description = 'Utsunomiya City in Tochigi Prefecture is rapidly growing, maintaining its reputation as one of Japan''s top cities for gyoza, thanks to the redevelopment around the JR station and the opening of the LRT. The city beautifully blends nostalgia with modernity, offering numerous photogenic spots. In this travel feature, Mio Kudo explores the current attractions of Utsunomiya, including the iconic Gyoza Statue, tasting innovative gyoza at ''Bariryu'', visiting the historic Utsunomiya Futarasan Shrine, shopping for gyoza souvenirs at ''Karlas'', and enjoying a special drink at the long-established bar ''Yumezake OGAWA''. The journey also includes a refreshing experience at ''Wakatake no Mori Wakayama Farm'' surrounded by bamboo groves, a coffee break at ''THE STANDARD BAKERS'', and a mystical visit to the ''Oya History Museum'' located 30 meters underground.' where id = 'bsv-KpOfyZ7oG0Iov-plG';
update content_bodies set title = '関水渚｜「国立市・国分寺市・小金井市」湧水でつながるまち ふらり散歩旅【旅色Movie】', description = '関水渚さんが訪れたのは、東京都の中心に位置する国立市、国分寺市、小金井市で、豊かな自然と都市が共存する暮らしやすい地域です。このエリアは、東京の大都市とは思えない緑に囲まれ、地元の素材を活かした郷土料理や長い歴史を体験できます。動画では、国立のシンボルストリート「大学通り」、交通安全発祥の地「谷保天満宮」、レトロな雰囲気の「江戸東京たてもの園」、静かな「滄浪泉園」、屋上の隠れ家「イエノウエノカフェ」、そして「お鷹の道・真姿の池湧水群」での散歩が紹介されています。これらのスポットを通じて、湧水の美しさを楽しむことができます。' where id = 'NyUcmpoz3kY7kl3WAiUSP';
update content_bodies set title = 'Nagisa Sekimizu | A Stroll Through Kunitachi, Kokubunji, and Koganei Connected by Spring Water【Tabiiro Movie】', description = 'Nagisa Sekimizu visits Kunitachi, Kokubunji, and Koganei, three cities located in the heart of Tokyo, known for their coexistence of rich nature and urban life. This area, which feels far removed from the bustling metropolis of Tokyo, offers lush greenery, local cuisine that utilizes regional ingredients, and a deep historical background. The video showcases various attractions, including the symbolic ''University Street'' in Kunitachi, the historic Yaho Tenmangu Shrine, the Edo-Tokyo Open Air Architectural Museum, the serene Sōrōsen-en garden, and the hidden café ''Ienoueno Cafe'' on a rooftop. The journey concludes with a leisurely walk along the O-taka no Michi and the Misakiko Spring Water Group, allowing viewers to appreciate the beauty of spring water.' where id = 'P2hCWxVgg_iLAXN3f8fp5';
update content_bodies set title = '内田 理央｜MY HADANO STORY「わたしの秦野、再発見」｜秦野市[神奈川県]【旅色Movie 180秒】', description = '神奈川県秦野市は丹沢山地の麓に広がり、豊かな湧水と四季の自然に恵まれた町です。名水百選に選ばれた湧水群があり、ハイキングや登山の拠点としても人気が高く、自然の中でリフレッシュできます。また、地元の農産物も豊富で、地域の魅力を感じられるグルメや季節のイベントが開催されています。映像を通じて、四季折々の自然と名水に育まれた秦野の魅力をじっくりと楽しんでください。' where id = 'Z-6mKUgo5OhstaxbXJEYr';
update content_bodies set title = 'Rio Uchida | MY HADANO STORY ''Rediscovering Hadano'' | Hadano City [Kanagawa]【Tabiiro Movie 180 seconds】', description = 'Hadano City, located at the foot of the Tanzawa Mountains in Kanagawa Prefecture, is blessed with rich spring water and seasonal nature. It features a selection of famous springs and is popular as a base for hiking and climbing, allowing visitors to refresh themselves in nature. The area is also abundant in agricultural products, offering local gourmet food and seasonal events that showcase the region''s charm. Enjoy the beauty of Hadano, nurtured by its seasonal nature and famous springs, through this video.' where id = 'KR4EpBQI0cfH8pn0YmHqc';
update content_bodies set title = '桜井日奈子｜千葉の東に教えたくなる旅先あり。東金というベストプレイス', description = '今年デビュー10周年を迎える桜井日奈子さんが、千葉県の東部に位置する東金市を巡る1泊2日の旅に出かけました。都心から車や電車でわずか1時間ほどの距離にある東金市は、豊かな自然や歴史、グルメが揃っており、訪れる人々を驚かせています。2024年は市制施行70周年の記念の年で、さまざまなイベントや記念グッズが企画されています。旅の内容には、八鶴湖の散策、ブドウやブルーベリー狩り、地元の野菜を探すこと、古民家レストランでのランチ、樹齢400年以上の杉並木を訪れること、そして美しい景色を楽しむことが含まれています。' where id = 'MiDTTOzO4s21jhG4XrCHm';
update content_bodies set title = 'Hinako Sakurai | A Travel Destination in the East of Chiba: Togane, the Best Place to Visit', description = 'Hinako Sakurai, celebrating her 10th anniversary this year, embarked on a two-day trip to Togane City, located in the eastern part of Chiba Prefecture. Just an hour''s drive or train ride from the city center, Togane offers a surprising blend of rich nature, intriguing history, and delightful gourmet experiences. Many visitors are astonished to discover such a refreshing getaway so close to Tokyo. Notably, 2024 marks the 70th anniversary of Togane''s city establishment, with various events and commemorative goods planned throughout the year. The trip includes activities like walking around the historic Hachikurako Lake, grape and blueberry picking, exploring local produce, enjoying lunch at a traditional restaurant, and visiting scenic parks.' where id = '1YiJZlxQUAbKJiHYIf8Ta';
update content_bodies set title = '内田理央｜心華やぐ小江戸へ 川越さんぽ旅', description = '内田理央さんが訪れたのは、埼玉県初の市として大正11年に誕生し、令和4年に市制施行100周年を迎えた川越市です。歴史ある町並みには観光やグルメスポットが豊富にあり、1日では巡り切れないほどの魅力があります。古き良き文化に包まれた“小江戸”川越での1泊2日の旅では、川越氷川神社や蔵造りの町並み、シマノコーヒー大正館での休憩、うなぎ林屋での極上うな重、HAZEでの和ろうそく作り、小江戸蔵里での地酒試飲、そして美々庵での着物体験など、様々な楽しみが待っています。' where id = 'B3E3uXNkfHscGn8oKjweM';
update content_bodies set title = 'Rio Uchida''s Heartwarming Trip to Kawagoe: A Stroll Through the Little Edo', description = 'Rio Uchida visits Kawagoe City, established as Saitama''s first city in 1922 and celebrating its 100th anniversary in 2022. This historic town is filled with numerous attractions and gourmet spots, making it impossible to explore everything in just one day. The journey includes a one-night, two-day stay in the charming ''Little Edo'' Kawagoe, where visitors can enjoy walking through the streets steeped in traditional culture. Highlights of the trip include visiting the famous Hikawa Shrine, strolling through the Kurazukuri townscape, relaxing at Shimano Coffee Taisho-kan, savoring exquisite unaju at Unagi Hayashiya, experiencing candle-making at HAZE, tasting local sake at Koedo Kurari, and transforming into a kimono at Bibi-an.' where id = 'T-5cUJ_7AwZlAop3PZQW5';
update content_bodies set title = '土屋アンナ｜わたしのふるさと発見 栃木県那須町できらめき旅', description = '栃木県那須町は自然豊かなリゾート地で、カフェや美術館、テーマパークが点在しています。さらに、パンの激戦区であり、美味しいワイン作りにも適した場所です。土屋アンナさんは、那須町をより深く知るための充実した日帰り旅に出かけます。旅のプランには、那須ステンドグラス美術館で美しい教会や作品を見学し、ペニーレイン那須店で絶品のブレッドモーニングを楽しみ、那須高原HERB''sでアロマ手作り体験をし、NASU 661 WINE HILLSでワインを試飲し、お土産を購入する内容が含まれています。' where id = 'Z16hwglYZr1ln-yqyDNKu';
update content_bodies set title = 'Anna Tsuchiya | Discovering My Hometown: A Sparkling Trip in Nasu Town, Tochigi Prefecture', description = 'Nasu Town in Tochigi Prefecture is a resort area rich in nature, featuring cafes, art museums, and theme parks. It is also known for its competitive bread scene and ideal conditions for wine production. Anna Tsuchiya embarks on a fulfilling day trip to explore Nasu Town more deeply. The itinerary includes visiting the Nasu Stained Glass Museum to admire beautiful churches and artworks, enjoying a delicious bread morning at Penny Lane Nasu, experiencing handmade aromatherapy at Nasu Kogen HERB''s, and tasting wine at NASU 661 WINE HILLS, where she also purchases souvenirs.' where id = 'GSgf35A-JfjPe2n7FXFrC';
update content_bodies set title = '宮澤エマ｜また来たくなる 静岡県・伊豆の国市で一期一会の旅', description = 'NHK大河ドラマ「鎌倉殿の13人」で重要な役どころを演じる女優宮澤エマさんが、まだじっくりと観光をしたことがない伊豆の国市を訪れます。彼女は、自然や食、文化、歴史などの魅力を満喫するため、さまざまなスポットを巡ります。旅の中では、標高452mの「伊豆パノラマパーク」での絶景や、世界遺産「韮山反射炉」、クラフトビールを楽しむ「反射炉ビヤレストランほむら」、いちご工場、茶畑、そして香山寺での坐禅体験など、一期一会の出会いに胸を弾ませながら旅を楽しみます。' where id = 'sVyi3KKLImrbCYegATQ_n';
update content_bodies set title = 'Emma Miyazawa | A Journey in Izunokuni City, Shizuoka Prefecture That Makes You Want to Come Back', description = 'Actress Emma Miyazawa plays a significant role in the NHK historical drama ''Kamakura-dono no 13-nin,'' set in Izunokuni City. Although she has not yet explored the area thoroughly, she embarks on a journey to fully enjoy the city''s attractions. Excited about the unique encounters with nature, food, culture, and history, she sets off on her adventure, visiting various spots including the breathtaking Izu Panorama Park, the World Heritage Site Nirayama Reverberatory Furnace, and experiencing Zen meditation at Koyasan Temple.' where id = 'urXMGiSWZ5opU2864n1af';
update content_bodies set title = '稲村亜美｜わたしを元気にする 熊谷の旅【旅色Movie】', description = '埼玉県熊谷市を訪れた稲村亜美さんは、ラグビータウンとして知られるこの街で、ラグビーのモニュメントがある駅前から旅をスタートします。ラグビーが大好きな彼女は、熊谷の魅力を探る1泊2日の旅にワクワクしています。旅のプランには、「キャップ・ラガーズクラブハウス熊谷」でのラグビーグッズ購入、「熊谷スポーツ文化公園」でのラグビー体験、「大福茶屋さわた」でのパワーチャージ、「妻沼聖天山歓喜院」の散策、「星溪園」でのお茶体験、そして堀内製菓での「五家宝」お土産購入が含まれています。' where id = 'ujLYxWHl7bPD4YAxDgXR3';
update content_bodies set title = 'Ami Inamura | A Journey in Kumagaya that Energizes Me【Tabiiro Movie】', description = 'Ami Inamura visits Kumagaya City in Saitama Prefecture, a town thriving as a rugby hub. As a rugby enthusiast, she is excited to start her journey from the station, which features a rugby monument. The trip, lasting one night and two days, aims to explore the hidden charms of Kumagaya. The itinerary includes purchasing rugby goods at ''Cap Ruggers Clubhouse Kumagaya'', trying rugby at ''Kumagaya Sports Culture Park'', recharging at ''Daifuku Chaya Sawata'', strolling through ''Minuma Seitenzan Kanki-in'', experiencing tea at ''Seikeien'', and picking up ''Gokabo'' sweets as souvenirs from Horiuchi Seika.' where id = 'klm21dGY6YJa9KsyOJqNR';
update content_bodies set title = '美村里江：わたしらしい東京を探しに', description = '東京は常に変化し続ける“未完のまち”であり、新しい文化を吸収しながらも歴史的な情緒を残しています。多くの人が知っている東京はほんの一部であり、まだまだ知らないことがたくさんあります。この記事では、東京の今と昔を探求し、自分自身の好きな東京を見つけることを促しています。美村里江は1984年に埼玉県で生まれ、2003年にドラマ『ビギナー』でデビューし、その後多くのドラマや映画、舞台で活躍しています。また、エッセイや書評の執筆活動も行っており、著書もあります。' where id = 'IDFkw-KfjExlZm8XWExse';
update content_bodies set title = 'Rie Mimura: Exploring My Tokyo', description = 'Tokyo is a city that is constantly evolving, described as an ''unfinished city'' that absorbs new cultures while retaining its historical charm. While many are familiar with only a small part of Tokyo, there is so much more to discover. This article encourages readers to explore both the contemporary and historical aspects of Tokyo to find their own unique connection to the city. Rie Mimura, born in 1984 in Saitama, made her debut in the drama ''Beginner'' in 2003 and has since appeared in numerous television dramas, films, and stage productions. She is also a writer, known for her essays and book publications.' where id = 'pKgVcDrQK4VeLT1_aD3AI';
update content_bodies set title = '米倉涼子｜移り変わる東京を体験【旅色Movie】', description = '2020年、東京は再開発が進み、新たな姿に生まれ変わりつつあります。この動画では、明治から昭和にかけてのモダンな建築が今も愛されている場所や、新たに生まれ変わったスポットを紹介し、東京の過去と現在を見通す試みがなされています。米倉涼子は1975年8月1日生まれ、神奈川県出身で、モデルから女優に転身し、ドラマ『松本清張黒革の手帖』や『ドクターX』などに出演。2008年にはミュージカル『CHICAGO』の日本版で主演を務め、2012年と2019年には日本人女優として初めてブロードウェイに出演しました。11月6日には映画「ブラック・ウィドウ」でスカーレット・ヨハンソン演じるナターシャ・ロマノフの声優を務めることが決定しています。' where id = 'EbRrZBhru6xyjbl4toVZo';
update content_bodies set title = 'Ryoko Yonekura | Experience the Changing Tokyo [Tabiiro Movie]', description = 'In 2020, Tokyo is undergoing continuous redevelopment, transforming into a new city. The video explores beloved modern architecture from the Meiji to Showa eras, as well as newly revitalized spots, offering a glimpse into both the past and present of Tokyo. Ryoko Yonekura, born on August 1, 1975, in Kanagawa Prefecture, transitioned from modeling to acting, starring in popular dramas such as ''Matsumoto Seicho''s Kurokawa no Techou'' and ''Doctor X.'' She made her musical debut in the Japanese version of ''CHICAGO'' in 2008 and became the first Japanese actress to perform on Broadway three times in 2012 and 2019. She will voice the character Natasha Romanoff in the Japanese release of ''Black Widow'' on November 6.' where id = '_LCpe1xWTTEewFXUjNmsR';
update content_bodies set title = 'トリンドル玲奈｜鎌倉さんぽ、江ノ電方面をぶらり', description = '鎌倉は、訪れる目的やエリアによって多彩な表情を見せる観光地です。この動画では、トリンドル玲奈さんが夏の終わりの鎌倉を巡り、その魅力を紹介します。「古都」としての一面だけでなく、様々な魅力を持つ鎌倉の姿を楽しむことができます。トリンドル玲奈さんは1992年1月23日生まれ、オーストリア・ウィーン出身で、2011年に『JJ』のモデルとして芸能活動を開始しました。2012年にはドラマ『黒の女教師』で女優デビューし、以来多くの作品に出演しています。2019年からは『with』のモデルとしても活躍し、バラエティ番組でも人気を博しています。' where id = '7FSK4bB_at8lyiIO6CUVN';
update content_bodies set title = 'Reina Trindl''s Stroll in Kamakura: Exploring the Enoden Area', description = 'Kamakura, a rich tourist destination, showcases diverse expressions depending on the purpose of the visit or the area explored. In this video, Reina Trindl takes us on a journey through Kamakura at the end of summer, highlighting its charm beyond just being an ''ancient capital.'' Reina Trindl, born on January 23, 1992, in Vienna, Austria, began her entertainment career as a model for ''JJ'' in 2011. She made her acting debut in the 2012 drama ''Kuro no Onna Kyoushi'' and has since appeared in various works. Since 2019, she has been a model for ''with'' and is also active in variety shows as a popular talent.' where id = 'GjERF_KSNhXE-ZCfj0k3L';
update content_bodies set title = '志田未来｜箱根で過ごす、アカデミックな旅時間 60秒ver 【旅色Movie】', description = 'プライベートでも旅のしおりを自作するほどの旅好きの志田未来さんが、新しい箱根を巡る旅ムービーを60秒で紹介します。箱根は国内観光リゾートの元祖とも言われ、息をのむ絶景や歴史情緒、アート、グルメなど、エリアごとに異なる魅力が詰まっています。この特別なムービーでは、箱根町の美しさを体験できる内容となっています。フルバージョンや他のバージョンもリンクからご覧いただけます。' where id = 'fd--YnVRA6I0bPhNQ1qnN';
update content_bodies set title = 'Mirai Shida | An Academic Journey in Hakone - 60 Seconds Version [Tabiiro Movie]', description = 'In this 60-second travel movie, Mirai Shida, an avid traveler who even creates her own travel itineraries, explores the new attractions of Hakone. The film showcases the rich experiences that Hakone, a pioneer of domestic tourist resorts, has to offer, including breathtaking views, historical charm, art, and gourmet delights. Each area reveals unique attractions, making it a special movie for those interested in the beauty of Hakone Town, Kanagawa Prefecture, Japan. For a full version, visit the provided link.' where id = 'dZnwmfrW7-XJcTZJ7fnUb';
update content_bodies set title = '志田未来｜箱根で過ごす、アカデミックな旅時間 【旅色Movie】', description = '旅好きの志田未来さんが箱根の新しい魅力を巡る旅ムービーです。箱根は国内観光リゾートの元祖であり、息をのむ絶景や歴史情緒、アート、グルメなど、町の魅力が詰まっています。特別なムービーを通じて、各エリアの魅力を体験できます。さらに、箱根町の旅をコンパクトに知りたい方のために、60秒版や15秒版も用意されています。志田未来さんは1993年生まれで、2006年にドラマ『14才の母』で主演を務め、その後も多くの作品に出演し、声優としても活躍しています。' where id = 'BLtjW35_P5HIzR2fRK88Q';
update content_bodies set title = 'Mirai Shida | An Academic Journey in Hakone [Tabiiro Movie]', description = 'Mirai Shida, a travel enthusiast who even creates her own travel itineraries, explores the new attractions of Hakone in this travel movie. Hakone, known as the original domestic tourist resort, is filled with the joys of travel, showcasing breathtaking views, historical charm, art, and gourmet experiences that highlight the unique appeal of the town. For those interested in a more compact overview of Hakone, shorter versions of the movie are available. Mirai Shida, born on May 10, 1993, in Kanagawa Prefecture, gained fame for her role in the drama ''14-Year-Old Mother'' in 2006 and has since received accolades, including the Japan Academy Prize for Newcomer of the Year for her performance in ''No One''s Protecting Me.'' She continues to work in various dramas and films, as well as voice acting.' where id = 'UXQpD36IgogMx8UiI5s0i';
update content_bodies set title = '志田未来｜箱根で過ごす、アカデミックな旅時間 15秒ver 【旅色Movie】', description = 'プライベートでも旅のしおりを自作するほどの旅好きの志田未来さんが、新しい箱根を巡る旅ムービーを15秒で紹介します。箱根は国内観光リゾートの元祖とも言われ、息をのむ絶景や歴史情緒、アート、グルメなど、町の魅力が詰まった特別な映像です。フルバージョンや60秒バージョンも用意されており、さらに箱根町の魅力を知りたい方におすすめです。' where id = 'qB80KOAgU6KsluOLFIApz';
update content_bodies set title = 'Mirai Shida | An Academic Journey in Hakone - 15 Seconds Version [Tabiiro Movie]', description = 'In this 15-second travel movie, Mirai Shida, an avid traveler who even creates her own travel itineraries, explores the new attractions of Hakone. The film showcases the rich experiences that Hakone, a pioneer of domestic tourist resorts, has to offer, including breathtaking views, historical charm, art, and gourmet delights. Viewers can witness the unique appeal of the town through this special movie. For a full version, visit the provided YouTube link.' where id = '2P2GYjyzt8A8ma6UnSpI8';
update content_bodies set title = '堀田茜｜静岡県・御殿場市を巡る旅 【旅色Movie】', description = '富士山を望む静岡県御殿場市を訪れた堀田茜さん。御殿場ならではの美しい富士山ビューを楽しみながら、豊かな自然の恵みを味わい、富士山について深く知る旅が始まります。旅の中では、地元のそば店や公園、和菓子屋、アウトレットでのヘリ体験など、様々なスポットを訪れ、御殿場の魅力を探求します。' where id = 'ElDSDhIJQ0FOrWVslpSJH';
update content_bodies set title = 'Akane Hotta''s Journey in Gotenba City, Shizuoka Prefecture | Tabiiro Movie', description = 'Akane Hotta visits Gotenba City, a place where you can admire Mount Fuji. The city offers a unique view of the mountain, characterized by its gentle slopes and symmetrical shape. Hotta''s journey begins as she seeks to discover the deep and unseen charms of Gotenba, enjoying breathtaking scenery, indulging in local natural delicacies, and learning more about Mount Fuji. The itinerary includes stops at local soba restaurants, parks, traditional sweet shops, and even a helicopter experience at the Gotenba Premium Outlets.' where id = 'JVni2TZcwSXfEB-Heibxe';
update content_bodies set title = '板谷由夏｜都留市で見つけた私のサードプレイス【旅色Movie】', description = '山梨県都留市は、澄んだ空気と豊かな緑に囲まれ、長い歴史が息づく場所です。江戸時代の俳人・松尾芭蕉ゆかりの地としても知られています。板谷由夏さんは、自然のパワースポットやグルメを楽しめる大人のサードプレイスを旅しました。旅の中では、都留を代表する「太郎・次郎滝」や「戸塚醸造店」での日本酒とお酢の見学、イタリアの郷土料理を楽しむ「Locanda Abbracci」、お土産選びの「ドレッシング工房freckle」、そして「cafe織水」でのリラックスタイムが含まれています。' where id = 'OplBRDQfZ_4n9CrybZu9Y';
update content_bodies set title = 'Yuka Itaya | My Third Place Found in Tsuru City | Tabiiro Movie', description = 'In the rich greenery and clear air of Tsuru City, Yamanashi Prefecture, a place steeped in history, Yuka Itaya explores a sophisticated third place known for its natural power spots and gourmet experiences. The journey includes visits to the famous Taro and Jiro Falls, a tour of the Tozuka Brewery to learn about sake and vinegar production, enjoying Italian regional cuisine at Locanda Abbracci, selecting souvenirs at the Dressing Workshop Freckle, and relaxing at Cafe Orimizu.' where id = 'xWqO5kvpQ21cYU5B8W0eb';
update content_bodies set title = '松井玲奈｜山梨県河口湖でアート旅【旅色Movie】', description = 'この旅では、写真映えする意外な場所を訪れ、旅の楽しさを味わいます。河口湖は初めての訪問で、ほとんどの場所から富士山が見えることに驚きました。曇りの日でしたが、近くで富士山を見られるのは嬉しい体験でした。特に印象的だったのは北口本宮冨士大社で、大きな杉の木が連なり、圧倒的な存在感がありました。参道の灯籠が苔むしている様子も素晴らしく、苔好きな私としては見入ってしまいました。新鮮な空気を吸いながら灯籠から時間の流れを感じるのは素敵な体験でした。また、「HanaCafe Kikyou」でいただいた「桔梗信玄ソフト」は、きなこと黒蜜がかかった和風のソフトクリームで、特に黒蜜の部分が美味しかったです。' where id = '-PpPsWscB_GNRlZBO7Yrl';
update content_bodies set title = 'Rena Matsui | Art Journey at Lake Kawaguchi【Tabiiro Movie】', description = 'This journey takes you to picturesque and unexpected locations, allowing you to experience the joy of travel. It was my first visit to Lake Kawaguchi, where I was surprised to see Mount Fuji from almost every spot I visited. Despite the cloudy weather, being able to see Mount Fuji up close was a treat. A highlight was the Kitaguchi Hongu Fuji Sengen Shrine, where the impressive rows of large cedar trees left a strong impression. The moss-covered lanterns along the path from the torii gate to the main shrine were also remarkable. As a moss lover, I found myself captivated by the lanterns. Walking along the path while breathing in the fresh air and feeling the passage of time through the lanterns was a wonderful experience. Additionally, I enjoyed the ''Kikyō Shingen Soft'' at ''HanaCafe Kikyou,'' a soft-serve ice cream with a Japanese twist, topped with kinako and black syrup, which was incredibly delicious.' where id = 'J8BkHrR_7oRN-VaNqWLY0';
update content_bodies set title = '矢田亜希子｜高原の自然と名湯に癒される山ノ内町で大人の冬旅', description = '長野駅から車で約1時間の山ノ内町は、スキーやスノボをしなくても楽しめる圧倒的な冬景色と極上の温泉、さらには美味しいグルメが揃っています。矢田亜希子さんもその魅力に大喜び。北信州の冬を満喫する旅に出かけましょう。彼女の旅を通じて、自然の美しさと温泉の癒しを体験できます。' where id = 'YHQis0gR1ZTNPjc1wvc4Q';
update content_bodies set title = 'Akiko Yada | A Relaxing Winter Trip in Yamanouchi Town Surrounded by Nature and Hot Springs', description = 'Yamanouchi Town, located about an hour''s drive from Nagano Station, offers stunning winter scenery, exquisite hot springs, and delicious cuisine, much to the delight of Akiko Yada. This trip invites you to enjoy the winter of Northern Shinshu, even if you don''t ski or snowboard. Join Akiko Yada as she explores the beauty and charm of this winter destination.' where id = 'TxEUdvaXfbn2rSG7mC5zB';
update content_bodies set title = '新垣結衣｜いまの旅の気分はウェルネス in 三重県', description = '17周年を迎えた今号では、新垣結衣さんが三重県の伊勢志摩と鳥羽へ“ウェルネスな旅”に出かけました。“ウェルネスな旅”は、心身を健やかにする自分らしい旅を意味し、自分のご機嫌をとれることが大切です。この旅では、瀧原宮での挨拶や、鳥羽市立海の博物館での歴史体験、松阪牛のすき焼きを楽しむ牛銀での食事、神明神社での願い事、志摩地中海村でのウェルネスなひと時などが紹介されています。新しい旅のスタイルがここにあります。' where id = 'BsckiW9-sX2B0h4k9xQBp';
update content_bodies set title = 'Yui Aragaki | Wellness Travel in Mie Prefecture', description = 'In this 17th-anniversary issue, Yui Aragaki embarks on a ''wellness journey'' to Ise-Shima and Toba in Mie Prefecture. The concept of a ''wellness journey'' is interpreted by Tabiiro as a personal trip that promotes mental and physical well-being. Essentially, if you can take care of your own happiness, anything goes! This journey introduces a travel style that is yet to be discovered. The video includes visits to various locations such as Takihara Shrine, the Toba City Museum of History and Folklore, and a delightful experience at Ushigin for Matsusaka beef sukiyaki, culminating in a wellness moment at Shima Mediterranean Village.' where id = 'TTBouYZFOb99YMqx6D3xO';
update content_bodies set title = '宇垣美里｜水の都・大垣（岐阜）を巡る旅 15秒ver', description = '宇垣美里さんが訪れたのは、日本の中心に位置する岐阜県大垣市です。この街は豊かな地下水に恵まれ、「水の都」として知られています。松尾芭蕉ゆかりの地や、石田三成が本拠地とした大垣城など、歴史的なスポットが豊富にあります。宇垣さんと共に、水の都を巡る旅に出かけましょう。' where id = '_of7ubs664NkoScdDbdcw';
update content_bodies set title = 'Misato Ugaki | A Journey Through the Water City of Ogaki (Gifu) - 15 Seconds Version', description = 'Misato Ugaki visits Ogaki City in Gifu Prefecture, located in the heart of Japan. Known as the ''Water City'' due to its abundant underground water, Ogaki is rich in historical sites, including places associated with Matsuo Basho and Ogaki Castle, which was the stronghold of Ishida Mitsunari. Join Ugaki on a journey to explore this charming city.' where id = 'XDvCLx49qcQeBGP1FPe1t';
update content_bodies set title = '久間田琳加｜いいとこどりの下田（静岡）ホッピング【旅色Movie】', description = 'りんくまこと久間田琳加さんが、伊豆半島の南側に位置する下田市で絶景とグルメを楽しむ旅を紹介します。下田は江戸時代にペリーが来航し、日本で初めて開港した歴史ある港町です。美しい白浜のビーチや、ダイナミックな景観が広がる伊豆半島ジオパークなど、自然のエネルギーに満ちたスポットが魅力です。また、キンメダイをはじめとする美味しいグルメも堪能します。この旅は、下田の美しい風景と食の魅力を余すところなく伝えています。' where id = 'w9Yxer6y46R3dd8tDhWkr';
update content_bodies set title = 'Rinka Kumada''s Exciting Trip to Shimoda, Shizuoka | Tabiiro Movie', description = 'Rinka Kumada, known as Rinkuma, embarks on a delightful journey in Shimoda City, located on the southern side of the Izu Peninsula, where she enjoys breathtaking views and delicious cuisine. Shimoda is a historic port town, known for being the first open port in Japan after Commodore Perry''s arrival during the Edo period. The area boasts beautiful beaches like Shirahama and dynamic landscapes within the Izu Peninsula Geopark, offering vibrant natural spots. Rinka also indulges in local delicacies, including Kinmedai, a type of fish. This trip showcases the best of Shimoda''s scenic beauty and culinary delights.' where id = 'CazfQ4UKp33ltUarBoYZZ';
update content_bodies set title = '【石川 恋】東尋坊や丸岡城へ…福井県坂井市の旅を堪能＜旅色＞60秒ver', description = '福井県坂井市を石川恋さんが旅する様子を収めたムービーです。美しい絶景や、普段は見られない石川恋さんの素顔が楽しめます。旅の中では、東尋坊や丸岡城などの名所が紹介されており、坂井市の魅力が伝わります。坂井市の旅をもっと詳しく知りたい方にはフルバージョンが、短時間で見たい方には15秒バージョンも用意されています。' where id = 'yzdNMTstk2-TdnnMmAMY4';
update content_bodies set title = 'Ishikawa Ren Enjoys a Trip to Sakai City, Fukui Prefecture - 60-Second Version', description = 'Ishikawa Ren travels to Sakai City in Fukui Prefecture, showcasing stunning views and revealing her rarely seen side in a travel movie. The video highlights the beautiful scenery of the area, including famous spots like Tojinbo and Maruoka Castle. For those interested in a more in-depth exploration of Sakai City, a full version is available, as well as a shorter 15-second version for a quick glimpse.' where id = 'xh_QF9WhP0lfzCUSxuQKu';
update content_bodies set title = '【石川 恋】福井県坂井市への旅＜旅色＞15秒ver', description = '福井県坂井市を石川恋さんが旅する様子を15秒のムービーで紹介しています。旅先の絶景や、普段は見られない石川恋さんの素顔が楽しめる内容です。坂井市の旅についてもっと知りたい方はフルバージョンを、短いバージョンを見たい方は60秒バージョンも用意されています。石川恋さんは1993年に栃木県で生まれ、書籍『学年ビリのギャルが1年で偏差値を40上げて慶應大学に現役合格した話』の表紙モデルとして注目を集め、その後女優や『CanCam』の専属モデルとして活躍しています。' where id = 'ujIGYE41Wp5ouApfovgua';
update content_bodies set title = 'Ishikawa Ren''s Trip to Sakai City, Fukui Prefecture - 15 Seconds Version', description = 'Ishikawa Ren travels to Sakai City in Fukui Prefecture, showcasing stunning views and her rarely seen genuine side in this travel movie. For those who want to know more about the trip, a full version is available, as well as a 60-second version for a brief glimpse. Ishikawa Ren, born in Tochigi Prefecture in 1993, gained attention as the cover model for the book ''The Story of a Gal Who Raised Her Academic Score by 40 Points in a Year and Entered Keio University.'' She has since worked as an actress and a model for ''CanCam.''' where id = '0nmcz1MpJoF6zINu5NIrO';
update content_bodies set title = '藤原紀香｜金沢・加賀で日本ならではの美を再発見する旅', description = '北陸の観光都市・金沢と歌舞伎の町・小松がある加賀で、日本の美を再発見する旅を紹介します。藤原紀香は、海外旅行の経験を通じて日本文化の理解の重要性を感じています。彼女は、酒造りや菓子作り、紙漉き、漆塗り、着物工房などの伝統工芸を体験することを楽しんでおり、伝統技術を継ぐ世代が減少していることを懸念しています。旅を通じて日本の文化を見直す機会が増えることを願い、今こそ「日本文化を楽しむ旅」が重要だと感じています。コロナが早く収束し、旅行ができるようになることを期待しています。' where id = 'pnd8Kalex5a6xZOmTOAmF';
update content_bodies set title = 'Norika Fujiwara | A Journey to Rediscover Japan''s Unique Beauty in Kanazawa and Kaga', description = 'This video article explores the rich cultural and historical regions of Kanazawa and Kaga, known for their natural beauty. Norika Fujiwara reflects on her past travels abroad and emphasizes the importance of understanding Japan''s own culture. She enjoys experiencing traditional crafts such as sake brewing, confectionery making, paper crafting, lacquer work, and kimono production. With a decline in the number of artisans preserving these traditions, she believes that travel can inspire people to appreciate Japan''s heritage. Fujiwara feels that now is the perfect time for a journey to enjoy Japanese culture, hoping for a swift end to the COVID-19 pandemic to enable more travel opportunities.' where id = 'w7lhZpD50uOBaKHvtHMPc';
update content_bodies set title = '桜井日奈子｜石川県七尾市・和倉温泉を巡る旅 60秒Ver', description = '桜井日奈子さんと共に、北陸の名湯として知られる石川県七尾市の和倉温泉を巡る旅に出かけます。新鮮な海の幸を楽しみ、浴衣を着て温泉街を散策し、伝統的な美に触れることができます。1泊2日の旅の見どころをダイジェストでお届けします。' where id = 'IzYew9cRXCnhIFdPdOJ0l';
update content_bodies set title = 'Hinako Sakurai''s Journey in Nanao City, Ishikawa Prefecture - Wakura Onsen 60-Second Version', description = 'Join Hinako Sakurai on a journey through Wakura Onsen, a renowned hot spring area in Nanao City, Ishikawa Prefecture. Enjoy fresh seafood, stroll through the hot spring town in a yukata, and experience traditional beauty. This digest presents a wealth of highlights from a 1-night, 2-day trip.' where id = '8ufuZHmrq-QYIEFRunMdQ';
update content_bodies set title = '桜井日奈子｜石川県七尾市・和倉温泉を巡る旅 30秒Ver', description = '桜井日奈子さんと共に、北陸の有名な温泉地である石川県七尾市・和倉温泉を巡る旅に出かけます。新鮮な海の幸を楽しみ、浴衣を着て温泉街を散策し、伝統的な美に触れることができます。1泊2日の旅の見どころをダイジェストでお届けします。' where id = 'LScroad5yiebg15GgUlvv';
update content_bodies set title = 'Hinako Sakurai''s Journey in Nanao City, Ishikawa Prefecture - Wakura Onsen 30-Second Version', description = 'Join Hinako Sakurai on a journey through Wakura Onsen, a renowned hot spring area in Nanao City, Ishikawa Prefecture. Enjoy fresh seafood, stroll through the hot spring town in a yukata, and experience traditional beauty. This digest presents a wealth of highlights from a 1-night, 2-day trip.' where id = '5iPHnUG6MERRz2R9NBnUN';
update content_bodies set title = '桜井日奈子｜石川県七尾市・和倉温泉を巡る旅 【旅色Movie】', description = '桜井日奈子さんと共に、石川県七尾市の和倉温泉を巡る旅に出かけます。新鮮な海の幸を楽しみ、浴衣を着て温泉街を散策し、伝統的な美に触れる1泊2日の旅です。観光列車「花嫁のれん号」に乗り、能登食祭市場で浜焼きを味わい、青林寺で穏やかな時間を過ごし、坐禅体験でリフレッシュします。また、和倉温泉総湯の足湯でひと休みし、迫力満点の祭り会館を訪れ、人気のジェラート店「能登ミルク」で甘いひとときを楽しむことができます。' where id = 's31vJFnRYYwSPge2h_zQn';
update content_bodies set title = 'Hinako Sakurai''s Journey Through Nanao City and Wakura Onsen, Ishikawa Prefecture | Tabiiro Movie', description = 'Join Hinako Sakurai on a journey through Wakura Onsen, a renowned hot spring area in Nanao City, Ishikawa Prefecture. Experience the local seafood, stroll through the hot spring town in a yukata, and immerse yourself in traditional beauty. This 1-night, 2-day trip is packed with highlights, including a ride on the sightseeing train ''Hanayome Noren'', tasting grilled seafood at ''Noto Shokumatsuri Market'', enjoying a peaceful moment at ''Seirinji Temple'', refreshing with a Zen meditation experience, relaxing at the foot bath of ''Wakura Onsen Souyu'', visiting the impressive ''Festival Hall'', and indulging in popular gelato at ''Noto Milk''.' where id = 'PrKh1WKDjO0qaEqEVhBDD';
update content_bodies set title = '岡田結実｜いわて北三陸・洋野町で海まちトリップ', description = '岡田結実さんが訪れたのは、岩手県沿岸北部の洋野町です。自然が豊かでグルメな町を好む岡田さんにとって、洋野町は楽しい体験が満載の場所です。美しい景色と美味しい料理を楽しむ欲張りな旅が展開されます。旅のハイライトには、有家海岸の訪問、新鮮なホヤ料理を楽しむ「食事処 はまなす亭」、マイ箸作り体験ができる「おおのキャンパス」、そして「種市海浜公園」でのリラックスした散歩が含まれています。岡田さんの明るいキャラクターが地元の文化や料理を探求する中で輝いています。' where id = 'FqU3Gvvt41_iXUYm6A89v';
update content_bodies set title = 'Yui Okada''s Coastal Trip in Hirono Town, Iwate', description = 'Yui Okada visits Hirono Town, located in the northern coastal area of Iwate Prefecture. Known for her love of nature and gourmet food, Okada finds Hirono Town to be a delightful destination filled with enjoyable experiences. The trip includes beautiful scenery and delicious cuisine, making it a fulfilling journey. Highlights of her adventure include visiting the stunning Ariake Coast, trying fresh sea urchin dishes at Hamanasutei, creating personalized chopsticks at Oono Campus, and enjoying a relaxing stroll at Taneguchi Seaside Park. Okada''s vibrant personality shines through as she explores the local culture and culinary delights.' where id = 'uWOTa9BZS8j0wgXO4nM5v';
update content_bodies set title = '橋本マナミ｜福島県・いわき市を巡る旅 【旅色Movie】', description = '橋本マナミさんが訪れたのは、福島県の最南端に位置するいわき市です。この街は「いわき湯本温泉」や「フラガール」の誕生地として知られ、年間を通じて温暖な気候に恵まれています。旅では、美しい自然と温かい人々との出会いが描かれています。主な見どころは、「薄磯海岸」でのフラ体験、「波立海岸・弁天島」での絶景、「アクアマリンふくしま」での海の知識の深耕、「三崎公園」でのいわき市の全景、「温泉神社」での涼の体験、「鶴のあし湯」での癒し、そして「とうふ工房・奈良屋」での名物ソフトを楽しむことです。' where id = 'K96oxSoIPT03HTactBuDW';
update content_bodies set title = 'Manami Hashimoto''s Journey in Iwaki City, Fukushima Prefecture | Tabiiro Movie', description = 'In this travel movie, Manami Hashimoto explores Iwaki City, located at the southernmost tip of Fukushima Prefecture. Known for its ''Iwaki Yumoto Onsen'' and as the birthplace of ''Hula Girls'', the city enjoys a mild climate year-round. The journey showcases the beautiful nature and warm-hearted people of Iwaki. Highlights include a hula experience at ''Hanaiso Beach'', breathtaking views at ''Naminari Beach and Benten Island'', learning about the ocean at ''Aqua Marine Fukushima'', panoramic views from ''Misaki Park'', enjoying coolness at ''Onsen Shrine'', relaxing at ''Tsuru''s Ashiyu'', and taking a break with the famous soft serve at ''Tofu Workshop Nara-ya''.' where id = 'mVzjGgwvgkyBR-_zybrJC';
update content_bodies set title = '本田望結｜心に残る一瞬を求めて 花火の里・福島県浅川町へ【旅色Movie】', description = '浅川町は田園に囲まれた自然豊かな町で、江戸時代から花火を打ち上げている“花火の里”として知られています。見学施設や歴史文化を感じさせるスポットが点在し、町の魅力を知るためのおすすめコースや、年間を通じて開催される印象的な花火イベントが紹介されています。また、2004年生まれの俳優・フィギュアスケーター本田望結のプロフィールも紹介され、彼女の人気の理由や最近の活動について触れられています。' where id = '_Amy9nwCtJAk_vIgWKIsc';
update content_bodies set title = 'Miyu Honda | Seeking Memorable Moments in Asakawa Town, Fukushima Prefecture - A Travel Color Movie', description = 'Asakawa Town is a nature-rich area surrounded by rural landscapes, known as the ''Fireworks Town'' since the Edo period. The town features various historical and cultural spots, including a fireworks museum. This video provides a digest of the town''s attractions, including recommended courses and the stunning fireworks events held throughout the year that are sure to leave a lasting impression. The profile of Miyu Honda, a talented actress and figure skater born in 2004, is also highlighted, showcasing her rise to fame and recent works.' where id = '97zR-bHtVuLW0AJOyJKW8';
update content_bodies set title = '内田理央｜福島県白河市でのんびりトリップ【旅色Movie】', description = '女優の内田理央さんが、自然と歴史情緒にあふれる福島県白河市を訪れます。この地域は「みちのくの玄関口」として知られ、豊かな自然と文化的な魅力が詰まっています。内田さんの旅を通じて、白河市の美しさと文化的な重要性が紹介されます。' where id = '_Q7rIgKx6C9eTtFX86PVd';
update content_bodies set title = 'Riao Uchida''s Relaxing Trip in Shirakawa City, Fukushima Prefecture | Tabiiro Movie', description = 'Actress Riao Uchida visits Shirakawa City in Fukushima Prefecture, known as the ''Gateway to Michinoku,'' rich in nature and historical charm. The trip showcases the beauty and cultural significance of the area.' where id = 'dnoLnBQrqExPv-OzTJBjI';
update content_bodies set title = '常盤貴子｜期待を超える、すごい町　美しき釧路町', description = '常盤貴子さんが訪れたのは、1980年に町制施行された北海道釧路町です。釧路町は北海道の南東部に位置し、南側は太平洋、そして原始時代から続く釧路湿原国立公園が広がっています。観光、グルメ、アクティビティなど、どの選択肢も期待以上の感動を提供し、訪れる者を温かく迎えます。美しき釧路町を訪れ、その魅力を体験しましょう。' where id = 'FIHfV0euXpgjXN9QjYgTN';
update content_bodies set title = 'Takako Tokiwa | A Town Beyond Expectations: Beautiful Kushiro Town', description = 'Takako Tokiwa visits Kushiro Town, established in 1980 in Hokkaido''s southeastern region. This town, bordered by the Pacific Ocean and home to the ancient Kushiro Wetland National Park, offers visitors unforgettable experiences through its tourism, gourmet food, and activities. Each choice promises to exceed expectations, welcoming visitors warmly and leaving a lasting impression. Explore the beautiful Kushiro Town and discover its wonders.' where id = 'HqyTjjW9Ry9-c2xcBMN05';
update content_bodies set title = '森七菜｜“楽しい”がキラキラ輝く 函館さんぽ【旅色Movie】', description = '森七菜さんが北海道の函館市を訪れ、異国情緒あふれる街並みや夜の美しいイルミネーション、おいしい海鮮を存分に楽しむ様子を紹介しています。飾らない人柄が光る楽しい旅の様子が映し出されており、見ているだけでウキウキするような体験が詰まっています。' where id = 'lwpqvtnKnJpMYKrrSOr-0';
update content_bodies set title = 'Nana Mori | A Sparkling Fun Stroll in Hakodate【Tabiiro Movie】', description = 'Nana Mori visits Hakodate, Hokkaido, where she enjoys the charming streets filled with exotic atmosphere, beautiful illuminations at night, and delicious seafood. The video captures the joyful essence of her trip, showcasing her unpretentious personality and the delightful experiences she encounters throughout her journey.' where id = 'YOaQAGkVJk-SH0RiYzllu';
update content_bodies set title = '【川島海荷】北海道の秘境、岩内町でアクティブステイ＜旅色＞15秒ver', description = 'ニセコ連峰岩内岳に囲まれ、紺碧の日本海に面した岩内町は、地元で揚がる新鮮な海の幸や、港町としての歴史を伝えるスポット、スノーリゾートなど多彩な魅力にあふれています。川島海荷さんと共に、温かい町の人々と触れ合いながら自然を満喫する旅に出かけましょう。岩内町の旅をもっと知りたい方は、フルバージョンをご覧ください。' where id = 'wDxvUKwVpXBlJPjat5qSI';
update content_bodies set title = 'Kawashima Umika''s Active Stay in Iwanai Town, Hokkaido - 15 Seconds Version', description = 'Iwanai Town, nestled in the Niseko mountain range and facing the deep blue Sea of Japan, is rich in attractions, including fresh seafood from the local waters, historical sites reflecting its heritage as a port town, and snow resorts. Join Umika Kawashima on a journey to enjoy nature while interacting with the warm-hearted locals. For a more in-depth exploration of Iwanai Town, check out the full version.' where id = 'PpLMBZz47boQOL58z6Flq';
update content_bodies set title = '川島海荷と行く北海道・岩内町のアクティブステイ', description = 'ニセコ連峰岩内岳に囲まれ、紺碧の日本海に面する岩内町は、地元で揚がる新鮮な海の幸や、港町としての歴史を伝えるスポット、スノーリゾートなど多彩な魅力にあふれています。川島海荷さんと共に、温かい町の人々と触れ合いながら自然を満喫する旅に出かけます。岩内町の旅をもっと知りたい方は、フルバージョンのリンクをチェックしてください。' where id = 'PpyNRtYZyV1zdXZ5yfJWu';
update content_bodies set title = 'Active Stay in Iwanai Town, Hokkaido with Uika Kawashima - 60 Seconds Version', description = 'Iwanai Town, nestled in the Niseko mountain range and facing the deep blue Sea of Japan, is rich in attractions, including fresh seafood from the local waters, historical sites reflecting its heritage as a port town, and snow resorts. Join Uika Kawashima on a journey to enjoy nature while interacting with the warm-hearted locals. For a more in-depth exploration of Iwanai Town, check out the full version linked in the description.' where id = 'KnetkMXV3I0wmoKk20rPZ';
update content_bodies set title = '川島海荷｜北海道岩内町でアクティブステイ【旅色Movie】', description = 'ニセコ連峰岩内岳に囲まれ、紺碧の日本海に面した岩内町は、前浜で揚がる新鮮な海の幸や、港町としての歴史を伝えるスポット、スノーリゾートなど多彩な見どころがあります。川島海荷さんと共に、温かい町の人々と触れ合いながら自然を満喫する旅に出かけます。旅のルートはリンクから確認できます。また、岩内町の旅をもっとコンパクトに知りたい方は60秒版や15秒版の動画もご覧ください。' where id = 'Ml0g-RgdtzS2phMEpAyCf';
update content_bodies set title = 'Kawashima Umika | Active Stay in Iwanai Town, Hokkaido【Tabiiro Movie】', description = 'Iwanai Town, nestled in the Niseko mountain range and facing the deep blue Sea of Japan, is rich in attractions, including fresh seafood from the local fishing grounds, historical sites reflecting its heritage as a port town, and ski resorts. Join Umika Kawashima on a journey to enjoy nature while interacting with the warm-hearted locals. For a more compact overview of the trip, check out the 60-second version or the 15-second version linked in the description.' where id = 'nkLy91LQhGLwSzJsPu3v2';
update content_bodies set title = 'マギー｜冬の北海道 白糠と釧路でおいしいグルメと北の動物たちに出合う旅【旅色Movie】', description = '広大な大地と果てしない海が魅力の白糠町でおいしいグルメを楽しんだ後、釧路湿原を訪れ北の動物たちにも挨拶をするマギーさんの旅を紹介します。冬の美しい風景の中、のんびりとした時間を過ごしながら、北海道東部の魅力を満喫する様子が描かれています。' where id = 'T8V1txizz1o0OISGKT9Bi';
update content_bodies set title = 'Maggie | A Journey to Enjoy Delicious Gourmet and Northern Animals in Shiranuka and Kushiro, Hokkaido in Winter【Tabiiro Movie】', description = 'This video showcases the beautiful winter landscapes of eastern Hokkaido, where Maggie explores the vast land and endless sea of Shiranuka. After enjoying delicious local cuisine, she visits the Kushiro Wetlands to greet the northern wildlife. The journey is a leisurely exploration of the region''s charm.' where id = 'fbwnk7MTHntcNUavVWreb';
update content_bodies set title = '［稲村亜美］北の大地・上士幌の自然とグルメに出会う旅【旅色】15秒ver', description = 'スキーリゾート地として知られる上士幌町は、緑豊かな季節にも魅力を発揮します。旧国鉄士幌線の遺構や、牛やヤギがのんびりと放牧される広大な牧場、大地が育んだブランド牛などのグルメが楽しめます。明るい笑顔の稲村亜美さんと共に、大自然と美味しい食を満喫する旅に出かけましょう。' where id = 'CwvCEMSUzDH2LwYst1YID';
update content_bodies set title = 'A Journey to Discover Nature and Gourmet in Kamishihoro, Hokkaido with Ami Inamura【Tabiiro】15-second version', description = 'Kamishihoro, known as a ski resort, showcases its charm even in the vibrant green season. The area features remnants of the old National Rail Shihoro Line, vast pastures where cows and goats graze leisurely, and gourmet offerings including brand beef nurtured by the land. Join the cheerful Ami Inamura on a journey to enjoy the great outdoors and delicious food.' where id = 'ZB2vG8qG9St98HsiM14j_';
update content_bodies set title = '［稲村亜美］北の大地・上士幌の自然とグルメに出会う旅【旅色】60秒ver', description = 'スキーリゾート地として知られる上士幌町は、緑豊かな季節にも魅力を発揮します。旧国鉄士幌線の遺構や、牛やヤギがのんびりと放牧される広大な牧場、大地が育んだブランド牛などのグルメが楽しめます。明るい笑顔の稲村亜美さんと共に、大自然と美味しい食事を満喫する旅に出かけましょう。' where id = 'mO5tYxoGs8oWHai9ZO0Mb';
update content_bodies set title = 'A Journey to Discover Nature and Gourmet in Kamishihoro, Hokkaido with Ami Inamura【Tabiiro】60 Seconds Version', description = 'Kamishihoro, known as a ski resort, showcases its charm even in the vibrant green seasons. The area features remnants of the former National Rail Shihoro Line, vast pastures where cows and goats graze leisurely, and gourmet offerings such as brand beef nurtured by the land. Join the cheerful Ami Inamura on a journey to enjoy the great outdoors and delicious food.' where id = 'r9oNp2MKrjOIbZjDEuiXd';
update content_bodies set title = '稲村亜美｜北の大地・上士幌の自然とグルメに出会う旅【旅色Movie】', description = 'スキーリゾート地として知られる上士幌町は、緑豊かな季節にも魅力を発揮します。旧国鉄士幌線の遺構や、牛やヤギがのんびりと放牧される広大な牧場、大地が育んだブランド牛などのグルメが楽しめます。明るい笑顔の稲村亜美さんと共に、大自然と美味しい食を満喫する旅に出かけましょう。' where id = 'VVKVEGn_DsVW1bBY8Q2M6';
update content_bodies set title = 'Ami Inamura | A Journey to Experience Nature and Gourmet in Kamishihoro, Hokkaido【Tabiiro Movie】', description = 'Kamishihoro, known as a ski resort, showcases its charm even in the vibrant green seasons. The area features remnants of the former National Rail Shihoro Line, vast pastures where cows and goats graze leisurely, and gourmet offerings from the land, including brand beef. Join the cheerful Ami Inamura on a journey to enjoy the great outdoors and delicious food.' where id = 'ygVAokg8BchuasmMtX2tH';
update content_bodies set title = '堀田茜｜北海道上川の自然に心ときめく旅【旅色Movie】', description = 'この動画では、北海道上川町の美しい自然を紹介しています。鮮やかな花が咲くガーデンや丘の上の鐘、ロープウェイからの雄大な山々の景色が楽しめます。訪れる人々は、この美しい環境で心と体をリフレッシュできるでしょう。見どころには、「大雪 森のガーデン」でのグルメ体験や、「層雲峡温泉街」での爽やかな風、源泉かけ流しの「ホテル大雪」が含まれています。また、断崖絶壁に流れる「銀河の滝・流星の滝」や、地元食材を使った「ビアグリルキャニオン」の料理も楽しめます。約7分間の空の旅「大雪山層雲峡・黒岳ロープウェイ」や、隠れ家的な「倉沼CAFE」、海外からの観光客にも人気の「旭川市旭山動物園」、大雪山を一望できる「森のゆ 花神楽」も紹介されています。' where id = 'IqL0O5_U8lrC3sJ8ujtSH';
update content_bodies set title = 'Akane Hotta | A Heart-Throbbing Journey in Nature of Kamikawa, Hokkaido【Tabiiro Movie】', description = 'This video showcases the stunning natural beauty of Kamikawa Town in Hokkaido, featuring vibrant flower gardens, a bell on a hill, and breathtaking mountain views from a ropeway. Visitors can rejuvenate their minds and bodies in this picturesque setting. Highlights include the gourmet experience at ''Daisetsu Forest Garden,'' the refreshing breeze at ''Sounkyo Onsen Town,'' and the natural hot springs at ''Hotel Daisetsu.'' The majestic ''Ginga and Ryusei Falls'' and local cuisine at ''Beer Grill Canyon'' are also featured. A scenic 7-minute aerial journey over Daisetsu can be enjoyed via the ''Daisetsuzan Sounkyo Kurodake Ropeway,'' along with a hidden garden cafe, ''Kurabuna Cafe,'' and the Asahiyama Zoo, known for its international visitors. Lastly, ''Mori no Yu Hanakagura'' offers a day trip hot spring with a view of Daisetsu Mountain.' where id = 'QRMn1waU0tqu4Mh6ZTVaJ';
update content_bodies set title = '鈴木杏樹｜神戸、よくばり旅のすゝめ【旅色Movie】', description = '鈴木杏樹さんが幼少期を過ごした神戸を巡る旅を紹介します。異国情緒あふれる街並みや美しい港町の風景、山側の素晴らしい景色が魅力のこの街では、定番の観光スポットから話題のニュースポット、さらには神戸グルメまで楽しむことができます。神戸の魅力を余すところなく体験できる「よくばり旅」のプランをお教えします。' where id = 'yNh6cpJRVJ1On-6_7p2Ms';
update content_bodies set title = 'Anju Suzuki | Recommended Indulgent Trip in Kobe【Tabiiro Movie】', description = 'Anju Suzuki takes us on a journey through Kobe, where she spent her childhood. The city is known for its beautiful foreign-like streets and picturesque port town scenery, complemented by stunning views from the mountains. This trip covers everything from classic attractions to trendy new spots, as well as the delicious Kobe cuisine, offering a comprehensive guide to an indulgent experience in Kobe.' where id = 'VDd7pc5ceLuhokotMs6cT';
update content_bodies set title = '武田梨奈｜ひと足お先に初夏の沖縄・那覇バカンス', description = '武田梨奈さんが訪れたのは、海開きを迎えた沖縄で、すっかり夏の陽気に包まれています。新しい発見を求める武田さんにとって、沖縄は魅力的な要素が満載の場所です。賑やかな表通りから歴史的な地区まで、軽やかで爽やかな初夏の南国トリップを楽しむ様子が描かれています。' where id = 'nQKF2JLJ5yrF3h6cxg_Ou';
update content_bodies set title = 'Rina Takeda | Early Summer Vacation in Naha, Okinawa', description = 'Rina Takeda visits Okinawa, which has welcomed the start of summer with its beautiful beaches. For Takeda, who is always seeking new discoveries, Okinawa is a captivating place filled with intriguing sights. The trip includes exploring lively streets and historical districts, offering a light and refreshing experience in this tropical paradise.' where id = '_wVRLLa-dvBQHG5ivXE8E';
update content_bodies set title = '旅色 創刊15周年｜旬の旅情報を発信するWEBマガジン', description = 'ウェブマガジン「旅色」が創刊15周年を迎え、自分に合った旅のスタイルや行きたい場所のプランを見つける手助けをしています。「わたしに似合う旅スタイル」をテーマに、著名人が日本各地を訪れ、その地域の魅力を紹介します。浜辺美波さんや新垣結衣さんなど、様々なタレントが登場し、各地の観光スポットを取り上げています。' where id = 'xk7ULXZDeppsbwBF83J4i';
update content_bodies set title = 'Tabiiro 15th Anniversary | A WEB Magazine Delivering Seasonal Travel Information', description = 'The web magazine ''Tabiiro'' celebrates its 15th anniversary, helping readers discover travel styles that suit them and plans for desired destinations. With the theme ''Travel Styles That Suit Me,'' well-known personalities explore various regions of Japan, highlighting their unique attractions.' where id = 'bCUQUhqxbhzzIvSAWmI-2';
update content_bodies set title = '日本の伝統的な「女将」とのインタビュー - 日本語で「おかみ」と呼ばれる', description = '「おかみ」とは、日本の旅館での滞在をより充実させる女将を指します。三重県鳥羽市の美しい地域を探索しながら、快適な滞在を楽しむことができます。鳥羽は海産物や温泉、伝統的な日本の宿で知られています。名古屋や大阪から近鉄特急で簡単にアクセス可能です。詳細については、近鉄鉄道、旅館組合、鳥羽市観光協会の公式ウェブサイトを訪れることができます。' where id = 'TL8-Ch9UPEBt5M-_RHrgP';
update content_bodies set title = 'INTERVIEW WITH JAPANESE TRADITIONAL ''PROPRIETRESS'' - Called in Japanese ''OKAMI''', description = '''OKAMI'' refers to the Japanese proprietress who enhances your experience at ryokans in Toba. Visitors can enjoy a comfortable stay while exploring the beautiful region of Toba in Mie Prefecture, known for its seafood, hot springs, and traditional Japanese inns. The area is easily accessible from major cities like Nagoya and Osaka via Kintetsu Limited Express trains. For more information, you can visit the official websites of the Kintetsu railway, the ryokan association, and the tourism association in Toba.' where id = 'UzZlspniZIYFGzSaS-a9j';
update content_bodies set title = '宇垣美里｜水の都・大垣市（岐阜県）を巡る旅', description = '宇垣美里さんが訪れたのは、岐阜県大垣市。豊かな地下水に恵まれたこの街は「水の都」として知られ、松尾芭蕉ゆかりの地や石田三成が本拠地とした大垣城など、歴史的なスポットが豊富です。宇垣さんは、船町港跡を散策し、水門川でたらい舟を楽しみ、ブランチヒロノヤで贅沢なコース料理を堪能します。また、桝工房ますやで桝づくり体験をし、マスカフェでコーヒーを楽しみ、金蝶園総本家で水まんじゅうを味わいます。旅の締めくくりには、美濃赤坂駅から中山道赤坂宿までの歴史散策を行い、最後に一句詠みます。' where id = 'joIxspONjY3HabUCDO9ZQ';
update content_bodies set title = 'Misato Ugaki''s Journey Through Ogaki City, the Water City of Gifu Prefecture', description = 'Misato Ugaki visits Ogaki City, located in the heart of Japan''s Gifu Prefecture, known as the ''Water City'' due to its abundant underground water. The city is rich in historical sites, including the famous Ogaki Castle, associated with Ishida Mitsunari, and places linked to Matsuo Basho. Throughout her journey, Ugaki explores various attractions such as the remnants of Funamachi Port, enjoys a ride on a traditional tarai boat on Suimon River, and indulges in a luxurious meal at Branch Hirono-ya. She also experiences making masu (traditional wooden sake measuring cups) at Masu Kobo Masuya, enjoys coffee at Masu Cafe, and savors freshly made water dumplings at Kinjouen Sohonke. The trip concludes with a historical walk from Minokasaka Station to Nakayama Road Akasaka-juku, where Ugaki reflects on her experiences with a haiku.' where id = 'aKL0soRV3DkMZI1TIOnBb';
update content_bodies set title = '剛力彩芽｜焼酎王国・鹿児島へ', description = '第6号目では、女優の剛力彩芽さんが日本有数の焼酎の世界に飛び込みます。西郷隆盛が焼酎を買い占めた伝説の老舗蔵で焼酎の造り方を学び、雄大な桜島を一望しながら“幻の焼酎”を味わいます。鹿児島ならではの美食と共に、自分好みの焼酎と出会う旅を提案しています。剛力さんは、モデルや女優として活躍し、特技はダンスと料理、趣味はフルートとお菓子作りです。' where id = 'rBpCF34syEcxVXwYFgrrI';
update content_bodies set title = 'Ayame Gōriki | Exploring the Shochu Kingdom of Kagoshima', description = 'In the sixth issue, actress Ayame Gōriki dives into the rich and diverse world of shochu, a traditional Japanese spirit. She learns about the production process at a legendary distillery, known for its historical connection to Saigo Takamori, who famously hoarded shochu. While enjoying breathtaking views of Sakurajima, she tastes a rare shochu and discovers her personal favorites alongside Kagoshima''s unique culinary delights. This journey is perfectly tailored for the ''cool girl'' who enjoys drinking adventures.' where id = 'WXRBCGpp2WYex1ZgFFUlG';
update content_bodies set title = '真矢ミキ｜歴史・科学・自然が融合するまち肝付町をたっぷり巡る旅【旅色Movie】', description = '鹿児島県の肝付町は、大隅半島の東側に位置し、中央には標高900m級の肝属山系が広がる自然豊かな町です。町の9割が山林で占められ、神話や伝承が息づく一方で、ロケットが飛び立つ宇宙科学の最前線でもあります。真矢ミキさんが案内するこの旅では、肝付町の魅力をたっぷりと体験でき、過去、現在、未来を同時に感じることができます。' where id = 'QnMBXwqhVlzFdgePeyepC';
update content_bodies set title = 'Miki Maya | A Journey Through the Town of Kimotsuki, Where History, Science, and Nature Converge【Tabiiro Movie】', description = 'Kimotsuki Town, located on the eastern side of the Osumi Peninsula in Kagoshima Prefecture, is a nature-rich area where 90% of the land is covered by forests, dominated by the 900-meter-high Kimotsuki mountain range. This town is steeped in ancient myths and traditions while also being at the forefront of space science with rocket launches. Miki Maya guides viewers on a journey to explore the charm of Kimotsuki Town, where one can experience the past, present, and future all at once.' where id = '6fgcVFyg0ziwsmCK-AbD7';
update content_bodies set title = '菜々緒｜宮古島に流れるゆったりとした時間【旅色Movie】', description = 'この動画記事では、菜々緒が宮古島の穏やかな雰囲気を楽しむ様子が紹介されています。美しい景色と静かな時間が流れるこの場所での、リラックスしたライフスタイルを体験することを視聴者に促しています。また、全国の宿泊施設や飲食店、観光スポットの情報は、SNSで発信中です。チャンネル登録やイイねもお忘れなく！' where id = 'CjjrTCR4QfL2aH6nR1pB1';
update content_bodies set title = 'Nanao | Relaxing Time Flowing in Miyako Island [Tabiiro Movie]', description = 'This video article features Nanao enjoying the serene atmosphere of Miyako Island. It highlights the beauty and tranquility of the location, inviting viewers to experience the laid-back lifestyle of the island. For more information on accommodations, dining, and tourist spots across the country, follow us on our social media platforms: Twitter, Facebook, and Instagram. Don''t forget to subscribe to our channel and like our content!' where id = 'xuRWuduF5FDvtwbADSZwL';
update content_bodies set title = '川瀬良子｜農業とリゾートを融合させた新しい旅スタイル“アグリツーリズモリゾート”【旅色】HOTEL STYLE BOOK', description = '東京駅から新幹線で1時間10分、那須塩原駅に到着し、そこから送迎バスで約40分の場所にある「星野リゾート リゾナーレ那須」。栃木県北部・那須岳の山裾に位置し、大自然に囲まれたこのリゾートホテルのコンセプトは“アグリツーリズモリゾート”。アグリツーリズモとは、イタリア語の農業（アグリクルトゥーラ）と観光（ツーリズモ）を組み合わせた造語で、地元の自然を楽しみながら農体験や文化をリゾートで味わえる新しい形のホテルです。農業好きな私としてはその響きに心が躍りますが、まだこのコンセプトを完全には理解できていません。実際に宿泊してその真髄を見つけたいと思います。' where id = 'nuFikf4fLfjF8nt9oyuSy';
update content_bodies set title = 'Ryoko Kawase | A New Travel Style Combining Agriculture and Resort: ''Agritourism Resort''【Tabiiro】HOTEL STYLE BOOK', description = 'Just 1 hour and 10 minutes by Shinkansen from Tokyo Station, you arrive at Nasushiobara Station. From there, a shuttle bus takes you to ''Hoshino Resort Risonare Nasu,'' located about 40 minutes away. Nestled at the foot of Mount Nasu in northern Tochigi Prefecture, this resort hotel embodies the concept of ''Agritourism Resort.'' Agritourism is a blend of the Italian words ''agricoltura'' (agriculture) and ''turismo'' (tourism), allowing guests to enjoy the local nature while experiencing agricultural activities and cultural aspects of the area. As someone who loves farming, the idea of ''agriculture'' excites me, but I must admit that I am still trying to fully grasp this unfamiliar concept. I look forward to discovering its true essence through a stay at the resort.' where id = 'BbX8hrarw6MY9dpDsEzGz';
update content_bodies set title = '鳥羽の海産物 ー巨大アワビ、カキ、エビー', description = 'この文章では、日本の鳥羽で捕れる海産物を紹介しています。特に巨大アワビ、カキ、エビなどが取り上げられ、読者にお気に入りの海産物をコメントで共有するよう呼びかけています。また、三重県に位置する鳥羽についての情報も提供されており、地元の温泉、伝統的な女将とのインタビュー、日本式旅館の体験を推奨する動画へのリンクが含まれています。さらに、名古屋や大阪から近鉄特急で鳥羽にアクセスする方法や、近鉄鉄道の公式ウェブサイト、地元の観光資源へのリンクも掲載されています。' where id = 'a9Yyfz5gQbhphybG-845P';
update content_bodies set title = 'SEAFOOD IN TOBA, JAPAN - Giant Abalones, Oysters, Prawns', description = 'This text introduces the seafood available in Toba, Japan, highlighting favorites such as giant abalones, oysters, and prawns. It invites readers to share their favorite seafood in the comments. Additionally, it provides information about Toba, located in Mie Prefecture, including links to videos about local hot springs, interviews with traditional landladies, and recommendations for experiencing Japanese-style inns. The text also includes travel information on how to access Toba from Nagoya and Osaka stations via Kintetsu Limited Express, along with links to the Kintetsu railway official website and local tourism resources.' where id = 'z_phmgph1GDxwcWOFXHQa';
update content_bodies set title = '【夏菜】福生（ふっさ）で日帰り“ハシゴ酒蔵”＜飲み旅本。＞', description = '日本酒の歴史や製造工程、貴重なエピソードを学び、試飲も楽しめる酒蔵見学は、その地域の成り立ちや歴史を知る良い機会です。今回は東京・福生市の日帰り酒蔵巡りを紹介します。日本酒好きの女優・夏菜さんが、2軒の老舗酒蔵を訪れ、本音でハシゴ酒を楽しみました。スケジュールは、福生駅から田村酒造場、次に石川酒造を訪れ、史料館で歴史を学び、最後に併設のレストラン「福生のビール小屋」で出来立てのビールとイタリアンを堪能する内容です。' where id = 'gMFZrSuQ_AcaVeYwn2ota';
update content_bodies set title = 'Natsuna''s Day Trip ''Sake Brewery Hopping'' in Fussa', description = 'This article introduces a day trip to Fussa City, Tokyo, where you can explore traditional sake breweries. The visit includes learning about the history and production process of sake, along with unique stories, culminating in a tasting experience. Actress Natsuna, who loves sake, shares her honest impressions while visiting two long-established breweries. The itinerary includes a visit to Tamura Sake Brewery, followed by Ishikawa Sake Brewery, where visitors can also learn about the brewery''s history at the attached museum. The trip concludes with a meal at ''Fussa Beer Hut,'' enjoying freshly brewed beer and Italian cuisine.' where id = 'oVSqK9Hz9akO6nVcq-Hk9';
update content_bodies set title = 'NIIGATA カルチャー ツーリズム Episode4 - 新発田・村上エリア -', description = 'このエピソードでは、新発田・村上エリアに焦点を当て、地域の豊かな歴史、文化、自然を紹介する文化観光コンセプトムービーが制作されています。旅人の成長や変革につながる瞬間を捉えた映像で、音楽は新潟県と東京で活躍する音楽クリエイター「Soil Works」がプロデュースしています。NIIGATA カルチャー ツーリズムは、地域の伝統や食文化、文化財を体感する新たな旅の提案を行い、訪れる人々に心の豊かさを実感させることを目指しています。新潟の文化資源の豊かさを体感できる旅を通じて、自然の恵みや四季の特徴を反映した文化を楽しむことができます。令和6年度には、新発田・村上エリアの文化魅力を知ってもらう取り組みが行われます。' where id = '-BmlH-AKAg13CZp4QQBUI';
update content_bodies set title = 'NIIGATA Culture Tourism Episode 4 - Shibata and Murakami Area', description = 'This episode of NIIGATA Culture Tourism focuses on the Shibata and Murakami area, showcasing a cultural tourism concept video that highlights the region''s rich history, culture, and natural beauty. The video captures moments that lead to personal growth and transformation for travelers. The music is produced by Soil Works, a music creator active in both Niigata and Tokyo. NIIGATA Culture Tourism aims to provide a unique travel experience that allows visitors to immerse themselves in local traditions, cuisine, and cultural heritage. The initiative emphasizes the abundance of cultural resources in Niigata, reflecting the region''s diverse landscapes, including the Sea of Japan, majestic mountains, and rivers, as well as the changing seasons. In the fiscal year 2024, efforts will be made to promote the cultural attractions of the Shibata and Murakami area, which includes Shibata City, Murakami City, Agano City, Tainai City, Seiro Town, Sekikawa Village, and Awashimaura Village.' where id = 'oh1FmYMxVfTWM0Vf9q2NQ';
update content_bodies set title = 'NIIGATA カルチャー ツーリズム Episode5 - 長岡エリア -', description = '「NIIGATA カルチャー ツーリズム」Episode5では、長岡エリアの文化をテーマにしたコンセプトムービーが紹介されています。この映像は、長岡の色とりどりの文化の美しさを体感し、心が豊かになる瞬間を表現しています。文化観光は、地域に根付く伝統芸能や食、文化財を通じて、人生の豊かさを体感する旅として提案されています。長岡市、柏崎市、小千谷市、見附市、出雲崎町、刈羽村の文化的魅力を広めることを目的としています。楽曲は、地元の音楽クリエイター「Kiwy-」によるオリジナルです。このプロジェクトは、新潟県の自然の美しさと文化資源を探求し、旅行者に充実感や幸福感をもたらすことを目指しています。' where id = 'aCo1WOUZnlwQ6UM0BGNOA';
update content_bodies set title = 'NIIGATA Culture Tourism Episode 5 - Nagaoka Area', description = 'This episode of NIIGATA Culture Tourism focuses on the Nagaoka area, showcasing its rich cultural heritage through a concept movie. The film captures the beauty and diversity of Nagaoka''s culture, inviting viewers to experience moments that enrich the heart. The journey emphasizes cultural tourism as a way to experience the richness of life, highlighting the region''s traditional arts, cuisine, and cultural assets. The initiative aims to promote the cultural attractions of Nagaoka City, Kashiwazaki City, Ojiya City, Mitsuke City, Izumozaki Town, and Kariwa Village. The original music for the film is produced by local music creator Kiwy-. The project encourages travelers to explore the natural beauty and cultural resources of Niigata Prefecture, enhancing their sense of fulfillment and happiness.' where id = 'U70fuge_hvSi-3QN-70Fl';
update content_bodies set title = '日本の伝統的な「女将」とのインタビュー - 日本語で「おかみ」と呼ばれる', description = '「おかみ」とは、日本の旅館での滞在をより充実させる女将を指します。三重県鳥羽市の美しい地域を探索しながら、快適な滞在を楽しむことができます。鳥羽は海産物や温泉、伝統的な日本の宿で知られています。名古屋や大阪から近鉄特急でアクセス可能です。地元の海産物や温泉、旅館協会へのリンク、アクセス情報やチケット購入オプションも提供されています。' where id = '2xS4yuRK6Rcz0eO0hrOd9';
update content_bodies set title = 'INTERVIEW WITH JAPANESE TRADITIONAL ''LANDLADY'' - Called in Japanese ''OKAMI''', description = '''OKAMI'' refers to the Japanese landlady who enhances your experience at ryokans in Toba. Visitors can enjoy a comfortable stay while exploring the beautiful region of Toba in Mie Prefecture, known for its seafood, hot springs, and traditional Japanese inns. The area is accessible from Nagoya and Osaka via Kintetsu Limited Express trains. For more information, links to local seafood, hot springs, and ryokan associations are provided, along with access details and ticket purchasing options.' where id = 'AJzpuNLV6SbkX6VxGcGsG';
update content_bodies set title = '伊勢志摩旅行ガイド', description = '伊勢志摩は日本の中央部に位置しており、美味しい海鮮、素晴らしい景色、そして温泉を楽しむことができます。訪れる人々を待っているこの地域は、自然の美しさと料理の魅力を満喫できる理想的な旅行先です。' where id = '_BSzP8RmIm78rtNwzK-Ml';
update content_bodies set title = 'ISE TOBA SHIMA TRAVEL GUIDE', description = 'Iseshima is situated in the central region of Japan, offering visitors a delightful experience with its delicious seafood, stunning views, and relaxing hot springs. It is a perfect destination for those looking to enjoy the natural beauty and culinary delights of the area.' where id = 'NyB3K7Mh73vW8KJm71uGa';
update content_bodies set title = '伊勢志摩のすべて', description = '伊勢志摩は、真珠で有名な美しい阿児湾があり、約60の島々が点在するリアコーストラインを持っています。この海域は、素晴らしい海の恵みを私たちに提供し続けています。2000年以上にわたり、最高の漁獲物は伊勢神宮や皇室に捧げられてきました。古代の詩でも豊かな土地として称えられ、伊勢志摩は貴族や著名人に愛されてきました。日本の精神を体現し、独自の景観や味覚、楽しみを提供しています。鳥羽市は真珠の王、御木本幸吉の故郷であり、伊勢志摩の中心に位置しています。アクセスが良く、多様な宿泊スタイルも魅力です。伊勢志摩の魅力に身を委ねてみませんか？' where id = 'epuQQBkmY7hZfUT5jP26B';
update content_bodies set title = 'All about Iseshima', description = 'Iseshima is renowned for the breathtaking beauty of Ago Bay, famous for its pearls. The ria coastline features around 60 islands, providing a rich bounty from the sea. For 2,000 years, the finest catches have been presented to the gods at Ise Jingu and the Imperial Court. Celebrated in ancient poetry, Ise Shima has been cherished by nobility and distinguished individuals. It embodies the spirit of Japan, offering unique sights, tastes, and experiences. Toba City, the birthplace of Kokichi Mikimoto, the ''king of pearls,'' is centrally located in Iseshima, making it easily accessible and offering a variety of accommodations. Experience the lasting allure of Ise Shima.' where id = 'iHHor3B206jLkGmg_nDsx';
update content_bodies set title = '鳥羽は可能性がいっぱい', description = '三重県鳥羽市では、ありきたりでない特別な冒険が待っています。新鮮な海の幸を楽しみ、自然の中でアクティビティを体験し、地元の人々と笑い合うことができます。鳥羽市は、昼も夜も笑顔があふれる場所であり、可能性に満ちています。「TOBA IS YOUR OYSTER」というフレーズは、シェークスピアの言葉に由来し、世界が無限の機会で満ちていることを示しています。鳥羽は、あなたの心が自由になれる場所です。' where id = 'G2TqqKZGc0M8TilxRu12E';
update content_bodies set title = 'TOBA IS YOUR OYSTER', description = 'Toba city in Mie Prefecture invites you to explore a unique adventure away from the usual tourist spots. Enjoy fresh seafood, engage in various activities, and share laughter with the locals. The city promises a joyful experience from day to night, embodying the idea that Toba is full of possibilities. The phrase ''TOBA IS YOUR OYSTER'' is inspired by Shakespeare''s quote, suggesting that the world is full of opportunities, and Toba is a place where you can embrace them. The video promotes Toba as a destination where your heart can feel free and alive.' where id = '_VIC7t3vd4gNmohgce1go';
update content_bodies set title = '4分間「くらげ」を見る動画', description = '仕事の息抜きに、ただクラゲを見つめる時間を楽しんでください。僕は鳥羽水族館のクラゲコーナーが大好きで、見ていると時間を忘れてしまいます。4分間あればいろんなことができますが、僕にとってこの4分間はとてつもなく贅沢なひとときです。' where id = 'pAsMzxfcGczk6DTyNGdJS';
update content_bodies set title = 'Jellyfish for 4 Minutes', description = 'Take a break from work and enjoy a moment of relaxation by simply watching jellyfish. The jellyfish section at the Toba Aquarium is one of my favorites, and I often lose track of time while observing them. Although there are many things you could do in four minutes, for me, this time spent watching jellyfish is incredibly luxurious.' where id = '-XRt94uioOhdwc_EHLdBL';
update content_bodies set title = 'ミスインターナショナルフランスのリジアが鳥羽に来た', description = 'この動画では、ミスインターナショナルフランスのリジアが鳥羽を訪れた様子を紹介しています。彼女の訪問中の活動や、鳥羽での存在感についての情報が含まれています。' where id = 'yD632TuW6LdJ1dzW4ESgq';
update content_bodies set title = 'Miss International France Lysia came to Toba', description = 'This video features Miss International France, Lysia, who has visited Toba. It highlights her presence in the city and provides insights into her activities during the visit.' where id = '6zAW92CjM_dmCt65jntRf';
update content_bodies set title = 'ファンタスティック鳥羽', description = '鳥羽の街を発見してください。ここでは、海女さんや持続可能な漁業の伝統を持つ男女が海と独自の絆を築いています。この場所は単なる立ち寄りスポットではなく、自然と人間の関係を見直す機会を提供します。鳥羽海女文化館や鳥羽市水産研究所、牡蠣養殖場、ミキモト真珠島、海女小屋体験など、さまざまな観光名所を探索できます。鳥羽でのアクティビティについての詳細は、公式ウェブサイトをご覧ください。' where id = 'tWzA_YDEdSok5JK5FmAKq';
update content_bodies set title = 'Fantastique Toba', description = 'Discover the city of Toba, where both men and women have forged a unique bond with the sea, exemplified by the Ama divers and their ancestral tradition of sustainable fishing. This destination offers more than just a stopover; it invites visitors to rethink the relationship between nature and humanity. Explore various attractions such as the Toba Sea-Folk Museum, Toba City Fisheries Research Institute, oyster farms, Mikimoto Pearl Island, and the Ama Hut Experience. For more information on activities in Toba, visit the official website.' where id = '-8blN5DAarBAIc-BvNgBy';
update content_bodies set title = 'マコンデ美術館　タンザニアに開花した芸術文化', description = 'タンザニアはアフリカ大陸の東に位置し、日本人にはあまり知られていない国かもしれませんが、マコンデ族の美しい芸術が存在します。彼らは黒檀を素材にした彫刻を作り、人や動物、抽象的な作品を表現します。経済的には豊かではないものの、作品には怒りや悲しみ、喜びなどの感情が豊かに表現されており、これらは生きる困難を受け入れる覚悟を示しています。マコンデの芸術は、過去と現在、死者と生者、神と人が共存する社会を物語っており、私たち日本人にも多くの示唆を与えています。約400点の作品があるマコンデ美術館は、単なる工芸品ではなく、普遍的なテーマを含む現代アートです。訪れるたびに新たな発見があり、なぜこの美術館が伊勢志摩にあるのかを知るためには、実際に足を運ぶことが必要です。' where id = '7UeY54l-BOiorRlTIOVej';
update content_bodies set title = 'Makonde Museum: The Blossoming of Artistic Culture in Tanzania', description = 'Tanzania, located in East Africa, may be unfamiliar to many Japanese people, but it is home to the Makonde tribe, known for their exquisite art. The Makonde have a long tradition of creating sculptures from ebony, depicting humans, animals, and abstract forms. Despite their economic hardships, their works express a rich array of emotions, including anger, sadness, resignation, joy, and fear, often intertwined in a way that affirms life. This art reflects the timeless human emotions that remain unchanged through the ages, suggesting that the feelings of people in Tanzania are not so different from those in materially advanced countries like Japan. The Makonde''s art tells a story of the connection between earth and life, the past and present, the living and the dead, and the divine and human. The Makonde Museum, housing around 400 pieces, is not merely a collection of traditional crafts but a significant contemporary art form that resonates with universal themes. Visitors are encouraged to return multiple times to gain deeper insights, as the answers may lie within the Makonde''s creations. To understand why this museum exists in Ise-Shima, one must visit and explore.' where id = '_v5FcEb6uSBbDapCeP1s2';
update content_bodies set title = '鳥羽市観光プロモーション映像', description = '鳥羽はあなたに恋しています。心をときめかせるものは、何気ないところに潜んでいます。ゆっくりと時間をかけて巡ることで、思いがけない出会いがあるかもしれません。奥まった道に踏み込むと、まだ見ぬときめきが待っているかもしれません。美しい海や独自の暮らしを残す離島、受け継がれる海女文化が息づく鳥羽には、日本の美しい営みがあふれています。ゆったりとした温泉や、海の幸、山の幸が旅を豊かにしてくれます。自然の恵みもたっぷりです。あなたはどんな鳥羽を好きになってくれるでしょうか。想像するだけでドキドキします。あなたに喜んでもらいたい、幸せな気分になってもらいたい。鳥羽はあなたに恋しています。' where id = 'ACHw3stJSWLyZjz6cX5jk';
update content_bodies set title = 'Toba City Tourism Promotion Video', description = 'Toba is in love with you. The things that make your heart flutter can be found in the most ordinary places. By taking your time to explore, you may encounter unexpected delights. If you take one more step down a less-traveled path, you might discover new thrills waiting for you. Toba is home to beautiful seas, unique lifestyles preserved on remote islands, and a rich ama culture. The essence of Japan''s beautiful traditions is alive throughout Toba. Enjoy the relaxing hot springs and the bountiful gifts from the sea and mountains that enrich your journey. With nature''s blessings all around, what kind of Toba will you fall in love with? Just imagining it makes your heart race a little. We want to make you happy and bring you joy. Toba is in love with you.' where id = 'XWAuqtQn7vFs_gx4mrTLT';
update content_bodies set title = '3年に一度の「祖谷のかずら橋」架け替え', description = '祖谷のかずら橋は、3年ごとに架け替えられます。この架け替えの理由や直面する課題、そしてそれに対する解決策について紹介しています。また、2018年に行われた架け替えの様子を収めた動画もあります。' where id = 'eXfDTf0bOoQJShS2z-lB7';
update content_bodies set title = 'Vine Architects Preserving the Iya Vine Bridge Every 3 Years', description = 'The Iya Vine Bridge is replaced every three years. This summary discusses the reasons for the replacement, the challenges involved, and the solutions to these issues. A video from 2018 showcases the bridge''s replacement process.' where id = 'eFM6zYNCwANT3ziqgbATn';
update content_bodies set title = 'ものがたりが生きる里「古津軽（こつがる）」プロモーション動画', description = '青森県津軽地方は、祭りや信仰、芸能、民藝、食、珍しい風習など、独特の文化が花開いています。これらの文化は代々人から人へと受け継がれ、今も息づいています。「古津軽（こつがる）」は、こうした古き良き生活文化を再発見し、小さな物語として体験する旅です。この動画では、古津軽の世界観をご覧いただけます。' where id = '4o-fRSkZM8cAsEztJPaBm';
update content_bodies set title = 'Kotsugaru: A Promotional Video of the Living Stories', description = 'The Tsugaru region in Aomori Prefecture is known for its unique culture, which includes festivals, beliefs, performing arts, folk crafts, cuisine, and rare customs that have been passed down through generations. The journey of ''Kotsugaru'' invites you to rediscover these cherished cultural traditions and experience them as small stories. This video showcases the worldview of Kotsugaru.' where id = 'BXKQ6UlVRBi_Zw34n4ENf';
update content_bodies set title = 'ドラマティックアート　関門海峡&門司港', description = '関門海峡では1日に700隻の船が行き交い、門司港レトロには明治から大正時代の建築物が今も残っています。この映像は、夜明けからナイトタイムまでのドラマティックなシーンを満載しており、歴史的な重要性と活気ある雰囲気を強調しています。' where id = 'pPPrUd2GjX8JPajisYRR4';
update content_bodies set title = 'Dramatic Art: Kanmon Strait & Mojiko', description = 'This video showcases the dramatic scenery of the Kanmon Strait, where 700 ships pass daily, and the Mojiko Retro area, known for its preserved architecture from the Meiji to Taisho periods. The footage captures the beauty of these locations from dawn to night, highlighting their historical significance and vibrant atmosphere.' where id = 'uZ1eCytlJFLX9hb_5xMM2';
update content_bodies set title = '神秘のパワースポット　平尾台', description = '平尾台は、日本の天然記念物であり、著名なカルスト台地の一つです。ここでは、石灰岩が羊の群れのように見える羊群原や、すり鉢状の地形のドリーネ、神秘的な鍾乳洞など、魅力的な自然の景観が広がっています。これらの神秘的な風景は、訪れる価値があるスポットです。' where id = 'ip0ZG3NyTLHWDTPXYyVRe';
update content_bodies set title = 'Mystical spot: Hiraodai', description = 'Hiraodai is a designated natural monument in Japan and is recognized as one of the country''s most famous karst plateaus. This area features stunning natural formations, including limestone that resembles flocks of sheep, conical dolines, and captivating limestone caves. These mystical landscapes offer a unique experience that should not be missed.' where id = 'uSOJVLsDR0s9UsgUG32Ef';
update content_bodies set title = 'さざなみの風景　曽根干潟', description = '自然豊かな曽根干潟の景色をカメラ女子とともに綴るショートストーリーです。満潮から干潮に移り行く潮の動きや、絶滅危惧種であるズグロカモメなど、干潟の魅力が満載で、自然の美しさを感じることができます。' where id = '2LlPjOEKPPGf8uBB9iygl';
update content_bodies set title = 'Rippling landscape: Sone Tidal Flats', description = 'This short story captures the natural beauty of the Sone Tidal Flats through the lens of a young woman photographer. It highlights the enchanting scenery, showcasing the dynamic movement of the tides as they transition from high to low. The narrative also emphasizes the presence of the endangered Saunder’s gull, adding to the allure of the tidal flats.' where id = 'ey5vYw9NUU-q6SJunUX9A';
update content_bodies set title = '真っ赤なかけはし　若松ワンデードライブ', description = '洞海湾をまたいで北九州市戸畑区と若松区を結ぶ真っ赤なかけはし「若戸大橋」。このドライブでは、若松の魅力的で自然豊かなスポットを巡ることができ、地域の魅力を体験することができます。' where id = 'zDQcxAjUVAS0p_GByAVtO';
update content_bodies set title = 'Ruby-red Suspension Bridge: A one-day drive around Wakamatsu', description = 'The bright-red suspension bridge, Wakato Bridge, spans across Dokai Bay and connects the Tobata and Wakamatsu wards in Kitakyushu. This drive offers a chance to explore the charming and naturally beautiful areas of Wakamatsu, showcasing the region''s attractions.' where id = '4DeYG3hY1urUPwnUKkLLm';
update content_bodies set title = '「ていたん」＆「ブラックていたん」と行く 環境未来都市 北九州市！', description = '北九州市の環境マスコットキャラクター「ていたん」と「ブラックていたん」が、市内の環境施設や美しい街並み、豊かな自然を巡りながら、環境未来都市としての北九州市をPRします。彼らは持続可能性や環境意識を重視した未来の都市のモデルとして、北九州市の魅力を伝えています。' where id = 'AaFZWOvCPJt808XkV3riB';
update content_bodies set title = 'Sightseeing with Teitan and Black Teitan: Kitakyushu, the Future City', description = 'In Kitakyushu, the environmental mascots Teitan and Black Teitan guide visitors through the city''s environmental facilities, charming urban landscapes, and rich natural surroundings. They promote Kitakyushu as a model for future cities focused on sustainability and environmental awareness.' where id = 'qPe0ADkkjU4dGI53CfWaW';
update content_bodies set title = 'ぎゅーっと　北九州のおいしいもの', description = '北九州の美味しい食べ物をぎゅっと詰め込んだ内容で、街の至る所にある魅力的な料理に食欲をそそられること間違いなしです。' where id = 'F8SlVz_i-MVRoF3HakPcb';
update content_bodies set title = 'Jam-packed: Kitakyushu’s delectable cuisine', description = 'This content showcases the delicious foods of Kitakyushu, enticing viewers with a variety of tempting dishes found throughout the city.' where id = 'Bo_jn8FeUFcaYPYDzEbq2';
update content_bodies set title = 'きらめく北九州　工場萌え＆新日本三大夜景皿倉山', description = '北九州は、洞海湾沿岸に広がる工場群と皿倉山の自然美が融合した独特の魅力を持っています。昼夜を問わず、工場が織りなす景観は見事で、特に夜には工場の光が幻想的な世界を演出します。また、皿倉山からの夜景は新日本三大夜景の一つとして知られ、訪れる人々に感動を与えます。流れ星も見られるこの場所は、魅力的な雰囲気をさらに引き立てています。' where id = 'ob4Z-R-ziAJcipaR_R7zl';
update content_bodies set title = 'Twinkling Kitakyushu: Love of factories & Mt. Sarakura, one of Japan’s three new major night views', description = 'Kitakyushu offers a unique blend of industrial charm and natural beauty. The factories lining the coast of Dokai Bay create a stunning visual experience both during the day and at night. At night, the illuminated factories transform the landscape into a magical realm. Additionally, the view from Mt. Sarakura is renowned for its breathtaking night scenery, making it one of Japan''s three new major night views. Visitors can also enjoy the spectacle of shooting stars from this vantage point, adding to the enchanting atmosphere.' where id = 'GxmVtSAvs7Y1WEzi8BkKU';
update content_bodies set title = '四国の地方の魅力 Route 02', description = 'このセクションでは、四国の地方の魅力を紹介し、特にRoute 02に焦点を当てています。' where id = 'iZVTtoXWiSqp6r0CYtafe';
update content_bodies set title = 'ShikokuLocalCharm Route 02', description = 'This section introduces the local charm of Shikoku, focusing on Route 02.' where id = 'd_7gUdHeJIjwdCLV-LR0q';
update content_bodies set title = '剣山の四季', description = '剣山の四季を紹介する内容です。四季折々の美しい風景や自然の変化を通じて、剣山の魅力を伝えています。春の新緑、夏の青空、秋の紅葉、冬の雪景色など、各季節の特徴を楽しむことができる場所として、訪れる人々に感動を与えることでしょう。制作はにし阿波観光圏によるものです。' where id = 'r_TcyTuvFzNBhG83CzG_n';
update content_bodies set title = 'Four seasons Mt.Tsurugi', description = 'This content introduces the four seasons of Mt. Tsurugi.' where id = 'PZ-9ygUNyf29yHB79niZy';
update content_bodies set title = '隠れた日本、祖谷渓谷と徳島・四国の他の魅力', description = '西阿波観光エリアは、そびえ立つ山々に囲まれた静かな楽園で、時間が止まったかのような場所です。この地域は、変わらぬ風景と人々の温かさが特徴です。訪れる人々は、霧に包まれた谷や急な山肌に寄り添う小さな集落を探索する中で、手つかずの静けさを感じます。孤立と限られた資源によって形成された密接なコミュニティは、強い絆と協力の精神を育んできました。平安時代から、西阿波の人々は見知らぬ人々を温かく迎え入れ、家族のように接してきました。この地域の独特の文化は、東洋文化の学者アレックス・カーを魅了し、彼は祖谷の谷を日本のシャングリラと表現しました。今日、世界中からの旅行者が西阿波の穏やかな美しさと魅力を体験しに訪れています。' where id = 'iVP3TsR4I6scOWOMJWsm0';
update content_bodies set title = 'Hidden Japan Iya Valley and other Wonders Tokushima, Shikoku', description = 'The Nishi-Awa Tourism Area is a secluded paradise nestled among towering mountains, where time seems to stand still. This region is characterized by its unchanging landscapes and the warmth of its people. Visitors are greeted by a sense of untouched tranquility as they explore the misty valleys and quaint hamlets that cling to steep mountainsides. The close-knit communities, shaped by isolation and limited resources, have developed strong bonds and a spirit of cooperation. Since the Heian period, the residents of Nishi-Awa have welcomed strangers with open arms, treating them as family. The unique culture of this area has captivated scholars like Alex Kerr, who described the Iya valleys as a Japanese Shangri-La. Today, travelers from around the globe come to experience the serene beauty and charm of Nishi-Awa.' where id = '9g_4N7KSnBPJ9xeReiGmX';
update content_bodies set title = '西阿波紹介短片', description = 'この動画は、中華圏（台湾・香港）向けに西阿波を紹介する内容です。大歩危、祖谷、四国、徳島、西阿波、三好などの地域が取り上げられています。' where id = 'Mrylb8_Hd3CfFVKdtmpnn';
update content_bodies set title = 'Introduction to Nishi-Awa', description = 'This is an introduction video for Nishi-Awa aimed at the Chinese-speaking regions, specifically Taiwan and Hong Kong. It highlights various locations such as Oboke, Iya, Shikoku, Tokushima, Nishi-Awa, and Miyoshi.' where id = 'BE9HUMyn6DzSPXRb_UClV';
update content_bodies set title = '三好市女子旅', description = '女子が楽しむために企画された三好市の旅です。' where id = 'ITecN0A6zJWyuXz76nt5f';
update content_bodies set title = 'Miyoshi City Women''s Trip', description = 'A journey through Miyoshi City designed for women.' where id = 'Fd0bhlzXSMNdE1Pqy6vxW';
update content_bodies set title = 'ウォータースポーツのまち三好市', description = '2017年に徳島県三好市でレースラフティングの世界選手権が開催されました。この動画では、三好市の魅力をまとめています。' where id = 'DmlbMOY4mQQ4N2zk4kPsc';
update content_bodies set title = 'Miyoshi City: A Town of Water Sports', description = 'Miyoshi City in Tokushima Prefecture hosted the World Rafting Championship in 2017. This video summarizes the attractions of the city.' where id = 'LSgBZvDXu8Do7vWtu7aca';
update content_bodies set title = '匠が護る伝統工芸　その技と未来', description = '本プロジェクトは、匠たちが伝統工芸やその技を守り、これらの文化的実践の未来を確保するための献身を強調しています。福井県小浜市の支援を受け、地域のさまざまな工房や寺院が参加し、地域の豊かな遺産を紹介しています。若狭工房、妙楽寺、飯盛寺、四季彩館 酔月などが協力し、これらの工芸品の保存に貢献しています。プロジェクトは若狭工房が主催し、音楽はアキラノスケが提供、ロゴデザインはたねまきデザインが担当しています。撮影は小川浩之氏が行っています。' where id = '4-dUAHSPugSkt5H_p3YjI';
update content_bodies set title = 'Artisans preserving traditional crafts, skills, and the future', description = 'This project highlights the dedication of artisans in preserving traditional crafts and their skills, ensuring the future of these cultural practices. Supported by the city of Obama in Fukui Prefecture, the initiative involves various local workshops and temples, showcasing the rich heritage of the region. Collaborators include Wakasakobo, Myourakuji, Iimoriji, Shikisai-kan Suigetsu, and several others, all contributing to the preservation of these crafts. The project is organized by Wakasakobo, with music provided by Akiranosuke and logo design by Tanemaki Design. Cinematography is handled by Hiroyuki Ogawa from Photo & Movie Create Augusta.' where id = 'AbLODvN9_LQD516rBz7Q-';
update content_bodies set title = '匠が護る伝統工芸　その技と未来', description = 'このプロジェクトは、伝統工芸や技術を守り、その未来を確保することに尽力する匠たちの活動を紹介しています。福井県小浜市のさまざまな地域団体との協力を通じて、工房や寺院、地元の商店が連携しています。若狭工房が主催し、さまざまな匠や団体の協力を得て、現代社会における文化遺産と工芸の重要性を強調しています。' where id = 'm5B92dokVQk_8_k1wPJoQ';
update content_bodies set title = 'Artisans preserving traditional crafts, skills, and the future', description = 'This project highlights the efforts of artisans dedicated to preserving traditional crafts and skills, ensuring their future. It showcases the collaboration of various local entities in Obama City, Fukui Prefecture, including workshops, temples, and local businesses. The initiative is supported by the Wakasa Workshop and features contributions from various artisans and organizations, emphasizing the importance of cultural heritage and craftsmanship in contemporary society.' where id = 'LcLiaFDM_6PjA_lhEZCKD';
update content_bodies set title = '若狭塗と若狭めのうの工程紹介', description = '小浜市が誇る伝統的工芸品である若狭塗と若狭めのうの製造工程の一部を紹介しています。これらの工芸品は地域の文化を反映しており、その製造過程には独自の技術と美意識が込められています。' where id = '16452onSMBR-Z8wHfiRoh';
update content_bodies set title = 'Introduction to the Process of Wakasa Lacquer and Wakasa Agate', description = 'Wakasa lacquer and Wakasa agate are traditional crafts that the city of Obama takes pride in. This text introduces some parts of their manufacturing processes.' where id = 'O2s1Vw_rzlfiBgFKO_0QH';
update content_bodies set title = '「いしのいのりを」 若狭めのう細工職人', description = '「いしのいのりを」は、若狭めのう細工の職人技を紹介する作品です。小浜市や福井県の地域団体の支援を受け、飯盛寺や若狭姫神社、玉守神社などの協力を得て制作されています。主催は若狭工房で、若狭めのう細工を専門とする宗助工房が参加しています。音楽はアキラノスケが提供し、ナレーションはフアンチョ・サンタマリアが担当。映像は小川浩之が手掛け、ロゴデザインはたねまきデザインによるものです。' where id = '8MkojOZTaGswkiwTbVROY';
update content_bodies set title = 'Whispers of the Stones: Wakasa Agate Craftsman', description = 'This piece highlights the artistry of Wakasa agate craftsmanship, showcasing the intricate work of skilled artisans. The production is supported by various local organizations in Obama City, Fukui Prefecture, and features collaborations with several temples and cultural institutions. The project is organized by Wakasa Workshop, with contributions from Sousuke Workshop, which specializes in Wakasa agate. The film includes music by Akiranosuke and narration by Juancho Santamaria, with cinematography by Hiroyuki Ogawa. The logo design is by Tanemaki Design.' where id = '6sUdpjwhzSHLIMUx-0HDT';
update content_bodies set title = '斜めの旅もいいんじゃない？【にし阿波傾斜地農業＊キャンプ・徳島県三好市＆東みよし町】', description = '世界農業遺産に認定された「にし阿波」で、伝統的な傾斜地農業を体験できます。夜には、人気のキャンプ場「美濃田の淵」で、傾斜地で育てられた野菜を使ったキャンプ飯を楽しむことができます。この「斜めの旅」は、農業とアウトドア活動、そして徳島県にし阿波の自然や文化を体験する絶好の機会です。' where id = '0RtKNFMONgekF5r1E-vzW';
update content_bodies set title = 'Why Not a Slanted Journey? 【Nishi-Awa Sloped Agriculture * Camping in Miyoshi City & Higashi-Miyoshi Town, Tokushima Prefecture】', description = 'Experience traditional sloped agriculture in the world agricultural heritage site of ''Nishi-Awa''! At night, enjoy camp meals made with vegetables grown on the slopes at the popular campsite ''Minoda no Fuchi.'' This ''slanted journey'' offers a unique opportunity to experience agriculture and outdoor activities, as well as the nature and culture of Nishi-Awa in Tokushima Prefecture.' where id = '1xkFehKl3JFqJoa22SC-p';
update content_bodies set title = '大垣市移住定住プロモーション動画', description = 'この動画は、都会の生活に心を奪われた男性が、大垣市に住む恋人との会話を通じて、現在の大垣市の魅力を知り、故郷の大切さに気づく様子を描いています。最終的に彼は大垣に戻る決意をします。BGMには「木綿のハンカチーフ」の現代版アレンジが使用されており、元々は故郷にいる女性が都会に行った恋人を思う歌詞ですが、動画では女性が大垣の魅力を伝え、恋人を故郷に呼び戻すストーリーになっています。出演者には根矢涼香と森岡龍が、監督は二瓶剛が務め、撮影は古屋幸一が担当しました。ロケ地にはソフトピアジャパンや大垣城などが含まれています。' where id = '-QTROaUBqooT1KsvUa0gG';
update content_bodies set title = 'Ogaki City Migration and Settlement Promotion Video', description = 'The video tells the story of a man captivated by city life who, through conversations with his girlfriend living in Ogaki City, discovers the charm of the city and recalls the importance of his hometown. Ultimately, he decides to return to Ogaki. The background music features a modern arrangement of ''Cotton Handkerchief,'' originally about a woman in the countryside longing for her city-bound lover. In this video, however, the woman shares the allure of Ogaki, calling her boyfriend back from the city. The video features actors Ryoka Neya and Ryu Morioka, directed by Takeshi Nihei, with various crew members contributing to its production. Filming locations include Softpia Japan, Ogaki Castle, and several other notable sites in Ogaki City.' where id = 'NhBOtusecd3udav98XKyV';
update content_bodies set title = '「碓氷峠 廃線ウォーク」〜行き止まりのレールの先を、次の世代に〜', description = '1893年に開通した信越本線の横川-軽井沢区間は、群馬県に位置しながら長野県歌に登場します。この区間は、蚕糸や製糸製品を東京・横浜へ運ぶために重要でしたが、1997年に廃線となりました。2018年からは、歴史的価値を体感できる約11kmのガイド付きウォーキングツアーが定期的に開催されています。この取り組みは、廃線跡を観光資源として活用し、持続可能な観光を目指しています。これまでに6000名以上が参加し、草刈りを行うサポーターチームも結成されました。人間だけでなく動物の生態系維持にも寄与することを目指し、参加者は保全と活用の両立を体感できます。この活動は、文化ツーリズム賞を受賞し、現在あるものを大切にすることの重要性を伝えています。' where id = '5Gqd67FblXLrKQiWwhxRi';
update content_bodies set title = 'Usui Pass Abandoned Railway Walk: Passing the Dead End Rails to the Next Generation', description = 'The Usui Pass section of the Shin''etsu Main Line, which opened in 1893, is primarily located in Gunma Prefecture but is mentioned in the Nagano Prefectural song. The railway was crucial for transporting silk products to Tokyo and Yokohama. After electrification and a switch to a new line, the section was abandoned in 1997. Since 2018, guided walking tours have been held regularly, allowing participants to walk approximately 11 km through historically significant areas. The tour emphasizes sustainable tourism by preserving the abandoned railway as a cultural resource. Over 6,000 people have participated in the past five years, and a support team has been established to maintain the area. The initiative aims to create a sustainable ecosystem for both humans and wildlife. The project has been recognized with the Cultural Tourism Award at the Sports Culture Tourism Awards, highlighting the importance of valuing existing resources and the lessons learned from the past.' where id = 'TG_HcmPt9joEOE4mtM_4K';
update content_bodies set title = '【バーチャルリアリティ 碓氷峠廃線ウォーク】 「AIりんな車掌チャレンジ」Chapter one', description = '群馬県安中市の「廃線ウォーク」は、悲しい記憶を観光資源に変え、地域コミュニティのつながりを深めることを目指しています。1997年に廃線となった信越本線の区間をVR映像で体験でき、360度自由に見渡せる内容です。AIりんなが車内放送を再現し、旅行気分を楽しむことができます。自宅にいながらも、出かけられない時にこの体験を通じて、思い出を感じることができます。今後、イベントでのVR体験ブースも予定されています。Chapter oneでは、AIりんなが歌う「最高新記憶」がBGMとして使用され、Chapter twoは別の地点の映像で制作されます。' where id = 'gWClmfNpy_D-EJ-7HdG41';
update content_bodies set title = 'Virtual Reality Usui Pass Abandoned Line Walk - ''AI Rinna Conductor Challenge'' Chapter One', description = 'The Usui Pass Abandoned Line Walk in Annaka City, Gunma Prefecture, aims to transform sad memories into tourism resources, deepening community connections through remembrance. This VR experience allows users to explore the abandoned section of the Shin''etsu Main Line, which was closed in 1997, from the comfort of their homes. The 360-degree video features AI Rinna, who recreates the train announcements, providing an immersive experience. Users can enjoy the journey alongside Rinna, dressed in a conductor''s uniform, even when they cannot travel. Future events will include VR booths for public promotion. Chapter One features a special version of the background music ''Saiko Shin Kioku'' sung by AI Rinna, while Chapter Two will showcase footage from a different location.' where id = 'cwoIrWbvEHcgGofPHr8U3';
update content_bodies set title = '群馬・観光：Anoraks Design Market × 碓氷峠 廃線ウォーク × Black Tree innovation', description = '66.7‰の急勾配を持つ碓氷峠は、横川と軽井沢の間で104年間の挑戦の歴史を刻んできました。廃線から23年が経った今も、横川のまちには汽笛の音が響き続けています。この言葉やデザイン、映像は、これからの歴史の一部となります。子どもから大人まで楽しめるように、好きなことを語り、形にすることを促進しています。現在、トートバッグやTシャツなど、思い出を持ち運べる商品を製作中で、日常生活の一部となるアイテムを展開しています。緑が眩しい季節や色鮮やかな紅葉が終わった後も、この場所で楽しいことは続きます。' where id = 'Vtk48MzDfY55P3l3jwmJR';
update content_bodies set title = 'Gunma Tourism: Anoraks Design Market × Usui Pass Abandoned Line Walk × Black Tree Innovation', description = 'The Usui Pass, with its steep gradient of 66.7‰, has a history of challenges spanning 104 years between Yokokawa and Karuizawa. Even 23 years after the line''s closure, the sound of the whistle continues to resonate in Yokokawa. This phrase, along with the design and visuals, will become part of the future history. The initiative encourages people of all ages to express their passions and create tangible items. They are currently developing products that allow memories to be carried, including tote bags and T-shirts, which will become part of daily life. Fun activities will continue in this location, even after the vibrant green season and colorful autumn leaves have passed.' where id = 'nC9_59d33U5Xb598zUuem';
update content_bodies set title = '【喜界島】優しさも、おすそ分け', description = '喜界島に移住して3年目の主人公が、自転車で島を駆け回りながら「おすそ分け」のお礼を言う物語が展開されます。物語は、島民の優しさと自然の美しさを描いています。主人公以外の出演者は、実際の喜界島の住民です。喜界島は鹿児島から南に約380km、奄美大島の東25kmに位置し、太平洋と東シナ海が交わる隆起珊瑚礁の島です。年間平均2mmずつ隆起し続ける学術的に貴重な島で、サトウキビ畑が広がり、黒糖や黒糖焼酎が特産品です。また、国内最大の白ゴマの産地としても知られています。名所には奄美十景の一つである百之台公園、美しいスギラビーチやハワイビーチ、古いサンゴの石垣などがあり、近年はダイビングスポットとしても注目されています。' where id = 'JXO9ZtTqCTNxYG0WIx8gz';
update content_bodies set title = 'Kikai Island, Japan', description = 'The story unfolds as the protagonist, who has moved to Kikai Island for three years, rides around the island on a bicycle to express gratitude for the kindness of the locals through the concept of ''sharing.'' The narrative highlights the warmth of the island''s residents and the beauty of its natural surroundings. Notably, the other participants in the story are actual residents of Kikai Island. Kikai Island is located approximately 380 km south of Kagoshima and 25 km east of Amami Oshima, floating on a raised coral reef where the Pacific Ocean meets the East China Sea. The island is scientifically significant as it continues to rise at an average rate of 2 mm per year. It is known for its sugarcane fields, producing local specialties like brown sugar and brown sugar shochu, and is the largest producer of white sesame in Japan. The island features several attractions, including Hyakunodai Park, Sugirabeach, Hawaii Beach, and ancient coral stone walls, and has recently gained attention as a diving spot.' where id = '6VAAGusWui5ce8sYinVg_';
update content_bodies set title = '福井の冬は蟹やスキー場だけじゃない！あたたかい故郷に会いに行こう！【地味にすごい、福井動画コンテスト入賞作品】', description = '本作品は、福井県が実施した「地味にすごい、福井」をテーマにした動画コンテストの入賞作品です。制作者は、自然豊かで四季の美しい福井県の魅力を伝えたいと考えていますが、認知度や魅力度ランキングでは毎年下位に位置しています。冬の魅力を凝縮したこの動画では、メディアで取り上げられる華やかな部分と、普段は注目されない住民の暮らしの両方に焦点を当てています。北陸新幹線の開業により、福井を訪れる人が増えることを願っています。心の故郷、福井にぜひ訪れてみてください。' where id = '5BUg9RPbFtalqKUlqRx0X';
update content_bodies set title = 'Fukui in Winter: More Than Just Crabs and Ski Resorts! Come Visit Your Warm Hometown! [Award-Winning Entry in the ''Surprisingly Amazing Fukui'' Video Contest]', description = 'This work is an award-winning entry in a video contest organized by Fukui Prefecture, themed ''Surprisingly Amazing Fukui.'' The creator highlights the natural beauty and seasonal changes of Fukui, which often ranks low in recognition and attractiveness. The video captures the lesser-known charms of winter in Fukui, focusing on both the glamorous aspects frequently covered by the media and the everyday lives of its residents. With the opening of the Hokuriku Shinkansen to Fukui and Tsuruga, the creator hopes more people will visit to experience the local cuisine and meet the gentle, modest people of Fukui. Come visit your heartfelt hometown, Fukui!' where id = '4-QGp0JgyFKGjLWyLlSl5';
update content_bodies set title = '【喜界島】いつも心に残る島', description = '喜界島は鹿児島から南に約380km、奄美大島の東25kmに位置する隆起珊瑚礁の島です。太平洋と東シナ海が交わるこの島は、豊かな自然環境と独自の文化、優しい島民によって、訪れる人々に忘れられない旅の思い出を提供します。喜界島は年間平均2mmのペースで隆起し続けており、学術的にも貴重な存在です。島内には広大なサトウキビ畑が広がり、黒糖や黒糖焼酎が特産品として知られています。また、国内最大の白ゴマの産地でもあります。観光名所には奄美十景の一つである百之台公園、美しいスギラビーチやハワイビーチ、古いサンゴの石垣などがあり、近年はダイビングスポットとしても注目されています。' where id = '7aPH7F7FCZvFO3xISV8Jq';
update content_bodies set title = 'Kikai Island, Japan', description = 'Kikai Island, located approximately 380 km south of Kagoshima and 25 km east of Amami Oshima, is a unique coral reef island where the Pacific Ocean meets the East China Sea. The island is known for its rich natural environment, vibrant culture, and friendly locals, making it a memorable travel destination. Kikai Island is scientifically significant as it continues to rise at an average rate of 2 mm per year. The landscape is dominated by sugarcane fields, producing local specialties such as brown sugar and brown sugar shochu. It is also recognized as the largest producer of white sesame in Japan. Notable attractions include Hyakunodai Park, Sugirabeach, Hawaii Beach, and ancient coral stone walls. Recently, the island has gained attention as a diving spot.' where id = 's-1u52bWvAlnDGGFXJeas';
update content_bodies set title = '【喜界島】サンゴでできた喜びの島', description = '喜界島は奄美大島からわずか20分のフライトで到着するサンゴの島で、美しい海の青と大地の緑が織りなす豊かな自然環境が魅力です。優しい島民との交流は、訪れる人々に笑顔あふれる体験を提供します。喜界島は鹿児島から南に約380km、奄美大島の東25kmに位置し、太平洋と東シナ海が交わる場所に浮かぶ隆起珊瑚礁の島です。年間平均2mmずつ隆起し続けるこの島は、学術的にも貴重です。サトウキビ畑が広がり、黒糖や黒糖焼酎が特産品として知られています。また、国内最大の白ゴマの産地でもあります。名所には奄美十景の一つである百之台公園、美しいスギラビーチやハワイビーチ、古くからのサンゴの石垣などがあり、近年はダイビングスポットとしても注目されています。' where id = 'KdGkZc-UF062YVJUadVK5';
update content_bodies set title = 'Kikai Island, Japan', description = 'Kikai Island is a coral island located just a 20-minute flight from Amami Oshima. It boasts a rich natural environment characterized by the beautiful blue sea and lush green land. The friendly locals provide a warm and welcoming experience for visitors. Geographically, Kikai Island is situated approximately 380 km south of Kagoshima and 25 km east of Amami Oshima, floating on a raised coral reef where the Pacific Ocean meets the East China Sea. The island continues to rise at an average rate of 2 mm per year, making it scientifically significant. Sugarcane fields dominate the landscape, producing local specialties such as brown sugar and brown sugar shochu. Kikai Island is also known for being the largest producer of white sesame in Japan. Notable attractions include Hyakunodai Park, Sugirabeach, Hawaii Beach, and ancient coral stone walls. Recently, it has gained attention as a diving spot.' where id = 'xcfYnlWeKvmp1KLnWvqpj';
update content_bodies set title = 'Sounds of ZEN　～ZENの息づくまち福井～', description = '「ZEN」シリーズ動画では、福井の精神文化や歴史遺産の魅力を紹介しています。大本山永平寺をはじめ、一乗谷朝倉氏遺跡やおろしそば、伝統的工芸品など、福井の歴史と風土に根ざした要素が取り上げられています。川のせせらぎや職人の繊細な技の音に焦点を当て、圧倒的な映像と共に表現されています。ナレーターの大和田伸也氏が朴訥な語り口で「ZEN」の雰囲気を引き立て、福井の魅力を深く伝えています。' where id = 'QakT8UR9LQLKnaBXGHUVG';
update content_bodies set title = 'Sounds of ZEN - The Town of Fukui Breathing ZEN', description = 'The video series ''ZEN'' showcases the rich cultural heritage of Fukui, starting from the famous Eiheiji Temple, through historical sites like the Asakura Clan ruins in Ichijodani, to local delicacies such as oroshi soba and traditional crafts. The series emphasizes the sounds of nature, like the murmuring of rivers, and the delicate techniques of artisans, all presented with stunning visuals. Narrated by Shinya Oowada, the storytelling harmonizes with the essence of ''ZEN'', offering a simple yet profound introduction to Fukui''s spiritual culture and historical treasures.' where id = 'Y-VaMUtUQgcTl_eKnqBTi';
update content_bodies set title = '【歴史・文化編】Sounds of ZEN', description = 'この動画は、福井の精神文化や歴史遺産に焦点を当てています。大本山永平寺を起点に、一乗谷朝倉氏遺跡やおろしそば、伝統的工芸品など、福井の「ZEN」の魅力を探求します。川のせせらぎや職人の繊細な技の音に着目し、圧倒的な映像で表現されています。ナレーターには大和田伸也氏が参加し、朴訥とした語り口で「ZEN」の雰囲気を引き立てています。' where id = '_MdVu_GEzgrqCQpX8Zl6q';
update content_bodies set title = 'Sounds of ZEN: History and Culture Edition', description = 'This video focuses on the spiritual culture and historical heritage of Fukui, starting from the Eiheiji Temple, and including sites like the Ichijodani Asakura Clan Ruins, traditional soba noodles, and crafts. It highlights the allure of Fukui''s ''ZEN'' through the sounds of nature, such as flowing rivers, and the delicate techniques of artisans, all presented with stunning visuals. Narrated by Shinya Oowada, the video captures the essence of ''ZEN'' with a simple and harmonious storytelling style.' where id = 'mvlIG3C-wxf2037utOD3-';
update content_bodies set title = '【食編】Sounds of ZEN', description = 'この動画は、福井の「食」に焦点を当てています。大本山永平寺をはじめ、一乗谷朝倉氏遺跡やおろしそば、伝統的工芸品など、福井の歴史や風土に根ざした精神文化や歴史遺産の魅力を、川のせせらぎや職人の繊細な技の音に着目して表現しています。ナレーターには大和田伸也氏が参加し、ZENの雰囲気に調和した朴訥な語り口で紹介しています。福井の観光情報も提供されています。' where id = 'GwLtB2QQ8jx7ufcV46Agh';
update content_bodies set title = 'Sounds of ZEN - Food Edition', description = 'This video focuses on the rich cultural heritage and spiritual essence of Fukui, starting from the historic Eiheiji Temple, through the Asakura clan ruins in Ichijodani, to local delicacies like oroshi soba and traditional crafts. It highlights the allure of Fukui''s ''ZEN'' by emphasizing the sounds of nature, such as flowing rivers, and the delicate techniques of artisans. The narration by Nobuya Oowada complements the serene atmosphere of ''ZEN'' with a simple and heartfelt storytelling style.' where id = 'AhYldib2OSwACB0LDNua4';
update content_bodies set title = '【自然・景観編】Sounds of ZEN', description = 'この動画は、福井の自然や景観に焦点を当てています。大本山永平寺をはじめ、一乗谷朝倉氏遺跡やおろしそば、伝統的工芸品など、福井の歴史や風土に根ざした精神文化や歴史遺産を紹介します。川のせせらぎや職人の繊細な技の音に着目し、圧倒的な映像と共に表現されています。ナレーションは大和田伸也氏が担当し、ZENの雰囲気に調和した朴訥な語り口で魅力を伝えます。' where id = 'QLHd6dlU0OxlPS_XSbtQN';
update content_bodies set title = 'Sounds of ZEN - Nature and Scenery Edition', description = 'This video focuses on the natural beauty and landscapes of Fukui, starting from the renowned Eiheiji Temple, and including historical sites like the Asakura Clan Ruins in Ichijodani, local soba noodles, and traditional crafts. It highlights the spiritual culture and historical heritage of Fukui, emphasizing the sounds of nature, such as flowing rivers, and the delicate techniques of artisans. The narration by Nobuya Oowada complements the serene atmosphere of ''ZEN'' with a simple and heartfelt storytelling style.' where id = 'RuVmXqQ-n65M-z_4nClTM';
update content_bodies set title = '【伝統工芸編】Sounds of ZEN', description = 'この動画は福井の伝統工芸に焦点を当て、古くからの歴史や風土に根ざした精神文化や歴史遺産の魅力を紹介しています。大本山永平寺を起点に、一乗谷朝倉氏遺跡やおろしそばなど、福井の特産品を取り上げています。川のせせらぎや職人の繊細な技の音に注目し、圧倒的な映像で表現されています。ナレーションは大和田伸也氏が担当し、ZENの雰囲気に調和した朴訥な語り口で進行します。福井の観光情報は、https://www.fuku-e.com/をご覧ください。' where id = 'r-Pgfuh-BW-_pkQ379GzI';
update content_bodies set title = 'Sounds of ZEN - Traditional Crafts Edition', description = 'This video focuses on the traditional crafts of Fukui, highlighting the region''s rich spiritual culture and historical heritage, which are rooted in its long history and unique environment. It begins at Eiheiji Temple and explores sites like the Asakura clan ruins and local specialties such as oroshi soba. The video emphasizes the sounds of nature, like the murmuring of rivers, and the delicate techniques of artisans, all presented through stunning visuals. Narrated by Shinya Oowada, the narration complements the serene atmosphere of ''ZEN''. For more tourism information about Fukui, visit https://www.fuku-e.com/' where id = 'R9ubD8oNRb-WmbbcPHKvi';
update content_bodies set title = '【祭り編】Sounds of ZEN', description = 'この動画は、福井の「祭り・行事」に焦点を当てています。大本山永平寺を起点に、一乗谷朝倉氏遺跡やおろしそば、伝統的工芸品など、福井の歴史や風土に根ざした精神文化や歴史遺産の魅力を、川のせせらぎや職人の繊細な技の音に着目して表現しています。ナレーターには大和田伸也氏が参加し、朴訥とした語り口で「ZEN」の雰囲気を引き立てています。福井の観光情報は、提供されたリンクをご覧ください。' where id = 'ruZJapDp-jt6O5SYvGIXx';
update content_bodies set title = 'Sounds of ZEN - Festival Edition', description = 'This video focuses on the cultural and historical heritage of Fukui, starting from the Eiheiji Temple, and including sites like the Ichijodani Asakura Clan Ruins, traditional soba noodles, and crafts. It highlights the spiritual culture of Fukui, emphasizing the sounds of nature and the delicate techniques of artisans. The narration by Nobuya Oowada adds a rustic charm that harmonizes with the ''ZEN'' atmosphere. For more information on Fukui tourism, visit the provided link.' where id = '9wkllHNqB2fX1a3k3wSkG';
update content_bodies set title = '【短編ver.】Sounds of ZEN　～ZENの息づくまち福井～', description = 'この短編は、福井のZENの本質を紹介します。大本山永平寺をはじめ、一乗谷朝倉氏遺跡やおろしそば、伝統的工芸品など、福井の歴史や風土に根ざした精神文化や歴史遺産を取り上げています。川のせせらぎや職人の繊細な技の音に焦点を当て、圧倒的な映像で表現されています。ナレーションは大和田伸也氏が担当し、ZENの雰囲気に調和した朴訥な語り口で紹介されています。' where id = 'xp6N_EFu0HTfcDqUpExB1';
update content_bodies set title = 'Sounds of ZEN - The Town of Fukui Embracing ZEN', description = 'This short version highlights the essence of ZEN in Fukui, starting from the renowned Eiheiji Temple, and including historical sites like the Ichijodani Asakura Clan Ruins, local specialties such as Oroshi Soba, and traditional crafts. The video focuses on the sounds of nature, like the murmuring of rivers, and the delicate techniques of artisans, showcasing the rich spiritual culture and historical heritage of Fukui. Narrated by Shinya Oowada, the presentation harmonizes with the ZEN atmosphere through a simple and heartfelt storytelling style.' where id = 'v2uPP5-ckWJyhn-xvOVb-';
update content_bodies set title = '美女2人が温泉へ！？あわら温泉で遊び倒す!', description = '福井県の「あわら温泉」は「関西の奥座敷」として知られる温泉地で、イタリア出身のダニエラさんと南アフリカ出身のプリスカさんがその魅力を堪能します。足湯やマッサージ湯など、さまざまな温泉を楽しむ二人は大はしゃぎ。さらに、飲み好きの二人は「湯けむり横丁」で何を飲んだのか、ほろ酔いの状態でリポートできるのでしょうか？現在はコロナウイルスの影響で県外への旅行が難しいですが、落ち着いた際にはぜひ福井を訪れてほしいとのことです。' where id = 'Pgbj6Ok0AMY4S7ReGvvl-';
update content_bodies set title = 'Two Beauties Enjoying a Hot Spring!? Having Fun at Awara Onsen!', description = 'In Awara Onsen, one of the top hot spring destinations in Fukui Prefecture, known as the ''hidden retreat of Kansai,'' two women, Daniela from Italy and Priska from South Africa, indulge in various hot spring experiences. They have a great time enjoying foot baths and massage baths. Additionally, the two, who enjoy drinking, explore ''Yukemuri Yokocho'' and share what they drank. Will they be able to report back while slightly tipsy? Although travel and tourism outside the prefecture are currently challenging due to the COVID-19 pandemic, visitors are encouraged to come to Fukui once things settle down!' where id = 'GaSG6UfyjQFkJpwjjhlyo';
update content_bodies set title = '【丸岡RUCKver】きてみね～の福井県民下手ラップ', description = '福井県民が愛する地元の魅力を歌ってPRするミュージックビデオ「下手ラップ」に、女子フットサルチームの「丸岡RUCK」が登場します。福井丸岡RUCKは、日本女子フットサルリーグに加盟する「ふくい県民応援チーム」として、下手ラップに合わせて県内の観光地を紹介しています。「ふっく〜い　きてみね〜の！」というフレーズは一度聴いたら忘れられないほど印象的で、ぜひ一緒に歌って踊ってほしいです。現在はコロナウイルスの影響で県外への旅行が難しい状況ですが、落ち着いた際にはぜひ福井を訪れてください。公式YouTubeチャンネルやオリジナルの下手ラップ、歌詞カードも公開されています。' where id = '2zvhvEasK3leGMwhkVZfZ';
update content_bodies set title = 'Maruoka RUCK Version: Fukui Prefecture''s Local Charm in a Fun Rap', description = 'The music video ''Heta Rap,'' which promotes the local attractions beloved by the people of Fukui Prefecture, features the women''s futsal team ''Maruoka RUCK.'' The team, part of the Fukui Prefecture support team in the Japan Women''s Futsal League, introduces various tourist spots in the prefecture while rapping along to the catchy tune. The memorable phrase ''Fukui, kitemine!'' invites everyone to sing and dance along. Although travel and tourism outside the prefecture are currently challenging due to the COVID-19 pandemic, visitors are encouraged to come to Fukui when the situation stabilizes. The official YouTube channel and additional resources, including the original ''Heta Rap'' and lyrics, are available online.' where id = '-SB_diTEAUOnv_Efgztlz';
update content_bodies set title = '公式MV『きてみね～の！』～福井県民下手ラップ～', description = 'この公式ミュージックビデオでは、ラップをしたことがない福井県民が、愛する福井県をテーマにした本格的なラップを披露しています。「ふっく〜い　きてみね〜の！」というキャッチーなフレーズは、一度聞いたら忘れられないものです。老若男女に向けて心を込めて届けられ、みんなで歌えるように呼びかけています。現在はコロナウイルスの影響で旅行が難しい状況ですが、落ち着いた際にはぜひ福井を訪れてほしいというメッセージも含まれています。音源や歌詞カードは公式サイトで公開されており、旅行関連のページへのリンクもあります。プロジェクトに協力した地元の団体や個人への感謝も述べられています。' where id = 'jc_Phw3gqkNBaIn5snlrk';
update content_bodies set title = 'Official MV ''Kitemine-no!'' - Fukui Prefecture''s Unique Rap', description = 'In this official music video, residents of Fukui Prefecture, who have never rapped before, express their love for their home through a genuine rap song. The catchy phrase ''Fukui, Kitemine-no!'' is unforgettable and aims to resonate with people of all ages. The video encourages everyone to remember the lyrics and sing along. Despite the current challenges posed by the COVID-19 pandemic, the message invites viewers to visit Fukui when the situation improves. Additional resources, including audio and lyrics, are available on the official website, along with links to travel-related pages. Special thanks are given to various local organizations and individuals who contributed to the project.' where id = 'V4MnC7N__lkb-BGG4l8KK';
update content_bodies set title = '宇和島に住む', description = 'この動画は宇和島に住むことについて紹介しています。' where id = 'kzzctpUA7_Anelnxw0mrZ';
update content_bodies set title = 'Living in Uwajima', description = 'This video introduces the experience of living in Uwajima.' where id = 'GbyTec8ecD_rOh75msUUS';
update content_bodies set title = '大垣市観光PR　「水の都」 篇', description = '上田定行さんのナレーションによる観光PR動画で、ディレクターは遠藤輝一、プロデューサーは山崎淳也と日比野允が担当し、名古屋テレビ映像が制作しています。大垣観光協会の公式チャンネルでは、自然や歴史、文化など大垣の魅力を紹介しています。大垣市は岐阜県西部に位置し、人口16万人を抱える「水の都」として知られています。俳人松尾芭蕉の紀行文「奥の細道」の終着地であり、関ケ原合戦では西軍の石田三成の本拠地となった大垣城や、豊臣秀吉が一夜で築いた墨俣一夜城などの歴史的な名所があります。3月下旬から5月には舟下りやたらい舟、大垣まつりが開催され、多くの観光客で賑わいます。' where id = '4IPIEpUSk9cyQXcuxzH0q';
update content_bodies set title = 'Tourism Promotion of Ogaki City: The Water City', description = 'This is a tourism promotion video narrated by Sadaaki Ueda. Directed by Keiichi Endo and produced by Junya Yamazaki and Masaru Hibino, the video is created by Nagoya Television. The official channel of the Ogaki Tourism Association introduces various attractions of Ogaki, including its nature, history, and culture. Ogaki City, located in the western part of Gifu Prefecture, is home to 160,000 residents and is known as ''The Water City'' due to its abundant underground water. It is recognized as the endpoint of Matsuo Basho''s travelogue ''The Narrow Road to the Deep North'' and was the base for Ishida Mitsunari during the Battle of Sekigahara. The city features historical sites like Ogaki Castle and the Suimon Castle, built overnight by Toyotomi Hideyoshi. From late March to May, Ogaki hosts boat rides and the UNESCO Intangible Cultural Heritage-listed Ogaki Festival, attracting many tourists.' where id = '6cxw0vuOx1_6n2bQYZMKq';
update content_bodies set title = '【岐阜県西美濃の桜】ぎふ西美濃さくら交響曲', description = '岐阜県西部の西美濃に位置する桜スポットを紹介します。大垣市の大垣城や、松尾芭蕉の紀行文「奥の細道」のむすびの地として知られる場所、さらには養老公園や谷汲山華厳寺など、自然と歴史が共存する魅力的なスポットが多数あります。特に3月下旬から5月にかけては、桜の季節を迎え、多くの観光客が訪れます。また、ユネスコ無形文化遺産に登録された大垣まつりなどのイベントも開催され、地域の魅力をさらに引き立てています。' where id = 'mH3XR_2j8-rSUR-IO4Xrk';
update content_bodies set title = 'Cherry Blossoms in Gifu''s Nishi-Mino: Gifu Nishi-Mino Sakura Symphony', description = 'This text introduces cherry blossom spots in the western part of Gifu Prefecture, specifically in Nishi-Mino. Notable locations include Ogaki Castle, the starting point of Matsuo Basho''s ''Oku no Hosomichi'', and various parks and temples such as Yoro Park and Tanjugusan Kegonji Temple. The area is rich in history and nature, attracting many visitors, especially during the cherry blossom season from late March to May. Events like the Ogaki Festival, recognized as an intangible cultural heritage by UNESCO, further enhance the region''s appeal.' where id = '3qffytnXUL271dnMiscXZ';
update content_bodies set title = '水の都・大垣を巡る旅', description = '大垣市は日本のほぼ中央に位置し、豊かな地下水に恵まれ「水の都」と称されています。松尾芭蕉ゆかりの地や、関ケ原合戦の際に石田三成の本拠地となった大垣城など、歴史的なスポットが豊富です。自然と歴史が共存するこの町では、3月下旬から5月にかけて舟下りやたらい舟、大垣まつりなどのイベントが開催され、多くの観光客で賑わいます。大垣観光協会の公式チャンネルでは、自然や文化などの魅力を動画で紹介しています。' where id = 'm5U3nyfxeeBsu7iGd3UfR';
update content_bodies set title = 'A Journey Through the Water City of Ogaki', description = 'Ogaki City, located in the central part of Japan, is known as the ''Water City'' due to its abundant underground water. The city is rich in historical sites, including Ogaki Castle, which served as the base for Ishida Mitsunari during the Battle of Sekigahara, and is associated with the famous poet Matsuo Basho. Visitors can enjoy a journey through this city, exploring its natural beauty and historical significance. From late March to May, Ogaki hosts various events, including boat rides and the UNESCO-recognized Ogaki Festival, attracting many tourists. The official Ogaki Tourism Association channel provides videos showcasing the city''s diverse attractions.' where id = 'grlZ5WyQLE-tZYx6kImLv';
update content_bodies set title = '水の都・大垣を巡る旅', description = '大垣市は日本のほぼ中央に位置し、豊かな地下水に恵まれ「水の都」と称されています。松尾芭蕉ゆかりの地や、関ケ原合戦で石田三成の本拠地となった大垣城など、歴史的なスポットが豊富です。自然と歴史が共存するこの町では、3月下旬から5月にかけて舟下りやたらい舟、大垣まつりなどのイベントが開催され、多くの観光客で賑わいます。大垣市の魅力を紹介するこの動画は、視聴者に水の都を巡る旅を提案しています。' where id = 'JqkYM-u6eOt9o8Rm8w3kT';
update content_bodies set title = 'A Journey Through the Water City of Ogaki', description = 'Ogaki City, located in the central part of Japan, is known as the ''Water City'' due to its abundant underground water resources. The city is rich in historical sites, including Ogaki Castle, which served as the base for Ishida Mitsunari during the Battle of Sekigahara, and is also associated with the famous haiku poet Matsuo Basho. Visitors can enjoy a variety of attractions that blend nature and history. From late March to May, Ogaki hosts events such as boat rides and the UNESCO Intangible Cultural Heritage-listed Ogaki Festival, attracting many tourists. This video showcases the charm of Ogaki City and invites viewers to explore its unique offerings.' where id = 'VA_3l4sOCdofzp-a9DYAu';
update content_bodies set title = '岐阜県大垣市のたらい舟体験の紹介', description = '「水の都おおがきたらい舟」は、2003年度から期間限定で実施されている川下りの体験です。この動画では、下船場周辺の船町川湊の雰囲気を楽しむことができます。「水の都おおがきたらい舟」についての詳細は、大垣観光協会の公式ウェブサイトをご覧ください。大垣市は岐阜県西部に位置し、人口16万人を有し、豊富な地下水に恵まれ「水の都大垣」として知られています。また、俳人松尾芭蕉の紀行文「奥の細道」の終着地であり、関ケ原合戦の際には西軍石田三成の本拠地となった大垣城や、豊臣秀吉が一夜で築いたとされる墨俣一夜城などの歴史的な名所もあります。3月下旬から5月には舟下りや大垣まつりが開催され、多くの観光客で賑わいます。' where id = 'rfotNakWN5Hhl97FBjIbX';
update content_bodies set title = 'Introduction to the Tarai Boat Experience in Ogaki City, Gifu Prefecture', description = 'The ''Tarai Boat Experience in the Water City of Ogaki'' has been offered since 2003 as a limited-time riverboat ride. This video showcases the atmosphere around the disembarkation area and the Funamachi River Port. For more details about the ''Tarai Boat Experience,'' please visit the Ogaki Tourism Association''s website. Ogaki City, located in the western part of Gifu Prefecture, has a population of 160,000 and is known for its abundant underground water, earning it the nickname ''Water City Ogaki.'' It is also recognized as the endpoint of Matsuo Basho''s travelogue ''Oku no Hosomichi'' and features historical sites such as Ogaki Castle and the Sumiyoshi Castle, built by Toyotomi Hideyoshi. From late March to May, the city attracts many tourists with boat rides and the Ogaki Festival, which was registered as a UNESCO Intangible Cultural Heritage in 2016.' where id = 'bQy6hYByi77bxQD_xo_it';
update content_bodies set title = '北九州の夏が来る2024', description = '2023年のわっしょい百万夏祭りの様子が紹介されています。今年も北九州市の各地で祭囃子の音が響き渡り、北九州の夏がやってきたことを感じさせます。' where id = 'd2eW2cS8-tm1DQPunQa9H';
update content_bodies set title = 'Summer in Kitakyushu 2024', description = 'The 2023 Wasshoi Hyakuman Summer Festival was held in Kitakyushu. The sounds of festival music could be heard throughout the city, signaling the arrival of summer in Kitakyushu once again.' where id = 'DPXl5LzsYNaaFkfmmvAcS';
update content_bodies set title = '短編映画 「赤い河童と赤い橋」 予告', description = '完全新作短編映画「赤い河童と赤い橋」のトレーラー第1弾です。この作品にご期待ください。' where id = '5M_yA8TYTsq3oHJfVJoxR';
update content_bodies set title = 'Short Film ''The Red Kappa and the Red Bridge'' Trailer', description = 'This is the first trailer for the completely new short film ''The Red Kappa and the Red Bridge.'' Please look forward to it.' where id = 'F-3gLqIXJigPLmSFHqJD7';
update content_bodies set title = '[非公式] 記録 わっしょい！北九州の夏祭り', description = '今年は多くの祭りが中止となり、非常に残念です。そのため、疫病退散を願ってこの作品を作りました。また、日本国際観光映像祭の日本部門vlog部門で優秀作品賞をいただき、大変光栄に思っています。1日でも早く普通の暮らしが戻ることを心から願っています。' where id = 'P5GHcIFOBX4Hu_LW5QAzh';
update content_bodies set title = '[Unofficial] Record of the Wasshoi! Kitakyushu Summer Festival', description = 'This year, many festivals have been canceled, which is disappointing. In light of this, I created this to wish for the eradication of the epidemic. I am also honored to have received the Excellence Award in the Vlog category at the Japan International Tourism Film Festival. I sincerely hope that we can return to our normal lives as soon as possible.' where id = 'EE1vhiaLJBW8zHljVrVda';
update content_bodies set title = '北海道の冒険旅行：釧路、阿寒、摩周【4K】（ショートバージョン） -手つかずの北海道-', description = '手つかずの北海道は、日本の自然の美しさと冒険の機会で知られる地域です。東北海道に位置する釧路湿原国立公園と阿寒摩周国立公園は、希少な野生動物や多様な生態系の宝庫です。地元の人々は、この貴重な自然を長年にわたり守り続けてきました。この4K動画では、手つかずの北海道の壮大な風景と豊かな生物多様性を紹介しています。' where id = 'TnWNIdxGlE8Yh_wLIxnAj';
update content_bodies set title = 'Japan Hokkaido Adventure Travel in Kushiro, Akan, Mashu【4K】(Short ver.) -Untouched HOKKAIDO-', description = 'Untouched Hokkaido is a pristine region in Japan, celebrated for its natural beauty and adventure opportunities. The area includes Kushiro Shitsugen National Park and Akan Mashu National Park, both located in eastern Hokkaido, which are home to unique wildlife and diverse ecosystems. The local communities have long been dedicated to preserving this precious nature. This 4K video showcases the stunning landscapes and rich biodiversity of Untouched Hokkaido.' where id = '-2vrKmwaNeG23nJcaeYU_';
update content_bodies set title = 'Untouched HOKKAIDO : 日本北海道阿寒湖のトレッキング【4K】', description = 'この動画では、日本の北海道の美しい自然、特に阿寒湖とその周辺地域に焦点を当てています。ナレーターは初めてのクロスカントリースキーの体験を語り、最初は難しさを感じたものの、ガイドの助けを借りて楽しむことができたと述べています。北海道は手つかずの風景で知られ、冒険旅行者にとっての聖地です。この地域には、希少な野生動物や自然の美しさが豊富な釧路湿原国立公園や阿寒摩周国立公園があり、地元の人々によって長年守られてきました。この動画は、この素晴らしい環境の本質を捉えています。' where id = 'pv1HdwBqNyUfLCXyeruCP';
update content_bodies set title = 'Untouched HOKKAIDO : Japan Hokkaido Lake Akan Lake top Trekking【4K】', description = 'This video showcases the pristine nature of Hokkaido, Japan, particularly focusing on Lake Akan and its surrounding areas. The narrator shares their experience of cross-country skiing for the first time, describing the initial challenges but ultimately enjoying the activity thanks to helpful guidance. Hokkaido is celebrated for its untouched landscapes and is a haven for adventure travelers. The region includes Kushiro Shitsugen National Park and Akan Mashu National Park, which are rich in rare wildlife and natural beauty, preserved by local communities for generations. The video captures the essence of this remarkable environment.' where id = 'BgkYh7wL6SM7yGCqE1Q6O';
update content_bodies set title = 'Untouched HOKKAIDO : 日本の北海道 阿寒摩周国立公園 ボッケ（泥火山） 森の雪歩き【4K】', description = 'この4K動画では、日本の北海道の手つかずの自然、特に阿寒摩周国立公園とボッケ泥火山に焦点を当てています。雪の靴を履いて森を歩き、氷に覆われた湖を渡る旅を通じて、冒険旅行者を惹きつける手つかずの風景が紹介されています。北海道は、釧路湿原国立公園や阿寒摩周国立公園に生息する希少な野生動物で知られています。地元の人々は、この貴重な自然環境を長年にわたり保護しており、未来の世代のためにその美しさを守っています。' where id = 'g0CSGZ2uFS4_YseJmwK3z';
update content_bodies set title = 'Untouched HOKKAIDO : Japan Hokkaido Akan-Mashu National Park Bokke (Mud Volcano) Forest Snow Walk【4K】', description = 'This 4K video showcases the pristine nature of Hokkaido, Japan, particularly focusing on the Akan-Mashu National Park and the Bokke mud volcano. The journey involves snowshoeing through a forest and across an ice-covered lake, highlighting the untouched landscapes that attract adventure travelers. Hokkaido is celebrated for its rich biodiversity, with rare wildlife thriving in the Kushiro Shitsugen and Akan Mashu National Parks. The local communities have played a vital role in preserving this precious environment, ensuring that the natural beauty remains intact for future generations.' where id = 'kbu1-5Yr6GA1z6Fj2B4bF';
update content_bodies set title = 'Untouched HOKKAIDO : 日本北海道川湯温泉と川の散策路', description = '川湯の朝は温かい蒸気に包まれ、魔法のような異世界の雰囲気が漂います。町の通りには川と温泉が流れています。北海道は、自然に囲まれた冒険旅行者の聖地として知られています。東北海道には、希少な野生動物や多様な生物が生息する釧路湿原国立公園と阿寒摩周国立公園があります。この貴重な自然は、地元の人々によって長い間守られてきました。この4Kビデオでは、手つかずの北海道の壮大な自然を紹介しています。' where id = 'hz-aG8ts_NKUvdnQhNPda';
update content_bodies set title = 'Untouched HOKKAIDO : Japan Hokkaido Kawayu Onsen Hot Spring and River Walking Trail', description = 'Kawayu''s mornings are characterized by warm steam and a unique atmosphere, with rivers and hot springs flowing through the town. Hokkaido is a haven for adventure travelers, surrounded by pristine nature. The region is home to Kushiro Shitsugen National Park and Akan Mashu National Park, which host rare wildlife and diverse ecosystems. Local communities have long protected this precious nature. This 4K video showcases the stunning landscapes of Untouched Hokkaido.' where id = 'MMkQrrHaLHY92DmhDbLR8';
update content_bodies set title = 'Untouched HOKKAIDO : 日本の北海道・摩周湖のスノーシュー体験', description = '摩周湖は、世界で最も透明度の高い湖の一つとして知られるカルデラ湖であり、この地域の生態系にとって重要な水源です。この水は、厳しい冬の間に積もった雪が溶けることで生まれます。北海道は、自然に囲まれた冒険旅行者にとって神聖な土地として知られています。北海道の東部には、希少な野生動物や多様な生態系を有する釧路湿原国立公園と阿寒摩周国立公園があります。地元の人々は、この貴重な自然を長年にわたり守り続けてきました。この4K動画では、手つかずの北海道の壮大な自然を紹介しています。' where id = 'EiWcWFyG3plNRXAyNjk4A';
update content_bodies set title = 'Untouched HOKKAIDO : Japan Hokkaido Lake Mashu Snowshoeing', description = 'Lake Mashu, a caldera lake in Hokkaido, is renowned for its exceptionally clear waters, which are vital for the region''s ecosystem. The lake''s water originates from snow that accumulates during the harsh winter and melts in spring. Hokkaido is celebrated as a sacred land for adventure travelers, offering pristine natural landscapes. The eastern part of Hokkaido is home to Kushiro Shitsugen National Park and Akan Mashu National Park, which host rare wildlife and diverse ecosystems. The local communities have long protected this precious nature, ensuring its preservation for future generations. This 4K video showcases the breathtaking beauty of Untouched Hokkaido.' where id = 'mayXV_eORIsEvUKbO2ZZf';
update content_bodies set title = 'Untouched HOKKAIDO : 日本北海道釧路湿原国立公園冬の野生動物ツアー【4K】', description = 'この4K動画では、北海道の美しい自然、特に釧路湿原国立公園に焦点を当てています。早朝のシーンでは、世界的に有名なタンチョウヅルをカメラで捉える写真家たちの姿が映し出され、湿原にはシカやキツネ、ウサギなどの多様な野生動物が生息しています。北海道は冒険旅行者にとって神聖な土地として知られ、地元の人々によってその貴重な自然が長い間守られてきました。この動画は、豊かな生物多様性とこのユニークな環境を保護する重要性を強調しています。' where id = 'aauhDpFE-woHiAWcBppjS';
update content_bodies set title = 'Untouched HOKKAIDO : Japan Hokkaido Kushiro-Shitsugen National Park Winter Wildlife Tour【4K】', description = 'This 4K video showcases the breathtaking natural beauty of Hokkaido, particularly focusing on the Kushiro Shitsugen National Park. Early morning scenes capture photographers aiming their cameras at the iconic Red-Crowned Cranes, while the wetlands are home to a variety of wildlife, including deer, foxes, and rabbits. Hokkaido is celebrated as a sacred land for adventure travelers, with its pristine nature preserved by local communities. The video highlights the rich biodiversity and the importance of protecting this unique environment.' where id = 'NOyQqNJaO8cZ3YkcdbT_p';
update content_bodies set title = 'Untouched HOKKAIDO : 日本北海道釧路湿原国立公園カヌーツアー -冬- 【4K】', description = '釧路湿原国立公園を流れる釧路川では、冬でもカヌーが楽しめます。気温が-10度以下になる中、特定の気象条件下でしか見られない冬の風景が広がります。この動画では、まるで別世界にいるかのような美しい景色が捉えられています。手つかずの自然が残る北海道は、冒険旅行者にとって聖地として知られています。釧路湿原国立公園や阿寒摩周国立公園には、希少な野生動物が生息し、地域の人々によって大切に守られてきた貴重な自然があります。この4K動画は、北海道の壮大な自然を紹介しています。' where id = 'S26DydmbJ5VgztOvyazVG';
update content_bodies set title = 'Untouched HOKKAIDO : Japan Hokkaido Kushiro-Shitsugen National Park Canoe Tour -winter- 【4K】', description = 'Canoeing along the Kushiro River in Kushiro Shitsugen National Park is a popular winter activity, even in temperatures below -10 degrees Celsius. The video captures a unique winter landscape that can only be experienced in the early morning under specific weather conditions. The stunning visuals create an otherworldly atmosphere, showcasing the untouched beauty of Hokkaido, a region known for its natural adventures. The area is home to rare wildlife and has been preserved by local communities for generations. This 4K video highlights the magnificent nature of Hokkaido, emphasizing its status as a sacred land for adventure travelers.' where id = '8Bz7aGPRSdz4gVz0vWF3F';
update content_bodies set title = '手付かずの北海道：釧路、阿寒、摩周、川湯で自然と共生する | 日本旅行【4K】', description = '手付かずの北海道は、釧路湿原、阿寒湖、摩周湖を含む東北海道の美しい地域です。この地域は自然の美しさと生物多様性に恵まれており、希少なブレキストンオウルや優雅なタンチョウなどの野生動物が生息しています。先住民族アイヌの人々は、自然に対して深い敬意を持ち、すべての環境要素に神が宿ると信じています。この信念は、土地とその資源との調和の取れた関係を育んでいます。この地域の手つかずの風景は何世紀にもわたって守られており、自然愛好家や冒険者にとって理想的な目的地です。この映像は、第6回日本国際観光映像祭（JWTFF2024）で日本部門プロジェクト部門最優秀賞を受賞しました。' where id = 'bf685BYKdSmYHBYrbfdqh';
update content_bodies set title = 'Untouched HOKKAIDO : Co-existing with nature in Kushiro, Akan, Mashu and Kawayu | JAPAN TRIP 【4K】', description = 'Untouched Hokkaido is a stunning region in East Hokkaido, featuring the Kushiro Shitsugen Wetland, Lake Akan, and Lake Mashu. This area is rich in natural beauty and biodiversity, home to unique wildlife such as the rare Blakiston''s fish owl and the elegant red-crowned cranes. The indigenous Ainu people hold a deep respect for nature, believing that deities inhabit all elements of the environment. This belief fosters a harmonious relationship with the land and its resources. The region''s pristine landscapes have been preserved for centuries, making it a perfect destination for nature lovers and adventurers. The film has received the Best Project Award in the Japan category at the 6th Edition of the Japan World’s Tourism Film Festival (JWTFF2024).' where id = '4_hWyQbIYVB0K7pi_PcKP';
update content_bodies set title = '夏の北海道冒険旅行、釧路、阿寒、摩周【4K】-手つかずの北海道-', description = '手つかずの北海道は、日本の冒険旅行者に最適な自然豊かな地域です。東北海道に位置する釧路湿原国立公園と阿寒摩周国立公園は、希少な野生動物や多様な生態系の宝庫です。地元の人々は長年にわたり、この貴重な自然を守ってきました。この4K動画では、地域の美しい風景やアクティビティを紹介しています。ガイドツアー、釣り、サイクリング、ハイキング、カヌーなどが楽しめます。阿寒エリアではアイヌ文化やオンネト湖のサイクリング、メアカン山のハイキングがあり、摩周エリアでは温泉や地元のフルーツが楽しめます。釧路エリアでは和商市場や釧路湿原国立公園でのカヌーツアーが紹介されており、手つかずの北海道の美しさを探求することを促しています。' where id = 'E-umUswt-0Vd-Du7DSAdX';
update content_bodies set title = 'Japan Hokkaido Adventure Travel in summer, Kushiro, Akan, Mashu【4K】-Untouched HOKKAIDO-', description = 'Untouched Hokkaido is a pristine region in Japan, ideal for adventure travelers. It features the Kushiro Shitsugen National Park and Akan Mashu National Park, both located in eastern Hokkaido, which are home to rare wildlife and diverse ecosystems. The local communities have long protected this precious nature. This 4K video showcases the stunning landscapes and activities available in the area, including guided tours, fishing, cycling, hiking, and canoeing. Highlights include the Akan area with its Ainu culture, Lake Onneto cycling, and Mt. Meakan hiking. The Mashu area offers hot springs and local fruits, while the Kushiro area features the Washo Market and canoe tours in Kushiro-Shitsugen National Park. The video serves as an invitation to explore the untouched beauty of Hokkaido.' where id = 'MGopYeVUQWif5o7rpP-Nq';
update content_bodies set title = '手つかずの北海道：釧路湿原国立公園北斗サイトウォーキングツアー【4K】', description = '手つかずの北海道は、日本の自然の美しさと冒険の機会で知られる地域です。特に、東北海道に位置する釧路湿原国立公園と阿寒摩周国立公園は、希少な野生動物や多様な生態系の宝庫です。この貴重な自然は、地元の人々によって長い間守られてきました。この動画では、釧路湿原展望台から北斗遺跡までのウォーキングツアーを紹介し、地域の静かな風景と豊かな生物多様性を強調しています。' where id = '8231IFKqqPSXcB0cAJGJw';
update content_bodies set title = 'Untouched HOKKAIDO : Kushiro-Shitsugen National Park Hokuto Site Walking Tour【4K】', description = 'Untouched Hokkaido is a pristine area in Japan, celebrated for its natural beauty and adventure opportunities. The region, particularly Kushiro Shitsugen National Park and Akan Mashu National Park in eastern Hokkaido, is home to unique wildlife and diverse ecosystems. Local communities have long protected this valuable nature. The video showcases a walking tour from the Kushiro Marsh Observatory to the Hokuto Ruins, highlighting the serene landscapes and rich biodiversity of the area.' where id = 'eRoyTWrWEuLCBZTRX27lv';
update content_bodies set title = '手つかずの北海道：北海道釧路湿原国立公園カヌーツアー', description = '手つかずの北海道は、日本の自然の美しさと冒険の機会で知られる純粋な地域です。この地域には、東北海道に位置する釧路湿原国立公園と阿寒摩周国立公園が含まれており、珍しい野生動物や多様な生態系が生息しています。地元の人々は、長年にわたりこの貴重な自然を守る重要な役割を果たしてきました。4K映像では、この手つかずの楽園の美しい風景と野生動物が紹介されています。' where id = 'eLsrNpOs4GLaG650r5rvW';
update content_bodies set title = 'Untouched Hokkaido: Japan Hokkaido Kushiro-Shitsugen National Park Canoe Tour', description = 'Untouched Hokkaido is a pristine area in Japan, renowned for its natural beauty and adventure opportunities. The region includes Kushiro Shitsugen National Park and Akan Mashu National Park, both located in eastern Hokkaido, which are home to unique wildlife and diverse ecosystems. The local communities have played a vital role in preserving this precious nature over the years. A 4K video showcases the stunning landscapes and wildlife of this untouched paradise.' where id = 'cszLPnrjxVnq2CCgFsA3Y';
update content_bodies set title = 'アトサヌプリハイキングツアー', description = 'アトサヌプリハイキングツアーは、北海道の美しい自然を体験できる機会を提供します。特に水のカムイ観光圏内での探検が楽しめます。詳細については、提供された日本語または英語のウェブサイトをご覧ください。' where id = 'VTnu_RywFYWPRIoaFI4sX';
update content_bodies set title = 'Atosa-nupuri Hiking Tour', description = 'The Atosa-nupuri Hiking Tour offers an opportunity to explore the untouched beauty of Hokkaido, specifically within the water-rich Kamui tourism area. For more information, visit the Japanese or English websites provided.' where id = 'lh3lmmZnFHYyX0ibHSL8u';
update content_bodies set title = '釧路川源流カヌーツアー', description = '釧路川源流カヌーツアーは、北海道の手つかずの水域を探検するユニークな機会を提供します。このツアーは、地域の自然の美しさと文化的重要性を強調する「水のカムイ観光圏」の一部です。詳細については、提供された日本語または英語のウェブサイトをご覧ください。' where id = 'igShmSaEu17S3QK6iEHG6';
update content_bodies set title = 'Kushiro River Headwaters Canoe Tour', description = 'The Kushiro River Headwaters Canoe Tour offers a unique opportunity to explore the pristine waters of Hokkaido. This tour is part of the Untouched Hokkaido tourism area, which emphasizes the natural beauty and cultural significance of the region. For more information, visit the Japanese or English websites provided.' where id = '1VNnzVlCoS3NGg2-amWVn';
update content_bodies set title = 'メアカン山ハイキング：阿寒湖畔コース（往復12km、7時間）', description = 'メアカン山のハイキングコースは、往復12kmで、所要時間は約7時間です。このコースは、自然の美しさと手つかずの風景で知られる北海道の地域に位置しています。ハイキング中には、阿寒湖畔エリアの素晴らしい景色を楽しむことができ、自然愛好者やアウトドア愛好者にとって魅力的な目的地となっています。詳細については、提供された日本語および英語のウェブサイトを確認することができます。' where id = '-V0o01iNjSynorF60qpUg';
update content_bodies set title = 'Mt. Meakan Hiking: Akan Lakeside Course (12 km Round Trip) 7 hours', description = 'The Mt. Meakan hiking course is a 12 km round trip that takes approximately 7 hours to complete. It is located in the untouched region of Hokkaido, known for its natural beauty and pristine landscapes. The hiking experience offers stunning views of the Akan Lakeside area, making it a fantastic destination for nature lovers and outdoor enthusiasts. For more information, visitors can check the Japanese and English websites provided.' where id = 'OtwCKnP0nyGIAlUwvYnNR';
update content_bodies set title = '電動アシスト自転車でのオンネトーサイクリング（初心者向け）', description = 'このアクティビティは、初心者向けに設計された電動アシスト自転車を使用して、北海道のオンネトー湖を探索するユニークな機会を提供します。伝統的なサイクリングの体力的な負担を感じることなく、地域の自然の美しさを楽しむことができます。手つかずの北海道の風景は、このゆったりとしたライドの素晴らしい背景を提供します。詳細については、Untouched HokkaidoやSuper Fantastic Kushiro, Lake Akanの日本語および英語のウェブサイトを確認できます。' where id = 'x-VQoXun8cQ6z42_z6gaa';
update content_bodies set title = 'Lake Onneto cycling with electric-assist bike (for beginner)', description = 'This activity offers a unique opportunity to explore Lake Onneto in Hokkaido using an electric-assist bike, making it accessible for beginners. The experience is designed for those who want to enjoy the natural beauty of the area without the physical strain of traditional cycling. The untouched landscapes of Hokkaido provide a stunning backdrop for this leisurely ride. For more information, visitors can check the Japanese and English websites of Untouched Hokkaido and Super Fantastic Kushiro, Lake Akan.' where id = '9FXo_FQOcCJES2LhzOYYf';
update content_bodies set title = '未開の北海道 2021: 釧路、阿寒、摩周、川湯と共存する自然', description = '未開の北海道は、日本の自然の美しさと冒険の機会で知られる地域です。北海道の東部には、希少な野生動物や多様な生態系が生息する釧路湿原国立公園と阿寒摩周国立公園があります。地元の人々は、この貴重な自然を長年にわたり保護してきました。この4Kビデオでは、未開の北海道の壮大な風景と豊かな生物多様性を紹介しています。' where id = 'wKVBMZd2eyWyU4nUs7n2d';
update content_bodies set title = 'Untouched HOKKAIDO 2021: Co-existing with nature in Kushiro, Akan, Mashu and Kawayu(short ver.)', description = 'Untouched Hokkaido is a pristine region in Japan, celebrated for its natural beauty and adventure opportunities. The eastern part of Hokkaido features Kushiro Shitsugen National Park and Akan Mashu National Park, which are home to unique wildlife and diverse ecosystems. Local communities have long played a vital role in preserving this precious nature, ensuring that it remains unspoiled. This 4K video showcases the breathtaking landscapes and rich biodiversity of Untouched Hokkaido.' where id = 'hpZD7HDBGYGpAi_UIhzbu';
update content_bodies set title = '手つかずの北海道：日本の自然のワンダーランド（冬）', description = '北海道の東部は、北アメリカのプレート上に位置し、非常に珍しい植物や野生動物が生息する独自の地域です。地元の人々は自然と共存し、手つかずの自然エリアを保護してきました。主な観光地には、特別天然記念物である丹頂鶴の生息地である釧路地域や、国指定の自然記念物である霧多布岬があります。ボートクルーズで美しい夕日を楽しんだり、地元の炉端焼きや福司酒造の日本酒を味わったりできます。阿寒川沿いのスノーシューイングでは神秘的なオアシスに出会え、アイヌ文化も色濃く残っています。日本最大のカルデラ湖である屈斜路湖には多くの野生の白鳥が集まり、硫黄の蒸気を噴出する硫黄山も見どころです。川湯温泉では豊富な温泉水が楽しめ、摩周湖はその透明度と美しい青色で知られています。' where id = 'DXikhIrAGhaUnXVW87U-k';
update content_bodies set title = 'Untouched Hokkaido : Japan’s Natural Wonderland(Winter)', description = 'Eastern Hokkaido is a unique region located on the North American tectonic plate, rich in rare plant life and wildlife. The local communities have lived in harmony with nature, preserving untouched natural areas. Key attractions include the Kushiro area, home to the red-crowned crane, and Cape Kirakotan, a national natural monument. Visitors can enjoy stunning sunsets on a boat cruise, savor local Robatayaki cuisine, and taste Fukutsukasa sake, brewed with local spring water. Snowshoeing along the Akan River leads to a mystical oasis, while the Ainu culture, the indigenous people of Hokkaido, remains vibrant. Lake Kussharo, Japan''s largest caldera lake, hosts wild swans, and Mt. Iou emits sulfurous steam. Kawayu Onsen offers abundant hot spring water, and Lake Mashu is renowned for its clarity and unique blue color.' where id = 'm1GiL2EbzdsfVjDWzz1oM';
update content_bodies set title = '宇和島を巡る ～宇和島に行きたくなる／連れていきたくなる（15秒Ver.）', description = 'この動画は、宇和島を巡ることについて紹介しており、宇和島の魅力を伝えています。' where id = 'mLCDDczRg19Px-Qu2qujo';
update content_bodies set title = 'Exploring Uwajima - A Place You Want to Visit and Take Others (15-Second Version)', description = 'This video introduces the experience of exploring Uwajima.' where id = 'v3WA-vCV13w446zzBYGDy';
update content_bodies set title = '摩周湖：手つかずの北海道', description = '摩周湖は、北海道の弟子屈町に位置し、その独特な青色「摩周ブルー」で知られています。このカルデラ湖は、世界で最も透明度の高い湖であり、海抜351メートルに位置し、周囲約20キロメートル、最大深度211.4メートルを誇ります。300〜400メートルの急峻な崖に囲まれ、霧や水位の不思議な安定性でも有名です。湖の周辺は特別保護区域に指定されており、人間の手が加わらない自然が保たれています。摩周湖がある東北海道は、北アメリカのプレート上に位置し、独自の地理と希少な植物が豊富です。地元の人々は、地域の野生動物と共存し、手つかずの自然を守っています。' where id = 'rEwS8hESddoV6gvMHAK_i';
update content_bodies set title = 'Lake Mashu: Untouched Hokkaido', description = 'Lake Mashu, located near Teshikaga Town in Hokkaido, is renowned for its strikingly unique blue color, known as ''Mashu blue.'' This caldera lake, which is the clearest in the world, sits at an elevation of 351 meters above sea level, with a circumference of approximately 20 kilometers and a maximum depth of 211.4 meters. Surrounded by steep cliffs, Lake Mashu is famous for its mist and the mysterious stability of its water level, despite having no rivers flowing in or out. The area is a protected zone, ensuring that its pristine nature remains untouched by human activity. Eastern Hokkaido, where Lake Mashu is located, is characterized by its unique geography and rare plant life, as it lies on the North American tectonic plate. The local communities have coexisted with the region''s wildlife, preserving many natural areas in their untouched state.' where id = 'XdFMgt3DcejAjfjNP8n_W';
update content_bodies set title = '釧路湿原エリアのカヌーツアー：手つかずの北海道', description = '釧路湿原エリアでは、釧路川沿いの自然環境を探るユニークなカヌーツアーが提供されています。ドライスーツを着用し、ガイド付きのツアーに参加することで、カワセミやカワウソ、オオワシなど多様な野生動物を観察しました。東北海道は独自の歴史と地理を持ち、北アメリカのプレート上に位置しているため、非常に珍しい植物が豊富です。地元の人々は何世代にもわたり、この地域の野生動物と共存しており、国立公園内には手つかずの自然エリアが多く残されています。' where id = 'd8SYOGvzqBE16n37Mp-C8';
update content_bodies set title = 'Kushiro wetland area canoe tour: Untouched Hokkaido', description = 'The Kushiro wetland area offers a unique canoe tour that allows participants to explore the natural habitats along the Kushiro River. Dressed in a dry suit, I experienced a guided trip where I observed a diverse range of wildlife, including kingfishers, otters, and Stellar’s Sea Eagles. Eastern Hokkaido is characterized by its distinct history and geography, situated on the North American tectonic plate, which contributes to its rare plant life. The local communities have lived in harmony with the region''s wildlife for generations, preserving many untouched natural areas within the national parks.' where id = 'dpvCmo2IBqYTaFtKzmiLC';
update content_bodies set title = '風景編①｜ふじのくに美しく品格のある邑', description = '農山村地域には、農業の営みを通じて育まれた美しい風景が広がっています。これらの風景は見る人を癒し、懐かしい日本の原風景を思い起こさせるものであり、まさに「心のふるさと」と言えるでしょう。静岡県内の四季折々の美しい風景をぜひご覧ください。ふじのくに美しく品格のある邑についての詳細は、http://www.fujinokuni-mura.net/をご覧ください。静岡県の旬な農山村イベント情報は、https://www.shizuoka-murasapo.net/で確認できます。' where id = 'qheCD9eLV45jMmd9LD8HL';
update content_bodies set title = 'Charming and Graceful Villages in ''FUJINOKUNI''', description = 'The rural areas of Fujinokuni showcase stunning landscapes shaped by agricultural practices. These scenes provide a sense of healing and evoke a nostalgic feeling reminiscent of Japan''s original landscapes, truly representing a ''hometown of the heart.'' Experience the beautiful seasonal views of Shizuoka Prefecture. For more information about the charming villages of Fujinokuni, visit http://www.fujinokuni-mura.net/. For updates on seasonal rural events in Shizuoka Prefecture, check https://www.shizuoka-murasapo.net/.' where id = '877-SjbObrFbatJWJXcHa';
update content_bodies set title = 'TOKAIDOプロモーションビデオ', description = '静岡県を東西に走る東海道の魅力を紹介するプロモーションビデオです。昔の歴史を今に伝える街歩きの楽しさを体験できる内容となっています。' where id = '3QcbOtFh1PMxlP6ASsOE3';
update content_bodies set title = 'TOKAIDO Promotional Video', description = 'The Tokaido runs through Shizuoka Prefecture from east to west. This video introduces the charm of walking through towns that convey the history of the past to the present.' where id = 'h4gXR1dYkA2egcDhJlMAy';
update content_bodies set title = '伊豆半島を体験する', description = 'この文章では、伊豆半島ジオパークで体験できるさまざまな楽しみを紹介しています。' where id = 'PZoVWvGFHKH9Enoa09SEe';
update content_bodies set title = 'Experience the Izu Peninsula', description = 'This text introduces the various enjoyable experiences available at the Izu Peninsula Geopark.' where id = '5hqOJ-mvyBO4ms3LslXWm';
update content_bodies set title = '富山｜TOYAMA SPRING MOVIE 4K', description = 'この映像は、富山の美しさを紹介しています。伊織橋や富山県美術館、フランス料理レストランのラ・シャンスなどの観光名所が登場します。また、砺波チューリップ公園や高岡御車山祭、立山、黒部平、黒部ダムなどの自然の景観も強調されています。その他の注目スポットには、室堂、雷鳥荘、みくりが池、立山黒部アルペンルート、称名滝が含まれています。' where id = 'NqTqc3-cfsxrzT7N-Ca8t';
update content_bodies set title = 'Toyama | TOYAMA SPRING MOVIE 4K', description = 'This video showcases the beauty of Toyama, featuring various attractions such as Iori Bridge, Toyama Prefectural Museum of Art and Design, and La Chance, a French cuisine restaurant. It also highlights the Tonami Tulip Park, Takaoka MikurumaYamasai festival, and the stunning natural landscapes of Tateyama, Kurobedaira, and Kurobe Dam. Other notable locations include Murodo, Raichoso, Mikurigaike, and the Tateyama Kurobe Alpine Route, as well as the impressive Shomyodaki waterfall.' where id = 'wifK9zVrEyQd0WQ1yfJy7';
update content_bodies set title = '伊豆半島ジオパークのマリンスポーツ　海ジオムービー「イメージワード編」', description = 'ユネスコ世界ジオパークに認定された伊豆半島ジオパークでの海のアクティビティの魅力を紹介する「海ジオ」シリーズの第3弾です。' where id = 'lsdEk2flSN_Gp5dBW4ZuW';
update content_bodies set title = 'Marine Sports in Izu Peninsula Geopark: Ocean Geo Movie ''Image Word Edition''', description = 'This is the third installment of the Ocean Geo series, showcasing the charm of enjoying marine activities in the Izu Peninsula Geopark, which is recognized as a UNESCO Global Geopark.' where id = 'PR0vi7ZW9U87vD45sdBd7';
update content_bodies set title = '立山黒部｜TATEYAMA SUMMER MOVIE 4K', description = '立山黒部エリアは、壮大な自然景観と観光名所が魅力です。主な見どころには、雄大な称名滝や美しい黒部峡谷トロッコ、リラックスできる足湯があります。訪れる人々は、立山山脈の象徴的な場所である弥陀ヶ原やみくりが池を探索できます。また、工学の驚異である黒部ダムも必見です。その他の注目スポットには、室堂や雷鳥荘、黒部平があり、この美しい地域での息をのむような景色と体験を提供しています。' where id = 'dyXnuQjWezsnJJWVkreS0';
update content_bodies set title = 'Tateyama Kurobe | TATEYAMA SUMMER MOVIE 4K', description = 'The Tateyama Kurobe area features stunning natural landscapes and attractions. Key highlights include the majestic Shomyo Falls, the scenic Kurobe Gorge Railway, and relaxing footbaths. Visitors can explore the iconic Tateyama mountain range, including Midagahara and Mikurigaike. The Kurobe Dam, a marvel of engineering, is also a must-see. Other notable locations include Murodo and Raichoso, as well as Kurobedaira, offering breathtaking views and experiences in this beautiful region.' where id = 'c4mqhgdUbsoQBR3IGrLaV';
update content_bodies set title = '立山黒部', description = '立山黒部地域は、黒部や称名滝、黒部峡谷トロッコなどの美しい自然景観と観光名所が点在しています。訪れる人々は、静かな黒薙温泉を楽しんだり、雄大な立山山脈を探索したりできます。主な見どころには、弥陀ヶ原、みくりが池、そして壮大な黒部ダムがあります。また、雷鳥荘などの宿泊施設や、黒部平からの美しい景色も楽しめます。さらに、五箇山の相倉合掌造り集落は、伝統的な文化体験を提供し、この美しい地域の魅力を高めています。' where id = 'Mdj5JyvbFzOcEc1hHkwhB';
update content_bodies set title = 'Tateyama Autumn Movie 4K', description = 'The Tateyama region features stunning natural landscapes and attractions, including Kurobe, Shomyo Falls, and the Kurobe Gorge Railway. Visitors can enjoy the serene Kuronogi Hot Spring and explore the majestic Tateyama mountain range. Key highlights include Midagahara, Mikurigaike, and the impressive Kurobe Dam. The area also offers accommodations like Raichoso and scenic views from Kurobedaira. Additionally, the historic Gokayama village showcases traditional Gassho-style houses, enriching the cultural experience of this beautiful region.' where id = 'SDPDszZBJRaZ3Gv7NE_He';
update content_bodies set title = '宮古ブルー透明度の高い「あお」', description = '「宮古ブルー」という色をご存知でしょうか。これは、青にも緑にも見える宮古島の自然が生み出す独特のブルーを指します。少しだけ海中散歩の気分でご覧ください。宮古諸島の美しい景色を集めたパンフレットのデジタル版が公開されましたので、ぜひご覧ください。' where id = 'Y6C8p_IUwy9c8CiLLJpdV';
update content_bodies set title = 'Miyako BLUE infinitely clear ocean', description = 'Have you heard of the color ''Miyako Blue''? It refers to the unique blue created by the natural beauty of Miyako Island, which can appear both blue and green. Take a moment to enjoy a glimpse of the underwater world. A digital version of a brochure showcasing the beautiful scenery of the Miyako Islands has been released! Be sure to check it out.' where id = 'HCvCUcH6nrIhV4D8wLRRD';
update content_bodies set title = '宇和島 ～宇和島を知りたくなる（30秒Ver.）', description = 'この動画は、宇和島の魅力を紹介し、視聴者にこの街についてもっと知りたくなるよう促しています。' where id = 'YGyP7OSe8-nYYTso_mcic';
