update content_bodies set title = '宇和島を巡る ～宇和島に行きたくなる／連れていきたくなる（30秒Ver.）', description = 'この動画は、宇和島を巡ることについて紹介しており、宇和島の魅力を伝えています。' where id = 'S-fke4QGzBlb1kyeuF0Kp';
