update content_bodies set title = '宇和島に住む ～宇和島に関わりたくなる／住みたくなる／住み続けたくなる（30秒Ver.）', description = 'この動画は、宇和島に住むことの魅力や体験について紹介しています。宇和島の生活がどのようなものであるかを知ることで、地域に関わりたい、住みたい、そして住み続けたいと思わせる内容となっています。' where id = 'pt-EvcEsfDduHe5gNcLDp';
