update content_bodies set title = 'ユネスコ隠岐世界地質公園の美しい景色', description = '島根県の隠岐は、雄大で美しい景色で知られています。ユネスコ隠岐世界地質公園では、これらの絶景が立体的に表現され、地域の自然の美しさと壮大さが強調されています。' where id = 'DLN7fs7bASo94kOXCKGR4';
update content_bodies set title = 'Stunning Scenery of UNESCO Oki Geopark', description = 'The Oki Islands in Shimane are renowned for their breathtaking landscapes. The UNESCO Oki Geopark showcases these magnificent views, highlighting the natural beauty and grandeur of the region.' where id = 'GNN2uTgGR8arCh9K-HzqW';
update content_bodies set title = '日東タタラ炉', description = '日東タタラ炉は、島根県に位置する伝統的な日本の製鉄施設で、美しい自然景観が広がっています。この場所は、日本の豊かな文化遺産を体現しており、世代を超えて受け継がれてきた製鉄の古来の技法を示しています。この炉は、日本の産業史において重要な側面を表すだけでなく、自然と職人技の調和の取れた関係を強調しています。' where id = 'zTfO473fQPj50sqGL77jH';
update content_bodies set title = 'Nittoho Tatara Furnace', description = 'The Nittoho Tatara Furnace is a traditional Japanese iron-making facility located in Shimane Prefecture, known for its beautiful and untouched landscapes. This site embodies the rich cultural heritage of Japan, showcasing the time-honored methods of iron production that have been passed down through generations. The furnace not only represents a significant aspect of Japan''s industrial history but also highlights the harmonious relationship between nature and craftsmanship.' where id = 'UDmaQnQ9foUk98lYRwwgo';
update content_bodies set title = '出雲大社', description = '出雲大社は島根県に位置し、美しい自然景観で知られる重要な文化遺産です。特に「縁結びの聖地」として有名で、恋愛や人間関係を求める訪問者が多く訪れます。この神社は、日本の美しい精神を体現しており、手つかずの自然環境がその静かな雰囲気を引き立てています。' where id = 'MoIxG_8G67cAC_xwcoaOF';
update content_bodies set title = 'Izumo Taisha Grand Shrine', description = 'Izumo Taisha Grand Shrine, located in Shimane Prefecture, is renowned for its stunning natural landscapes and is considered a significant cultural site in Japan. It is often referred to as a matchmaking sanctuary, attracting visitors seeking love and relationships. The shrine embodies the beautiful spirit of Japan, showcasing untouched environments that enhance its serene atmosphere.' where id = 'Gywgb9-X9ktroitEWd1Xf';
update content_bodies set title = 'ユネスコ支援の隠岐諸島グローバルジオパークでのライブパフォーマンス', description = '隠岐諸島は島根県に位置し、美しい自然景観と文化遺産で知られています。このライブパフォーマンスは、ユネスコ支援の隠岐諸島グローバルジオパークで行われ、地域のダイナミックな景観と日本の美しい精神を披露します。このイベントは、島々の独特な環境と文化的重要性を強調し、参加者にとって記憶に残る体験となるでしょう。' where id = 'WZMnG-c9NZkz65SmHQfeQ';
update content_bodies set title = 'Live Performance at the UNESCO-supported Oki Islands Global Geopark', description = 'The Oki Islands, located in Shimane Prefecture, are renowned for their stunning natural landscapes and cultural heritage. This live performance takes place in the UNESCO-supported Oki Islands Global Geopark, showcasing the area''s dynamic views and the beautiful spirit of Japan. The event highlights the unique environment and cultural significance of the islands, making it a memorable experience for attendees.' where id = 'P-9j32vCeYxQK4aj6rjkf';
update content_bodies set title = '出雲大社', description = '出雲大社は、島根県に位置する美しい景観を持つ聖地です。日本の精神を体現し、地域の原風景を示しています。この場所は、結びつきや絆を形成する重要な場所として知られています。' where id = 'BlAU4OlFoRXCNp9iEH6zx';
update content_bodies set title = 'Izumo Taisha', description = 'Izumo Taisha is a sacred place known for its beautiful scenery in Shimane, Japan. It embodies the essence of Japanese spirituality and showcases the original landscapes of the region. This site is recognized as a significant location for forming connections and bonds.' where id = 'xC7gSmPphHxZAlJO2gGpE';
update content_bodies set title = '日刀保踏鞴', description = '日刀保踏鞴は島根に位置し、絶佳の美景で知られています。日本の精神を体現し、地域の原風景を示しています。また、日本の古い製鉄の伝統とも関連しています。' where id = 'qqEtTrsed7S4wQWa2deiA';
update content_bodies set title = 'Nihon Tohbatake', description = 'Nihon Tohbatake is a place in Shimane known for its stunning natural beauty. It embodies the essence of the Japanese spirit and showcases the original landscapes of the region. Additionally, it is associated with Japan''s ancient iron-making traditions.' where id = '2PUEfPu3eJuyt2HAZZYYu';
update content_bodies set title = '大橋川、宍道湖の朝陽', description = '島根の素晴らしい美景を表現しています。日本の自然の美しさを感じさせるこの景色は、詩的で絵画のようであり、大橋川と宍道湖の朝陽の輝きを強調しています。' where id = 'QKzXLIUcU-ycRQebvnd2I';
update content_bodies set title = 'The Morning Sun over Ohashi River and Lake Shinji', description = 'A beautiful view in Shimane, capturing the essence of Japan''s natural beauty. The scene is described as poetic and picturesque, highlighting the splendid light of the morning sun over Ohashi River and Lake Shinji.' where id = 'VToVh2sUC0t1IFJZfAkVh';
update content_bodies set title = '隱岐世界地質公園美景音樂會', description = '隱岐の美しい風景を楽しむ音楽会です。島根に位置する隱岐の雄大な自然と、日本の精神を感じることができる特別な体験を提供します。' where id = 'cvnFUCVRB2fYlHZMApN_F';
update content_bodies set title = 'Oki World Geopark Scenic Music Concert', description = 'The concert showcases the magnificent beauty of Oki, located in Shimane, Japan. It highlights the stunning landscapes and the essence of Japanese spirit, offering a unique experience that combines nature and music.' where id = 'H_HXO6zesM7WcjJm-Yo0f';
update content_bodies set title = '島根の絶佳美景 印象篇', description = '島根は、今なお悠久の歴史と伝統文化を保っています。高精細な4K映像を通じて、美しく素朴な日本の原風景を楽しみましょう。島根にお越しいただき、美しさに出会い、リアルな体験を感じてください。島根の魅力を全方位で展開する5分間のハイライト版です。' where id = '2_jOf9SIbQheqjNGjsixi';
update content_bodies set title = 'The Stunning Scenery of Shimane: An Impression', description = 'Shimane retains a long-standing history and traditional culture. Let''s appreciate the beautiful and simple essence of Japan through high-definition 4K imagery. We welcome you to Shimane to encounter beauty and experience authenticity. This is a condensed 5-minute version showcasing the charm of Shimane in its entirety.' where id = 'xiWNihbWypwmHzTqxEOmx';
update content_bodies set title = '島根的絕佳美景 印象篇', description = '島根には悠久の歴史と文化が今も息づいています。高解像度の4K映像を通じて、心惹かれる美しい日本の原風景をお楽しみください。さあ、島根へ行き、本物の風景に出会う旅に出かけましょう。本篇の映像は、島根の魅力を五分間の短編に凝縮しています！' where id = 'AjrWM6JzQYeMdUYika5Xb';
update content_bodies set title = 'Stunning Scenery of Shimane: An Impression', description = 'Shimane is a place where ancient history and culture still thrive today. Experience the captivating beauty of Japan''s original landscapes through high-resolution 4K imagery. Come and embark on a journey to encounter the authentic scenery of Shimane. This video encapsulates the charm of Shimane in a concise five-minute short film!' where id = 'Anj4duSHGkOdBsPUkPJ-k';
update content_bodies set title = '島根の絶佳美景', description = '島根は、今なお悠久の歴史と伝統文化を保っています。高精細な4K映像を通じて、美しく素朴な日本の原風景を楽しみましょう。島根にお越しいただき、美しさに出会い、リアルな体験をしてください。' where id = 'adYTAER8EOjP-T-99BCSW';
update content_bodies set title = 'The Stunning Scenery of Shimane', description = 'Shimane retains a long history and traditional culture. Let''s appreciate the beautiful and simple original appearance of Japan through high-definition 4K images. We welcome you to Shimane to encounter beauty and experience authenticity.' where id = 'gT57TerVaTZ-wf_TbDufH';
update content_bodies set title = '島根的絕佳美景', description = '島根には悠久の歴史と文化が今も息づいています。高解像度の4K映像を通じて、心惹かれる美しい日本の原風景をお楽しみください。さあ、島根へ行き、真実の風景に出会う旅に出かけましょう。' where id = 'WsYvSE2HQD9i_kigYEl4S';
update content_bodies set title = 'Stunning Scenery of Shimane', description = 'Shimane is a place where ancient history and culture still thrive today. Experience the captivating beauty of Japan''s original landscapes through high-resolution 4K imagery. Come and embark on a journey to encounter the true scenery of Shimane.' where id = 'Aa0jFvyKvY9YTZ-5AN_il';
update content_bodies set title = '島根県の美しい風景編集動画', description = 'この編集動画では、島根県の美しく懐かしい風景を4K HDで紹介しています。地域の豊かな歴史と文化を強調し、島根が提供する本物の体験を視聴者に呼びかけています。この動画は、日本の原風景を通じた視覚的な旅であり、この地域に息づく時を超えた美しさを強調しています。' where id = 'uZnhYTvvu3X2JhD2zA0m-';
update content_bodies set title = 'Shimane Prefecture''s Beautiful Scenery Editorial Video', description = 'This editorial video showcases the beautiful and nostalgic landscapes of Shimane Prefecture in stunning 4K HD. It highlights the region''s rich history and culture, inviting viewers to experience the authenticity that Shimane offers. The video serves as a visual journey through Japan''s original scenery, emphasizing the timeless beauty that continues to thrive in this area.' where id = '2fJSfp9hX6fQzAprKzB8j';
update content_bodies set title = '「島根恋旅」withしまねっこ', description = '島根県を舞台にしたご当地ソング「島根恋旅」は、１２年連続で紅白歌合戦への出場を目指す水森かおりさんを応援しています。この取り組みを支援するために、しまねっこと島根県の「水森かおり『島根恋旅』応援団」が協力し、県民参加の応援PVを制作しました。' where id = 'JBBemO0HOsM6IOjKsHUtQ';
update content_bodies set title = 'Shimane Love Journey with Shimane-kko', description = 'The local song ''Shimane Love Journey'' aims for 12 consecutive appearances in the Kohaku Uta Gassen, supporting singer Kaori Mizumori. To assist in this endeavor, Shimane-kko and the ''Kaori Mizumori Shimane Love Journey Support Group'' collaborated to create a promotional video featuring participation from the residents of Shimane Prefecture.' where id = 'tsyk2nqvGC112Qp-cd6VE';
update content_bodies set title = 'とっておきの島 ～島ガールが紡いだご縁～', description = 'この物語は、島根県・隠岐の島で遊覧船のガイドを務める戸田さおりさんを中心に展開します。彼女は10年前に大阪から隠岐に移住し、故郷の祖母の意思を継いでいます。ガイドの仕事の傍ら、島で出会った仲間たちと共に隠岐を盛り上げる活動を行っています。友人の結婚をきっかけに、戸田さんは島の人々を巻き込んだサプライズを計画します。隠岐民謡「しげさ節」の一節をモチーフにしたウェディングレセプションが、フェリーの上で行われますが、実は島の人々も別のサプライズを用意していました。この13分36秒のドキュメンタリー映像は、隠岐の魅力を再認識し、発信することを目的としており、自由に使用可能です。DVD希望者は、神々の国しまね実行委員会に問い合わせてください。' where id = '_S9mco92MZuLqlrjXH3BA';
update content_bodies set title = 'A Special Island - Connections Woven by Island Girls', description = 'The story follows Saori Toda, a tour boat guide on Oki Island in Shimane Prefecture, who moved from Osaka ten years ago to fulfill her late grandmother''s wishes. Alongside her guiding work, she engages in community activities with friends she met on the island to promote Oki. When one of her friends decides to leave the island due to marriage, Saori plans a surprise involving the entire community. Inspired by a line from the local folk song ''Shigesabushi,'' the surprise takes place on a ferry during a wedding reception. However, the islanders have their own surprise planned for that day. This 13-minute and 36-second documentary, produced by ''Obza Eye'' and ''Orange and Partners,'' aims to help the local community rediscover and promote the charm of Oki Island. The video can be freely used without modification, and those interested in a DVD can contact the Shimane Prefecture Committee.' where id = '93ZkTscXdjw6FciLfs_Jj';
update content_bodies set title = 'しまねっこのうた＆ダンス', description = '島根県の観光キャラクターであり、「神々の国しまね」のマスコットキャラクターである「しまねっこ」のうたとダンスについて紹介しています。みんなにもこのうたとダンスを覚えてほしいという願いが込められています。作詞作曲はことのはもえ、うたはことのはが担当し、振付はリライズダンススクールの門脇のぞみが行っています。ダンスには左側にみなみ、右側にさくらが参加しています。' where id = 'RO0cgtWoOV54_VC_otlNz';
update content_bodies set title = 'Shimanekko''s Song and Dance', description = 'This is the song and dance of Shimanekko, the mascot character of Shimane Prefecture and ''The Land of the Gods.'' The creators hope everyone will learn it! The song is written and composed by Moeko Kotonohana, sung by Kotonohana, and choreographed by Nozomi Kadowaki from Rerise Dance School. The dance features Minami on the left and Sakura on the right.' where id = '3fWiUc5ki4CBJ9z0L5JKt';
update content_bodies set title = '神々の国しまね劇場『ヤマタノオロチ』', description = '島根県の観光キャラクター「しまねっこ」と観光大使が、有名な出雲神話であるヤマタノオロチ退治を紙芝居形式で紹介します。しまねっこの可愛らしい黄色い手が紙芝居を持っている姿が魅力的です。また、2011年12月3日と4日に開催される『「きゃら在月」inしまね』の告知も含まれています。2012年7月21日から始まる「神話博しまね」に向けて、神話を予習し、より楽しい島根の旅を楽しむための良い機会です。' where id = 'Nh3oj1pdpuOG71tVjXVFS';
update content_bodies set title = 'Yamata no Orochi at Shimane Theater', description = 'The official mascot of Shimane Prefecture, ''Shimanekko,'' along with the Shimane tourism ambassador, presents the famous Izumo myth of the Yamata no Orochi slaying through a picture-story show. Shimanekko''s cute yellow hands holding the picture book add charm to the performance. Additionally, there is an announcement for the event ''Charazai Tsuki in Shimane'' taking place on December 3rd and 4th, 2011. As the ''Mythology Expo Shimane'' is set to begin on July 21, 2012, this is a great opportunity to learn about the myths and enhance your travel experience in Shimane.' where id = '6YBpH8fDytqO3nF1ZZD6A';
update content_bodies set title = '石置き木羽葺屋根の美と技｜国指定重要文化財 渡邉邸を空から歩いて巡る【新潟・関川村】', description = '新潟県関川村にある渡邉邸は、江戸時代に豪農・渡邉家によって築かれた国指定重要文化財です。本動画では、約3000坪の広大な敷地に広がる歴史と美しさを、ドローン映像や内部・蔵・庭園を通じて紹介します。見どころは、日本最大規模の石置き木羽葺屋根や、職人の技が息づく柱や梁、囲炉裏の温もり、江戸時代の身分制度を伝える茶の間の構造などです。また、国名勝に指定された遠州流庭園や、江戸から平成にかけての大修理の歴史も紹介されます。' where id = 'YTW4HgNPeW5TRxR4akEws';
update content_bodies set title = 'The Beauty and Craftsmanship of Stone Roofed Wooden Houses: Aerial Tour of the Watanabe Residence, a National Important Cultural Property in Sekikawa Village, Niigata', description = 'The Watanabe Residence, built by the wealthy Watanabe family during the Edo period, is a designated National Important Cultural Property located in Sekikawa Village, Niigata Prefecture. This video showcases the residence''s historical beauty through aerial drone footage, as well as interior views of the building, its storehouses, and gardens, all spread over a vast area of approximately 3,000 tsubo. Highlights include Japan''s largest stone roofed wooden house, spaces reflecting the craftsmanship of artisans such as pillars, beams, and traditional tatami rooms, a nationally designated scenic garden, and the legacy of renovations from the Edo to the Heisei era. The video captures the grandeur of the estate, including the storehouses, the warmth of the hearth, and the structure of the tea room that reflects the class system of the Edo period.' where id = 'Okh9iC6L5tvTqkxo_DU7D';
update content_bodies set title = '空の道　－南紀熊野ジオパーク－', description = '360°撮影されたドローン映像で、南紀熊野の空の旅を楽しむことができます。この映像では、円月島、千畳敷、三段壁、富田川、フェニックス褶曲、橋杭岩、梶取崎、古座川の一枚岩、滝の拝、王子ヶ浜、熊野川、瀞峡、北山川など、南紀熊野ジオパーク内の美しいスポットが紹介されています。このプロジェクトは和歌山県が企画・制作し、南紀熊野ジオパーク推進協議会の協力を得て、株式会社ジオ・ラボと株式会社KOOが制作協力を行っています。' where id = 'zVCBE8spSa6Y-l8f3QDeU';
update content_bodies set title = 'Sky Road - Nanki Kumano Geopark', description = 'Enjoy a sky journey over Nanki Kumano with 360° drone footage. The video showcases various stunning locations within the Nanki Kumano Geopark, including Engetsu Island, Senjojiki, Sandanbeki, Tomitagawa, Phoenix Fold, Hashikuiiwa, Kajitorizaki, Kozagawa''s single rock, Taki no Hai, Oji Beach, Kumano River, Dorokyo, and Kitayama River. The project is organized by Wakayama Prefecture, with support from the Nanki Kumano Geopark Promotion Council and production assistance from Geo Lab Co., Ltd. and KOO Co., Ltd.' where id = '2x0iQTRBX6avZF4WVhFQz';
update content_bodies set title = 'しまねっこのうた＆ダンス（左右反転バージョン）', description = '島根県の観光キャラクターであるしまねっこのダンスを、みんなに覚えてもらいたいという思いから、鏡に映ったような左右反転バージョンが作られました。このダンスは、ろうにゃくなんにょを問わず、誰でも楽しめるように設計されています。作詞作曲はことのはもえ、歌はことのは、振付はリライズダンススクールの門脇のぞみ、ダンスはみなみが担当しています。' where id = 'jEy4IDPdmNZF0tKIdU-CL';
update content_bodies set title = 'Shimanecco''s Song & Dance (Mirror Version)', description = 'This is a mirror version of the dance for Shimane''s tourism character, Shimanecco, who represents ''Shimane, the Land of the Gods.'' The creator wanted everyone to learn the dance, so they made this version that reflects the movements as if seen in a mirror. The dance is intended for people of all ages to enjoy. The song is written and composed by Moeko Kotonoh, sung by Kotonoh, choreographed by Nozomi Kadowaki from Rerise Dance School, and performed by Minami.' where id = 'p_hK48ssbh5UJzd0KiYm3';
update content_bodies set title = '直江津港のエクスカーション No.3', description = 'フルブルーム桜ツアーでは、直江津港周辺やその先を訪れることを提案しています。特に桜の季節には、美しい景色を楽しむことができます。' where id = 'NpkHR1ArFpIH9gujJv-07';
update content_bodies set title = 'Port of Naoetsu excursion No.3', description = 'The Full-Bloomed Sakura Tour invites visitors to explore the area around Naoetsu Port and beyond, especially during the cherry blossom season.' where id = '-4BWbm9YvhbgxumWkZZxk';
update content_bodies set title = '南紀熊野への道：日本の田舎における伝統、自然、土地', description = '南紀熊野は、日本の田舎地域であり、著名な熊野古道の巡礼路が存在します。過去千年にわたり、一般市民から天皇まで、多くの人々が京都から熊野へと向かいました。現在でも、訪問者はその巡礼者たちの足跡を辿ることができます。この地域の人々は、厳しい自然環境とその恵みと共に、伝統的な儀式や祭り、料理、生活様式を長い間受け継いできました。南紀熊野ジオパークは、古代から現代までの伝統、自然、土地が交差する場所です。' where id = 'SmnGzjk8WX6rLZyp7EtJi';
update content_bodies set title = 'The Road to Nanki Kumano: Tradition, Nature and the Land in Rural Japan', description = 'Nanki Kumano is a rural region in Japan known for the Kumano Kodo Pilgrimage Routes, which have been traveled for over a thousand years by people from all walks of life, including emperors. Today, visitors can still follow the paths of these pilgrims. The local community has preserved traditional rituals, festivals, cuisine, and livelihoods, all intertwined with the rugged landscape and its natural resources, welcoming travelers from around the globe. The Nanki Kumano Geopark serves as a meeting point of tradition, nature, and the land, connecting the past with the present.' where id = '5IAznzpa-If_cGD38WCgq';
update content_bodies set title = '南紀熊野ジオパークの絶景３６０（４K, VR対応）・フェニックス褶曲', description = '南紀熊野ジオパークで地球の活動が生み出した絶景をゆっくりと眺める体験を提供します。自然の美しさを楽しみながら、周囲の音に耳を傾け、空気を感じることができます。この没入型の体験は、地球とのつながりを深め、その素晴らしさを再認識させてくれます。' where id = 'o_gEaX0yiTMZdMCT0sciS';
update content_bodies set title = 'Breathtaking Views of Nanki Kumano Geopark (4K, VR Compatible) - Phoenix Fold', description = 'Experience the stunning landscapes created by Earth''s activities at Nanki Kumano Geopark. Take your time to simply gaze at the beauty of nature, listen to the sounds around you, and feel the air. This immersive experience invites you to connect with the planet and appreciate its wonders.' where id = '3PUvDFqgMTwtomzhAoBhL';
update content_bodies set title = 'フロッタージュで絵本を作りました', description = '南紀熊野ジオパークでは地域の民話をもとにした絵本を制作しています。「橋杭岩の立岩伝説」では、大地の素晴らしさを伝えるために、実物の橋杭岩の上に紙を置き、鉛筆で凸凹をこすり写すフロッタージュ技法を用いています。この絵本は和歌山県立図書館やジオパークエリア内の各市町村図書館、南紀熊野ジオパークのホームページから閲覧可能です。ぜひ一度ご覧ください。' where id = '4rv2hQyQZSgKHbjQdfiva';
update content_bodies set title = 'Creating a Picture Book with Frottage', description = 'The Nanki Kumano Geopark is producing a picture book based on local folklore. The story ''The Legend of Hashikui-iwa'' uses the frottage technique, where paper is placed on the actual Hashikui-iwa rock and rubbed with a pencil to capture its texture, to convey the beauty of the earth. The picture book can be viewed at the Wakayama Prefectural Library, various municipal libraries within the geopark area, and on the Nanki Kumano Geopark website. We encourage you to take a look.' where id = '_22NLFAjqFzxStfkQtfL2';
update content_bodies set title = '那智勝浦の町中をプラット歩こう！～まちなかジオツアー～', description = '温泉や生まぐろ、絶景など、那智勝浦の魅力をジオパークの視点で楽しむことができます。町を散策するためのガイドマップ「プラットナ」が作成されており、ジオ視点での見どころを紹介しています。このガイドは紀伊勝浦駅の観光案内所などで入手可能ですので、ぜひ手に取って実際に町を歩いてみてください。' where id = 'jjFqlf6ab820vS2k9c3wC';
update content_bodies set title = 'Explore Nachikatsuura Town with a Geo Tour!', description = 'Experience the unique aspects of Nachikatsuura, where hot springs, fresh tuna, and breathtaking views all have a geological twist! A guide map called ''Plattna'' has been created to help visitors explore the town from a geo-park perspective. This summary introduces some highlights featured in Plattna. The guide is available at tourist information centers, such as the Kii-Katsuura Station, so be sure to pick one up and take a walk to discover the beauty of the area!' where id = '3YXTXXOVbbYRiI5AsGYqL';
update content_bodies set title = '南紀熊野ジオパークの絶景３６０（VR対応）・橋杭岩', description = '地球の活動によって生まれた絶景を、ゆっくりと眺めることができます。自然の音を聞き、空気を感じることで、心を落ち着けるひとときをお楽しみください。' where id = 'JvfABudyz8KOCellZiOWE';
update content_bodies set title = 'Stunning 360° Views of Nanki Kumano Geopark: Hashikui-iwa', description = 'Experience the breathtaking landscapes created by Earth''s activities at Nanki Kumano Geopark. Take your time to simply admire the beauty, listen to the sounds of nature, and feel the fresh air around you.' where id = '31Zq6RkWpDYWNRROSRmCA';
update content_bodies set title = 'UNDER GROUND OSAKA', description = '大阪のディープなサブカルチャーを体験できるスポットを紹介する動画です。アニメショップが数多く集まる「日本橋でんでんタウン」や、メイド喫茶でのひとときを楽しんだ後、昭和サブカルチャーの聖地として知られる「味園ビル」を訪れることができます。世界的に有名なメイドカフェやコスプレなど、魅力的なサブカルチャーが揃う大阪で、忘れられない体験をお楽しみください。大阪の魅力をもっと知りたい方は、ぜひチャンネル登録をお願いします！' where id = 'LLbZS-47nY2L7OXq4xO-t';
update content_bodies set title = 'UNDER GROUND OSAKA', description = 'Explore Osaka''s vibrant subculture through its unique hotspots, including Nipponbashi Denden Town, renowned for its numerous anime shops. Experience the charm of maid cafés before visiting the Misono building, a hidden gem celebrated as a hub for various Japanese subcultures. With world-famous maid cafés, cosplay, and other intriguing subcultures, Osaka offers an unforgettable experience. Don''t miss the chance to immerse yourself in one of the city''s most distinctive areas. Subscribe to our channel for more insights into Osaka''s wonders!' where id = 'Uka-X6Y4OJt3_DLGJjEyL';
update content_bodies set title = '大阪の観光スポットは朝から晩まで楽しめる！', description = '公式ウェブサイトOSAKA-INFOでは、大阪のさまざまな観光名所に関する情報が提供されています。訪れる人々は、日中ずっと楽しめる多様な観光スポットやアクティビティを探索できます。また、大阪アメイジングパスも紹介されており、観光客は市内の多くの名所や体験にアクセスできる特典があります。' where id = 'tjFPAqMXK8ICotqO1djHX';
update content_bodies set title = 'Osaka’s sights will keep you busy from morning to night!', description = 'The official website, OSAKA-INFO, provides comprehensive information about the various attractions in Osaka. Visitors can explore a wide range of sights and activities that will keep them engaged throughout the day. The Osaka Amazing Pass is also highlighted, offering tourists access to numerous attractions and experiences in the city.' where id = 'h-aD0KY725SkJe0DmoI5L';
update content_bodies set title = '自然から伝統まで、すべてを体験しよう！', description = '公式ウェブサイトOSAKA-INFOでは、大阪の観光名所や体験を紹介しています。特に、大阪アメイジングパスは、訪問者が大阪の自然の美しさや文化的伝統を体験できるさまざまなスポットを探索する機会を提供します。' where id = 'MdHnZTprW9AHzm9zjm-0o';
update content_bodies set title = 'Experience it all, from nature to tradition!', description = 'The official website for Osaka, known as OSAKA-INFO, provides a comprehensive guide to the city''s attractions, including the Osaka Amazing Pass. This pass offers visitors the opportunity to explore various sites and experiences that showcase both the natural beauty and cultural traditions of Osaka.' where id = 'GAnPRBiKsw81-Ot183mKg';
update content_bodies set title = '歴史的なダウンタウンアーケードを散策しよう', description = '天神橋筋商店街は、大阪にある日本最長の商店街で、全長2.6km、約600店舗が並んでいます。江戸時代に大阪天満宮のために発展したこのアーケードは、昔ながらのダウンタウンの雰囲気を今も残しています。新鮮な野菜や果物、着物、中古本、判子など、生活に必要なさまざまな商品が揃っています。また、名物のまんじゅうやコロッケなどのスナックを楽しんだり、大阪の商人たちのユーモアを味わったりすることもできます。天満ガラスや満月ポンなど、大阪ならではの特産品を扱う専門店もあり、ギフトにも最適です。' where id = 'u4uAFKCvblx2655jB-LpX';
update content_bodies set title = 'Enjoy a stroll in this historic downtown arcade', description = 'The Tenjinbashi-Suji Shopping Street in Osaka is the longest shopping arcade in Japan, stretching 2.6 km and featuring around 600 stores. Established during the Edo Era to serve the nearby Osaka Temmangu shrine, it retains a nostalgic downtown atmosphere. Visitors can find a variety of goods, from fresh produce and kimonos to used books and traditional hanko stamps. The arcade is also known for its famous snacks, such as manju sweet cakes and potato croquettes, as well as the lively humor of local traders. Unique Osaka products, including Temma glassware and Mangetsupon crackers, are available, making it an excellent spot for gift shopping.' where id = 'Soq6oZrmqE4qIYp2QQ_N0';
update content_bodies set title = '生き物の個性を感じる', description = 'NIFRELは、生き物の美しさをアートとして楽しむユニークな博物館です。訪問者は、色鮮やかな魚が魅了する「Colors」や、サバイバルスキルを見せる生き物がいる「Abilities」、多様な形の生き物を楽しむ「Shapes」など、7つのテーマゾーンを探索できます。2階には、活発な動物が集まる「Behavior」や、絶滅危惧種のホワイトタイガーやミニカバがいる「Waterside」があります。また、自然の美しさを表現した巨大な地球儀がある「WONDER MOMENTS」アートスペースも必見です。ユニークな体験として、「食べられる水」を提供するピクニックカフェや、展示物とのふれあいを撮影するフォトサービスもあります。入場料は大人1,900円、子供1,000円、幼児600円です。NIFRELは大阪のEXPOCITYにあり、10:00から20:00まで営業しています。' where id = 'SC2Fj-bpo4fE_7guf60kZ';
update content_bodies set title = 'Sense the individuality of living things', description = 'NIFREL is a unique museum that celebrates the beauty of living things, presenting them as art. Visitors can explore seven themed zones, including Colors, showcasing vividly colored fish; Abilities, where creatures demonstrate survival skills; and Shapes, featuring a variety of animal forms. The second floor includes Behavior, highlighting active animals, and Waterside, home to endangered species like white tigers and mini hippos. A highlight is the WONDER MOMENTS art space, featuring a giant globe that captures the beauty of nature. Unique experiences include a picnic cafe offering ''edible water'' and a photo service that captures moments of interaction with the exhibits. Admission prices are 1,900 yen for adults, 1,000 yen for children, and 600 yen for infants. NIFREL is located in EXPOCITY, Osaka, and operates from 10:00 to 20:00.' where id = 'ny5oHsiMzTvVfzHc6uMAm';
update content_bodies set title = '自転車で古代文化遺産を巡る', description = 'MOZU-FURUレンタサイクルは、堺市、藤井寺市、羽曳野市での観光用に電動自転車をレンタルするサービスです。自転車は任意の場所で受け取り、返却でき、同じ場所に返却すれば500円で利用できます。大泉公園観光案内所から出発し、堺のシンボルである世界三大古墳の一つ、仁徳天皇陵を訪れることをお勧めします。486mの長さを誇るこの巨大な古墳の荘厳な雰囲気を感じることができます。また、近くには堺市博物館があり、古墳内部のバーチャルリアリティ体験や、仁智天皇陵の丸い端を見渡せる展望台があります。さらに東には、皇大神の古墳がある古市古墳群があり、西には路面電車と刃物作りの地区があります。サービス料金は1,000円（税別）で、同じ場所に返却すれば500円になります。' where id = 'wK4aWGY3B7hGu-oUOxkjr';
update content_bodies set title = 'Tour ancient cultural heritage by bike', description = 'The MOZU-FURU Rent-a-cycle service offers electric bike rentals for sightseeing in Sakai, Fujiidera, and Habikino. You can pick up and drop off the bike at any location, with a fee of 500 yen if returned to the same spot. Starting from the Daisen Park Tourist Information Center, recommended sites include the Nintoku-tennō-ryō Kofun, one of the world''s largest burial mounds, and the Sakai City Museum, which features a virtual reality experience of the mound''s interior. Further east, the Furuichi Tombs, including the tomb of Emperor Ojin, are also notable attractions. The service costs 1,000 yen per person, including tax, and offers language support.' where id = 'Oep2cmM4gw-dxJlLeIWWf';
update content_bodies set title = '緑にあふれた奥河内を楽しむ一日', description = '奥河内黒丸村は、河内長野の魅力を存分に味わえる場所です。新鮮な地元産の農産物を扱うファーマーズマーケットや、地元の食材を使ったバイキングレストラン、収穫体験ができる畑があります。また、豊かな自然を巡るための自転車レンタルも可能です。近くには、森林サテライトの金根館や、河内長野の歴史を学べる村歴史館があります。大阪河内の木を使ったカトラリー作りや、家族繁栄を願うお守り作りの体験も楽しめます。30〜40分のドライブで、河内長野の新名所の一つである滝畑ダムにアクセスでき、自然に囲まれた美しい湖の景色を堪能できます。' where id = 'HomV6cEkQg3PPfJE2NXHH';
update content_bodies set title = 'Enjoy a day bursting with greenery in Okukawachi', description = 'Okukawachi-kuromaro village offers a delightful experience in Kawachi Nagano, featuring a farmer''s market with fresh produce, a buffet restaurant using local ingredients, and fields for pick-your-own crops. Visitors can rent bicycles to explore the lush nature of the area. Nearby attractions include the Kinkonkan forest satellite and the Village History Hall, where one can learn about the region''s history. Unique experiences such as cutlery making with local wood and crafting charms are available. A short drive leads to the scenic Takihata Dam, known for its stunning landscapes and serene lake. Bicycle rentals are available, with prices starting at 1,000 yen for hybrid cycles.' where id = '8qumsweSdSXzqGGYN-JJ-';
update content_bodies set title = '【¥0】大阪を無料で楽しもう！', description = '公式ウェブサイトOSAKA-INFOでは、大阪を無料で楽しむ方法についての情報を提供しています。大阪アメイジングパスに関する情報もあり、訪問者にさまざまな特典や割引を提供しています。' where id = '3xM9dA6fzzY6h4eLIXjH9';
update content_bodies set title = 'Enjoy Osaka for ¥0!', description = 'The official website for Osaka, OSAKA-INFO, provides information on how to enjoy the city for free. It features the Osaka Amazing Pass, which offers various benefits and discounts for visitors.' where id = 'DDyhywOOWWC_71zfIUpaw';
update content_bodies set title = '朝から夜まで見どころいっぱい！', description = '大阪の公式ウェブサイトでは、朝から夜まで楽しめるさまざまな観光スポットやアクティビティの情報が提供されています。観光客は、大阪周遊パスを利用することで、多くの施設や体験にアクセスできます。詳細については、公式ウェブサイトをご覧ください。' where id = 'NnWk_JJ1Hl8x0EKfO7cAt';
update content_bodies set title = 'A Day Full of Attractions from Morning to Night!', description = 'The official website for Osaka provides information about various attractions and activities available throughout the day. Visitors can explore the city using the Osaka Amazing Pass, which offers access to numerous sites and experiences. For more details, visit the official website.' where id = 'd-IyPLH_Uc3Q4dfIm_X-q';
update content_bodies set title = '大阪で日本一を体感！', description = '公式ウェブサイトOSAKA-INFOでは、大阪の観光名所や体験に関する情報を提供しています。訪問者は、大阪周遊パスを利用して、さまざまなスポットやアクティビティにアクセスすることができます。' where id = 'yQw-9POP5j9bwSQdwi24g';
update content_bodies set title = 'Experience Japan''s Best in Osaka!', description = 'The official website, OSAKA-INFO, provides information about Osaka''s attractions and experiences. Visitors can explore the city using the Osaka Amazing Pass, which offers access to various sites and activities.' where id = 'm36imKcjPsmaQ4rlA4qw6';
update content_bodies set title = '昔ながらの下町で散策を楽しむ', description = '公式ウェブサイトでは、大阪の伝統的な下町エリアを散策するための情報が提供されています。訪問者は、街のさまざまな観光名所やアクティビティについての詳細を見つけることができます。また、大阪周遊パスも紹介されており、これを利用することで大阪の複数のスポットやサービスを便利に体験することができます。' where id = '_OY-FTkmW0667f1XsAQqG';
update content_bodies set title = 'Enjoy a Stroll in the Traditional Downtown', description = 'The official website provides information about exploring Osaka''s traditional downtown areas. Visitors can find details on various attractions and activities available in the city. Additionally, the Osaka Amazing Pass is highlighted, which offers a convenient way to experience multiple sites and services throughout Osaka.' where id = 'VR0vPzUjP5SsmM3fwRtSZ';
update content_bodies set title = '生きものたちの個性にふれる', description = '公式ウェブサイトでは、大阪におけるさまざまな生きもののユニークな特徴を探求する情報が提供されています。また、観光客が大阪を楽しむためのさまざまな特典を提供する大阪周遊パスについても紹介されています。' where id = 'rx-85q-l1MK33hLjCX7vz';
update content_bodies set title = 'Encountering the Personalities of Living Beings', description = 'The official website provides information about exploring the unique characteristics of various living beings in Osaka. It also features the Osaka Amazing Pass, which offers various benefits for tourists looking to enjoy the city.' where id = 'hj0nZhFofnXWMrC1YT5QX';
update content_bodies set title = '自転車で古代の文化遺産めぐり', description = '公式ウェブサイトでは、大阪の古代文化遺産を自転車で巡る情報が提供されています。大阪周遊パスの紹介もあり、観光客がこの街の豊かな歴史や文化を体験するためのさまざまな特典が用意されています。' where id = 'rYkbvcBaFkdyccrCWu6Mx';
update content_bodies set title = 'Exploring Ancient Cultural Heritage by Bicycle', description = 'The official website provides information about exploring ancient cultural heritage sites in Osaka by bicycle. It highlights the Osaka Amazing Pass, which offers various benefits for tourists looking to experience the city''s rich history and culture.' where id = 'tNbjiiCw3AsnlJXqVxBaw';
update content_bodies set title = '緑あふれる奥河内で一日中遊ぶ', description = '大阪の奥河内エリアでは、一日中さまざまなアクティビティを楽しむことができます。公式ウェブサイトでは、この緑豊かな楽園での観光名所や体験に関する情報が提供されています。また、大阪周遊パスを利用すれば、さらにお得に市内を探索することができます。' where id = 'ezj9NuugnwHTRVfOqdBJn';
update content_bodies set title = 'Play All Day in the Lush Oku-Kawachi', description = 'Explore the beautiful Oku-Kawachi area in Osaka, where you can enjoy a variety of activities throughout the day. The official website provides information on attractions and experiences available in this green paradise. Additionally, the Osaka Amazing Pass offers great value for those looking to explore the city further.' where id = 'ZWHHNhdNUgpaGyJwqZPEc';
update content_bodies set title = '大自然も伝統も、気軽に体験！', description = '公式ウェブサイトOSAKA-INFOでは、大阪の観光情報を提供しています。大阪周遊パスについても紹介されており、さまざまな体験や観光名所を楽しむことができます。' where id = '2kCbQP4U_xTSKaKeYXr4L';
update content_bodies set title = 'Experience Nature and Tradition with Ease!', description = 'The official website, OSAKA-INFO, provides information about exploring Osaka. It highlights the Osaka Amazing Pass, which offers various experiences and attractions in the city.' where id = '3K1COKqcJvaZLbaHo71zv';
update content_bodies set title = '0円で楽しめる大阪！', description = '公式ウェブサイトOSAKA-INFOでは、大阪をお金をかけずに楽しむ方法についての情報が提供されています。大阪周遊パスに関する詳細も含まれており、さまざまな観光名所や体験を楽しむことができます。' where id = 'HXrTUy-xCy5H9RDppDFpP';
update content_bodies set title = 'Enjoy Osaka for Free!', description = 'The official website OSAKA-INFO provides information on how to enjoy Osaka without spending any money. It includes details about the Osaka Amazing Pass, which offers various attractions and experiences in the city.' where id = 'BlDZ4XIAB5RyNz_rE_ark';
update content_bodies set title = '大阪旅游記２０１７', description = '台湾で人気のYouTuber三原慧悟さんと俳優葛西健二さんが、大阪のあまり知られていないスポットを満喫する旅をしました。彼らは、知っているようで実は知らない大阪の魅力を体験しました。2017年3月18日と19日には、台湾の三井アウトレットパーク林口で「スポーツと食」をテーマにした大阪旅游展のイベントが開催され、二人もトークショーに登場しました。大阪の魅力を体験するために、ぜひお越しください。' where id = '6AANg4iYJwZWcqkmAjJj3';
update content_bodies set title = 'Osaka Travel Diary 2017', description = 'In March 2017, popular Taiwanese YouTuber Keigo Mihara and actor Kenji Kasai embarked on a journey to explore lesser-known spots in Osaka. They enjoyed various attractions that many might think they know but actually don''t. On March 18 and 19, a travel event themed ''Sports and Food'' was held at Mitsui Outlet Park in Linkou, Taiwan, featuring an Osaka tourism exhibition. Both Mihara and Kasai participated in a talk show during the event, inviting everyone to join and experience the charm of Osaka.' where id = '5fbrCeCuHVEUF45s2Kf05';
update content_bodies set title = '万博記念公園 EXPO’70パビリオン 別館', description = '万博記念公園のEXPO’70パビリオン別館は、大阪に位置する重要な観光スポットです。この施設は、1970年に開催された万博の歴史に興味を持つ訪問者にとって、当時の文化や技術の進歩を知るための貴重な情報を提供しています。' where id = 'AOuBQodX0YwXy8-FMEyd6';
update content_bodies set title = 'Expo ''70 Pavilion Annex', description = 'The Expo ''70 Pavilion Annex is part of the Expo ''70 commemorative park, located in Osaka. It serves as a significant site for visitors interested in the history of the Expo and offers insights into the cultural and technological advancements showcased during the event.' where id = 'AVEs05RXdrkVRZ8dK4MiG';
update content_bodies set title = '万博記念公園 EXPO’70パビリオン 別館', description = '万博記念公園に位置するEXPO’70パビリオン別館は、1970年の万博の歴史に興味を持つ訪問者にとって重要な場所です。このパビリオンでは、万博に関連するさまざまな展示やイベントが行われており、大阪を訪れる観光客にとっての主要な観光名所となっています。' where id = 'uRr6bkt7RMRo1edWAacfN';
update content_bodies set title = 'Expo ''70 Pavilion Annex', description = 'The Expo ''70 Pavilion Annex is located in the Expo ''70 Commemorative Park in Osaka, Japan. It serves as a significant site for visitors interested in the history of the 1970 World Expo. The pavilion showcases various exhibitions and events related to the Expo, making it a key attraction for tourists exploring Osaka.' where id = 's3F2uegVytkBy0IhAJTFX';
update content_bodies set title = '電車で巡る関西「目的地：大阪」', description = 'この動画シリーズでは、日本の関西地域の必見スポットや体験を紹介しています。今回のエピソードでは、ホストのダイアン・キチジツがヘリコプターで大阪の夜空を探索し、有名なダウンタウンの名所を新たな視点から見る様子が描かれています。詳細については公式ウェブサイトをご覧ください。関西エリアの発見を楽しんでください！' where id = 'O0lYAiqWDiuKIfW6ahKV4';
update content_bodies set title = 'Discover Kansai by Train ''Destination OSAKA''', description = 'This video series highlights the must-see attractions and experiences in the Kansai region of Japan. In this episode, host Diane Kichijitsu takes viewers on a helicopter tour over Osaka, showcasing the city''s famous downtown landmarks from a unique aerial perspective. For more information, visit the official website and enjoy your journey exploring the Kansai area!' where id = 'v0DSlEE4GiSJQpwHt9vzt';
update content_bodies set title = '電車で巡る関西の旅「行き先：嵐山（京都）」', description = 'この動画シリーズでは、日本の関西地域の必見スポットや体験を、さまざまな電車を利用して紹介しています。今回のエピソードでは、ホストのダイアン・キチジツが阪急電車を利用して京都の嵐山を訪れます。彼女は、伝統的な人力車に乗って町を巡ることから旅を始め、名所である竹林の独特な道を通り、美しい世界遺産の禅寺に到達します。' where id = 'RY0N91rlWSOdN9U_Ak8a8';
update content_bodies set title = 'Discover Kansai by Train ''Destination ARASHIYAMA (KYOTO)''', description = 'This video series highlights the must-see attractions and experiences in the Kansai region of Japan, utilizing various train lines for convenience. In this episode, host Diane Kichijitsu travels on the Hankyu train line to Arashiyama in Kyoto. She begins her journey by exploring the town in a Jinrikisha, a traditional rickshaw. The episode features a unique path through the famous bamboo forests, leading to a stunning Zen temple that is recognized as a World Heritage site.' where id = 'Ltq86RmsRKRiGzz5SU5hE';
update content_bodies set title = '近鉄で行く関西の旅「伊勢志摩編」', description = 'この動画シリーズでは、関西地域の必見スポットや体験を紹介し、様々な鉄道路線の便利さを活用しています。今回のエピソードでは、ホストの福龍勝が近鉄鉄道を利用して伊勢志摩を訪れます。まずはミキモト真珠島で真珠養殖の歴史を学び、その後、伊勢志摩の女性ダイバーが手に入れた新鮮な海の幸を味わいます。' where id = 'dCi6PMuqxXa0fJNbhOKCo';
update content_bodies set title = 'Discover Kansai by Train ''Destination ISE-SHIMA''', description = 'This video series highlights the essential attractions and experiences in the Kansai region of Japan, emphasizing the convenience of train travel. In this episode, host Katsura Fukuryu travels to Ise-shima using the Kintetsu railway. The journey begins at Mikimoto Pearl Island, where viewers learn about the history of pearl cultivation. Following this, the host enjoys fresh seafood caught by the local women divers, showcasing the region''s culinary delights.' where id = 'FUlLPgRaqEj8uIB7p59gF';
update content_bodies set title = '電車で巡る関西「目的地：神戸」', description = 'この動画シリーズでは、関西地域の必見スポットや体験を、さまざまな鉄道路線の便利さを活用して紹介します。今回のエピソードでは、ホストの桂福龍が阪神電車を利用して神戸市を訪れます。最初に日本酒の醸造所を巡り、最高の日本酒を味わった後、ハーバーランドに向かい、美しい夜景を楽しみます。' where id = '-P6IDP_dP8BdbicOTLt44';
update content_bodies set title = 'Discover Kansai by Train ''Destination KOBE''', description = 'This video series highlights the must-see attractions and experiences in the Kansai region of Japan, utilizing the convenience of various train lines. In this episode, host Katsura Fukuryu travels to Kobe city via the Hanshin railway. The journey begins with a tour of Japanese sake breweries, where he samples some of the finest sake. Following this, he visits Harborland to enjoy the stunning nighttime scenery.' where id = 'oIFDXkmPw8A33Sqt7VZoM';
update content_bodies set title = '関西を電車で巡る「目的地：宇治、伏見（京都）」', description = 'この動画シリーズでは、日本の関西地域の必見スポットや体験を紹介し、様々な電車の便利さを活用しています。今回のエピソードでは、ホストのダイアン・キチジツが京阪電車を利用して京都に向かいます。最初に伏見稲荷大社を訪れ、数多くの鮮やかな赤い鳥居をくぐった後、宇治市に向かい、最高の日本茶を味わいます。' where id = 'taew5tx0G7QqvX388e12p';
update content_bodies set title = 'Discover Kansai by Train ''Destination UJI, FUSHIMI (KYOTO)''', description = 'This video series highlights essential attractions and experiences in the Kansai region of Japan, emphasizing the convenience of train travel. In this episode, host Diane Kichijitsu travels to Kyoto using the Keihan railway. She begins her journey at Fushimi Inari Shrine, famous for its numerous vibrant red torii gates, before continuing to Uji city, renowned for its exceptional Japanese tea.' where id = '9yxg_nXSvCwndW6QsddSH';
update content_bodies set title = '電車で巡る関西の旅「目的地：高野山」', description = 'この動画シリーズでは、日本の関西地域の必見スポットや体験を、便利な鉄道路線を利用して紹介しています。今回のエピソードでは、ホストのダイアン・キチジツが南海電鉄を利用して和歌山県の高野山に向かいます。彼女はまず、寺院の敷地や神聖な仏教の名所を探索し、美しい秋の紅葉を楽しみます。その後、宿坊で美味しい精進料理を味わいます。旅行を計画している方には、南海全線2日間パスが利用可能です。公式ウェブサイトで最新情報を確認し、関西エリアの旅を楽しんでください！' where id = 'U7Aa0DAiaFsKHfizHm3K9';
update content_bodies set title = 'Discover Kansai by Train ''Destination KOYASAN''', description = 'This video series highlights the must-see spots and experiences in the Kansai region of Japan, utilizing various train lines for convenience. In this episode, host Diane Kichijitsu travels to Koyasan in Wakayama prefecture via the Nankai train line. She explores the temple grounds and sacred Buddhist sites, showcasing the vibrant colors of autumn leaves. Additionally, she enjoys delicious vegetarian Buddhist cuisine at Shukubo. For those interested, the Nankai All Line 2-day Pass is available for travel. Check the official website for more information and enjoy your journey in the Kansai area!' where id = 'YNTN5OUUoNiI37DfXcNet';
update content_bodies set title = '関西を列車で巡る「目的地：広島」', description = 'この動画シリーズでは、日本の関西地域の必見スポットや体験を紹介し、さまざまな鉄道路線の便利さを活用しています。今回のエピソードでは、ホストの福龍勝がJR新幹線で広島に向かい、平和記念公園を観光し、地元の名物であるお好み焼きを作る方法を学びます。' where id = 'tj1EFwOoltbiwfO5FJ9RJ';
update content_bodies set title = 'Discover Kansai by Train "Destination HIROSHIMA"', description = 'This video series highlights the essential attractions and experiences in the Kansai region of Japan, emphasizing the convenience of train travel. In this episode, host Katsura Fukuryu takes the JR bullet train to Hiroshima, explores the Peace Memorial Park, and learns to cook the local specialty, Okonomiyaki.' where id = 'Gv0ENEjkEYWHaI-rTcqrW';
update content_bodies set title = '東京から秩父への日帰り旅行 | 美しい秋の列車の旅 | 日本旅行VLOG', description = 'この旅行VLOGでは、モナが東京から秩父への美しい秋の風景を楽しむ列車の旅を紹介します。ラビュー特急に乗り、色鮮やかな紅葉を堪能しながら、田舎の魅力や地元の美味しい料理を楽しむ様子が描かれています。訪れた場所には、宝登山神社や長瀞駅、長瀞渓谷などが含まれ、月の石もみじ公園や温泉での夕食も楽しむ様子が収められています。視聴者には、チャンネルへのいいねやコメント、登録を促し、チャンネルメンバーシップを通じて詳細な旅行日程をダウンロードできることが案内されています。' where id = 'LOVukgRFfpswyR6Cf3wDy';
update content_bodies set title = 'Day Trip to Chichibu from Tokyo | Beautiful Autumn Train Journey | JAPAN TRAVEL VLOG', description = 'In this travel vlog, Mona takes viewers on a scenic train journey from Tokyo to Chichibu aboard the Laview express train, showcasing the stunning autumn foliage. The trip highlights the beauty of the countryside, with its vibrant autumn leaves and local delicacies. Mona shares her experiences at various locations, including Hodosan Jinja Shrine, Nagatoro Station, and the picturesque Nagatoro Valley. The video also features a visit to Tsukinoishi Momiji Park and concludes with a relaxing dinner at a hot spring. Viewers are encouraged to engage with the channel through likes, comments, and subscriptions, and can access a detailed trip itinerary through channel memberships.' where id = 'PbbPgAdoLVTI8BF7CApJM';
update content_bodies set title = '日本の隠れた山峡への秋の列車冒険 | 黒部 & 金沢 | 日本旅行VLOG', description = 'この旅行VLOGでは、モナが黒部峡トロリー列車に乗って、富山の秋の列車旅を紹介します。黒部の美しい自然と金沢の人気スポットを楽しむ様子が映し出されており、視聴者は宇奈月温泉駅や猫又駅、兼六園などの様々な場所を見ることができます。また、カジカでのランチやもりもり寿司でのディナーなど、地元の料理も紹介され、土産物店や市場の訪問も含まれています。モナは視聴者にチャンネルへのいいね、コメント、登録を促し、チャンネルメンバー向けに詳細な旅行日程を提供しています。' where id = 'YH3D3kgfoTyhcN1hGKu4H';
update content_bodies set title = 'Autumn Train Adventure to Japan’s Hidden Mountain Gorges | Kurobe & Kanazawa | JAPAN TRAVEL VLOG', description = 'In this travel vlog, Mona takes viewers on an autumn train journey through Toyama, specifically on the Kurobe Gorge Trolley Train. The video showcases the stunning natural beauty of Kurobe and highlights popular attractions in Kanazawa. Viewers can expect to see various locations, including Unazuki Onsen Station, Nekomata Station, and the famous Kenrokuen Garden. The vlog also features local cuisine, such as lunch at Kazika and dinner at Morimori Sushi, along with visits to souvenir shops and markets. Mona encourages viewers to engage with her channel by liking, commenting, and subscribing, and offers a detailed trip itinerary for channel members.' where id = 'd2-v3T1SpO7KcLYU_DFPr';
update content_bodies set title = '京都のもう一つの側面 | 大原、宮間、妖怪村の隠れた田舎旅行 | 日本旅行VLOG', description = 'この旅行VLOGでは、モナが京都のあまり知られていない地域を探索します。特に美しい秋の季節に、大原と宮間の静かな田舎町を訪れます。動画では、三千院や妖怪で知られる東映京都スタジオパークを訪れる様子が紹介されており、絵画のような風景や文化体験を楽しむことができます。地元の料理や観光名所も取り上げられています。このチャンネルは、日本でのユニークな旅行体験を提供することを目的としており、視聴者に「いいね」やコメント、チャンネル登録を促しています。詳細な旅行日程はチャンネルメンバー向けに提供されており、モナのインスタグラムでも追加コンテンツが見つかります。' where id = 'vDvgaK26qllP9TNc1iqFL';
update content_bodies set title = 'Another Side of Kyoto | Hidden Countryside Trip to Ohara, Miyama & Yokai Village | JAPAN TRAVEL VLOG', description = 'In this travel vlog, Mona explores the lesser-known areas of Kyoto, focusing on the serene countryside towns of Ohara and Miyama, particularly during the beautiful autumn season. The video features visits to Sanzen-in Temple and TOEI Kyoto Studio Park, known for its association with Yokai, Japanese folk monsters. Viewers can enjoy the picturesque landscapes and cultural experiences, including local cuisine and attractions. The channel aims to provide unique travel experiences in Japan, encouraging viewers to engage through likes, comments, and subscriptions. A detailed trip itinerary is available for channel members, and additional content can be found on Mona''s Instagram.' where id = 'yxnMrQ89JJ4wkZgwTqbg3';
update content_bodies set title = '日本の隠れた北 | 青森の手つかずの美しさへの初秋の旅 | おいらせ | 日本旅行VLOG', description = 'この旅行VLOGでは、モナが青森の初秋の旅に視聴者を案内します。青森県、日本航空、星野リゾートの協賛で、自然の美しさが際立つおいらせ渓谷や、伝統的な祭り、地元のグルメを紹介しています。旅程には、十和田神社や十和田湖、おいらせ渓流ホテルの訪問が含まれ、部屋のツアーや食事体験も楽しめます。モナは、視聴者に「いいね」やコメント、チャンネル登録を促し、日本のユニークな旅行体験をもっと楽しんでもらうよう呼びかけています。' where id = 'Jl0NOfm709Fyv4h6klgsp';
update content_bodies set title = 'Japan’s Hidden North | Early Autumn Trip to Aomori’s Untouched Beauty | Oirase | JAPAN TRAVEL VLOG', description = 'In this travel vlog, Mona takes viewers on an early autumn trip to Aomori, Japan''s hidden northern region. Sponsored by Aomori Prefecture, Japan Airlines, and Hoshino Resorts, the video showcases the stunning natural beauty of Oirase Gorge, along with traditional festivals and local gourmet food. The itinerary includes visits to various attractions such as Towada Shrine, Lake Towada, and the Oirase Keiryu Hotel, where viewers can enjoy a room tour and dining experiences. Mona encourages viewers to like, comment, and subscribe for more unique travel experiences in Japan.' where id = 'B0Za1bYhCAqQfIIhwsXdb';
update content_bodies set title = '日本の田舎での夏 | 地元の電車で長野を探索 | 白馬と安曇野 | 日本旅行VLOG', description = 'この旅行VLOGでは、モナが地元の電車を利用して長野の隠れた魅力を探索します。美しい夏の田園風景を楽しみながら、白馬と安曇野に焦点を当てています。動画では、柳原駅やaoレイクサイドカフェ、白馬岩岳マウンテンリゾート、大王わさび農場などの観光スポットを訪れる様子が紹介されています。また、地元の食事体験や、穂高神社や六山美術館といった文化的な場所も登場します。モナは、視聴者に「いいね」やコメント、チャンネル登録を促しています。' where id = 'ui4lMYqgTYTkFSCn0o81w';
update content_bodies set title = 'Summer in Rural Japan | Exploring Nagano by Local Train | Hakuba & Azumino | JAPAN TRAVEL VLOG', description = 'In this travel vlog, Mona explores the hidden gems of Nagano, Japan, using local trains. The video showcases the beautiful summer countryside, particularly focusing on the areas of Hakuba and Azumino. Viewers can enjoy the scenic journey, including stops at various attractions such as Yanaba Station, ao Lakeside Cafe, Hakuba Iwatake Mountain Resort, and Daio Wasabi Farm. The vlog also features local dining experiences and cultural sites like Hotaka Jinja Shrine and Rokuzan Art Museum. Mona encourages viewers to like, comment, and subscribe for more unique travel experiences in Japan.' where id = '3OiEkSrglzAwZmZLK70kV';
update content_bodies set title = '隠れた水の町、岐阜県郡上八幡へのローカルトレイン旅行 | JAPAN TRAVEL VLOG', description = 'この旅行Vlogでは、モナが岐阜県の郡上八幡へローカルトレインの旅を紹介します。郡上八幡は美しい水の景観と伝統的な雰囲気で知られ、「水の町」や「小京都」とも呼ばれています。1泊2日の旅では、星宮神社や郡上八幡城、飛騨牛や抹茶スイーツなどの地元の美食を楽しむ様子が描かれています。また、吉田川や古い町並みなどの風光明媚なスポットも訪れます。視聴者には、いいねやコメント、チャンネル登録を促し、チャンネルメンバー向けに詳細な旅程も提供しています。モナは自身の体験を共有し、田舎の日本のユニークな魅力を探求するよう視聴者に呼びかけています。' where id = 'QySBUhOIhuaMLi74gLgCJ';
update content_bodies set title = 'Hidden Water Town in Rural Japan | Local Train Trip to Gujo Hachiman, Gifu | JAPAN TRAVEL VLOG', description = 'In this travel vlog, Mona takes viewers on a local train journey to Gujo Hachiman, a charming town in Gifu Prefecture known for its beautiful water features and traditional atmosphere, often referred to as the ''Water Town'' or ''Little Kyoto.'' The trip spans two days and includes visits to various attractions such as Hoshinomiya-jinja Shrine, Gujo Hachiman Castle, and local culinary delights like Hida beef and matcha sweets. Viewers can also enjoy scenic spots like the Yoshida River and the old townscape. The video encourages engagement through likes, comments, and subscriptions, and offers a detailed itinerary for channel members. Mona shares her experiences and invites viewers to explore the unique aspects of rural Japan.' where id = 'Vke80AxNmg7HoYFlAYQSk';
update content_bodies set title = '広島のジブリの町への夏の列車旅行 | 尾道と鞆の浦 | 日本旅行VLOG', description = 'この旅行VLOGでは、モナが広島県の魅力的な港町、尾道と鞆の浦への列車の旅を紹介します。美しい景色や歴史的な町並み、スタジオジブリの映画『崖の上のポニョ』の舞台となった場所などが登場します。モナは視聴者にこの体験を楽しんでもらうよう呼びかけ、チャンネルのいいねやコメント、登録を促しています。また、チャンネルメンバーシップの開始を発表し、メンバーには動画で訪れた場所の詳細なスケジュールやアクセス方法を含む旅行プランをダウンロードできる特典を提供します。モナは視聴者への感謝の気持ちを表現しています。' where id = 'Tvb4DSsXxFgVxVCqAGguP';
update content_bodies set title = 'Summer Train Trip to Ghibli Town in Hiroshima | Onomichi & Tomonoura | JAPAN TRAVEL VLOG', description = 'In this travel vlog, Mona takes viewers on a train journey to the charming port towns of Onomichi and Tomonoura in Hiroshima Prefecture. The video showcases stunning views, historic townscapes, and locations featured in the Studio Ghibli film ''Ponyo on the Cliff by the Sea.'' Mona invites viewers to enjoy the experience and encourages them to like, comment, and subscribe to her channel for more unique travel content. Additionally, she announces the launch of channel memberships, offering members downloadable travel itineraries with detailed schedules and directions for the places visited in the video. Mona expresses her gratitude for the support from her audience.' where id = 'jYRo-YcVv36zHO8m2b6W1';
update content_bodies set title = '初夏の富山への逃避行 | 日本の田舎でのリラックスした海辺の列車旅 | 日本旅行Vlog', description = 'この旅行Vlogでは、モナが初夏の美しい富山の風景を列車で旅する様子を紹介します。富山の豊かな自然と美味しい海鮮を楽しみながら、雨晴海岸や大岩山日石寺、富岩運河環水公園などのスポットを訪れます。リラックスした時間や食事体験、地元の観光名所を強調し、田舎の日本の魅力を伝えています。モナは視聴者に、チャンネルを気に入ったら「いいね」やコメント、登録をするよう促しています。' where id = 'hwb7nFJ1JKtWOr-myN8L4';
update content_bodies set title = 'Early Summer Escape to Toyama | A Relaxing Seaside Train Trip in Rural Japan | Japan Travel Vlog', description = 'In this travel vlog, Mona takes viewers on a scenic train journey through Toyama during the early summer. She highlights the region''s natural beauty and delicious seafood, showcasing various locations such as the Amaharashi Coast, Ooiwasan Nisseki-ji Temple, and the Fugan Canal Kansui Park. The video includes moments of relaxation, dining experiences, and visits to local attractions, emphasizing the charm of rural Japan. Mona encourages viewers to engage with her channel by liking, commenting, and subscribing for more unique travel experiences.' where id = 'mbFj9InfvCAZAVCwdbi7n';
update content_bodies set title = '春の終わりに富士山エリアを巡る美しく儚い旅 | 日本旅行VLOG', description = 'こんにちは、モナです😊今回は春の終わりに富士山エリアを一泊二日で探索する旅をお届けします。西湖いやしの里根場、鳴沢氷穴、富士芝桜まつり、大石公園などを訪れ、日本の春の美しさを存分に楽しみました🌸また、2025年4月にオープンした河口湖近くのホテルにも宿泊しました。このVLOGが皆さんの旅行の参考になれば嬉しいです😉ぜひ楽しんでください！このチャンネルでは日本のユニークな旅行体験をお届けしています⛩️' where id = '3SZJMnhpFFYfmpSPd9pvp';
update content_bodies set title = 'A Beautiful yet Fleeting Journey through the Mt. Fuji Area at the End of Spring | JAPAN TRAVEL VLOG', description = 'In this travel vlog, Mona takes viewers on a one-night, two-day trip to the stunning Mt. Fuji area during the end of spring. The journey includes visits to various attractions such as Saiko Iyashi no Sato Nenba, Narusawa Hyoketsu Ice Cave, the Fuji Shibazakura Festival, and Oishi Park, showcasing the beauty of spring in Japan. Mona also shares her experience staying at a newly opened hotel near Lake Kawaguchi. This vlog serves as a helpful reference for those planning their own travels to this picturesque region. Viewers are encouraged to like, comment, and subscribe for more unique travel experiences in Japan.' where id = 'mUPBCQpyuVvKx1iNKQWrB';
update content_bodies set title = '日本の未開の地域 | 静岡のエメラルドグリーンの湖での列車旅行 | JAPAN TRAVEL VLOG', description = 'この旅行Vlogでは、モナが静岡の美しい新緑の季節に大井川鉄道を通る風光明媚な列車の旅を紹介します。未開の地域駅として知られる奥大井湖上駅や浜松の人気スポットを訪れる様子が描かれています。動画では、アプト式列車の乗車やカフェでの休憩、日本茶ソフトクリームや石松餃子などの地元の美味しい料理を味わうシーンが含まれています。モナは、日本でのユニークな旅行体験をもっと楽しむために、視聴者にチャンネルへの参加を呼びかけています。' where id = '94u2yZDnBJx-TOn4kQEra';
update content_bodies set title = 'Japan’s Unexplored Region | Train Trip on an Emerald Green Lake in Shizuoka | JAPAN TRAVEL VLOG', description = 'In this travel vlog, Mona takes viewers on a scenic train journey through Shizuoka, showcasing the lush greenery of the Oigawa Railway. The adventure includes a visit to the Okuoi Kojo Station, known as the ''unexplored region station,'' and highlights popular attractions in Hamamatsu. The video features various segments, including a ride on an Abt type train, a stop at a café, and tasting local delicacies like Japanese tea soft serve ice cream and Ishimatsu Gyoza. Mona encourages viewers to engage with her channel for more unique travel experiences in Japan.' where id = 'ojl232I40NPbC0uE3FoNl';
update content_bodies set title = '次の駅 - DREAM | 日本の田舎の桜の町への列車旅行 | 日本旅行VLOG', description = 'この旅行VLOGでは、モナが日本の田舎にある桜の町を巡る美しい列車の旅に視聴者を連れて行きます。長野県の高遠と諏訪での春の美しさを楽しみながら、観光客にはあまり知られていないスポットを紹介しています。高遠城址公園や慈雲寺、夕日の見える立石公園などの観光名所が登場します。また、地元の食事を楽しんだり、ガラス工房を訪れたりする様子も収められています。モナは、視聴者にチャンネルを気に入ってもらい、コメントや登録を促しています。' where id = '6xLrpsRbqWY5Yy1XkBG-f';
update content_bodies set title = 'The Next Station - DREAM | Train Trip to a Cherry Blossom Town in Rural Japan | JAPAN TRAVEL VLOG', description = 'In this travel vlog, Mona takes viewers on a scenic train journey through a cherry blossom town in rural Japan, specifically in Nagano Prefecture. The video showcases the beauty of spring in Takato and Suwa, highlighting lesser-known tourist spots. Viewers can expect to see various attractions, including Takato Castle Site Park, Jiunji Temple, and Tateishi Park during sunset. The vlog also features local experiences such as enjoying lunch and visiting a glassware shop. Mona encourages viewers to engage with her channel by liking, commenting, and subscribing for more unique travel experiences in Japan.' where id = '15wqz-vAR7txIXVUo2tK1';
update content_bodies set title = '東京から伊豆への早春の列車旅行 | 河津と伊東 | 日本旅行VLOG', description = 'この旅行VLOGでは、モナが東京から伊豆半島への2日間の列車旅行を紹介します。伊豆は豊かな自然と多様な食文化が魅力です。旅行中には、河津桜の名所や伊東の温泉エリアを訪れました。隠れた桜のカフェや伊東温泉、東海館、伊豆シャボテン動物園など、さまざまな観光スポットが紹介され、食事や宿泊の様子も楽しめます。モナは日本のユニークな旅行体験を楽しんでもらうよう呼びかけ、チャンネルの「いいね」やコメント、登録を促しています。' where id = 'c_WyZl5QNxV-elklqYj1I';
update content_bodies set title = 'Early Spring Train Trip to Izu from Tokyo | Kawazu & Ito | JAPAN TRAVEL VLOG', description = 'In this travel vlog, Mona takes viewers on a two-day train journey from Tokyo to the Izu Peninsula, known for its beautiful nature and delicious food. The trip includes visits to popular spots for viewing Kawazu Cherry Blossoms and the hot spring area in Ito. The video showcases various attractions, including a hidden cherry blossom viewing café, Ito Onsen, Tokaikan, and Izu Shaboten Zoo, along with delicious meals and accommodations. Mona invites viewers to enjoy the unique travel experiences in Japan and encourages them to like, comment, and subscribe to her channel.' where id = 'fBFbJn_YX8OWiZs8wtUvm';
update content_bodies set title = '種子島でのワーケーション♪', description = 'これは、種子島でのワーケーションをPRする動画です。ゆったりとした島の時間を感じながら、気ままに過ごすことができます。' where id = 'WSCbvbSk79uisZdvToqhD';
update content_bodies set title = 'Workation in Tanegashima♪', description = 'This is a promotional video for workation in Tanegashima! Experience a relaxed island time and enjoy a carefree stay.' where id = 'INT1aqZV8ItVt838mIAHF';
update content_bodies set title = 'アニメのような青春にぴったりの島 | 東京近郊の江ノ島日帰り旅行 | 日本旅行VLOG', description = 'この旅行VLOGでは、モナが東京近郊の湘南海岸にある美しい江ノ島への日帰り旅行を紹介します。湘南モノレールで江ノ島に向かい、島の美しい景色や美味しい食べ物を楽しむ様子を映しています。江ノ島に到着後の朝食、島内の散策、江ノ島神社の訪問、展望灯台の登頂など、様々なセグメントが含まれています。また、夕景の名所や海の洞窟も紹介し、夕日を見ながらのディナーで一日を締めくくります。このチャンネルは、日本でのユニークな旅行体験を提供することを目的としており、視聴者に「いいね」やコメント、チャンネル登録を促しています。' where id = 'hqsBIk5piFwCSgKfVVNmV';
update content_bodies set title = 'An Island That Suits Anime-Like Youth | Enoshima Island One Day Trip near Tokyo | JAPAN TRAVEL VLOG', description = 'In this travel vlog, Mona takes viewers on a day trip to Enoshima, a picturesque island on the Shonan coast near Tokyo. She travels via the Shonan Monorail, showcasing the stunning scenery and delicious food available on the island. The video includes various segments such as her arrival at Enoshima, enjoying breakfast, exploring the island, visiting Enoshima Shrine, and climbing the observation lighthouse for breathtaking views. Mona also highlights a famous spot for evening views and a sea cave, concluding her day with dinner while watching the sunset. The channel aims to provide unique travel experiences in Japan, encouraging viewers to like, comment, and subscribe.' where id = '0yZ70gtF9c7Mq3Y9s5R7O';
update content_bodies set title = '東京からの富士山エリア日帰り旅行 | 冬の電車旅行 | 日本旅行VLOG', description = 'こんにちは、モナです😊今回は東京からの冬の日帰り旅行で、美しい富士山のスポットを訪れます。富士山と自然から力をもらい、リラックスした時間を過ごしました🗻動画では、忍野八海や山中湖、北口本宮富士浅間神社など、富士山周辺の美しい場所を紹介しています。このチャンネルでは、日本のユニークな旅行体験をお届けしていますので、気に入ったらいいねやコメント、チャンネル登録をお願いします！' where id = 'PtKJsSdPFGCBDseDdGIZ8';
update content_bodies set title = 'Day Trip to Mt. Fuji Area from Tokyo | Winter Train Trip | JAPAN TRAVEL VLOG', description = 'In this travel vlog, Mona takes viewers on a winter day trip from Tokyo to the stunning Mt. Fuji area. The journey includes visits to picturesque spots around Mt. Fuji, where she finds relaxation and rejuvenation in nature. The video features various locations such as Oshino Hakkai, Lake Yamanaka, and the Kitaguchi Hongu Fuji Sengen Jinja Shrine, showcasing the beauty of the region. Mona encourages viewers to engage with her channel by liking, commenting, and subscribing for more unique travel experiences in Japan.' where id = 'oIqmjJqNENliW6cXubP3L';
update content_bodies set title = '東京のレトロな街並みを探る | 浅草かっぱ橋と根津 | 日本旅行VLOG', description = 'この旅行VLOGでは、モナが東京の懐かしいレトロな街並みを巡ります。特に、浅草かっぱ橋と根津を訪れ、かっぱ橋道具街や老舗のレストラン、根津神社、東京大学、隠れたレトロな美術館、レトロカフェなどの魅力を紹介します。モナは視聴者に楽しんでもらうよう呼びかけ、チャンネルのいいねやコメント、登録を促しています。日本でのユニークな旅行体験を提供するこのチャンネルをぜひご覧ください。' where id = 'Es7VqDwFFg95phzCNs0Cu';
update content_bodies set title = 'Exploring Tokyo’s Retro Neighborhoods | Asakusa Kappabashi & Nezu | JAPAN TRAVEL VLOG', description = 'In this travel vlog, Mona takes viewers on a journey through some of Tokyo''s nostalgic retro neighborhoods, specifically Asakusa Kappabashi and Nezu. The video showcases various attractions, including Kappabashi Kitchenware Town, long-established restaurants, Nezu Shrine, the University of Tokyo, hidden retro art museums, and a retro cafe. Mona invites viewers to enjoy the experience and encourages them to like, comment, and subscribe to her channel for more unique travel experiences in Japan.' where id = 'NYzhqHKbHyZZaGMT-xF1L';
update content_bodies set title = '千と千尋の神隠しの温泉町への雪の冬の旅 | 信夫温泉、雪猿公園 | 長野県、日本', description = 'この動画では、モナが長野県の信夫温泉、湯田中温泉、雪猿公園への2日間の旅を紹介しています。彼女は「千と千尋の神隠し」を思わせる雪に覆われた温泉町で日常の疲れを癒した体験を語ります。動画には、長野電鉄、温泉、宿泊した旅館、信夫温泉の夜の様子、居酒屋KIRAKUやENZA CAFEなどの地元の店の訪問、そして有名な雪猿を見ることができる雪猿公園のハイライトが含まれています。モナは視聴者に、彼女のチャンネルを気に入ったら、いいねやコメント、登録をするように促しています。' where id = 'M5kVBHD4X68qPuixNLaDQ';
update content_bodies set title = 'Snowy Winter Trip to Spirited Away Hot Spring Town | Shibu Onsen, Snow Monkey Park | Nagano, JAPAN', description = 'In this video, Mona shares her two-day trip to Shibu Onsen, Yudanaka Onsen, and the Snow Monkey Park in Nagano Prefecture. She describes her experience of relaxing in the snowy hot spring town reminiscent of ''Spirited Away.'' The video includes various segments showcasing the Nagano Electric Railway, the hot springs, the ryokan where she stayed, the nightlife in Shibu Onsen, and visits to local establishments like KIRAKU and ENZA CAFE. Additionally, she highlights the Snow Monkey Park, where visitors can see the famous snow monkeys. Mona encourages viewers to like, comment, and subscribe to her channel for more unique travel experiences in Japan.' where id = '5cXKqIfVQH4xPMXyLxQGH';
update content_bodies set title = '東京の「小京都」未体験のスポット | 新宿、六義園、神楽坂 | JAPAN TRAVEL VLOG', description = 'この旅行Vlogでは、モナが東京の「小京都」を探索し、日本文化を感じられるさまざまな場所を紹介します。彼女は、東京にいるとは思えないほどリラックスした休日を過ごしたことを語り、街の美しさや文化的なスポットを強調しています。動画では、新宿の風景、鶏すき焼きを楽しむための大和楽、静かな六義園、そして魅力的な神楽坂エリアを訪れ、神楽坂茶寮での抹茶モンブランも紹介されています。モナは視聴者に日本でのユニークな旅行体験を楽しんでもらい、チャンネルのいいね、コメント、登録を促しています。' where id = 'KWhPm89gmptIhNEHz3ef-';
update content_bodies set title = 'Little Kyoto in Tokyo You’ve Never Seen Before | Shinjuku, Rikugien, Kagurazaka | JAPAN TRAVEL VLOG', description = 'In this travel vlog, Mona explores ''Little Kyoto'' in Tokyo, showcasing various locations that embody Japanese culture. She shares her relaxing holiday experience, highlighting the beauty of the city and its cultural spots. The video features scenic streets in Shinjuku, a visit to Yamato Raku for chicken sukiyaki, the serene Rikugien Gardens, and the charming Kagurazaka area, including a delightful matcha Mont Blanc at Kagurazaka Saryo. Mona invites viewers to enjoy her unique travel experiences in Japan and encourages them to like, comment, and subscribe to her channel for more content.' where id = 'ohdyWW_lMqjwax-2NyeXI';
update content_bodies set title = 'ジブリのような海辺の町 | 東京近郊の鎌倉日帰り電車旅行 | 日本旅行VLOG', description = 'こんにちは、モナです😊今回は新宿からわずか1時間の場所にある、ユニークな海辺の町・鎌倉を訪れました。江ノ電を利用して、鎌倉の素晴らしいスポットを巡ります🚃。シチリガハマのビーチや海辺のカフェ、長谷寺、鎌倉大仏、そして小町通りを歩きながら食べ歩きする様子をお楽しみください。このチャンネルでは、日本のユニークな旅行体験をお届けしています⛩️。気に入ったら、ぜひチャンネル登録といいねをお願いします！動画では美しい風景と鎌倉の文化的な魅力が紹介されています。' where id = 'SVCaySF7WDWqxH243un_B';
update content_bodies set title = 'Ghibli-Like Seaside Town | Kamakura One Day Train Trip near Tokyo | JAPAN TRAVEL VLOG', description = 'In this travel vlog, Mona takes viewers on a journey to Kamakura, a charming seaside town located just an hour from Shinjuku, Tokyo. The video showcases various attractions accessible via the Enoden train, including Shichirigahama beach, a seaside café, Hasedera Temple, the Great Buddha of Kamakura at Kotoku-in, and the vibrant Komachi-dori Street. Mona invites viewers to enjoy the unique travel experiences in Japan and encourages them to like and subscribe to her channel for more content. The video features beautiful scenery and highlights the cultural richness of Kamakura.' where id = '7u7YocK1TMhdTTbkToXhW';
update content_bodies set title = '新宿から90分、東京で唯一の村に滞在 | 日野原村 | 日本旅行VLOG', description = 'この旅行VLOGでは、モナが東京で唯一の村、日野原村を訪れます。新宿から90分の距離にあり、400年以上の歴史を持つ宿「古民家の宿 山城」に滞在し、リラックスした時間を過ごします。動画では、ホッサワの滝や地元の豆腐店、村で唯一のスーパーなどの観光スポットが紹介されます。また、宿泊施設の部屋や浴室、夕食や朝食の様子もツアー形式でお届けします。このチャンネルは、日本のユニークな旅行体験を共有することを目的としており、視聴者に「いいね」とチャンネル登録を促しています。' where id = '0AizdXThC0n-tuunFuC-A';
update content_bodies set title = 'Staying The Only Village in Tokyo, 90 Minutes from Shinjuku | Hinohara Village | JAPAN TRAVEL VLOG', description = 'In this travel vlog, Mona explores Hinohara Village, the only village in Tokyo, located just 90 minutes from Shinjuku. She stays at ''Kominka no Yado Yamashiro'', a historic inn that is over 400 years old, where she enjoys a relaxing experience. The video features various attractions, including Hossawa Falls, a local tofu shop, and the village''s only supermarket. Mona also provides a tour of her accommodation, showcasing the room, bath, and meals, including dinner and breakfast. The channel aims to share unique travel experiences in Japan, encouraging viewers to like and subscribe.' where id = 'wlPyWHqZvNCqHMdSkEmEH';
update content_bodies set title = '東京近郊の自然の逃避行 | 秋のニッコー日帰り旅行 | 日本旅行VLOG', description = 'こんにちは、モナです😊今回は東京近郊にある栃木県のニッコー市を訪れました。ニッコーは美しい紅葉で有名なスポットです。隠れた名所である湯西川温泉を訪れ、日本の秋を楽しみました🍁このVLOGでは、湯西川の道の駅や、昼食を取った山賀、たかふさ神社、武家屋敷の平家の里、カフェ東など、さまざまな場所を紹介しています。このチャンネルでは、日本のユニークな旅行体験をお届けしていますので、ぜひチャンネル登録といいねをお願いします！' where id = 'FWVSCJ6yIXrw3irtxTpGv';
update content_bodies set title = 'Nature Escape near Tokyo | Day Trip to Nikko in Autumn | JAPAN TRAVEL VLOG', description = 'In this travel vlog, Mona takes viewers on a day trip to Nikko City in Tochigi Prefecture, Japan, renowned for its stunning autumn foliage. The video showcases the hidden gem of Yunishigawa Onsen, where Mona enjoys the beauty of autumn. The vlog includes various locations such as the Roadside Station Yunishigawa, Takafusa Shrine, and Heike no Sato, a samurai village. Viewers can also see her dining experience at Yamaga and a visit to Cafe Higashi. The channel aims to provide unique travel experiences in Japan, encouraging viewers to like and subscribe for more content.' where id = 'FxsnC-e8vLTbirt1vRgKG';
update content_bodies set title = '東京の古い町への日帰り旅行 | 谷中銀座と上野公園 | 日本旅行VLOG', description = 'こんにちは、モナです😊今回は東京の代表的な散策スポットである谷中銀座と上野公園を訪れました。レトロな町を散策しながら、歴史やアート、自然を体験し、リラックスした休日を過ごしました🧡この動画では、ランチに訪れたカヤバコーヒーや最後の将軍の墓、東京藝術大学のアートプラザ、上野公園、上野東照宮の訪問など、さまざまなハイライトが紹介されています。日本でのユニークな旅行体験を楽しんでいただければ幸いです。チャンネル登録といいねをよろしくお願いします！' where id = 'nt9I-oUBy70FJHbLdyXmA';
update content_bodies set title = 'Day Trip to Old Town of Tokyo | Yanaka Ginza & Ueno Park | JAPAN TRAVEL VLOG', description = 'In this travel vlog, Mona explores Yanaka Ginza and Ueno Park, two of Tokyo''s most iconic walking destinations. She enjoys a leisurely holiday, immersing herself in the historical and artistic atmosphere of the retro town while also appreciating nature. The video showcases various highlights, including a visit to Kayaba Coffee for lunch, the grave of the last Shogun, the Art Plaza of Tokyo University of the Arts, and Ueno Toshogu Shrine. Mona invites viewers to enjoy her unique travel experiences in Japan and encourages them to like and subscribe to her channel.' where id = 'bNmwtb_0odOk1rYtHpbsQ';
update content_bodies set title = '新宿から1時間の東京の田舎 | ジブリのような夏 | あきる野と所沢 | 日本旅行VLOG', description = 'この旅行VLOGでは、新宿からわずか1時間の美しい東京の田舎、あきる野を訪れます。また、アニメ映画『となりのトトロ』の生まれ故郷である所沢にも立ち寄り、ジブリのような雰囲気の中で夏の終わりを過ごします。伝統的な日本家屋のレストラン、温泉施設、日本庭園のカフェ、トトロの森などが紹介されており、日本のユニークな旅行体験を提供することを目的としています。チャンネルを気に入ったら、ぜひいいねと登録をお願いします。' where id = 'zJx7vTk4k3ZbeqYKPsn3c';
update content_bodies set title = 'Rural Tokyo, 1 Hour from Shinjuku | Ghibli-Like Summer | Akiruno & Tokorozawa | JAPAN TRAVEL VLOG', description = 'In this travel vlog, the creator explores Akiruno, a picturesque countryside area in Tokyo, just an hour away from Shinjuku. The journey also includes a visit to Tokorozawa, known as the birthplace of the beloved animated film ''My Neighbor Totoro.'' The video captures the essence of summer in a Ghibli-like atmosphere, showcasing traditional Japanese house restaurants, a hot spring facility, a Japanese garden cafe, and Totoro’s Forest. The channel aims to provide unique travel experiences in Japan, encouraging viewers to like and subscribe for more content.' where id = 'UVhGn1Oas26rY6LfkqMcf';
update content_bodies set title = '隠れた東京へようこそ、浅草から電車で5分 | 日本旅行VLOG | 北千住', description = 'この旅行VLOGでは、浅草から電車でわずか5分の場所にある東京の隠れた名所、北千住を訪れます。北千住は、居酒屋や銭湯が多く、伝統的な雰囲気が魅力の町です。動画では、すき焼きを楽しんだり、MUJIで買い物をしたり、裏路地のカフェを訪れたり、地元の寺社を散策したりする様子が紹介されています。このチャンネルは、日本でのユニークな旅行体験を提供することを目的としており、視聴者に「いいね」とチャンネル登録を促しています。' where id = 'l1vv4pvjNlz6FnfIfbX2m';
update content_bodies set title = 'Welcome to Hidden Tokyo, 5 Minutes from Asakusa by Train | JAPAN TRAVEL VLOG | Kitasenju', description = 'In this travel vlog, the host explores Kitasenju, a lesser-known area of Tokyo located just a five-minute train ride from Asakusa. Kitasenju is celebrated for its traditional atmosphere, featuring numerous izakayas (Japanese pubs) and public bathhouses. The video showcases various experiences, including enjoying sukiyaki, shopping at MUJI, visiting a back alley café, and strolling around local temples and shrines. The channel aims to provide unique travel experiences in Japan, encouraging viewers to like and subscribe for more content.' where id = 'WMV20LFn71FmiqWYNcL7y';
update content_bodies set title = '新宿から40分の東京の田舎への日帰り旅行 | 調布と八王子 | 日本旅行VLOG', description = 'この旅行VLOGでは、クリエイターが新宿からわずか40分の東京の田舎、調布と八王子を探索します。動画は、都市の喧騒から離れ、日常の疲れを癒すリフレッシュした体験を提供します。視聴者は、神代寺を訪れたり、昼食に神代蕎麦、夕食に日向山を楽しむ様子を通じて旅を楽しむよう招待されています。このチャンネルは、日本のユニークな旅行体験に焦点を当てており、視聴者に「いいね」とチャンネル登録を促しています。' where id = 'mfhaxTdNx9Rqo9ky-Tgz1';
update content_bodies set title = 'Day Trip to Rural Tokyo, 40 Minutes from Shinjuku | Chofu & Hachioji | JAPAN TRAVEL VLOG', description = 'In this travel vlog, the creator explores Chofu and Hachioji, rural areas of Tokyo that are just 40 minutes away from Shinjuku. The video captures the essence of escaping the city''s hustle and bustle, providing a refreshing experience to relieve daily fatigue. Viewers are invited to enjoy the journey, which includes visits to Jindaiji Temple and local dining experiences such as Jindaiji Soba for lunch and Hinatoriyama for dinner. The channel focuses on unique travel experiences in Japan, encouraging viewers to like and subscribe for more content.' where id = 'XKGMfbuJFlSPJ9x7tS1oo';
update content_bodies set title = '東京・浅草で試すべき10の日本食 | 日本旅行ガイド2024', description = 'この動画では、東京・浅草で試すべき10の食べ物とスイーツのお店を紹介しています。日本人に人気のあるお店や、SNSで話題のトレンドを取り上げており、浅草の美味しい料理を探求する旅行者にとっての参考になります。このチャンネルは、日本でのユニークな旅行体験を提供することを目的としており、視聴者に「いいね」とチャンネル登録を促しています。関連動画には、浅草を楽しむためのおすすめや、無料サービスが豊富な温泉ホテルの紹介があります。動画では、世界一強い抹茶ジェラートやウナギの握り、ジャンボメロンパンなど、さまざまな料理が紹介されています。' where id = '069_920gZcAbVvBZIYCKz';
update content_bodies set title = '10 Must-Try Japanese Food in Asakusa, Tokyo | Japan Travel Guide 2024', description = 'This video presents 10 must-try food and sweets shops in Asakusa, Tokyo, highlighting popular choices among locals and trending items on social media. It serves as a travel guide for those looking to explore the culinary delights of Asakusa. The channel aims to provide unique travel experiences in Japan, encouraging viewers to like and subscribe for more content. Related videos include recommendations for enjoying Asakusa and a hot spring hotel with numerous free offers. The video features various dishes, including the strongest matcha gelato, eel rice balls, and jumbo melon bread, among others.' where id = 'FtY7DC6lrGjb3NOsGPb2n';
update content_bodies set title = '東京の神秘的な火山島を訪れる | 伊豆大島 | 日本旅行', description = '今回は、東京の海に浮かぶ神秘的な火山島、伊豆大島での2日間1泊の旅行を紹介します。この旅では、東京では味わえない素晴らしい自然環境や食、歴史、文化を体験しました。大人になっても冒険を楽しむことの大切さを感じました。動画では、高速ジェットボートでの移動や、黒砂のビーチ、歴史的な名所の探索、地元の料理を楽しむ様子が収められています。視聴者には、ユニークな日本の旅行体験を楽しんでもらうためにチャンネル登録を促しています。' where id = 'hpS_04auQmAA-CzLjBZqF';
update content_bodies set title = 'Visiting Tokyo''s Mysterious Volcanic Island | Izu Oshima | Japan Travel', description = 'In this travel vlog, the creator shares their two-day, one-night adventure on Izu Oshima, a volcanic island near Tokyo. The trip highlights the island''s unique natural environment, delicious food, rich history, and vibrant culture, all of which offer a surprising contrast to the bustling city life of Tokyo. The video includes various activities such as taking a high-speed jet boat, exploring local attractions like the black sand beach and historical sites, and enjoying local cuisine. The creator encourages viewers to embrace adult adventures and invites them to subscribe for more unique travel experiences in Japan.' where id = 'gYVxuXNF9q3kmMRVDvMvV';
update content_bodies set title = '京都の小さな海町、伊根の夏を訪れて | 田舎の日本 | 天橋立', description = 'この動画では、京都の美しい海町「伊根」を訪れ、その魅力を紹介します。また、日本三景の一つである天橋立にも立ち寄ります。日本の夏の懐かしさを感じさせる内容で、ユニークな旅行体験を提供しています。視聴者にはチャンネルの「いいね」と「登録」を促しています。撮影日は2023年9月です。' where id = '1wcotDtmEZSVQ0NMn93dX';
update content_bodies set title = 'Visiting the Summer of Ine, the Little Sea Town in Kyoto | Rural Japan | Amanohashidate', description = 'In this video, the traveler explores ''Ine,'' a charming seaside town in Kyoto, known for its picturesque views. The journey also includes a visit to Amanohashidate, recognized as one of Japan''s three most beautiful landscapes. The content aims to evoke nostalgia for summer in Japan and offers unique travel experiences. Viewers are encouraged to like and subscribe to the channel for more travel insights. The video was filmed in September 2023.' where id = 'beFewdcfu1MBY3BSZXl9q';
update content_bodies set title = '東京スカイツリー展望台とソラマチ🌸 | ユニークな日本文化 | ジブリ、ポケモン、アニメ', description = 'この動画では、世界一高い塔である東京スカイツリーを訪れます。300以上のユニークな店舗が揃う東京ソラマチで、さまざまな食べ物やスイーツ、日本のアニメ文化を楽しみます。展望台の様子や、ランチに海鮮丼を食べるシーン、アニメショップのツアー、抹茶スイーツの紹介などが含まれています。このチャンネルは、日本でのユニークな旅行体験を提供することを目的としており、視聴者にいいねやチャンネル登録を促しています。' where id = 'n88UQOl912XjZpZR01JP7';
update content_bodies set title = 'Tokyo Skytree Observation Deck and Solamachi🌸 | Unique Japan Culture | Ghibli, Pokemon, and Anime', description = 'In this video, the traveler visits the Tokyo Skytree, the tallest tower in the world. They explore Tokyo Solamachi, which features over 300 unique stores, enjoying various foods, sweets, and aspects of Japanese anime culture. The video includes highlights such as the observation deck, a seafood bowl for lunch, a tour of an anime shop, and matcha sweets. The channel aims to provide unique travel experiences in Japan, encouraging viewers to like and subscribe for more content.' where id = '_PbKBn1Gvgtd53z8KeZiC';
update content_bodies set title = '2024年に浅草を楽しむためのベストな方法 | 日本旅行', description = 'この動画では、東京の人気観光地である浅草を紹介しています。制作者は、著名な浅草寺を訪れる体験や、あまり知られていない観光スポット、地元の美味しい食べ物をシェアしています。特に、世界一強い抹茶ジェラート、もんじゃ焼き、うなぎの握り、ジャンボメロンパンなどが紹介されています。また、無料の展望テラスも登場します。視聴者には、日本でのユニークな旅行体験をもっと知りたい方は、いいねやチャンネル登録を促しています。' where id = 'Lg3Jdz5LJO1Y949uu2rE0';
update content_bodies set title = 'Best Way to Enjoy Asakusa in 2024 | Japan Travel', description = 'This video showcases Asakusa, a popular tourist destination in Tokyo. The creator shares their experiences visiting iconic sites like Senso-ji Temple, as well as lesser-known attractions and local delicacies. Highlights include the strongest matcha gelato, monjayaki, eel rice balls, and jumbo melon bread. The video also features a free viewing terrace. Viewers are encouraged to like and subscribe for more unique travel experiences in Japan.' where id = '7DIbA7g42R4IHDM6lYhBO';
update content_bodies set title = '最新の東京旅行スポット | 築地市場よりも良い？ | 豊洲千客万来', description = '2024年2月に東京に新たにオープンした「豊洲千客万来」は、築地市場の発展を目指す新しい施設です。この場所は新たな観光名所になると期待されています。新鮮な海鮮やラーメン、日本のスイーツを楽しむことができ、旅行者にとって魅力的なスポットです。このチャンネルでは日本のユニークな旅行体験を紹介しており、視聴者にチャンネル登録を促しています。新しいスポットに対する興奮を表現し、豊洲千客万来の魅力を楽しむよう呼びかけています。' where id = 'b1nciykvRnmzanh4iKZ9y';
update content_bodies set title = 'Latest Travel Spot in Tokyo | Better Than Tsukiji Fish Market? | Toyosu Senkyaku Banrai', description = 'In February 2024, a new travel destination called ''Toyosu Senkyaku Banrai'' opened in Tokyo, aiming to enhance the legacy of the Tsukiji Fish Market. This facility is expected to attract tourists with its fresh seafood, ramen, and traditional Japanese sweets. The channel showcases unique travel experiences in Japan, encouraging viewers to like and subscribe for more content. The creator expresses excitement about this new spot and invites everyone to enjoy the offerings at Toyosu Senkyaku Banrai.' where id = 'n_tFBs4se8frrNdZvkpAx';
update content_bodies set title = '2024年の白川郷を楽しむ方法、2日1泊 | 日本旅行', description = 'この旅行ガイドでは、冬の白川郷への旅を紹介しています。白川郷は、伝統的な合掌造りの建物と美しい自然景観で知られる日本の風光明媚な村です。2日1泊の滞在を通じて、雪に覆われた村を散策したり、そばや飛騨牛ステーキなどの地元料理を楽しんだり、展望台からの景色を堪能する様子が描かれています。この動画は、白川郷の独特の魅力を体験することを視聴者に促し、さらなる旅行コンテンツの購読を呼びかけています。' where id = 'rXekt7ZyhwtLvEEwHE_kr';
update content_bodies set title = 'How to Enjoy Shirakawa-go in 2024, 2 days and 1 night | Japan Travel', description = 'This travel guide details a winter trip to Shirakawa-go, a picturesque village in Japan known for its traditional Gassho-zukuri architecture and stunning natural scenery. The itinerary covers a 2-day, 1-night stay, highlighting activities such as a morning walk through the snow-covered village, enjoying local cuisine including soba noodles and Hida beef steak, and exploring the area from an observation deck. The video encourages viewers to experience the unique charm of Shirakawa-go and invites them to subscribe for more travel content.' where id = 'QzSsAvUA3AKIy2CQ_Ob-Z';
update content_bodies set title = 'とおかまちプロモーションムービー（フルバージョン）', description = 'このプロモーションムービーは、十日町市の魅力と美しさを余すところなく表現しています。市制施行10周年を記念して制作され、完成版は平成28年3月に公開予定です。' where id = '9bQUWHsKc9VzUm6-LqnQe';
