update content_bodies set title = 'Tsukiji Fish Market🍣 | Everything I Ate at Japanese Street Food | Japan Travel | ASMR', description = 'In this video, the creator explores Tsukiji Fish Market, one of Japan''s most vibrant markets. They sample a variety of popular foods available at the market from the morning onwards. The channel aims to provide unique travel experiences in Japan, encouraging viewers to like and subscribe for more content. The creator also shares their Instagram for further engagement and expresses gratitude to viewers for watching.' where id = 'p1DNbByGVpTmPC0RcXAl2';
update content_bodies set title = 'KYOTO VLOG | 嵐山日帰り旅行 | 人気観光スポット | 日本旅行 | ASMR', description = 'このVLOGでは、京都を代表する観光地である嵐山を訪れます。美しい自然と美味しい食べ物に癒される様子が紹介されており、視聴者は京都らしい優雅な風景を楽しむことができます。このチャンネルは、日本でのユニークな旅行体験を提供することを目的としており、視聴者に「いいね」とチャンネル登録を促しています。動画では、阪急電車の乗車、嵐山到着、嵐山駅、着物の森、日本のカフェ（抹茶）、竹林の小道、嵯峨野トロッコ列車、嵐山のホットフード、天龍寺の訪問、着物の森のイルミネーションなどが紹介されています。' where id = '1ZlB-UFGa04TNgOzyQOfN';
update content_bodies set title = 'KYOTO VLOG | Arashiyama One Day Trip | Most Popular Tourist Spot | Japan Travel | ASMR', description = 'In this vlog, the traveler explores Arashiyama, a renowned tourist destination in Kyoto. The video showcases the stunning natural beauty and delicious cuisine of the area. Viewers are invited to enjoy the elegant scenery typical of Kyoto. The channel aims to provide unique travel experiences in Japan, encouraging likes and subscriptions. The video includes various segments such as the Hankyu train ride, arrival at Arashiyama, visits to Randen Arashiyama Station, Kimono Forest, a Japanese cafe serving matcha, the Bamboo Forest Path, a ride on the Sagano Romantic Train, and a visit to Tenryu-ji Temple, concluding with the illumination of the Kimono Forest.' where id = 'VNokqvX3TQvr9uAHIYXhV';
update content_bodies set title = 'KYOTO VLOG | 観光名所と人気の食べ物 | 祇園と清水寺を探索 | 日本旅行 | ASMR', description = 'このVLOGでは、日本の古都・京都を訪れ、必見の観光名所や人気のグルメを紹介しています。清水寺や歴史的な祇園地区を訪れ、八坂神社や八坂の塔、伝統的な抹茶デザートなどの様々な景色を楽しんでいます。また、日本風のスターバックスや先斗町などのユニークな場所での体験や、ステーキ丼やウナギなどの美味しい食べ物も紹介されています。このチャンネルは、日本でのユニークな旅行体験を提供することを目的としており、視聴者に「いいね」とチャンネル登録を促しています。次回の目的地は嵐山です。' where id = 'Fs8gG60yLXrJphgNjtj7i';
update content_bodies set title = 'KYOTO VLOG | sights and popular foods | Exploring Gion, Kiyomizu-dera Temple | Japan Travel | ASMR', description = 'In this vlog, the creator explores Kyoto, Japan''s ancient capital, highlighting must-see tourist attractions and popular local foods. The video features visits to Kiyomizu-dera Temple and the historic district of Gion, showcasing various sights such as Yasaka Shrine, Yasaka Pagoda, and traditional matcha desserts. The creator also shares experiences at unique locations like a Japanese-style Starbucks and Ponto-cho, along with delicious food options like steak bowls and eel. The channel aims to provide unique travel experiences in Japan, encouraging viewers to like and subscribe for more content. The next destination will be Arashiyama.' where id = '88uLtWlW1ZLFF814uMwHN';
update content_bodies set title = '無料サービスが豊富な浅草温泉ホテル | 日本旅行 | ASMR', description = 'この動画では、浅草の温泉ホテルでの体験が紹介されています。特に朝食の海鮮丼ビュッフェや多くの無料サービスが素晴らしいと強調されています。ホテルは浅草駅から徒歩約4分の便利な場所にあり、観光の拠点として最適です。動画には、ホテル到着時の様子や部屋のツアー、温泉施設の紹介などが含まれています。視聴者には、ユニークな旅行体験を楽しんでもらい、チャンネルの「いいね」と「登録」を促しています。' where id = '2Sp4vBB_qypKlm5ny6r_7';
update content_bodies set title = 'Asakusa Hot Spring Hotel with Too Many Free Offers | Japan Travel | ASMR', description = 'In this video, the host shares their experience at a hot spring hotel in Asakusa, highlighting the impressive seafood bowl buffet for breakfast and numerous complimentary services. The hotel is conveniently located just a four-minute walk from Asakusa Station, making it an ideal base for exploring the area. The video includes various segments such as the arrival at the hotel, a room tour, and an introduction to the hot spring facilities. Viewers are encouraged to enjoy the unique travel experiences presented and to like and subscribe to the channel for more content.' where id = '2_TU7VQndRQJB26wccxC1';
update content_bodies set title = '京都市観光PR映像_ショート動画⑦「とっておきの京都とその周辺地域」', description = 'この動画では、「とっておきの京都とその周辺地域」について紹介しています。京都の魅力や周辺の観光スポットを取り上げ、訪れる人々にその美しさや文化を伝える内容となっています。' where id = 'w4vTf0KOVrp2h_dGks_Fn';
update content_bodies set title = 'Kyoto City Tourism PR Video - Short Video ⑦ ''Special Kyoto and Its Surrounding Areas''', description = 'This video introduces ''Special Kyoto and Its Surrounding Areas''.' where id = 'rcucO7j-G7sFGNRO6uCTh';
update content_bodies set title = '浅草への旅 | 浅草寺を訪れ、周辺の食事を楽しむ | 日本旅行 | ASMR', description = 'この動画では、東京の人気観光地である浅草を訪れます。日本人に人気のある食べ物やスイーツを味わいながら、浅草を散策します。また、東京で最も古い寺院である浅草寺も訪れます。このチャンネルは、日本のユニークな旅行先を紹介することを目的としており、視聴者に「いいね」とチャンネル登録を促しています。動画には、浅草への旅、寺院訪問、抹茶モンブランやもんじゃ焼きなどの人気料理が含まれています。視聴者への感謝の気持ちを表し、次回の目的地である東京スカイツリーについても触れています。' where id = 'lj8sSO65wbLrFdtdCwqzl';
update content_bodies set title = 'Trip to Asakusa | Visiting Senso-ji Temple and eating around | Japan Travel | ASMR', description = 'In this video, the creator explores Asakusa, a popular tourist destination in Tokyo. The journey includes tasting various local foods and sweets that are currently favored by the Japanese. A visit to Senso-ji, Tokyo''s oldest temple, is also featured. The channel aims to showcase unique travel spots in Japan, encouraging viewers to like and subscribe for more content. The video includes segments on the trip to Asakusa, the temple visit, and popular local dishes, such as Matcha Mont Blanc and Monjayaki. The creator expresses gratitude for the viewers'' support and hints at the next destination, Tokyo Skytree.' where id = 'RcXjlmsWAzLBLy5gevvJe';
update content_bodies set title = '東京近郊の鎌倉・江ノ島日帰り旅行', description = 'この動画では、制作者が江ノ電を利用して鎌倉と江ノ島を訪れた体験を共有しています。東京からのアクセスが良く、独特の地元の雰囲気を楽しめる場所として、これらの場所への愛情を表現しています。動画では、アニメ「SLAM DUNK」との関係で知られる鎌倉高校前駅や、江ノ島周辺の散策が紹介されています。このチャンネルは、日本のユニークな旅行先を紹介することを目的としており、視聴者に「いいね」とチャンネル登録を促しています。また、次回は浅草と東京スカイツリーを訪れることを予告しています。' where id = 'AHdQTKz5tNjbchb5Z1Gd1';
update content_bodies set title = 'Kamakura & Enoshima one day trip near Tokyo', description = 'In this video, the creator shares their experience of visiting Kamakura and Enoshima using the Enoden train. They express their love for these locations, highlighting their unique local atmosphere and easy access from Tokyo. The video features the iconic Kamakurakōkōmae Station, known for its connection to the anime ''SLAM DUNK,'' and includes a walk around Enoshima. The channel aims to introduce viewers to unique travel destinations in Japan, encouraging likes and subscriptions. The creator also teases their next visit to Asakusa and Tokyo Skytree.' where id = 'IebozJko9zg-ii4sFvh97';
update content_bodies set title = '御前崎市民プレゼンツ　私たちの御前崎自慢10選', description = '御前崎市民が選んだ御前崎の自慢の10選を紹介しています。ぜひ御前崎市にお越しいただき、おいしい食べ物や美しい景色を楽しんでください。' where id = '11BzYIoy50jkb1Q__ghjs';
update content_bodies set title = '10 Highlights of Omaezaki City Selected by Its Citizens', description = 'This presentation introduces ten highlights of Omaezaki City chosen by its residents. We invite you to visit Omaezaki City and enjoy its delicious food and beautiful scenery.' where id = 'W6GuatqD2O3V3he7ar-Q1';
update content_bodies set title = '御前崎市観光PR動画～LIKE AN OMAEZAKI～', description = '静岡県最南端の岬のまち、御前崎。四季折々の海と里山の自然に彩られたこのまちで過ごす1日は、たくさんのおいしい食べ物や心洗われる絶景、魅力的な人々との出会いに満ちています。この動画を見れば、御前崎の魅力を知り、御前崎を好きになりたいと思うことでしょう。また、御前崎のように魅力的なまちへ行ってみたいと感じること間違いありません。' where id = 'XEJXadTMM7vuZYeVkOZj2';
update content_bodies set title = 'Omaezaki City Tourism PR Video - LIKE AN OMAEZAKI', description = 'Omaezaki, located at the southernmost tip of Shizuoka Prefecture, is a town where the beauty of nature in both the sea and the satoyama changes with the seasons. Spending a day here allows you to encounter delicious food, breathtaking views, and charming locals. After watching this video, you will surely come to appreciate the allure of Omaezaki and feel inspired to visit other equally captivating places, just like Omaezaki.' where id = 'qUDc3Cs1qWYp-OYMgVhr8';
update content_bodies set title = '鳥取山中に眠る天空の要塞「若松鉱山」紹介Ｍｏｖｉｅ', description = '若松鉱山は、30年前まで採掘が行われていた日本有数のクロム鉱山で、産出されたクロムは耐火煉瓦の原料として使用され、この地域での日本のクロム需要の大部分を賄っていました。1995年に閉山しましたが、今も当時の採掘、選鉱、破砕の様子が残る数少ない鉱山跡の一つです。2009年には経済産業省の「近代化遺産群 続33」に選定されています。' where id = 'CbN11e8Qji3lrhxjJyq85';
update content_bodies set title = 'Introduction to the Sky Fortress ''Wakamatsu Mine'' Hidden in the Tottori Mountains', description = 'Wakamatsu Mine, one of Japan''s leading chrome mines, was active until just 30 years ago. The chrome produced here was used as a raw material for fireproof bricks, fulfilling most of Japan''s chrome demand in the region during its peak. Although the mine closed in 1995, it remains one of the few mining sites in Japan where the conditions of mining, sorting, and crushing from that era are preserved. In 2009, it was designated as part of the ''Modern Industrial Heritage Group'' by the Ministry of Economy, Trade and Industry.' where id = 'tbEOQ24JqCVLzQBexdsJY';
update content_bodies set title = '時が止まる、ココロ動く。〜今日は何しに西尾市へ？〜ダイジェスト版B', description = '西尾市を訪れたカメラ好きの日本人女性とグルメなアジア系外国人女性が偶然出会い、一緒に観光を楽しむことになります。彼女たちは、西尾市ならではのグルメや自然、歴史などの観光資源を巡りながら、感情を動かしつつ、ゆったりとした贅沢な時間を体験します。また、観光情報を発信するインスタグラムや、観光スポットの情報提供を募集するお知らせも含まれています。西尾市の魅力を紹介する「西尾市観光文化振興課【公式】」チャンネルでは、職員が企画した面白い動画が毎月最終金曜に公開される予定です。' where id = 'Fawnq3UrfpPoK_z12eEgJ';
update content_bodies set title = 'Time Stops, Hearts Move. ~What to Do in Nishio City Today?~ Digest Version B', description = 'In Nishio City, a Japanese woman who loves photography and an Asian woman who enjoys gourmet food coincidentally meet while visiting alone and decide to explore together. They experience the unique attractions of Nishio City, including its gourmet offerings, nature, and history, while enjoying a leisurely and luxurious time that stirs their emotions.' where id = '_SorfcRd007ZHJiPzJcay';
update content_bodies set title = '時が止まる、ココロ動く。〜今日は何しに西尾市へ？〜ダイジェスト版A', description = '西尾市をそれぞれ一人で訪れたカメラ好きの日本人女性とグルメなアジア系外国人女性が偶然出会い、一緒に観光することになりました。彼女たちは、西尾市ならではの「グルメ」、「自然」、「歴史」といった観光資源を巡りながら、感情を動かしつつ、ゆったりとした贅沢な時間を体験します。また、観光情報を発信するインスタグラムや、観光スポットの情報提供を募るお知らせも含まれています。西尾市の魅力を紹介する「西尾市観光文化振興課【公式】」チャンネルでは、職員が企画した面白い動画が毎月最終金曜に公開される予定です。' where id = 'yUyCLMRnufUWP5m8d45I6';
update content_bodies set title = 'Time Stops, Hearts Move. ~What Brings You to Nishio City Today?~ Digest Version A', description = 'In Nishio City, a Japanese woman who loves photography and an Asian woman who enjoys gourmet food coincidentally meet while visiting alone. They decide to explore together, experiencing the unique attractions of Nishio City, including its gourmet offerings, nature, and history. This journey allows them to connect emotionally while enjoying a leisurely and luxurious time.' where id = '-8IAIHvpNk-EMDLFqyqze';
update content_bodies set title = '種子島星空PR動画', description = '令和4年度の特定有人国境離島地域社会維持推進交付金事業の一環として制作されたこの動画では、種子島の美しい星空を紹介しています。種子島は日本一きれいな星空に選ばれたこともあり、宇宙に最も近い島として知られています。日本随一の「星の島」として、種子島の魅力を伝えています。' where id = 'hWH2KrANGa5WMIBdmiH1l';
update content_bodies set title = 'Tanegashima Stargazing PR Video', description = 'This video showcases the beautiful starry sky of Tanegashima, which has been recognized as one of the most beautiful in Japan. Created as part of the 2022 Special Grant Program for the Maintenance of Specific Remote Islands, Tanegashima is known as the island closest to space and is celebrated as Japan''s premier ''Star Island.''' where id = 'MPts0brtLrdXZNPtTVv0F';
update content_bodies set title = '種子島観光協会PR動画', description = 'この動画は、種子島の観光をPRするためのものです。種子島の魅力を視覚的に体験できる内容となっており、ぜひご覧いただき、実際に種子島を訪れてみてください。' where id = 'KRUt19fGGm5jPXNdix0Ez';
update content_bodies set title = 'Tanegashima Tourism Association PR Video', description = 'This is a promotional video for Tanegashima tourism. You can see and feel the charm of Tanegashima, so please take a look and come visit Tanegashima!' where id = '2D27tjg0ClyZtkc9tFX7b';
update content_bodies set title = '種子島スタンプラリー広告動画　ロングVer.', description = 'この動画は、種子島スタンプラリーについて紹介しており、スタンプラリーの魅力や参加方法などが説明されています。種子島の観光名所を巡りながらスタンプを集める楽しさを伝える内容となっており、視聴者に参加を促すような構成になっています。' where id = 'hwRN2jnLV5XnoW3eTwPQ8';
update content_bodies set title = 'Tanegashima Stamp Rally Promotional Video - Long Version', description = 'This video introduces the Tanegashima Stamp Rally.' where id = 'd_w9wNIWDS7YPVRs-vqt4';
update content_bodies set title = '雪原カーニバルなかさとプロモーションムービー', description = '新潟県十日町市中里地域で毎年開催される「雪原カーニバルなかさと」のプロモーション映像です。この映像は、イベントへの思いを込めて制作されており、カーニバルの魅力や訪れる人々に提供されるユニークな体験を紹介しています。' where id = 'VGVtJrNMXnc2SHrghwsZu';
update content_bodies set title = 'The Movie of Snow Carnival in Nakasato, Tokamachi (for every year)', description = 'The Snow Carnival in Nakasato is an annual event held in the Nakasato region of Tokamachi City, Niigata Prefecture. This promotional video captures the spirit and excitement of the event, showcasing the unique experiences and attractions that the carnival offers to visitors.' where id = '42k87ZDQrAY28AD1WBHzJ';
update content_bodies set title = '【京都 上賀茂神社】笠懸神事　10月第3日曜日', description = '上賀茂神社は京都で最も古い社の一つで、境内全域が世界遺産に登録されています。平安時代から変わらない佇まいを今に伝えています。笠懸神事は毎年10月第3日曜日に行われ、日本書紀にも登場する騎射の一つである笠懸が披露されます。この神事では、射手が水平な的だけでなく、右下方・左下方に立てられた的を射るため、より高い技量が求められます。鎌倉時代には後鳥羽上皇が笠懸を行った記録があり、平成17年からは大日本弓馬会武田流の協力により毎年斎行されています。' where id = 'sjQT2OHKGCCm8ZLT5Ro2M';
update content_bodies set title = 'Kamo Shrine Kasakake Ceremony - Third Sunday of October', description = 'Kamo Shrine, one of the oldest shrines in Kyoto, is a UNESCO World Heritage site that has preserved its appearance since the Heian period. The Kasakake Ceremony, held on the third Sunday of October, features a traditional form of mounted archery known as ''Kasakake,'' which is mentioned in the Nihon Shoki. This event requires archers to shoot at targets not only at eye level but also at lower angles, demanding higher skill levels. Historical records indicate that Emperor Go-Toba performed Kasakake during the Kamakura period. Since 2005, the ceremony has been conducted annually with the support of the Takeda School of the All Japan Mounted Archery Association.' where id = '__T2E2mAcGaDkJFbGrlFC';
update content_bodies set title = '越後妻有 雪花火 プロモーションムービー', description = '「越後妻有 雪花火」は、越後妻有の雪原を舞台に花火を打ち上げ、闇の中に真っ白な雪の世界を一瞬浮かび上がらせるイベントです。豊かな地元の食と雪見酒、温かいおもてなしを楽しむことができます。日時は2015年3月7日（土）で、会場はナカゴグリーンパーク（十日町市上野甲2924-28）です。時間は後日更新されます。気象状況によっては花火の打ち上げが中止される場合があり、打ち上げ中の傘の使用はご遠慮ください。防寒・防雪対策を万全にしてお越しください。' where id = '8S0ebby0EbP3kY5BHRh1o';
update content_bodies set title = 'Echigo-Tsumari Snow Fireworks Promotion Movie', description = 'The ''Echigo-Tsumari Snow Fireworks'' event features fireworks launched against the backdrop of the snowy fields of Echigo-Tsumari, creating a momentary display of a pure white world in the darkness. Attendees can enjoy the rich local cuisine, snow-viewing sake, and warm hospitality. The event is scheduled for March 7, 2015, at Nakago Green Park in Tokamachi City, with the exact time to be updated later. Please note that fireworks may be canceled due to weather conditions, and the use of umbrellas during the fireworks display is discouraged. Attendees are advised to come prepared for cold and snowy conditions.' where id = 'zCKb9CW1-hfi4kHY5rbHI';
update content_bodies set title = '第66回十日町雪まつりプロモーションムービー', description = '第66回十日町雪まつりが平成27年2月20日（金）から22日（日）まで開催されます。このイベントは、雪をテーマにした祭りで、地域の文化や魅力を発信する重要な機会です。詳細は公式サイト（http://snowfes.jp/）をご覧ください。' where id = 'pQbzRtgZTlpDT3VaPmad8';
update content_bodies set title = '66th Tokamachi Snow Festival Promotion Movie', description = 'The 66th Tokamachi Snow Festival will be held from February 20 (Friday) to February 22 (Sunday), 2015. For more information, visit the official website at http://snowfes.jp/' where id = 'mQMZOv8-k5_8gIGc4Zhl8';
update content_bodies set title = '越後妻有 紡ぐ文化', description = 'この動画では、越後妻有の独自の文化である紡ぎについて紹介しています。越後妻有は新潟県十日町市に位置し、地域の伝統や技術が息づいています。紡ぎは、糸を作る技術であり、地域の人々の生活や文化に深く根ざしています。この文化を通じて、越後妻有の魅力や地域の人々の思いが伝わります。' where id = 'luZM94ZfNUEqjVLF55Udi';
update content_bodies set title = 'Echigo-Tsumari''s Spinning Culture', description = 'This video introduces the spinning culture of Echigo-Tsumari.' where id = 'eEHX3WNnvXBOm0HsQA-A1';
update content_bodies set title = '越後妻有 雪花火／Gift for Frozen Village 2021', description = 'この動画は、越後妻有で開催された「Gift for Frozen Village 2021」について紹介しています。このイベントは大地の芸術祭の一環として行われ、冬の花火が特徴的なアートの祭典です。越後妻有の美しい冬の風景とともに、芸術的な花火の演出が楽しめる内容となっています。' where id = 'dgjd9P-8M8N_nbFlaHGgV';
update content_bodies set title = 'Gift for Frozen Village 2021', description = 'This video introduces the event ''Gift for Frozen Village 2021'' held in Echigo-Tsumari, known for its art festival. It showcases the unique winter fireworks that are part of this artistic celebration.' where id = 'KNaZNJ9EhtYVa1E-uZtLb';
update content_bodies set title = '「森の学校」キョロロ　自然と里山の暮らし、地域の魅力を未来へ', description = '「森の学校」キョロロは、参加体験型の自然科学館で、展示物を通じて地域の環境に気づき、発見を楽しむことを目的としています。里山の概念は、人間の活動によって育まれた自然環境を指し、人口減少がその維持に直結することを強調しています。ミュージアムは、地域の知恵や活動の価値を科学的視点で再評価し、地域の魅力を高めることを目指しています。新潟県十日町市に位置し、生物多様性や文化に関する多様なプログラムを提供し、里山の保全と地域づくりに貢献しています。美しい自然に囲まれたこの施設は、教育、体験、観光の拠点として、持続可能な環境との関わりを促進しています。' where id = '1nFx1gd14qdCGoR145-Sv';
update content_bodies set title = 'Kyororo Forest School: Embracing Nature and Local Charm for the Future', description = 'Kyororo Forest School is an interactive nature science museum that encourages visitors to discover and appreciate the local environment through its exhibits. The concept of satoyama, a human-influenced natural environment, is central to the museum''s mission. It emphasizes the importance of human activities in maintaining these ecosystems, highlighting that a decline in population can threaten their sustainability. The museum aims to reveal the intrinsic value of local knowledge and practices through a scientific lens, fostering a sense of community and connection to the region. Located in Tokamachi City, the museum offers diverse programs related to biodiversity and cultural research, contributing to the preservation of satoyama and regional development. Surrounded by beautiful natural landscapes, it serves as a hub for education, experience, and tourism, promoting sustainable engagement with the environment.' where id = 'RgUeIYLRI7gSXk8FWmNVX';
update content_bodies set title = '雪とある日のとおかまち', description = 'この動画は新潟県十日町市における雪の日の様子を紹介しています。雪に覆われた風景や日常の様子が描かれ、冬の十日町の魅力を伝えています。' where id = 'LVAhzJBKvn6G7sXJVUjo9';
update content_bodies set title = 'One snowy day in Tokamachi', description = 'This video introduces a snowy day in Tokamachi, Niigata Prefecture.' where id = 'fymTwpywy_Vnq4-5KPops';
update content_bodies set title = '第２回新潟ふるさとCM大賞　十日町市応募作品【🏆 第３位受賞】', description = '第２回新潟ふるさとCM大賞に応募した十日町市の作品「ＩＴ（会いてぇ）キモチ、ツナグＳＮＳ」は、コロナ禍で都会の生活に疲れた孫と、孫に会える日を楽しみに待つ祖母の物語です。タイトルには、田舎（Inaka）と都会（Tokai）で離れた二人の会いたい（会いてぇ）気持ちが、スマホ(IT)やSNSを通じて繋がっているという思いが込められています。令和３年11月２日に行われた審査会では、全30市町村の作品の中で第３位を受賞しました。新潟ふるさとCM大賞は、地域の一体化を図り、地域活性化を目的に、UX新潟テレビ21・新潟県・新潟県市町村振興協会が主催し、令和２年度から開催されています。' where id = 'K8X4mqlxfn6aFcCORr0ZS';
update content_bodies set title = 'Second Niigata Furusato CM Award - Tokamachi City Entry [🏆 3rd Place Awarded]', description = 'The entry from Tokamachi City for the Second Niigata Furusato CM Award is titled ''IT (Aite) Kimochi, Tsunagu SNS''. It tells the story of a grandmother eagerly waiting to see her grandchild, who is tired of city life during the COVID-19 pandemic. The title reflects the feelings of longing (''Aite'') between the two, who are separated by distance between the countryside (Inaka) and the city (Tokai), yet are connected through smartphones (IT) and social media (SNS). The entry was awarded 3rd place among 30 submissions during the judging session held on November 2, 2021. The Niigata Furusato CM Award aims to promote local love and community cohesion through the creation of CM by various municipalities in Niigata Prefecture, and it has been held since the 2020 fiscal year, organized by UX Niigata Television 21, Niigata Prefecture, and the Niigata Prefectural Municipal Promotion Association.' where id = '4VRFU1RJXbGpYJCEkPsJZ';
update content_bodies set title = '第３回新潟ふるさとCM大賞　十日町市応募作品「農ある女子は、夢隠さず！」【第５位入賞】', description = '第３回新潟ふるさとCM大賞に応募した十日町市の作品「農ある女子は、夢隠さず！」は、女子サッカーチーム「FC越後妻有」が中心となって制作されました。このチームは2015年に設立され、全国から移住した選手たちが棚田の保全活動を行いながら、トップリーグを目指しています。農業とサッカーを両立させる選手たちの姿は多くのサポーターを惹きつけ、2022年には北信越女子サッカー2部リーグで優勝し、1部昇格を果たしました。「FC越後妻有」の存在は、十日町市が発信する新しい生き方のメッセージを体現しています。このCMは、視聴者に「私も十日町市で、自分の夢を叶えてみよう！」と思わせることを目指しました。2022年11月10日の審査会では、27市町村の中で第5位を受賞しました。' where id = 'SqpGE5FeTfNEpnzCyy6Mi';
update content_bodies set title = '5th Place Entry in the 3rd Niigata Furusato CM Award: Tokamachi City - ''Girls in Agriculture, No Dreams Hidden!''', description = 'The entry from Tokamachi City, titled ''Girls in Agriculture, No Dreams Hidden!'', participated in the 3rd Niigata Furusato CM Award. The women''s soccer team ''FC Echigo-Tsumari'' was established in 2015 as part of the ''Art of the Earth Festival'' project, focusing on the areas of Tokamachi City and Tsunan Town. Players, who have relocated from across the country, engage in rice terrace preservation activities while striving for the top league. Their ability to balance ''agriculture'' and ''soccer'' has attracted many supporters, leading to their victory in the Hokushin''etsu Women''s Soccer Division 2 and promotion to Division 1 in 2022. The existence of ''FC Echigo-Tsumari'' embodies a new lifestyle message from Tokamachi City, encouraging viewers to pursue their dreams in the city. The CM aims to inspire viewers to think, ''I want to realize my dreams in Tokamachi City!'' The CM was awarded 5th place among 27 entries during the judging session held on November 10, 2022.' where id = 'Elbh4nZgOIE1z7olmMbyM';
update content_bodies set title = '第４回新潟ふるさとCM大賞　十日町市応募作品「スノウリッチ なものがたり」', description = '第４回新潟ふるさとCM大賞に応募した十日町市の作品「スノウリッチなものがたり」は、平均積雪深が2メートルを超える世界有数の「雪国」としての十日町市の魅力を伝えています。雪をテーマにしたふるさとCMは初めての制作で、タイトルの「スノウリッチ」は日本遺産「究極の雪国とおかまち」のキャッチコピーで、雪の豊かさや文化を表現しています。雪だるまが紹介する写真は、昨冬に開催された2つのフォトコンテストの応募作品で、雪と共にある日常や楽しむ瞬間を市民の視点で捉えたエネルギーに満ちた内容です。' where id = 'FEUXMTDp-MqLMFeFMbRCB';
update content_bodies set title = 'The 4th Niigata Furusato CM Award: Tokamachi City Entry ''Snow Rich Story''', description = 'The entry ''Snow Rich Story'' from Tokamachi City for the 4th Niigata Furusato CM Award highlights the city''s identity as a renowned ''snow country,'' with an average snow depth exceeding 2 meters. This is the first time a hometown commercial focusing on ''snow'' has been produced for Tokamachi. The term ''Snow Rich'' is a catchphrase from the Japanese heritage ''Ultimate Snow Country Tokamachi - The True Story of Heavy Snow.'' It represents the abundance of snow and the rich culture and lifestyle that benefit from it. The snowman in the video introduces various photos from two photo contests held last winter, capturing everyday life in the snow and moments of joy experienced by the citizens. The portrayal of ''snow country'' is vibrant and full of energy.' where id = 'DtbXMQL3zlHyi-H7Qw2Mc';
update content_bodies set title = '第５回新潟ふるさとCM大賞　十日町市作品「ご当地サプリにびっくりどっぷり」', description = '第５回新潟ふるさとCM大賞において、十日町市の作品が紹介されます。元イタリア人国際交流員のマッテオ エンリコオルフィーさんが主演し、ユニークな登場人物たちが松之山温泉の効能の高さとその心地よさを表現したCMです。制作は十日町市が行い、収録・編集はフォーエス株式会社が担当しています。' where id = 'CsoLTon8puLBvk8nTGR1b';
update content_bodies set title = '5th Niigata Furusato CM Award - Tokamachi City Entry ''Surprised by Local Supplements''', description = 'The 5th Niigata Furusato CM Award features a work from Tokamachi City. Starring Matteo Enrico Orfi, a former Italian international exchange officer, the commercial showcases unique characters expressing the high efficacy and comfort of Matsunoyama Onsen. The production was done by Tokamachi City, with recording and editing by 4S Co., Ltd.' where id = '8_MUNBXSSJEt-Sq2EoFJ4';
update content_bodies set title = '【大地の芸術祭の里】新潟県十日町市 会沢集落', description = 'この動画では、新潟県十日町市にある会沢集落について紹介しています。この集落は【大地の芸術祭の里】の一部であり、地域の文化や芸術を体験できる場所です。' where id = 'vGj-giRth9nZ8Bt6VzBHM';
update content_bodies set title = 'The Art Festival Village: Aizawa Settlement in Tokamachi City, Niigata Prefecture', description = 'This video introduces the Aizawa settlement in Tokamachi City, Niigata Prefecture, which is part of the Art Festival Village.' where id = 'amNq_TXB-YKqwR5SBcLBg';
update content_bodies set title = '中手集落 canvas ４ | 栗真由美【越後妻有 この大地の里山は キャンバスになり 祭りがはじまる。】', description = '越後妻有地域は新潟県十日町市と津南町から成り、2000年から「大地の芸術祭」が開催されています。この祭りは、地域の人々の生活や四季折々の豊かな自然を表現する場です。この映像作品は、地域をキャンバスとして捉え、そこで暮らす人々や自然、文化の魅力を再認識することを目的としています。地域の暮らしを主役にしたドキュメンタリーであり、アーティストたちがインスピレーションを受ける地域の魅力に迫ります。監督は分部康仁、クリエーティブディレクターは引地央行、企画・プロデュースは酒井隆光が担当しています。人間と自然の関係を探ることが、この地域の基本理念となっています。' where id = '6D4VpOimMCpthrPc2xxJV';
update content_bodies set title = 'Chūte Settlement Canvas 4 | Yumi Kuri【Echigo-Tsumari: This Land''s Satoyama Becomes a Canvas and the Festival Begins】', description = 'The Echigo-Tsumari region, comprising Tokamachi City and Tsunan Town, has hosted the "Echigo-Tsumari Art Triennale" since 2000. This festival showcases the lives of local residents and the rich natural environment throughout the seasons. The video work captures the region as a canvas, highlighting the charm of its people, nature, and culture. It serves as a documentary focusing on the local lifestyle, inspired by the artists who visit for the festival. Directed by Yasuhito Bunbe, with creative direction by Hiroyuki Hikichi and produced by Takamitsu Sakai, the project aims to explore the relationship between humans and nature, emphasizing the region''s philosophy that "humans are encompassed by nature."' where id = '_dSUFg3eTXv7WZE6Wzc1P';
update content_bodies set title = '田野倉集落 canvas ２ | 石松丈佳【越後妻有 この大地の里山は キャンバスになり 祭りがはじまる。】', description = '越後妻有地域は新潟県十日町市と津南町から成り、2000年から「大地の芸術祭」が開催されています。この祭りは、地域の人々の生活や四季折々の自然の豊かさを表現する場です。この映像作品は、地域をキャンバスとして捉え、そこで暮らす人々や自然、文化の魅力を再認識することを目的としています。地域の暮らしを主役にしたドキュメンタリーであり、アーティストが作品のインスピレーションを得るための地域の魅力に迫ります。監督は分部康仁、クリエーティブディレクターは引地央行で、地域の価値をアートを通じて発信し、地域再生を目指しています。' where id = 'KdEBXaVXXwv_CYwKA3CNg';
update content_bodies set title = 'Tanokura Village Canvas 2 | Jouka Ishimatsu [Echigo-Tsumari: This Satoyama Becomes a Canvas and the Festival Begins.]', description = 'The Echigo-Tsumari region, encompassing Tokamachi City and Tsunan Town in Niigata Prefecture, has hosted the "Echigo-Tsumari Art Triennale" since 2000. This festival showcases the lives of local residents and the rich natural environment throughout the seasons. The video work captures the region as a canvas, highlighting the charm of its people, nature, and culture. It serves as a documentary that emphasizes the local lifestyle, inspiring artists who visit for the festival. Directed by Yasuhito Bunbe, with creative direction by Hiroyuki Hikichi, the project aims to rediscover the region''s appeal and promote its values through art, contributing to community revitalization.' where id = 'BcXud5cyYZteojBvySXVJ';
update content_bodies set title = '蓬平・会沢集落 canvas ３ | 蓮池もも', description = '越後妻有地域は新潟県十日町市と津南町から成り、2000年から「大地の芸術祭」が開催されています。この祭りは、地域の人々の生活と四季折々の自然の美しさを表現しています。映像作品は、地域をキャンバスとして捉え、そこで暮らす人々や自然、文化の魅力を再認識するドキュメンタリーです。監督の分部康仁氏は、地域の暮らしを主役に据え、アーティストがインスピレーションを受ける様子を描いています。人間と自然の関係を探ることがこの地域の基本理念であり、蓮池もも氏は2016年に移住し、地域の日常や歳時を描いた10メートルの絵巻を制作しました。この作品は、やぶこざきキャンプ場で展示され、山々の美しい景色とともに楽しむことができます。' where id = 'gz1n-YlWl14kttug1w0Ij';
update content_bodies set title = 'Yohira and Aizawa Settlement Canvas 3 | Momo Hasuike', description = 'The Echigo-Tsumari region, encompassing Tokamachi and Tsunan in Niigata Prefecture, has been the site of the "Echigo-Tsumari Art Triennale" since 2000. This festival showcases the rich natural beauty and the lives of the local people throughout the seasons. The video work, directed by Yasuhito Bunbe, captures the essence of the community as a canvas, highlighting the charm of the people, nature, and culture. It serves as a documentary that emphasizes the local lifestyle, inspired by the artists who visit for the festival. The project aims to explore the relationship between humans and nature, reflecting the region''s philosophy that humans are inherently connected to nature. Momo Hasuike, who moved to the area in 2016, created a 10-meter-long narrative artwork depicting daily life and seasonal events, displayed at the Yabukozaki Campground, which offers stunning views of the mountains.' where id = 'tlJXI-YX9_rw2SoXSrXUf';
update content_bodies set title = '羽州街道を往く～歩いて発見！秋田市・歴史文化遺産～', description = '羽州街道は、福島県の桑折から宮城県、山形県を経て秋田県、青森県の油川に至る道で、江戸時代には多くの人や物が行き交う大動脈でした。秋田市の沿線には、文化財に指定された古い建物や文化施設が点在し、今もその名残を感じることができます。また、秋田藩士・荻津勝孝の筆による「秋田街道絵巻」には、往時の街道の風景や人々の様子が生き生きと描かれています。秋田市では、これらの魅力を歴史ストーリーで結びつけ、独自の街道歩きを楽しめるようにPR映像を制作しました。様々な角度から羽州街道の魅力を紹介しています。' where id = 'vF-UTnrNyvSQ-SUEdjV38';
update content_bodies set title = 'Exploring the Ushu Highway: Discovering Historical and Cultural Heritage in Akita City', description = 'The Ushu Highway, which stretches from Koori in Fukushima Prefecture, through Miyagi and Yamagata Prefectures, up to Akita and finally to Aburakawa in Aomori Prefecture, served as a major artery during the Edo period, facilitating the movement of people and goods. Along the Ushu Highway in Akita City, there are numerous designated cultural properties, including old buildings and cultural facilities, where one can still feel the remnants of the past. The ''Akita Highway Picture Scroll,'' attributed to Akita samurai Katsu Takakatsu, vividly depicts the landscapes and people of the highway during its heyday. To promote these attractions, Akita City has produced a promotional video that connects these historical stories, allowing visitors to enjoy a unique walking experience along the highway, showcasing its charm from various perspectives.' where id = '6gpQsOY3imIqVHPL9P9g5';
update content_bodies set title = '羽州街道を往く～歩いて発見！秋田市・歴史文化遺産～ダイジェスト版', description = '羽州街道は、福島県の桑折から宮城県、山形県を経て秋田県、青森県の油川に至る道で、江戸時代には多くの人や物が行き交う重要な道でした。秋田市の沿線には、文化財に指定された古い建物や文化施設が点在し、今もその名残を感じることができます。また、秋田藩士・荻津勝孝の筆による「秋田街道絵巻」には、往時の街道の風景や人々の様子が生き生きと描かれています。秋田市では、これらの魅力を歴史ストーリーで結びつけ、独自の街道歩きを楽しめるようにPR映像を制作しました。様々な角度から羽州街道の魅力を紹介しています。' where id = 'JyCOx_0a1TV73d_4uGMLX';
update content_bodies set title = 'Traveling the Ushu Highway: Discovering Historical and Cultural Heritage in Akita City - Digest Version', description = 'The Ushu Highway, which stretches from Koori in Fukushima Prefecture, through Miyagi and Yamagata Prefectures, up to Akita Prefecture and finally to Aburakawa in Aomori Prefecture, served as a major artery during the Edo period, facilitating the movement of people and goods. Along the Ushu Highway in Akita City, there are numerous designated cultural properties, including old buildings and cultural facilities, where one can still feel the remnants of the past. The ''Akita Kaido Emaki,'' attributed to Akita samurai Katsu Takakatsu, vividly depicts the landscapes and people of the highway during its heyday. To promote these attractions, Akita City has produced a PR video that connects these historical stories, allowing visitors to enjoy a unique walking experience along the highway, showcasing its charm from various perspectives.' where id = 'tNFXKkxtEoKWCBYh6oe1x';
update content_bodies set title = '【岐阜県瑞浪市】あふれる愛で、クセ強し【体験観光プロモーション動画】', description = '瑞浪市には、豊かな自然やワクワクする体験、美味しい食べ物など、五感を刺激する魅力がたくさんあります。田舎の心地よさとストレスフリーな環境が魅力で、風が気持ちよく、水と空気も美味しいです。しかし、瑞浪市の一番の自慢は「ひと」です。自分たちのまちを愛し、個性的な人々が集まっています。彼らが営むお店や体験は楽しくないはずがありません。観光地ではなく“感幸地”として、心をゆさぶる体験ができる場所です。一度訪れたらクセになる瑞浪市で、ぜひ私たちのあふれる愛を受け取ってください。' where id = 'LKzT4UOVfVYEEN3arZ94q';
update content_bodies set title = 'Mizunami City, Gifu Prefecture: Overflowing Love and Unique Experiences', description = 'Mizunami City offers a wealth of attractions that stimulate the five senses, including rich nature, exciting experiences, and delicious food. It is a stress-free rural area with pleasant winds, and clean water and air. However, the city''s greatest pride lies in its people—unique individuals who deeply love their town and what they do. These passionate locals, often described as quirky, run shops and experiences that are sure to be enjoyable. Mizunami is not just a tourist destination; it is a place of ''emotional happiness'' where visitors can enjoy heartwarming experiences. Once you visit, it’s a place you’ll want to return to. Come and receive the overflowing love of Mizunami City.' where id = 'Cd1qA_nsAZC44p3Ko52g6';
update content_bodies set title = '北海道アドベンチャー旅行 / 黒松内低地エリアでのカヌー体験', description = '黒松内観光協会が提供するこのプロジェクトは、北海道の黒松内低地エリアでのカヌー体験を通じて、冒険旅行の魅力を紹介しています。この取り組みは、地域の魅力を活かした観光地づくりを推進するために、北海道観光振興機構の支援を受けています。訪れる人々は、自然の美しさと静けさを楽しみながら、アウトドアアクティビティを体験できます。詳細については、公式ウェブサイトやFacebook、InstagramなどのSNSをチェックしてください。' where id = '2o9SZXPjpJh-S_0UWR2mM';
update content_bodies set title = 'Hokkaido Adventure Travel / Canoeing in Kuromatsunai Lowland Area', description = 'The Kuromatsunai Tourist Association presents an exciting adventure travel opportunity in Hokkaido, focusing on canoeing in the scenic Kuromatsunai Lowland Area. This initiative is supported by the Hokkaido Tourism Organization, which aims to promote tourism by leveraging the unique attractions of the region. Visitors can explore the natural beauty and tranquility of the area while enjoying outdoor activities. For more information, you can visit their website or follow them on social media platforms like Facebook and Instagram.' where id = 'dmPLcRt_8EW5DW2qZY2Rj';
update content_bodies set title = '黒松内低地エリアの冒険旅行：北海道日本', description = '黒松内観光協会が北海道の黒松内低地エリアでの冒険旅行プロジェクトを紹介しています。この取り組みは、地域の魅力を活かした観光振興を目的として、北海道観光振興機構の支援を受けています。訪問者は、黒松内の自然の美しさや文化遺産を体験できるさまざまなアクティビティを楽しむことができます。詳細については、公式ウェブサイトやFacebook、Instagramなどのソーシャルメディアをチェックしてください。' where id = 'fDVAAGMX74zAQFiv5JMVN';
update content_bodies set title = 'Adventure Travel in Kuromatsunai Lowland Area: Hokkaido Japan', description = 'The Kuromatsunai Tourist Association presents an adventure travel project in the Kuromatsunai Lowland Area of Hokkaido, Japan. This initiative is supported by the Hokkaido Tourism Organization, aiming to promote tourism by highlighting the unique attractions of the region. Visitors can explore various activities and experiences that showcase the natural beauty and cultural heritage of Kuromatsunai. For more information, you can visit their website or follow them on social media platforms like Facebook and Instagram.' where id = 'xVVWsW46CcaZxhOfNaNL4';
update content_bodies set title = '北海道アドベンチャー旅行 / 黒松内低地エリアのハイキング', description = '黒松内観光協会が提供するこのプロジェクトは、北海道の黒松内低地エリアでのハイキングを中心としたアドベンチャー旅行の機会を提供します。この取り組みは、地域の魅力を活かした観光地づくりを推進するために、北海道観光振興機構の支援を受けています。訪れる人々は、黒松内の自然の美しさや多様な風景を探索でき、アウトドア愛好者にとって理想的な目的地となっています。' where id = 'LTpRlVfZx4SnNi0VCef4P';
update content_bodies set title = 'Hokkaido Adventure Travel / Hiking in Kuromatsunai Lowland Area', description = 'The Kuromatsunai Tourist Association presents an exciting opportunity for adventure travel in Hokkaido, specifically focusing on hiking in the Kuromatsunai Lowland Area. This initiative is supported by the Hokkaido Tourism Organization, which aims to promote tourism by leveraging the unique attractions of the region. Visitors can explore the natural beauty and diverse landscapes of Kuromatsunai, making it an ideal destination for outdoor enthusiasts.' where id = 'IjaSmavk_Qh0LTBEv-1_z';
update content_bodies set title = '北海道アドベンチャー旅行 / 黒松内低地エリアのサイクリング', description = '黒松内観光協会が提供するこのプロジェクトは、北海道の黒松内低地エリアでのサイクリングを中心としたアドベンチャー旅行の機会を紹介しています。この取り組みは、地域の魅力を活かした観光地づくりを推進するために、北海道観光振興機構の支援を受けています。訪れる人々は、美しい風景を楽しみながらアウトドアアクティビティを体験でき、冒険好きには最適な目的地となっています。' where id = '8-wNZnoLQDvsGaaA24WI5';
update content_bodies set title = 'Hokkaido Adventure Travel / Cycling in Kuromatsunai Lowland Area', description = 'The Kuromatsunai Tourist Association presents an exciting adventure travel opportunity in Hokkaido, focusing on cycling in the scenic Kuromatsunai Lowland Area. This initiative is supported by the Hokkaido Tourism Organization, which aims to promote tourism by leveraging the unique attractions of the region. Visitors can explore the beautiful landscapes and enjoy outdoor activities, making it a perfect destination for adventure enthusiasts.' where id = 'f0bVKwWWTKFHrLkrTfJDx';
update content_bodies set title = '予告編　-奈良 観光 秋-', description = '奈良県の自主制作観光PR映像です。シルクロードの終着点である奈良は、京都の華やかさとは異なる魅力を持つ古都です。この映像では、11月の奈良の様々なスポットを紹介しています。具体的には、野迫川村の雲海、長谷寺、談山神社、珈琲の館御園、明日香村、高松塚古墳壁画、曽爾高原、洞川温泉、みたらい渓谷などが含まれています。撮影にご協力いただいた皆様に感謝申し上げます。音楽にはヴィヴァルディの『四季』秋が使用されています。' where id = 'u9ekxWNjhaNrP8SEHYdvi';
update content_bodies set title = 'Trailer - Autumn in Nara Tourism', description = 'This is a self-produced promotional video for tourism in Nara Prefecture, Japan. Nara, the final destination of the Silk Road, offers a journey distinct from the splendor of Kyoto. The film showcases various locations in Nara during November, including the sea of clouds in Nosegay Village, Hasedera Temple, Tanzan Jinja Shrine, Coffee House Misono, Asuka Village, Takamatsuzuka Tumulus Mural Paintings, Soni Highland, Dorogawa Onsen, and Mitarai Valley. Special thanks to those who granted permission for filming. The music featured is Vivaldi''s ''The Four Seasons Autumn in F Major, RV. 293: I. Allegro.''' where id = 'wxX5ssN9t6KfuK2TCgTNQ';
update content_bodies set title = '京都 上賀茂神社 四季', description = '上賀茂神社は京都で最も古い社の一つであり、境内全域が世界遺産に登録されています。平安時代から変わらない佇まいを今に伝え、四季折々の自然や伝統の美しさを感じることができます。' where id = 'YJGRF0oe3ulVwhsb5pzT7';
update content_bodies set title = 'Kamigamo Shrine in Kyoto: The Four Seasons', description = 'Kamigamo Shrine, one of the oldest shrines in Kyoto, is a UNESCO World Heritage site. It has preserved its appearance since the Heian period, showcasing the beauty of nature and tradition throughout the four seasons.' where id = 'jJDKV2Asvvm86gPsoshH5';
update content_bodies set title = 'イカダ下り', description = '和歌山県の北山村で伝統的なイカダ下りを体験するユニークな冒険です。北山峡の美しい風景の中で、何世代にもわたるイカダ下りのスリルを感じることができます。熊野の森や谷に囲まれたこの場所で、熟練のイカダ職人と共に北山峡を下る特別な体験をお楽しみください。このツアーは10歳から75歳までの方が参加可能で、夏の5月から9月まで運営されています。' where id = 's3Ng6oyMN8p5ZbHBoGz_i';
update content_bodies set title = 'Ikada-Kudari', description = 'Experience a unique adventure with Traditional Ikada-Kudari in Kitayama village, Wakayama, Japan. This activity allows participants to feel the thrill of centuries-old log rafting in the picturesque Kitayama Gorge, surrounded by the stunning Kumano forests and valleys. Join skilled log runners as they navigate the gorge, offering an unforgettable experience. The tour is available for individuals aged 10 to 75 and operates during the summer months from May to September.' where id = 'tA6FkKz7BlqGc6e-oSrWz';
update content_bodies set title = 'そらにみつ あをによし -奈良 観光 秋-', description = 'この映像は、奈良の観光を促進するための自主制作PR映像で、英語と繁体字の字幕が追加されています。奈良はシルクロードの終着点であり、京都の華やかさとは異なる魅力を持つ古都です。映像では、野迫川村の雲海、長谷寺、明日香村、珈琲の館御園、高松塚古墳壁画、談山神社、曽爾高原、洞川温泉、みたらい渓谷など、さまざまな場所が紹介されています。音楽にはクロード・ドビュッシーの「月の光」が使用されています。撮影に協力してくださった皆様に感謝の意が表されています。' where id = 'BvOUius5jTcpzRN_OXL_y';
update content_bodies set title = 'Glimpses of NARA, Japan', description = 'This is a self-produced promotional video for tourism in Nara, Japan, featuring English and Traditional Chinese subtitles. The film explores Nara, the final destination of the Silk Road, highlighting its unique charm compared to the grandeur of Kyoto. The video showcases various locations, including the sea of clouds in Nosegay Village, Hasedera Temple, Asuka Village, Coffee House Misono, Takamatsuzuka Tumulus Mural Paintings, Tanzan Jinja Shrine, Soni Highland, Dorogawa Onsen, and Mitarai Valley. The film is accompanied by music from Claude Debussy''s ''Clair de Lune.'' Special thanks are given to those who permitted filming, and the video was created using high-quality equipment.' where id = 'HWM2g90guH-vOj65JqWjc';
update content_bodies set title = '【夏】真庭PR映像「Summer of Maniwa Okayama Japan」観光 PV', description = 'この映像は、岡山県真庭市と新庄村の夏の風景を紹介しており、夏に楽しめるアクティビティやイベントが描かれています。真庭は岡山県北部、鳥取県との境に位置し、里山と共に生きてきた歴史があります。蒜山高原や湯原温泉などの観光地があり、さまざまな自然環境に恵まれています。自然の中で楽しめる冒険の森やサイクリング、キャンプ、山乗渓谷のそうめん流しが人気です。また、経験豊富なガイドと共に行うリバートレッキングや巨木めぐりも魅力的なプログラムです。' where id = 'fAAXbRnEqS6WViXxQzD8-';
update content_bodies set title = 'Summer of Maniwa Okayama Japan - PR Video', description = 'This video showcases the summer scenery of Maniwa City and Shinjo Village in Okayama Prefecture, highlighting various activities and events that can be enjoyed during the summer. Located in the northern part of Okayama, bordering Tottori Prefecture, Maniwa has a rich history of living in harmony with the satoyama landscape. The region is blessed with diverse climates and nature, featuring popular tourist spots such as Hiruzen Highlands and Yubara Onsen. Visitors can enjoy outdoor activities like adventure forests, cycling, and camping, as well as the popular somen nagashi (flowing noodles) at Ryusuitei in Yamano Gorge. Additionally, guided experiences like river trekking and giant tree tours offer exciting programs for adventurers.' where id = '6RkZCVbS0dSJg7M7nGC48';
update content_bodies set title = '【春】真庭PR映像「Spring of Maniwa Okayama Japan」観光 PV', description = 'この映像は岡山県真庭市と新庄村の春の美しさを紹介しています。里山の中に咲く桜が特徴で、真庭は岡山県北部、鳥取県との境に位置し、自然と共に生きてきた地域です。蒜山高原や湯原温泉などの観光地もあり、さまざまな風土に恵まれています。冬が終わり、気温が上がると、桜が咲き始め、山々が華やかになります。南北に長い真庭では、約一ヶ月にわたって桜を楽しむことができます。' where id = 'UKICrvPg89YMJGowqq_En';
update content_bodies set title = 'Spring of Maniwa Okayama Japan - PR Video', description = 'This video showcases the beauty of spring in Maniwa City and Shinjo Village, located in Okayama Prefecture. The area is known for its cherry blossoms that bloom amidst the satoyama landscape. Maniwa, situated in the northern part of Okayama near the border with Tottori Prefecture, has a rich history of living in harmony with its natural surroundings. It is home to popular tourist destinations such as Hiruzen Highlands and Yubara Onsen, benefiting from diverse climates and nature. As winter ends and temperatures rise, cherry blossoms begin to bloom, bringing vibrant colors to the mountains. The elongated region of Maniwa allows visitors to enjoy cherry blossoms for about a month.' where id = 'C4RtpXxabMEW9wPt2Pv_U';
update content_bodies set title = '東北絆まつりを探る', description = '「東北絆まつり」は、日本の北部に位置する東北地方の6つの夏祭りを一堂に集めたイベントです。青森ねぶた祭、秋田竿燈まつり、盛岡さんさ踊り、山形花笠まつり、仙台七夕まつり、福島わらじまつりが一緒に開催され、地域の文化や食を体験できる機会を提供します。祭りは毎年5月下旬から6月中旬にかけて行われ、開催地は毎年変わります。詳細は公式ウェブサイトをご覧ください。' where id = 'VRmENGqrD0eW9aL7m8pK9';
update content_bodies set title = 'Explore Tohoku Kizuna Festival in Japan', description = 'The Tohoku Kizuna Festival is a unique event that showcases six traditional summer festivals from the Tohoku region of Japan, allowing visitors to immerse themselves in the local culture, festivals, and cuisine. The festival features the Aomori Nebuta Festival, Akita Kanto Festival, Morioka Sansa Dance, Yamagata Hanagasa Festival, Sendai Tanabata Festival, and Fukushima Waraji Festival, creating a vibrant atmosphere. This annual festival takes place from late May to mid-June, with its location changing each year. For more information, visit the official website.' where id = 'wSWw1-HhMEM_GTn27warM';
update content_bodies set title = '-水と還り、水と生きる- 滋賀県長浜市西浅井町ドキュメンタリー作品', description = 'この動画は「水と還り、水と生きる」について紹介しています。' where id = 'M7baK35e12HrIcA4cc5jY';
update content_bodies set title = '-Water and Return, Living with Water- A Documentary from Nishiazai Town, Nagahama City, Shiga Prefecture', description = 'This video introduces the theme of ''Water and Return, Living with Water''.' where id = 'A86hhO2qSvUhz9ThZ5712';
update content_bodies set title = '真庭PR映像「Autumn of Maniwa Okayama Japan」観光 PV', description = 'この映像は、岡山県真庭市と新庄村の秋の風景を紹介しています。真庭は岡山県北部、鳥取県との境に位置し、昔から里山と共に生きてきた地域です。蒜山高原や湯原温泉などの観光地があり、さまざまな風土と自然に恵まれています。肌寒さが増すと、里山は徐々に色づき、美甘渓谷や神庭の滝などの紅葉スポットやコスモスなどの秋の花が楽しめます。' where id = 'R3LbVLPrJtm8f0wiHKxt5';
update content_bodies set title = 'Autumn of Maniwa Okayama Japan - PR Video', description = 'This video showcases the autumn scenery of Maniwa City and Shinjo Village in Okayama Prefecture. Located in the northern part of Okayama, bordering Tottori Prefecture, Maniwa has a rich history of living in harmony with its satoyama (village forest). The region is blessed with various landscapes and natural attractions, including tourist spots like Hiruzen Plateau and Yubara Onsen. As the weather turns cooler, the satoyama gradually transforms with vibrant autumn colors. Visitors can enjoy beautiful fall foliage at locations such as Mimasaka Valley and Kanba Falls, as well as autumn flowers like cosmos.' where id = '9VbvLW8Odr496fr0A-r9C';
update content_bodies set title = '日本国際映像祭2025オフィシャルコレクション作品【時を旅する北山川筏下り】', description = '「時を旅する」筏は、かつて林業として栄えた筏流しの文化を紹介します。筏流しは時代と共に変化しながらも、今も同じ北山川の美しい風景の中を筏師の巧みな櫂さばきで下っていきます。夏には、旅行者がこの小さな村に訪れ、丸太筏に乗って急流を下る体験を楽しみます。筏師はエンジンを使わず、川の流れを読みながら自然の地形を利用して筏を進めます。この観光筏下りは、林業から観光への産業転換を遂げ、昔と変わらぬ風景を見せてくれ、まるでタイムマシーンに乗ったかのような体験を提供します。' where id = 'kh9HATKG_Wdu7JZK1rEX8';
update content_bodies set title = 'Official Collection Work of the Japan International Film Festival 2025: ''Traveling Through Time on the Kitayama River Raft''', description = 'The film ''Traveling Through Time'' showcases the culture of rafting on the Kitayama River, which once thrived as a forestry practice. The art of rafting has evolved over time, yet it continues to flow through the same picturesque landscapes, guided by the skilled paddling of the raft masters. During summer, tourists flock to this small village to experience the thrill of rafting down the rapids on log rafts. The raft masters navigate the river without the use of engines, skillfully reading the currents and utilizing the natural terrain to propel the rafts forward. This summer tradition has transformed from a forestry-based industry to a tourism attraction, offering a glimpse into Japan''s past while preserving the unchanged scenery, akin to a journey through time.' where id = '9kTDiJVTVR_8Xj_eZ5NbZ';
update content_bodies set title = '【360°VRで体験する】北山村の風景', description = '和歌山県北山村は、日本で唯一の飛び地の村であり、紀伊半島の山奥に位置する小さな村です。ここには、ユニークな魅力がたくさん詰まっています。北山川を丸太いかだで下る観光筏下りや、希少な柑橘「じゃばら」の原産地として知られています。また、秘境の美しい大自然の風景を楽しむことができます。VR映像を通じて、心が軽くなるような山間地の景色を体験してください。' where id = 'nhtpguq7ezJcj0OA8Es9Z';
update content_bodies set title = 'Experience the Scenery of Kitayama Village in 360° VR', description = 'Kitayama Village, located deep in the mountains of the Kii Peninsula in Wakayama Prefecture, is the only exclave village in Japan. Despite its small size, it is filled with unique attractions. Visitors can enjoy a scenic ride down the Kitayama River on a log raft, explore the origin of the rare citrus fruit ''Jabara,'' and take in the breathtaking natural landscapes of this hidden gem. Experience the lightness of the mountainous scenery through VR visuals.' where id = 'E53vbEr8bOv6BGtPBMScP';
update content_bodies set title = '【360°VRで体験する】北山川観光筏下り', description = '北山川観光筏下りは、浴びる水しぶきや迫る北山渓の岩肌、そして筏師の技術を体感できる360°VR映像体験です。全国で唯一の丸太筏に乗り、大自然の急流を下るこの体験は、まるで実際に乗船しているかのような臨場感を提供します。北山村の筏文化は貴重な文化資源として国内外で高く評価されており、美しい吉野熊野国立公園の自然と共に楽しむことができます。運航期間は5月3日から9月30日までです。' where id = 'XgynabeCDSyEndHR2kq4M';
update content_bodies set title = 'Experience Kitayama River Rafting in 360° VR', description = 'Experience the splashes of water, the looming cliffs of Kitayama Gorge, and the skilled techniques of the raft guides in this immersive VR experience. The ''Kitayama River Rafting'' offers a unique opportunity to ride on a log raft down the rapid currents of nature, making you feel as if you are truly on board. This rafting culture of Kitayama Village is highly regarded both domestically and internationally as a valuable cultural resource. Enjoy the stunning visuals of Yoshino-Kumano National Park alongside this traditional experience. The rafting operates from May 3 to September 30.' where id = '3duT6MsaM0kOpxzwB6dZA';
update content_bodies set title = '360° VR体験：和歌山の伝統的な丸太流し「いかだ下り」', description = '和歌山の「いかだ下り」を360度VR体験で楽しむことができます。視聴は10歳以上が対象で、通常の画面でも360度の景色を楽しめます。水しぶきや北山峡の壮大な岩の景観、伝統的なパドルを使って操る熟練のいかだ師の技を体感できます。この体験は、日本唯一の丸太流しの冒険であり、吉野熊野国立公園の美しい風景を背景に、全国的にも国際的にも評価されている北山村の豊かな文化を発見できます。運行シーズンは5月3日から9月30日までです。' where id = 'xQHY1fYefn1d26sVc8JpY';
update content_bodies set title = '360° VR Experience: Ikada-kudari, The traditional log rafting in Wakayama JAPAN.', description = 'Experience the unique log rafting adventure of Ikada-kudari in Wakayama, Japan, through an immersive 360-degree VR experience. Suitable for ages 10 and up, this experience allows you to feel the splashing water and witness the impressive rock formations of the Kitayama Gorge. You will be captivated by the skills of the raft masters as they navigate the Kitayama River using traditional paddles. This adventure showcases the rich cultural heritage of Kitayama Village, recognized both nationally and internationally, all set against the stunning backdrop of Yoshino-Kumano National Park. The rafting season runs from May 3 to September 30.' where id = 'qC3vIkslkf3F8I1ALXEls';
update content_bodies set title = '【360° VR体験】北山村、エンクレーブの村', description = '紀伊半島の山深くに位置する北山村は、日本唯一のエンクレーブ村であり、隠れた魅力に満ちた小さな村です。ここでは、伝統的な丸太の筏に乗って急流を下るスリリングなイカダ下りを体験できます。また、珍しい柑橘類であるジャバラの発祥の地でもあり、時に忘れられた美しい自然景観が広がっています。この没入型VR体験を通じて、日本の山の大自然の静かな美しさを感じ、心を癒すことができます。' where id = 'kYV1oaI6CV7w9c5M0YFmV';
update content_bodies set title = '360° VR Experience: Kitayama Village, The Enclave Village', description = 'Kitayama Village, located deep in the mountains of the Kii Peninsula, is Japan''s only enclave village, offering a unique and hidden experience. Visitors can enjoy the thrilling Ikada-Kudari log rafting, navigating the rapids on traditional log rafts. The village is also known as the birthplace of Jabara, a rare citrus fruit, and features stunning natural landscapes that remain untouched by time. This immersive VR experience allows you to explore the serene beauty of Japan''s mountain wilderness, providing a soothing escape into nature.' where id = 'H5X0GSmF8oM5OWv0-5vZ5';
update content_bodies set title = '北山川観光筏下り', description = '和歌山県北山村で楽しめる北山川観光筏下りは、日本で唯一、丸太を組んだ筏での川下り体験ができる場所です。この地域は、急激な地殻変動と北山川の浸食によって形成された標高差600mのV字峡谷が特徴です。ここにある付加体は、7000万年前に堆積した古い竜神付加体です。約30mの手作りの筏に乗り、600年の伝統を持つ筏師の技術を体験しながら、壮大な景色を楽しむことができます。特に、入り組んだ岩肌と激しい流れが織り成す景観は圧巻です。実施は5月の土日祝、6月の土日、7月から9月は木曜を除く毎日で、所要時間は約2時間（筏乗船時間約1時間10分）です。対象年齢は満10歳から満75歳までの健康な方です。' where id = 'MmRMaYS_1MDjHsZKViB7m';
update content_bodies set title = 'Kitanogawa River Rafting', description = 'Kitanogawa River in Kitayama Village, Wakayama Prefecture, offers a unique experience of rafting on a log raft, the only place in Japan where this is possible. The region features a V-shaped gorge with a height difference of 600 meters, formed by the rapid uplift of the land and the river''s erosion. The geological formations here are part of the ancient Ryujin accretionary complex, dating back 70 million years. Visitors can enjoy the breathtaking scenery while riding a traditional 30-meter-long raft, handcrafted by skilled raft masters who have passed down their techniques for 600 years. Experience the stunning views of intricate rock formations and swift currents while engaging in this unique water activity. Rafting is available on weekends and holidays in May, weekends in June, and daily (except Thursdays) from July to September. The activity lasts about 2 hours, with approximately 1 hour and 10 minutes spent on the raft. It is suitable for healthy individuals aged 10 to 75.' where id = 'u1jwKxKzToonG5Gt0I-FA';
update content_bodies set title = '鳥羽に温泉があって本当によかった（ロングVer)', description = '鳥羽温泉郷は、海女たちが漁の疲れを癒すための場所です。フォトグラファーの大野愛子さんは、真冬のナマコ漁で冷えた身体を鳥羽の温泉が温めてくれたと感謝の気持ちを表しました。三重県鳥羽の海は、伊勢湾と黒潮の潮流が交わり、アワビやサザエ、海藻などの豊かな生態系を形成しています。高齢化が進む中でも、海女たちは元気に漁に出ており、持続可能な漁業を守るための約束事を守っています。彼女たちの疲れた身体を癒すのは、海女小屋と鳥羽の温泉です。この地は、海女たちを支えるだけでなく、訪れる人々にも癒しを提供する場所となるでしょう。新たな文化「海女の湯治場」を紹介する映像もあります。' where id = 'H0XPdGt_iNmwoKFeiVkMZ';
update content_bodies set title = 'Glad There is a Hot Spring in Toba (Long Version)', description = 'The Toba Onsen area serves as a healing place for ama divers, who often endure the cold while fishing. Photographer Aiko Ohno expressed her gratitude for the hot springs in Toba, stating that they helped warm her frozen body after a winter sea cucumber dive. The waters of Toba, located in Mie Prefecture, are rich in marine life due to the complex currents of Ise Bay and the Kuroshio Current, providing a habitat for abalone, turban shells, and seaweed. Despite the aging population of ama divers, they continue to fish with vigor, adhering to traditions that ensure sustainable practices. The hot springs and ama huts play a crucial role in warming and rejuvenating these divers. This unique intersection of the sea and hot springs not only supports the ama but also offers healing to visitors, introducing a new cultural experience in Toba known as the ''Ama Healing Place.''' where id = 'fpeuEKQGj8CMxxup-c6GY';
update content_bodies set title = '鳥羽に温泉があって本当によかった！', description = '鳥羽温泉郷は、海女たちの疲れを癒す場所として知られています。フォトグラファーの大野愛子さんは、「真冬のナマコ漁で冷え切った身体を鳥羽の温泉が癒してくれた。鳥羽に温泉があって本当に良かった！」と語ります。三重県鳥羽の海は、伊勢湾と黒潮の潮流が交わり、アワビやサザエ、海藻の豊かな生息地を提供しています。高齢化が進む中でも、海女たちは伝統を守りながら活き活きと漁に出ています。彼女たちの冷えた身体を温め、疲れを癒すのが海女小屋と鳥羽の温泉です。この地は、海女たちを支える存在であり、訪れる人々にも癒しを提供する場所です。鳥羽の新たな文化「海女の湯治場」を紹介する映像です。' where id = 'H6BwQtS5RO_vewe9YKnnf';
update content_bodies set title = 'I''m Really Glad There''s a Hot Spring in Toba!', description = 'Toba Onsen, known as the healing place for ama divers, offers a sanctuary for those who work hard in the sea. Photographer Aiko Ohno shares her experience, stating, ''The hot springs in Toba warmed my chilled body after a winter sea cucumber dive. I''m truly grateful for the hot springs in Toba!'' The region, located in Mie Prefecture, is rich in marine life due to the complex currents of Ise Bay and the Kuroshio Current, providing a habitat for abalone, turban shells, and seaweed. Despite the aging population of ama divers, they continue to dive with vigor, adhering to traditions that ensure sustainable fishing. The hot springs and ama huts serve as a source of warmth and relaxation for these divers, embodying the essence of ''ama''s healing place.'' This video introduces the new culture of ''ama''s healing place'' in Toba, which not only supports the divers but also offers healing to visitors.' where id = '2pxDv1tXPHo0_R0nfmmpt';
update content_bodies set title = '鳥羽に温泉があって本当によかった！ （1分Ver.)', description = '「海女の湯治場、鳥羽温泉郷」は、海女たちが漁の疲れを癒すための場所です。フォトグラファーの大野愛子さんは、「真冬のナマコ漁で冷え切った身体を鳥羽の温泉が癒してくれた。鳥羽に温泉があって本当に良かった！」と語ります。三重県鳥羽の海は、伊勢湾と黒潮の潮流が交わり、アワビやサザエ、海藻の豊かな生息地となっています。海女たちは、資源を守るための約束を守りながら漁を行っています。若い担い手が減少し高齢化が進む中でも、彼女たちは生き生きと漁に出ています。冷えた身体を温め、疲れを癒すのは海女小屋と鳥羽の温泉です。この地は、海女たちを癒すだけでなく、訪れる人々にも癒しを提供する場所です。「海女の湯治場」という新たな文化を紹介する映像が公開されています。' where id = 'oVbe6vf76GYAtbzEyctbv';
update content_bodies set title = 'I''m Really Glad There''s a Hot Spring in Toba! (1-Minute Version)', description = 'The Toba Onsen area is a healing place for ama divers. Photographer Aiko Ohno shared her experience, stating, "The hot springs in Toba warmed my frozen body after a winter sea cucumber dive. I''m truly grateful for the hot springs in Toba!" The waters of Toba, located in Mie Prefecture, are rich in marine life due to the complex currents of Ise Bay and the Kuroshio Current, providing a habitat for abalone, turban shells, and seaweed. Ama divers, who dive into the sea to gather these resources, have adhered to many promises to ensure sustainable fishing practices. Despite the aging population and decreasing number of young divers, they continue to dive with vitality. The ama huts and Toba''s hot springs serve to warm and heal their tired bodies, embodying the essence of a "healing place for ama divers." This region, where the sea and hot springs meet, is not only a source of healing for the divers but also for visitors to Toba. The video introduces the new culture of "healing places for ama divers."' where id = 'GiLNycs_iERKkmfirymWq';
