update content_bodies set title = '鳥羽温泉郷　安楽島エリア', description = 'この動画では、鳥羽温泉郷の安楽島エリアについて紹介しています。安楽島は、温泉と自然が調和した美しい場所で、訪れる人々にリラックスしたひとときを提供します。温泉の効能や周辺の観光スポットについても触れられており、観光客にとって魅力的な情報が満載です。' where id = 'YuJArj02GIRk8p1Mcnkoe';
