update content_bodies set title = '鳥羽温泉郷　答志島エリア', description = '伊勢湾最大の離島である答志島には、3軒の温泉宿があり、九鬼水軍を率いた九鬼嘉隆の首塚や胴塚、太平洋の絶景を楽しめる希望の丘などの散策スポットが点在しています。特に、2～4月頃には和具浦漁港での塩ワカメ作りの風景が見られ、この島の風物詩となっています。また、答志島と菅島で水揚げされる一本釣りの鰆の中でも、秋と冬に獲れた脂肪分の高いものが「答志島トロさわら」としてブランド化されています。' where id = 'EElqq8IDu6DvwRhr7YKWh';
update content_bodies set title = 'Toba Onsen District - Toshijima Area', description = 'Toshijima is the largest offshore island in Ise Bay, featuring three hot spring inns. The island is home to various sightseeing spots, including the tombs of Kuki Yoshitaka, who led the Kuki navy, and Kibo Hill, which offers stunning views of the Pacific Ocean. From February to April, visitors can enjoy the traditional sight of salt-wakame seaweed production at Waguura Fishing Port. Additionally, the high-fat ''Toshijima Toro Sawara,'' a brand of Spanish mackerel caught by pole-and-line fishing in Toshijima and Sugashima during autumn and winter, is also notable.' where id = 'beGIlevXxi8tIThv369Qt';
update content_bodies set title = '鳥羽温泉郷　相差エリア', description = '三重県の伊勢志摩国立公園に位置する鳥羽市の相差エリアは、南鳥羽で最も人口が集まる海女と漁師の港町です。ここには17の温泉宿があり、現役の海女さんの話を聞きながら新鮮な魚貝類を楽しむ海女小屋体験ができます。また、「女性の願い事なら必ず一つは叶えてくれる」と言われる神明神社の参道にある石神さんなど、人気のスポットも訪れることができます。' where id = '6PxP_tkdLRUyKXvFb6oN0';
update content_bodies set title = 'Toba Onsen District - Ousatsu Area', description = 'Located in Mie Prefecture''s Ise-Shima National Park, Toba City features the Ousatsu area, a bustling port town known for its ama (female divers) and fishermen. This area has 17 hot spring inns and offers unique experiences such as listening to stories from active ama while enjoying fresh seafood at ama huts. Visitors can also explore popular spots like the Shinto shrine, Ishigami-san, located along the path to Shinmei Shrine, which is said to grant at least one wish for women.' where id = 'qlyHpGKUD5t6jZ_SbZ6RI';
update content_bodies set title = '飛騨千光寺の住職大円大志田インタビュー [日本語版]', description = '飛騨千光寺は、1600年前に仁徳天皇によって創建された古代の仏教寺院で、飛騨族が二面宿（両面宿名）を開いた際に設立されました。このインタビューでは、現住職の大円木下氏がコロナ時代における寺院の状況について語ります。このインタビューは飛騨神宝自然人クラブの企画で、動画制作はQPJ株式会社が担当しました。詳細については、飛騨千光寺のウェブサイトを訪れるか、QPJ株式会社のSNSをフォローしてください。' where id = '6CDAvBF2lB-42fHDTTvll';
update content_bodies set title = 'Hida Senkou-ji Temple Chief Priest Daien Oshita interview [English Ver.]', description = 'Hida Senkou-ji Temple, established 1600 years ago by Emperor Nintoku, is an ancient Buddhist temple that originated when the Hida tribe opened a double-sided inn. In this interview, the current chief priest, Daien Kinoshita, discusses the temple''s situation during the Corona era. The planning for this interview was done by the Hida Kamitakara Shizenjin Club, and the video was produced by QPJ Inc. For more information, you can visit the Hida Senko-ji website or follow QPJ Inc. on social media.' where id = 'Ejz06BZF4G2xWrXe2wyfk';
update content_bodies set title = 'フェリーでボンボヤージュ！', description = 'フェリーでボンボヤージュは、鹿児島と奄美の島々、沖縄を結ぶ魅力的な船旅です。美しいエメラルドグリーンの海、神秘的な緑の森や山々、育まれた文化や美味しい食事、そして心温まる人々との出会いが待っています。この奄美の島々を巡るフェリーの旅は、特別な思い出をあなたの心に刻むことでしょう。ゆったりと流れる島時間を楽しみながら、素晴らしい体験をお楽しみください。詳細は公式サイトやインスタグラムをご覧ください。' where id = 'wL8fvkYT80AAErcENE9ap';
update content_bodies set title = 'Ferry de Bon Voyage - A Journey Connecting the Amami Islands', description = 'Experience an exciting ferry journey that connects Kagoshima with the beautiful Amami Islands and Okinawa. This voyage offers stunning emerald green seas, lush green forests and mountains, rich culture, delicious food, and the warm hospitality of the local people. The ferry trip through the Amami Islands will create unforgettable memories, allowing you to enjoy the relaxed island time. For more information, visit the official site and Instagram.' where id = 'PvPWg85mJjYxWP3YuIX5L';
update content_bodies set title = 'フェリーでボンボヤージュ！', description = 'フェリーでボンボヤージュは、鹿児島と奄美の島々、沖縄を結ぶ魅力的な船旅です。美しいエメラルドグリーンの海、神秘的な緑の森や山々、豊かな文化と美味しい食事、そしてゆったりとした島時間を過ごす心優しい人々が、特別な思い出を刻みます。このフェリーサービスは、奄美群島航空・航路運賃軽減協議会と鹿児島県旅客船協会が企画・監修し、奄美海運株式会社、マリックスライン株式会社、マルエーフェリー株式会社が協力しています。素晴らしい船旅をお楽しみください！' where id = '3Xc7at9pVkXffb_C_S-eG';
update content_bodies set title = 'Ferry de Bon Voyage - A Journey Connecting the Amami Islands', description = 'Experience an exciting ferry journey that connects Kagoshima with the beautiful Amami Islands and Okinawa. This voyage offers stunning emerald green seas, lush forests, and mountains, along with rich culture and delicious cuisine. The relaxed island time and warm-hearted locals will create unforgettable memories during your trip. The ferry service is organized by the Amami Islands Air and Route Fare Reduction Council and the Kagoshima Passenger Ship Association, with cooperation from Amami Shipping Co., Marix Line Co., and Marue Ferry Co. Enjoy your journey!' where id = '2QSYME-SqF2zFMpsQY31z';
update content_bodies set title = '神秘の島々を巡る喜界航路', description = '喜界航路は鹿児島と喜界島、奄美大島、徳之島、沖永良部を結ぶ航路です。ここでは、夢のような景色や都会では味わえない文化、体験に出会えます。リラックスした時間を過ごし、心温まる出会いを通じて、人生において意味のある絆を築くことができます。フェリーで日本の南の島々の楽園を旅し、忘れられない思い出を持ち帰りましょう。' where id = 'gOfAQczQTH_NxZCDPjK1C';
update content_bodies set title = 'Explore Secret Paradise on the Kikai Ferry Route', description = 'The Kikai Island ferry route connects Kagoshima with Kikai Island, Amami Oshima Island, Tokunoshima, and Okinoerabu Island. Travelers can expect to encounter dream-like landscapes and unique cultural experiences that are absent in urban settings. This journey offers a chance to relax and create meaningful connections that can last a lifetime. Experience the beauty of Japan''s southern island paradise by ferry and return home with unforgettable memories.' where id = 'jB45AFglSCbeiQe9IerDf';
update content_bodies set title = '奄美の島々を巡るフェリーの旅-チュートリアル編', description = 'この公式ガイドでは、鹿児島と奄美の島々、沖縄を結ぶ魅力的なフェリーの旅を紹介しています。この旅では、美しい島々を巡りながら、心に残る思い出を作ることができます。企画・監修は奄美群島航空・航路運賃軽減協議会と鹿児島県旅客船協会が行い、奄美海運株式会社、マリックスライン株式会社、マルエーフェリー株式会社の協力を得ています。詳細は公式サイトやインスタグラムをご覧ください。' where id = 'WxbzuOrxxO67TUzO13anW';
update content_bodies set title = 'Ferry Travel to the Amami Islands - INTRO GUIDE', description = 'This official guide introduces an exciting ferry journey connecting Kagoshima with the Amami Islands and Okinawa. The voyage offers a chance to explore beautiful islands, creating unforgettable memories in Japan. The project is overseen by the Amami Islands Air and Ferry Fare Reduction Council and the Kagoshima Passenger Ship Association, with cooperation from Amami Shipping Co., Marix Line Co., and Marue Ferry Co. For more information, visit the official website and Instagram.' where id = 'F5lOeWSvFeLyaqKluFmMK';
update content_bodies set title = 'まだまだ魅力たっぷり、えびの市', description = 'えびの市の観光PRを担当するみなほです。新しい動画第3弾の公開をお知らせします！この動画では、えびの市の冬の美しい景色を集め、その魅力を紹介しています。ぜひご覧ください！動画には、矢岳高原、菅原神社（水流地区）、めがね橋（月の木川橋）、陣の池（小池・大池）、えびの高原などの場所が登場します。' where id = 'lregJnuSpeGYb2EapswqX';
update content_bodies set title = 'Ebino City: Still Full of Charm', description = 'This is a tourism promotion for Ebino City, presented by Minaho. We are excited to announce the release of our new video, the third installment! This video showcases the beautiful winter scenery of Ebino City, capturing its many attractions. We invite you to watch it! The video features locations such as Yadake Highland, Sugawara Shrine (Suiru District), Megane Bridge (Tsuki no Ki River Bridge), Jin Pond (Small Pond and Large Pond), and Ebino Highland.' where id = '6U8CSwywpkL1jX_f0ai0T';
update content_bodies set title = '真冬の飛騨 平湯大滝', description = '飛騨高山の冬の風景を体験できます。平湯大滝の水さえも凍りつく氷点下の世界で、自然の美しさを感じることができます。このVR体験では、氷の世界に没入し、厳しい寒さの中での自然の魅力を楽しむことができます。' where id = 'hbkIixXr-Ti3-B16uYdfd';
update content_bodies set title = 'Midwinter HIDA - Hirayu Waterfall VR', description = 'Experience the winter in Hida Takayama, where the temperatures drop below freezing, causing even the water of Hirayu Waterfall to freeze. This VR experience immerses you in a stunning world of ice, showcasing the beauty of nature in its coldest form.' where id = 'c6C7WKgLz0oSYmyl-4gZ5';
update content_bodies set title = '飛騨高山グルメ3傑', description = '岐阜の小京都、飛騨高山の隠れた名店3軒を紹介します。まずは「TEPPAN たなか」。目の前で焼かれるA5等級の飛騨牛ステーキは、五感で楽しむことができる最高のご馳走です。次に「オーベルジュ飛騨の森」。緑に囲まれた静かな隠れ家で、厳選された季節の食材を使ったシェフ自慢のイタリアンと自然派ワインを堪能できます。最後に「ゲストハウス&カフェSOY」。築100年を超える古民家を再生したこのゲストハウスでは、醤油や味噌、納豆、豆腐などの発酵食品を使った素朴な料理が楽しめます。飛騨高山に行った際は、ぜひこの3店舗を訪れてみてください！' where id = 'tH8X3qOIbC2bpIEZ13BnN';
update content_bodies set title = 'Three Culinary Gems of Hida Takayama', description = 'Discover three hidden culinary gems in Hida Takayama, often referred to as the Little Kyoto of Gifu. First is ''TEPPAN Tanaka'', where you can savor A5 grade Hida beef steak cooked right before your eyes, offering a delightful sensory experience. Next is ''Auberge Hidano no Mori'', a serene hideaway surrounded by nature, where you can enjoy exquisite Italian dishes and natural wines made from carefully selected seasonal ingredients. Lastly, ''Guesthouse & Cafe SOY'' is a guesthouse created from a 100-year-old folk house, focusing on traditional Japanese fermented foods like soy sauce, miso, natto, and tofu, all based on the concept of soybeans. If you visit Hida Takayama, be sure to check out these three establishments!' where id = 'I5qHY-wLkwUutvL8bHpaG';
update content_bodies set title = '初秋＿白川郷', description = '世界遺産である飛騨白川郷の初秋の美しさを体験できます。この映像では、伝統的な合掌造りの建物と澄んだ秋空との見事なコントラストが紹介されています。この地域でドローンを飛ばすには特別な許可が必要なため、ガイドツアーを利用することが推奨されます。企画は（株）飛騨上宝自然人倶楽部が行い、映像制作は（株）QPJが担当しています。詳細については、提供されたリンクから各社のウェブサイトやSNSをご覧ください。' where id = 'imZtlNrP6pk2IPL-_6gr8';
update content_bodies set title = 'Early Autumn in Hida Shirakawa-go', description = 'Experience the beauty of early autumn in Hida Shirakawa-go, a UNESCO World Heritage Site. This video showcases the stunning contrast between the traditional gassho-zukuri architecture and the clear autumn skies. Special permissions are required for drone flights in this area, so it''s advisable to utilize guided tours for such experiences. The project is produced by Hida Kamitakara Shizenjin Club Co., Ltd., with video production by QPJ Inc. For more information, visit the provided links to their websites and social media.' where id = 'freCvPsvZL69UoaZtM77V';
update content_bodies set title = '飛騨高山まんま農場 稲刈り ドローン', description = '飛騨高山上宝に位置する「まんま農場」の秋の収穫の様子をお届けします。ドローンを使って収穫の様子を観察すると、農場は秋のアースカラーで美しく彩られています。' where id = 'D7h-wQVnWdNjRBNoqPNGQ';
update content_bodies set title = 'Hida Takayama Manma Farm Rice Harvesting with Drone', description = 'This video showcases the autumn harvest at ''Manma Farm'' located in Hida Takayama Kamitakara. The harvesting process is viewed from a drone, revealing the farm''s landscape beautifully adorned in autumn earth tones.' where id = 'XgNoIUOZbWHzsNB1v1uRW';
update content_bodies set title = '元乃隅稲成神社', description = '1955年、地元の網元であった岡村斉さんの枕元に狐が現れ、『私をこの地に鎮祭せよ』と告げました。それ以来、元乃隅神社では狐を神使として祀っています。特に1987年から10年間にわたって奉納された123基の鳥居が海岸線に沿って並ぶ光景は圧巻で、多くの訪問者を惹きつけています。この神社は山陰地域の文化的な重要性を示す存在となっています。' where id = 'TohmSoIrZpA7BEziHmRb5';
update content_bodies set title = 'Motonosumi Inari - Shrine', description = 'In 1955, a fox appeared to Mr. Hitoshi Okamura, a local fisherman, and instructed him to establish a shrine in that location. Since then, Motonosumi Shrine has honored the fox as a deity. The shrine is renowned for its breathtaking sight of 123 torii gates, which were dedicated over a span of ten years starting in 1987, lining the coastline. This unique feature attracts many visitors and showcases the cultural significance of the shrine in the San''in region of Japan.' where id = 'D3ae060LeurNga5qEZbk8';
update content_bodies set title = '長浜神社 - 出雲の国の始まりを記した国引き神話の主役を祀る神社', description = '御祭神は八束水臣津野命で、国引き神話の主人公です。彼は出雲国を細長い布切れのように見て、国を小さく作り過ぎたと考え、国を大きくすることを決意しました。杵築の岬、狹田の国、闇見の国、美保の岬での四度の国引きを経て、国土を生成しました。八束水臣津野命は出雲国の総鎮守として長浜に祀られ、国を引き寄せ、人を引き寄せ、幸を引き寄せる偉大な神様として広く信仰されています。' where id = 'gGJDPyimqcX3c7zgM93jA';
update content_bodies set title = 'Nagahama Shrine - A Shrine Dedicated to the Hero of the Kunibiki Myth of Izumo', description = 'The enshrined deity is Yatsukamizuomitsunu no Mikoto, the protagonist of the Kunibiki myth. Long ago, he perceived Izumo Province as a narrow strip of land and decided to expand it. After four significant land-dragging events at Kiduki''s cape, Sada''s country, Kurami''s country, and Miho''s cape, he successfully created the land. Yatsukamizuomitsunu no Mikoto is revered as the general guardian of Izumo Province and the god of land dragging. He is widely worshiped as a great deity who attracts land, people, and happiness, as well as a god of victory.' where id = 'rDWmtfI_Lq576qIAVHl1d';
update content_bodies set title = '琵琶湖畔の突端に佇む寺院 伊崎寺', description = '伊崎寺は滋賀県近江八幡市の琵琶湖の湖畔に位置し、天台宗の三大聖地の一つとされています。この寺院は比叡山延暦寺の支院でもあり、毎年8月には「伊崎の棹飛」という行事が行われます。この行事は千年以上の歴史を持ち、行者が琵琶湖の絶壁から突き出た長さ13mの棹から7m下の水面に飛び込む伝統的なものです。初秋の近江八幡では、琵琶湖の美しい景観と伊崎寺の荘厳な雰囲気が広がっています。' where id = 'm0k3nILA8XZQCZKdSPovi';
update content_bodies set title = 'Isakiji, a temple standing at the tip of Lake Biwa', description = 'Isakiji is a temple located on the shores of Lake Biwa in Omihachiman City, Shiga Prefecture, recognized as one of the three major sanctuaries of the Tendai sect. This temple, a branch of Hieizan Enryakuji Temple, hosts an annual event called Saotobi of Isaki every August. This traditional event, which has a history of over 1000 years, involves a performer jumping into the water from a 13-meter long rod that extends 7 meters above the lake''s surface. In early autumn, the beautiful scenery of Lake Biwa complements the majestic atmosphere of Isakiji Temple.' where id = 'bBPVidqagFEmk_Vcxg31J';
update content_bodies set title = '【山形 - 東北 / 日本旅行】金山の道、百年の光', description = '山形県金山町は、2025年1月1日に町政100周年を迎えました。この100年間、町は変化と継続を経験し、山々や森、清流は時の流れを見守ってきました。この土地の神話的な生き物たちも、この世紀を見守っていたのかもしれません。人々が金山の歴史を振り返る中で、彼らはどんな風を感じ、どんな空を見上げているのでしょうか。2024年秋には、金山の100年を祝う「センテニアルフェスティバル」が開催され、金山の四季や変わりゆく町の風景、林業などの地元産業の歴史が紹介されました。また、町の人々の生活や言葉にも触れました。このお祝いは、感謝の気持ちを持って振り返り、希望を持って未来へ進むことを促しています。' where id = 'qXnlxJzP8FiczLoqxUrpf';
update content_bodies set title = 'Yamagata - Tohoku / Japan travel: The Kaneyama path, one hundred years of light', description = 'Kaneyama Town in Yamagata Prefecture celebrated its 100th anniversary of town administration on January 1, 2025. Over the past century, the town has experienced both change and continuity, with its mountains, forests, and rivers witnessing the passage of time. The local mythical creatures may have observed this century as well. As the community reflects on its history, they consider the winds and skies that have shaped their experiences. In autumn 2024, a ''Centennial Festival'' was held to honor this milestone, showcasing Kaneyama''s four seasons, its evolving landscape, and the history of local industries like forestry. The festival also highlighted the lives and stories of the town''s residents. This celebration invites everyone to look back with gratitude and forward with hope, carrying the light of a hundred years into the future.' where id = '7GTCCdyUTxKsgrkChnw_b';
update content_bodies set title = '山形ふるさとCM大賞2023', description = '第23回山形ふるさとCM大賞において、金山町が「手づくり部門賞」を受賞しました。今年度のテーマは「こころおどる冒険へ」で、神室ダム湖でのサップやカヤック体験、神室ファームでの乗馬体験、神室キャンプ場での非日常体験、神室山でのトレイルランニングや登山などをPRするCMを制作しました。CM制作に協力してくださった皆様、応援してくださった皆様に心から感謝申し上げます。' where id = 'wF9k_bxWR7tppTlMK2K-t';
update content_bodies set title = 'Yamagata - Tohoku / Japan travel: Yamagata Furusato CM Award 2023', description = 'At the 23rd Yamagata Furusato CM Award, hosted by Yamagata Television (YTS), Kaneyama Town won the ''Handmade Division Award''. This year''s theme was ''An Exciting Adventure'', promoting thrilling experiences such as stand-up paddleboarding and kayaking at Kamuro Dam Lake, horseback riding at Kamuro Farm, and unique experiences at Kamuro Campground, along with trail running and mountain climbing at Kamuro Mountain. The CM was created to showcase these exciting activities. We sincerely thank everyone who cooperated and supported us in the production of this CM.' where id = 'KcCMCvmBTOaKEzhoSEDJp';
update content_bodies set title = '【山形 - 東北 / 日本旅行】K-hourクリップ', description = '「K-hour映画」の総集編を公開しました。「K-hour」では金山の“暮らし”や“日常”を切り取り、訪れる人々に同じ日常を体験してもらうための動画を制作しています。金山町には、穏やかでゆっくりとした時間が流れ、訪れる人を温かく包み込みます。澄んだ空気や山の匂い、自然な笑顔が溢れ、日が暮れ、また昇ることで心をありのままに過ごす時間が生まれます。これまでの金山の四季を一つの作品にまとめました。これからも「金山の時間」を多くの方に見て感じてもらえれば嬉しいです。' where id = 'dDNVlNNcfFkbjOn6AAl1O';
update content_bodies set title = 'Yamagata - Tohoku / Japan travel K-hour clips', description = 'The K-hour movie compilation has been released. K-hour captures the ''lifestyle'' and ''daily life'' in Kaneyama, allowing visitors to experience the same daily moments. Kaneyama has a unique flow of time that is gentle and slow, enveloping visitors warmly. The clear air, the scent of the mountains, and the natural smiles create a serene atmosphere. As the day fades, it embraces daily activities, only to rise again, illuminating the day. This compilation showcases the essence of Kaneyama''s seasons. We hope more people can see and feel the ongoing ''time of Kaneyama.''' where id = 'B75A_0VCWtdw8FGQ5SAQ6';
update content_bodies set title = '【山形県金山町】2018山形ふるさとCM大賞「スギタ家の朝」', description = '株式会社山形テレビ（YTS）が主催する「第19回山形ふるさとCM大賞」に提出された作品です。この作品は金山町として初めて「優秀賞」を受賞しました。' where id = 'DflEi17mXdqbZ0-dduuwE';
update content_bodies set title = 'Kaneyama Town, Yamagata Prefecture: 2018 Yamagata Hometown CM Award ''Sugita Family''s Morning''', description = 'This is a submission for the 19th Yamagata Hometown CM Award organized by Yamagata Television (YTS). It is the first time Kaneyama Town has received the ''Excellence Award''.' where id = 'dpi-_m03aL4xmTIymTP_L';
update content_bodies set title = '山形ふるさとCM大賞2024　山形県金山町', description = '株式会社山形テレビ（YTS）が主催する「第24回山形ふるさとCM大賞」において、金山町が「特別賞」（プレゼン賞）を受賞しました。今年度は金山町町制施行100周年をテーマに、金山町の魅力を集めたPRCMを制作しました。この作品は「金山らしさが表現されていたこと」や「佐藤町長のプレゼンと登壇者のチームワーク」が高く評価され、受賞に至りました。応援してくださった皆様、誠にありがとうございました。' where id = 'jr0INWZrQKV8HzCDVT7qq';
update content_bodies set title = 'Yamagata Hometown CM Award 2024 - Kaneyama Town', description = 'Kaneyama Town received the ''Special Award'' (Presentation Award) at the 24th Yamagata Hometown CM Award, organized by Yamagata Television (YTS). This year''s entry was themed around the 100th anniversary of Kaneyama Town''s municipal establishment, showcasing the town''s charm through a promotional video. The work was highly praised for its expression of ''Kaneyama''s uniqueness'' and the teamwork displayed during Mayor Sato''s presentation, leading to the award. We sincerely thank everyone who supported us.' where id = 'QuYPLpcEbu_eCxHYzps33';
update content_bodies set title = '飛騨の里 保護猫センター 「にゃんLiving」 五十嵐 浩子　インタビュー', description = '飛騨の里で動物愛護活動を行う五十嵐浩子さんは、活動に関わる人々の負担を軽減する仕組み作りが必要だと感じ、「にゃんLiving」を設立しました。このインタビューでは、彼女の思いや取り組みについて詳しく紹介しています。保護猫の福祉を支えるための彼女の活動がどのように展開されているのかを探ります。' where id = '7RZ3xqqnbdGd25hlO4yU0';
update content_bodies set title = 'Hida no Sato Cat Protection Center ''Nyan Living'' Interview with Hiroko Igarashi', description = 'Hiroko Igarashi, the representative of ''Nyan Living'', created this cat protection center in Hida no Sato with the aim of reducing the burden on those involved in animal welfare activities. The interview explores her motivations and the initiatives she has implemented to support the welfare of stray and abandoned cats.' where id = '9KhcP8mJfxaMRSWUAlWvN';
update content_bodies set title = '岡山県北　森の芸術', description = '2024年9月28日から11月24日まで開催された「森の芸術祭・岡山」では、イベント終了後も一部のアート作品が常設展示され、訪れる人々を魅了し続けています。この動画では、アート作品とその周辺の観光スポットを紹介し、芸術と自然が織りなす特別な空間で岡山の新たな魅力を発見することを提案しています。常設展示には、奥津振興センターの「山に響くこだま」や、津山国際ホテルの「津山ピンポン広場」、新見図書館の「スタンダードカラー2024」、勝山町並み保存地区の「あしあと」、奈義町現代美術館の「未来のための宇宙論」などがあります。' where id = 'cj27R5EGm9oNsfutj73HS';
update content_bodies set title = 'The Forest Of The Arts Northern OKAYAMA', description = 'The ''Forest Art Festival Okayama'' was held from September 28 to November 24, 2024. After the event, some of the art pieces continue to be displayed permanently, captivating visitors. This video introduces the art works and nearby tourist spots, inviting you to discover the new charm of Okayama in a unique space where art and nature intertwine.' where id = 'YTICDGsVLWCjfi-2hDHde';
update content_bodies set title = 'おかやま日本遺産探訪7つのストーリーを巡る旅', description = '岡山県内の7つの日本遺産を魅力的な動画で紹介し、古のストーリーを疑似体感しながら地域の歴史や文化に触れる旅です。備前市の「旧閑谷学校」は1670年に設立された日本初の庶民のための公立学校で、国宝の講堂などが見どころです。倉敷は水運で栄え、和と洋の技術が融合した繊維産業が発展しました。備前焼は日本六古窯の一つで、シンプルな技法が特徴です。玉島・下津井地区は江戸時代に北前船の寄港地として発展し、独特の町並みが形成されました。また、桃太郎伝説に関連する古代遺跡も残っています。瀬戸内備讃諸島の花崗岩は日本の建築文化を支え、吹屋は弁柄と銅の生産で栄えた町です。これらの物語は、訪れる人々を地域の魅力へと誘います。' where id = 'iQiePOD8_EwA8fV7_a4GN';
update content_bodies set title = 'Exploring Okayama''s 7 Stories of Japan Heritage', description = 'This video guide takes you through seven sites of Japan Heritage in Okayama Prefecture, allowing you to experience ancient stories that transcend time. Each site reveals the region''s rich history and culture. Highlights include the ''Old Kanta School'' in Bizen City, Japan''s first public school for commoners, established in 1670. The textile town of Kurashiki flourished as a hub for goods, blending traditional Japanese and Western techniques. Bizen pottery, one of Japan''s six ancient kilns, showcases a unique, simple style. The port town of Tamashima thrived during the Edo period, trading goods like cotton and herring. Okayama is also known for the legend of Momotaro, with ancient ruins linked to this tale. The Setouchi Bisan Islands contributed to Japan''s architectural culture with their granite. Lastly, Bichu Buke, a former mining town, is famous for producing the red pigment ''Bengara,'' which has colored many traditional crafts. Each story invites visitors to delve into the region''s heritage.' where id = '4aIs26J0M8FdwVbFRJFus';
update content_bodies set title = '【岡山後楽園・岡山城】フォトコンテスト入賞作品を動画で紹介！', description = '日本三名園の一つである岡山後楽園と岡山城の魅力を発信するため、令和3年秋に開催された「マイベスト岡山後楽園・岡山城フォトコンテスト」の入賞作品を紹介する動画です。四季折々の美しい写真を楽しむことができ、昼間の風景だけでなく、夜間のライトアップイベント「幻想庭園」や「烏城灯源郷」の様子も収められています。現在、岡山城は大規模改修工事中ですが、今年の11月3日にリニューアルオープン予定です。新しく生まれ変わる岡山城にも期待が高まります。' where id = 'Hu8SaBMBgUsHho6O7xl_M';
update content_bodies set title = 'Introducing Award-Winning Works from the Okayama Korakuen and Okayama Castle Photo Contest!', description = 'This video showcases the award-winning entries from the ''My Best Okayama Korakuen and Okayama Castle Photo Contest'' held in the autumn of 2021, aimed at promoting the beauty of Okayama Korakuen, one of Japan''s three great gardens, and the majestic Okayama Castle. Enjoy stunning seasonal shots, including various landscapes from daytime and nighttime events like the ''Fantasy Garden'' and ''Ujo Lantern Festival.'' Currently, Okayama Castle is closed for major renovations but is set to reopen on November 3rd this year. Look forward to the renewed Okayama Castle!' where id = 'rh_asfswajvZpgQDobJ2L';
update content_bodies set title = '岡山の旅なら叶う！ 贅沢＆美味な果物時間【full ver.】', description = '晴れの国岡山は美味しい果物の産地として知られ、特に白桃やぶどうは全国的に有名です。夏から秋にかけての旬の時期には、岡山の“くだもの王国”としての魅力が最大限に発揮されます。果樹農園での収穫体験や、街の店舗での絶品フルーツメニューを楽しむことができ、贅沢で美味しい時間が待っています。次の旅は岡山で決まりです！' where id = 'S849ECKM5ryNZMC05erpG';
update content_bodies set title = 'Experience Luxury and Delicious Fruit Time in Okayama! [full ver.]', description = 'Okayama, known as the ''Sunny Country,'' is also a land of delicious fruits, particularly renowned for its white peaches and grapes, which have some of the highest production rates in Japan. From summer to autumn, during the peak season, Okayama showcases its reputation as the ''Fruit Kingdom.'' Visitors can enjoy fruit-picking experiences at orchards and discover exquisite fruit dishes at local shops, promising a luxurious and delightful time. So, make your next trip to Okayama!' where id = 'jky6rRbxTSpMiZHlZyR8P';
update content_bodies set title = '岡山県玉野市VP　観光篇', description = '岡山県玉野市に関する自主制作番組で、平成27年12月に制作されました。' where id = 'PHCTqCGjuvPWlJ6JvnZUs';
update content_bodies set title = 'Tamano City, Okayama Prefecture - Tourism Edition', description = 'This is a self-produced program about Tamano City in Okayama Prefecture, created in December 2015.' where id = 't61Sow6F6eRB4ARRlkdPm';
update content_bodies set title = '岡山県観光プロモーション動画「こころ晴ればれおかやまの旅」【公式】', description = 'このプロモーション動画では、岡山県内の四季折々の見どころや観光スポットを、タイムラプスやハイパーラプス、空撮といった最新の撮影技法を駆使して紹介しています。新たな視点から岡山の魅力を伝える内容となっており、観光客にとって興味深い映像が楽しめます。' where id = 'rDdYsfsoca6vflzo_0bR8';
update content_bodies set title = 'Okayama Prefecture Tourism Promotion Video ''Kokoro Harebare Okayama no Tabi'' [Official]', description = 'The promotional video showcases the seasonal attractions and sightseeing spots in Okayama Prefecture using advanced filming techniques such as time-lapse, hyper-lapse, and aerial shots, providing a fresh perspective on the region.' where id = '2khVWDDeCUQN4onWI0rns';
update content_bodies set title = '岡山県の離島の魅力', description = '穏やかな瀬戸内海に浮かぶ岡山の離島では、マリンスポーツやハイキング、サイクリング、島グルメなど多彩なアクティビティが楽しめます。豊かな自然と美しい景色に囲まれ、特別な島時間を体験することができます。瀬戸内の島々でしか味わえない魅力をぜひ体感してください。' where id = 'eumPMuH58CzrR0ZD5GpEw';
update content_bodies set title = 'The Charm of Okayama''s Islands', description = 'Okayama''s islands, floating in the calm Seto Inland Sea, offer a variety of activities such as marine sports, hiking, cycling, and island cuisine. Surrounded by rich nature and beautiful scenery, visitors can enjoy the unique island time experience. Discover the special moments that can only be found on the islands of Setouchi.' where id = 'kprPkdgEEpKnPynrhS3sp';
update content_bodies set title = '【1日目】2泊3日で周遊！岡山を味わい尽くす女子二人旅', description = '岡山県の魅力をどれだけ知っていますか？多くの人が倉敷の美しい街並みを思い浮かべるでしょうが、それだけではありません！この旅では、蒜山高原の大自然、歴史ある湯原温泉、恋人たちの聖地・黒島ヴィーナスロードなど、岡山の多様な魅力を紹介します。2泊3日の女子二人旅では、蒜山高原や真庭市の勝山、湯原温泉を訪れ、地元の美味しい料理や文化体験を楽しむことができます。岡山の隠れた魅力を発見し、思い出に残る旅を満喫しましょう。' where id = 'm24U9pekzY4tW_UycT8q3';
update content_bodies set title = 'Day 1: A 2-Night, 3-Day Tour! Enjoying Okayama with a Girlfriend', description = 'How much do you know about the charms of Okayama Prefecture? Many might recall the beautiful streets of Kurashiki, but there''s so much more! This trip highlights the refreshing natural beauty of Hiruzensei Plateau, the historic hot spring town of Yubara Onsen, and the romantic Kuroshima Venus Road, among other attractions. This 2-night, 3-day journey is designed for two women to fully experience the diverse attractions of Okayama. The itinerary includes visits to Hiruzensei Plateau, Maniwa City’s Katsu-yama, and Yubara Onsen, featuring local delicacies and cultural experiences. Discover the hidden gems of Okayama, from scenic landscapes to delicious cuisine, all while enjoying a memorable getaway.' where id = 'DGVZ7F2QnPFoiocodJNJ7';
update content_bodies set title = '【2日目】2泊3日で周遊！岡山を味わい尽くす女子二人旅', description = '岡山県の魅力をどれだけ知っていますか？多くの人が倉敷の美しい街並みを思い浮かべるでしょうが、それだけではありません！この旅では、蒜山高原の大自然、歴史ある湯原温泉、恋人たちの聖地・黒島ヴィーナスロードなど、岡山の多様な魅力を2泊3日で体験します。周遊エリアには、蒜山、勝山、湯原、倉敷、牛窓、備前などが含まれます。2日目は、湯原温泉での足湯体験や、倉敷美観地区の散策、伝統的なお菓子作りや季節のフルーツパフェを楽しむなど、地元の魅力を満喫します。また、ホテルグランヴィア岡山に宿泊し、地元の寿司店での食事も楽しめます。' where id = '0PAQqIDF6_Jq7IfDqGzeN';
update content_bodies set title = 'Day 2: A 2-Night, 3-Day Trip to Experience Okayama', description = 'How much do you know about the charms of Okayama Prefecture? Many might recall the beautiful streets of Kurashiki, but there''s so much more! This trip highlights the refreshing nature of Hiruzensei Plateau, the historic hot spring town of Yubara Onsen, and the romantic Kuroshima Venus Road, among other attractions. This itinerary for two women explores the diverse attractions of Okayama over two nights and three days, including areas like Hiruzensei, Katsuyama, Yubara, Kurashiki, Ushimado, and Bizen. Day 2 features visits to Yubara Onsen for foot baths, the scenic Kurashiki Bikan Historical Area, and various local experiences such as making traditional sweets and enjoying seasonal fruit parfaits. The trip also includes stays at Hotel Granvia Okayama and dining at local sushi restaurants.' where id = 'ndff4_F_uG4GyRdddC4cn';
update content_bodies set title = 'スリルと冒険！感動と驚きの山乗渓谷リバートレッキング（真庭市）【岡山観光WEB】', description = '岡山県で話題の体験やツアーを厳選して紹介しています。臨場感あふれる体験レポートや、予約・申込みに関する情報も掲載されています。' where id = '-s9ckd4A5MFHjdVdK12s_';
update content_bodies set title = 'Thrills and Adventure! Exciting River Trekking in Yamano Valley (Maniwa City)【Okayama Tourism WEB】', description = 'Discover the latest trending experiences and tours in Okayama Prefecture! This includes immersive experience reports along with information on reservations and applications.' where id = 'vUdQmBtQ3IRkhU1xKt3tB';
update content_bodies set title = '晴れの国おかやまで体験！', description = '岡山県では、瀬戸内海でのシーカヤックや漁師体験、高原でのサイクリング、リバートレッキング、さらにはジーンズ作りや備前焼の土ひねりなど、岡山ならではの多彩な体験・アクティビティを紹介しています。岡山の魅力的な体験をぜひお楽しみください。詳しくは岡山県公式観光サイトをご覧ください。' where id = 'Weu1DaffX9F_95mvTDW8m';
update content_bodies set title = 'Experience Okayama, the Land of Sunshine!', description = 'Okayama offers a variety of unique experiences and activities, including sea kayaking in the Seto Inland Sea, fishing experiences, cycling in highlands, river trekking, as well as hands-on activities like making jeans and crafting Bizen pottery. Discover the fun and engaging activities that Okayama has to offer! For more details, visit the Okayama Prefectural Official Tourism Site.' where id = 'GW7LYEmCJwc2IOnNSXLq2';
update content_bodies set title = '【Cinematic Vlog:日本遺産】『ジャパンレッド』発祥の地:吹屋ふるさと村（岡山県高梁市）', description = '吹屋は中国山地に抱かれた町で、江戸時代末期から明治時代にかけてベンガラ色の顔料とその原料であるローハの生産で栄えました。赤銅色の石州瓦とベンガラ色の外観で統一された町並みは印象的で、豪商たちの精巧な屋敷も見応えがあります。また、訪問者はベンガラの絵の具を使ってハンカチやバッグを作る体験プランも楽しむことができます。' where id = 'A9u2-q8zcoBRKzHgTrFmx';
update content_bodies set title = 'Cinematic Vlog: Japan Heritage - The Birthplace of Japan Red: Fukiya Furusato Village (Takahashi City, Okayama Prefecture)', description = 'Fukiya, nestled in the Chugoku Mountains, is a town that flourished through the production of Bengara pigment and its raw material, melanterite, during the late Edo and Meiji periods. The town is characterized by its nostalgic landscape, featuring buildings unified in Bengara red and reddish-brown Sekishu tiles. The exquisite mansions of wealthy merchants are worth a visit. Additionally, visitors can enjoy popular experiences such as making handkerchiefs and bags using Bengara pigment.' where id = 'gYtrHEjYKya-LX5OuByZe';
update content_bodies set title = '【吹屋ふるさと村】歩きたくなる紅色のまち！弁柄と銅の町・備中吹屋でベンガラ染体験！', description = '高梁市の山中に現れる赤い町並み「吹屋」は、江戸時代に赤の顔料「ベンガラ」の産地として栄えた独特の歴史を持っています。町並みを歩くだけでも楽しいですが、歴史を知ることで当時の様子が浮かび上がり、町が一層輝いて見えます。ベンガラ窯元の邸宅や工場跡、銅山の坑道跡、豪邸「広兼邸」を巡りながら散策し、「べんがら型染め体験」も楽しめます。このルートを辿れば、魅惑の吹屋を存分に満喫できること間違いありません！' where id = 'B39e4u0a6yt3RiYs4VxsX';
update content_bodies set title = 'Bengara-dyed Town: A Must-Visit in Bichu Fukiya, Okayama Prefecture', description = 'Fukiya, a town suddenly appearing in the mountains of Takahashi City, is known for its striking red buildings. Flourishing during the Edo period as a production site for the red pigment ''bengara'', the town has a unique history. Exploring the streets is enjoyable, but understanding its history brings the past vividly to life, making the town shine. Visitors can tour the bengara kiln residence, the remnants of a bengara factory, the copper mine tunnels, and the grand Hirokane residence. Additionally, the ''bengara dyeing experience'' offers a hands-on way to appreciate this charming town. Following this route guarantees a delightful experience in the enchanting Fukiya!' where id = 'QHiUOsbdG21U3xZv2W2AJ';
update content_bodies set title = '【吹屋ふるさと村】豪商たちが残した町並み 弁柄と銅の町・備中吹屋:日本遺産（岡山県高梁市）', description = '高梁市の山中に現れる赤い町並み「吹屋」は、江戸時代に赤の顔料「ベンガラ」の産地として栄えた独特の歴史を持っています。町並みを歩くだけでも楽しめますが、歴史を知ることで当時の様子が鮮明に浮かび上がり、町が一層輝いて見えます。ベンガラ窯元の邸宅や工場跡、銅山の坑道跡、豪邸「広兼邸」を巡りながら、町を散策し、「べんがら型染め体験」を楽しむことで、魅惑の吹屋を存分に満喫できるでしょう。' where id = 'v_n-m0hBhf9ned6yNnXQB';
update content_bodies set title = 'Bukei Furusato Village: A Town of Red and Copper - A Japanese Heritage Site in Takahashi City, Okayama', description = 'Bukei is a striking red town that suddenly appears in the mountains of Takahashi City. It flourished during the Edo period as a production site for the red pigment ''Bengara.'' While simply walking through the town is enjoyable, understanding its history brings the past vividly to life, making the town shine. Visitors can explore the former residences of Bengara kiln owners, the ruins of Bengara factories, the copper mine tunnels, and the grand Hirokane residence. Engaging in a ''Bengara dyeing experience'' while following this route ensures a delightful exploration of the enchanting Bukei.' where id = '1yt1CxQUJaPF9TUzVMyzK';